-- Biblioteca de 536 ejercicios con GIF de demostración, traducida al español.
-- Idempotente: se puede ejecutar de nuevo para actualizar textos sin duplicar filas.
-- Los GIF se sirven desde la API en /gifs/<codigo>.gif.

ALTER TABLE ejercicios ALTER COLUMN nombre TYPE VARCHAR(150);
ALTER TABLE ejercicios
    ADD COLUMN IF NOT EXISTS codigo VARCHAR(10),
    ADD COLUMN IF NOT EXISTS nombre_original VARCHAR(150),
    ADD COLUMN IF NOT EXISTS alias JSONB,
    ADD COLUMN IF NOT EXISTS zona VARCHAR(40),
    ADD COLUMN IF NOT EXISTS musculo_principal VARCHAR(60),
    ADD COLUMN IF NOT EXISTS musculos_secundarios JSONB,
    ADD COLUMN IF NOT EXISTS equipo VARCHAR(40),
    ADD COLUMN IF NOT EXISTS dificultad VARCHAR(20),
    ADD COLUMN IF NOT EXISTS categoria VARCHAR(30),
    ADD COLUMN IF NOT EXISTS descripcion TEXT,
    ADD COLUMN IF NOT EXISTS instrucciones JSONB,
    ADD COLUMN IF NOT EXISTS gif_url VARCHAR(255);
CREATE UNIQUE INDEX IF NOT EXISTS ux_ejercicios_codigo ON ejercicios (codigo);

INSERT INTO grupos_musculares (nombre) VALUES ('Antebrazos'), ('Pantorrillas')
ON CONFLICT (nombre) DO NOTHING;

INSERT INTO ejercicios (codigo, nombre, nombre_original, alias, grupo_muscular_id, zona, musculo_principal,
                        musculos_secundarios, equipo, dificultad, categoria, descripcion, instrucciones, gif_url)
VALUES
('0009', 'Fondo de pecho asistido (rodillas apoyadas)', 'assisted chest dip (kneeling)', '["fondos para pecho en máquina", "fondos pectorales con asistencia", "assisted chest dip (kneeling)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio enfocado en el pecho que se realiza en una máquina con las rodillas apoyadas en una almohadilla. La asistencia reduce la carga y facilita el movimiento mientras desarrollas fuerza o aprendes la técnica de los fondos.', '["Ajusta la máquina a la altura que prefieras y apoya bien las rodillas en la almohadilla.", "Sujeta las agarraderas con las palmas hacia abajo y los brazos completamente extendidos.", "Baja el cuerpo flexionando los codos hasta que la parte superior de los brazos quede paralela al piso.", "Haz una breve pausa y empuja para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0009.gif'),
('0015', 'Dominada asistida con agarre neutro cerrado', 'assisted parallel close grip pull-up', '["dominadas en máquina con agarre estrecho", "dominadas asistidas en barras paralelas", "assisted parallel close grip pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de espalda en máquina que brinda asistencia para realizar dominadas. El apoyo facilita el movimiento y te permite concentrarte en la técnica.', '["Ajusta el peso y la altura de la máquina según prefieras.", "Sujeta las barras paralelas con las manos juntas y las palmas enfrentadas.", "Cuélgate de las barras con los brazos completamente extendidos y los pies sin tocar el piso.", "Activa los músculos de la espalda y sube el cuerpo hacia las barras, manteniendo los codos cerca del torso.", "Sigue subiendo hasta que la barbilla quede por encima de las barras.", "Haz una breve pausa arriba y baja despacio hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0015.gif'),
('0017', 'Dominada asistida', 'assisted pull-up', '["dominadas en máquina", "dominadas con asistencia", "assisted pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que brinda apoyo para levantar el peso corporal al hacer dominadas. Trabaja principalmente los dorsales y también involucra los bíceps y los antebrazos.', '["Ajusta el peso y la altura de la máquina según prefieras.", "Sujeta las agarraderas con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Cuélgate con los brazos completamente extendidos y los pies sin tocar el piso.", "Activa los músculos de la espalda y sube el cuerpo hacia las agarraderas, manteniendo los codos cerca del torso.", "Sigue subiendo hasta que la barbilla quede por encima de las agarraderas.", "Haz una breve pausa arriba y baja despacio hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0017.gif'),
('0019', 'Fondo de tríceps asistido (rodillas apoyadas)', 'assisted triceps dip (kneeling)', '["fondos para tríceps en máquina", "fondos de brazos con asistencia", "assisted triceps dip (kneeling)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que permite trabajar los tríceps con asistencia, útil para quienes todavía no tienen la fuerza necesaria para hacer fondos sin apoyo. También involucra el pecho y los hombros como músculos secundarios.', '["Ajusta el peso y la altura de la máquina según prefieras.", "Arrodíllate sobre la almohadilla de frente a la máquina y sujeta las agarraderas.", "Baja el cuerpo flexionando los codos, manteniendo la espalda recta y el cuerpo cerca de la máquina.", "Haz una breve pausa abajo y empuja para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0019.gif'),
('0024', 'Sentadilla frontal con barra a banco', 'barbell bench front squat', '["sentadilla frontal en banco", "sentadilla a banco con barra al frente", "barbell bench front squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Isquiotibiales", "Glúteos", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja principalmente los cuádriceps y, en segundo plano, los isquiotibiales, los glúteos y las pantorrillas. Consiste en hacer una sentadilla con la barra apoyada al frente y requiere estabilidad abdominal, equilibrio y movilidad.', '["Ponte de pie con los pies al ancho de los hombros y la barra apoyada en la parte alta del pecho, justo debajo de las clavículas.", "Sujeta la barra con las palmas hacia abajo, manteniendo los codos elevados y la parte superior de los brazos paralela al piso.", "Baja en sentadilla flexionando las rodillas y las caderas, con la espalda recta y el pecho elevado.", "Haz una breve pausa abajo y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0024.gif'),
('0025', 'Press de banca con barra', 'barbell bench press', '["press plano", "pecho con barra", "barbell bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto clásico que trabaja principalmente los pectorales y también involucra los tríceps y los hombros. Se realiza acostado en un banco, subiendo y bajando una barra de forma controlada.', '["Acuéstate boca arriba en un banco plano, con los pies bien apoyados en el piso y la espalda contra el banco.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y sostenla justo encima del pecho con los brazos completamente extendidos.", "Baja la barra despacio hacia el pecho, manteniendo los codos cerca del torso.", "Haz una breve pausa cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta volver a la posición inicial, extendiendo los brazos.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0025.gif'),
('0026', 'Sentadilla con barra a banco', 'barbell bench squat', '["sentadilla en banco con barra", "sentadilla a banco", "barbell bench squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja principalmente los cuádriceps y también involucra los glúteos, los isquiotibiales y las pantorrillas. Consiste en hacer sentadillas con una barra y requiere buena técnica y fuerza.', '["Coloca una barra en un soporte para sentadillas a la altura del pecho.", "Ponte de espaldas al soporte con los pies al ancho de los hombros.", "Flexiona las rodillas y baja en sentadilla, manteniendo la espalda recta y el pecho elevado.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y da un paso atrás, manteniendo los pies al ancho de los hombros.", "Baja en sentadilla, manteniendo las rodillas alineadas con las puntas de los pies.", "Haz una breve pausa abajo y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0026.gif'),
('0027', 'Remo inclinado con barra', 'barbell bent over row', '["remo con barra para espalda", "remo de pie con torso inclinado", "barbell bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto para la parte alta de la espalda que consiste en inclinar el torso desde las caderas y llevar una barra hacia el cuerpo. Desarrolla fuerza y masa muscular en la espalda alta, los bíceps y los antebrazos, y requiere buena postura y estabilidad abdominal.', '["Ponte de pie con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Inclina el torso hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Sujeta la barra con las palmas hacia abajo y las manos un poco más separadas que el ancho de los hombros.", "Lleva la barra hacia la parte baja del pecho, juntando los omóplatos y contrayendo los músculos de la espalda.", "Haz una breve pausa arriba y baja la barra despacio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0027.gif'),
('0029', 'Sentadilla frontal con barra y agarre de cargada', 'barbell clean-grip front squat', '["sentadilla frontal con agarre de halterofilia", "sentadilla con barra al frente y codos altos", "barbell clean-grip front squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja los glúteos, los cuádriceps y los isquiotibiales, además de la zona abdominal para mantener la estabilidad. La barra se sostiene delante de los hombros con agarre de cargada, lo que exige buena movilidad y fuerza.', '["Ponte de pie con los pies al ancho de los hombros y la barra apoyada en la parte alta del pecho, con los codos hacia adelante.", "Baja flexionando las rodillas y llevando las caderas hacia atrás, como si fueras a sentarte en una silla.", "Mantén el pecho elevado y la espalda recta mientras bajas, sin dejar que las rodillas sobrepasen las puntas de los pies.", "Sigue bajando hasta que los muslos queden paralelos al piso o hasta donde puedas llegar con comodidad.", "Haz una breve pausa abajo y empuja con los talones para levantarte, extendiendo las caderas y las rodillas.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0029.gif'),
('0030', 'Press de banca con barra y agarre cerrado', 'barbell close-grip bench press', '["press cerrado", "press para tríceps con barra", "barbell close-grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja principalmente los tríceps y, en segundo plano, el pecho y los hombros. Se realiza acostado en un banco, subiendo y bajando una barra con agarre cerrado y los codos cerca del torso.', '["Acuéstate boca arriba en un banco plano, con los pies bien apoyados en el piso y la espalda contra el banco.", "Sujeta la barra con las manos un poco más juntas que el ancho de los hombros.", "Saca la barra del soporte y bájala despacio hacia el pecho, manteniendo los codos cerca del torso.", "Haz una breve pausa cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta volver a la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0030.gif'),
('0032', 'Peso muerto con barra', 'barbell deadlift', '["peso muerto convencional", "levantamiento de barra desde el piso", "barbell deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de fuerza que trabaja los glúteos, los isquiotibiales y la zona lumbar. Consiste en levantar una barra con peso desde el piso hasta quedar de pie, con énfasis en la técnica y la activación abdominal.', '["Ponte de pie con los pies al ancho de los hombros y la barra en el piso frente a ti.", "Flexiona las rodillas e inclina el torso desde las caderas para sujetar la barra con las palmas hacia ti y las manos un poco más separadas que el ancho de los hombros.", "Mantén la espalda recta y el pecho elevado mientras empujas con los talones para levantar la barra del piso, extendiendo las caderas y las rodillas.", "Al quedar de pie, contrae los glúteos y mantén firme la zona abdominal.", "Baja la barra hasta el piso flexionando las caderas y las rodillas, sin encorvar la espalda.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0032.gif'),
('0033', 'Press declinado con barra', 'barbell decline bench press', '["press de banca declinado", "pecho inferior con barra", "barbell decline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto enfocado en la parte inferior de los pectorales. Se realiza en un banco declinado, empujando una barra hacia arriba para trabajar el pecho, los tríceps y los hombros.', '["Acuéstate en un banco declinado con los pies asegurados y la cabeza más baja que las caderas.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y bájala despacio hacia el pecho, manteniendo los codos cerca del torso.", "Haz una breve pausa abajo y empuja la barra hacia arriba hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0033.gif'),
('0039', 'Sentadilla con barra al pecho', 'barbell front chest squat', '["sentadilla frontal al pecho", "sentadilla con carga frontal", "barbell front chest squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja los glúteos y también involucra los cuádriceps, los isquiotibiales, las pantorrillas y la zona abdominal. Consiste en hacer una sentadilla sosteniendo la barra frente al pecho y requiere fuerza, equilibrio y buena técnica.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra frente al pecho, con las manos al ancho de los hombros y los codos hacia adelante.", "Mantén firme la zona abdominal y el pecho elevado mientras bajas en sentadilla, llevando las caderas hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al piso o hasta donde puedas llegar con comodidad.", "Haz una breve pausa abajo y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0039.gif'),
('0042', 'Sentadilla frontal con barra', 'barbell front squat', '["sentadilla con barra al frente", "sentadilla con barra sobre los hombros por delante", "barbell front squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja los glúteos, los cuádriceps y los isquiotibiales, además de la zona abdominal para mantener la estabilidad. La barra se sostiene delante de los hombros, lo que exige movilidad y fuerza abdominal para conservar una buena postura.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra delante de los hombros, apoyada sobre las clavículas y los hombros.", "Mantén firme la zona abdominal y el pecho elevado mientras bajas en sentadilla, llevando las caderas hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al piso o hasta donde puedas llegar con comodidad.", "Haz una breve pausa abajo y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0042.gif'),
('0043', 'Sentadilla completa con barra', 'barbell full squat', '["sentadilla profunda con barra", "sentadilla completa con barra atrás", "barbell full squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja los glúteos y también involucra los cuádriceps, los isquiotibiales, las pantorrillas y la zona abdominal. Consiste en bajar en sentadilla con una barra sobre la parte alta de la espalda y requiere fuerza, equilibrio y buena técnica.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra sobre la parte alta de la espalda, apoyada en los trapecios o en la parte posterior de los hombros.", "Mantén firme la zona abdominal y el pecho elevado mientras empiezas a bajar.", "Flexiona las rodillas y las caderas, llevando las caderas hacia atrás y hacia abajo como si fueras a sentarte en una silla.", "Baja hasta que los muslos queden paralelos al piso o un poco más abajo.", "Mantén las rodillas alineadas con las puntas de los pies y el peso sobre los talones.", "Empuja con los talones para levantarte, extendiendo las caderas y las rodillas.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0043.gif'),
('0045', 'Press guillotina con barra', 'barbell guillotine bench press', '["press de banca al cuello", "press guillotina para pecho", "barbell guillotine bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Variante del press de banca en la que la barra baja hacia el cuello en lugar del pecho, con mayor énfasis en los pectorales superiores. Requiere un control cuidadoso y buena técnica para evitar lesiones.', '["Acuéstate boca arriba en un banco plano, con los pies bien apoyados en el piso y la espalda contra el banco.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Baja la barra despacio hacia el cuello, manteniendo los codos hacia afuera.", "Haz una breve pausa cuando la barra quede justo encima del cuello.", "Empuja la barra hacia arriba hasta volver a la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0045.gif'),
('0046', 'Sentadilla hack con barra', 'barbell hack squat', '["sentadilla con barra detrás de las piernas", "sentadilla hack libre", "barbell hack squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza del tren inferior que trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en hacer una sentadilla sosteniendo una barra detrás de las piernas, con énfasis en la cadena posterior y los cuádriceps.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra detrás de las piernas, apoyada contra la parte alta de los muslos.", "Baja flexionando las rodillas y las caderas, manteniendo la espalda recta y el pecho elevado.", "Sigue bajando hasta que los muslos queden paralelos al piso o hasta donde puedas llegar con comodidad.", "Haz una breve pausa y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0046.gif'),
('0047', 'Press inclinado con barra', 'barbell incline bench press', '["press de banca inclinado", "pecho superior con barra", "barbell incline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren superior que trabaja la parte alta de los pectorales y, en segundo plano, los hombros y los tríceps. Se realiza con barra en un banco inclinado y es habitual en las rutinas de fuerza para desarrollar el tamaño y la fuerza del pecho.', '["Ajusta un banco inclinado a un ángulo de 45 grados.", "Acuéstate en el banco con los pies bien apoyados en el piso.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y bájala despacio hacia el pecho, manteniendo los codos a 45 grados respecto al torso.", "Haz una breve pausa abajo y empuja la barra hacia arriba hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0047.gif'),
('0051', 'Sentadilla Jefferson con barra', 'barbell jefferson squat', '["sentadilla con barra entre las piernas", "sentadilla Jefferson con pies escalonados", "barbell jefferson squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en hacer una sentadilla con la barra entre las piernas y un pie adelantado, alternando la posición de los pies en cada repetición.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sujeta la barra con las palmas hacia ti y apóyala contra la parte delantera del cuerpo, justo debajo de la cintura.", "Adelanta el pie izquierdo y lleva el derecho hacia atrás, manteniendo la separación de los pies al ancho de los hombros.", "Flexiona las rodillas y baja en sentadilla, manteniendo la espalda recta y el pecho elevado.", "Empuja con los talones para levantarte y volver a la posición inicial.", "Repite el movimiento, alternando en cada repetición el pie que queda adelante y el que queda atrás."]'::jsonb, '/gifs/0051.gif'),
('0052', 'Press JM con barra', 'barbell jm bench press', '["press JM en banco", "press JM para tríceps", "barbell jm bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Movimiento de press enfocado en los tríceps que combina elementos del press de banca con agarre cerrado y de la extensión de tríceps. Se realiza acostado en un banco, bajando la barra al pecho con los codos cerca del torso y empujándola de nuevo hacia arriba.', '["Acuéstate boca arriba en un banco plano, con los pies bien apoyados en el piso y la espalda contra el banco.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Baja la barra hasta el pecho, manteniendo los codos pegados al torso.", "Empuja la barra hacia arriba hasta volver a la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0052.gif'),
('0053', 'Sentadilla con salto y barra', 'barbell jump squat', '["sentadilla explosiva con barra", "salto desde sentadilla con barra", "barbell jump squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Avanzado', 'Pliometría', 'Ejercicio dinámico del tren inferior que combina una sentadilla tradicional con un salto explosivo y una barra sobre la parte alta de la espalda. Trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas. Es un movimiento pliométrico que desarrolla potencia, fuerza y explosividad en las piernas.', '["Ponte de pie con los pies al ancho de los hombros y una barra sobre la parte alta de la espalda.", "Baja en sentadilla flexionando las rodillas y llevando las caderas hacia atrás.", "Al llegar a la parte baja de la sentadilla, impúlsate con fuerza hacia arriba para saltar.", "Durante el salto, extiende las caderas, las rodillas y los tobillos, impulsándote con las puntas de los pies.", "Aterriza suavemente en posición de sentadilla y repite de inmediato hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0053.gif'),
('0054', 'Zancada con barra', 'barbell lunge', '["desplante con barra", "zancada hacia adelante con barra", "barbell lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en dar un paso hacia adelante con una barra sobre la espalda alta, bajar en zancada y volver a ponerse de pie.', '["Ponte de pie con los pies al ancho de los hombros y una barra apoyada en la parte alta de la espalda.", "Da un paso hacia adelante con el pie derecho, manteniendo el torso erguido.", "Baja el cuerpo flexionando la rodilla derecha hasta que el muslo quede paralelo al piso.", "Empuja con el talón derecho para volver a la posición inicial.", "Repite con la pierna izquierda y sigue alternando las piernas hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0054.gif'),
('0063', 'Sentadilla con barra y pies juntos', 'barbell narrow stance squat', '["sentadilla con postura estrecha", "sentadilla cerrada con barra", "barbell narrow stance squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza del tren inferior que trabaja los glúteos, con una participación importante de los cuádriceps, los isquiotibiales y las pantorrillas. Se realiza con la barra sobre la espalda alta y una postura estrecha de los pies, con énfasis en la parte interna de los muslos y los glúteos.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra sobre la parte alta de la espalda, apoyada en los trapecios o en la parte posterior de los hombros.", "Mantén firme la zona abdominal y el pecho elevado mientras bajas despacio, flexionando las rodillas y llevando las caderas hacia atrás.", "Sigue bajando hasta que los muslos queden paralelos al piso o un poco más abajo.", "Haz una breve pausa y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0063.gif'),
('0064', 'Remo inclinado con barra a un brazo', 'barbell one arm bent over row', '["remo unilateral con barra", "remo con barra a una mano", "barbell one arm bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza unilateral para la espalda alta que requiere equilibrio, coordinación y estabilidad abdominal. Se realiza con el torso inclinado desde las caderas y la espalda recta, llevando una barra hacia el cuerpo con un brazo mientras mantienes una posición estable.', '["Ponte de pie con los pies al ancho de los hombros y las rodillas ligeramente flexionadas; sujeta una barra con una mano y la palma hacia ti.", "Inclina el torso hacia adelante desde las caderas, manteniendo la espalda recta y la cabeza alineada con la columna.", "Lleva la barra hacia el pecho, manteniendo el codo cerca del torso y juntando los omóplatos.", "Baja la barra de forma controlada hasta la posición inicial.", "Completa la cantidad de repeticiones que quieras realizar y luego cambia de brazo."]'::jsonb, '/gifs/0064.gif'),
('0066', 'Peso muerto lateral con barra a una mano', 'barbell one arm side deadlift', '["peso muerto tipo maleta con barra", "peso muerto unilateral con barra al costado", "barbell one arm side deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Cuádriceps", "Zona lumbar"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Variante unilateral del peso muerto que trabaja los glúteos, los isquiotibiales, los cuádriceps y la zona lumbar. Se realiza sosteniendo una barra con una mano al costado del cuerpo y exige equilibrio, fuerza de agarre y estabilidad abdominal.', '["Ponte de pie con los pies al ancho de los hombros y sujeta una barra con una mano y la palma hacia ti.", "Mantén la espalda recta y la zona abdominal firme.", "Flexiona las caderas y baja la barra por el lado externo de la pierna, manteniendo el brazo extendido y el pecho elevado.", "Baja la barra hasta donde puedas sin perder la técnica.", "Haz una breve pausa y vuelve despacio a la posición inicial.", "Completa la cantidad de repeticiones que quieras realizar y luego cambia de lado."]'::jsonb, '/gifs/0066.gif'),
('0068', 'Sentadilla a una pierna con barra', 'barbell one leg squat', '["sentadilla unilateral con barra", "sentadilla en una sola pierna con peso", "barbell one leg squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio exigente del tren inferior que trabaja principalmente los cuádriceps y también involucra los glúteos, los isquiotibiales y las pantorrillas. Requiere mucho equilibrio, fuerza y coordinación al hacer una sentadilla sobre una pierna con una barra en la espalda alta.', '["Ponte de pie con los pies al ancho de los hombros y sostén una barra sobre la parte alta de la espalda.", "Levanta un pie del piso y extiende la pierna hacia adelante, manteniéndola paralela al piso.", "Flexiona la pierna de apoyo y baja como si fueras a sentarte en una silla, manteniendo el pecho elevado y la espalda recta.", "Baja hasta que el muslo de la pierna de apoyo quede paralelo al piso y luego empuja con el talón para volver a la posición inicial.", "Completa la cantidad de repeticiones que quieras realizar y luego cambia de pierna."]'::jsonb, '/gifs/0068.gif'),
('0069', 'Sentadilla con barra sobre la cabeza', 'barbell overhead squat', '["sentadilla con barra arriba", "sentadilla con brazos extendidos sobre la cabeza", "barbell overhead squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio compuesto que trabaja los cuádriceps y consiste en hacer una sentadilla sosteniendo una barra sobre la cabeza. Exige mucha fuerza, equilibrio, movilidad y coordinación.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sujeta la barra con un agarre amplio y sostenla sobre la cabeza con los brazos completamente extendidos.", "Mantén firme la zona abdominal y baja en sentadilla, con el pecho elevado y las rodillas alineadas con las puntas de los pies.", "Haz una breve pausa abajo y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0069.gif'),
('0077', 'Zancada hacia atrás con barra (versión 2)', 'barbell rear lunge v. 2', '["desplante inverso con barra versión 2", "zancada reversa con barra variante 2", "barbell rear lunge v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja los glúteos y también involucra los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en dar una zancada hacia atrás con una barra sobre la espalda alta y volver a la posición inicial.', '["Ponte de pie con los pies al ancho de los hombros y sostén una barra sobre la parte alta de la espalda.", "Da un paso hacia atrás con el pie derecho y apoya la parte delantera del pie.", "Flexiona ambas rodillas para bajar hasta que el muslo izquierdo quede paralelo al piso.", "Empuja con el talón izquierdo para volver a la posición inicial.", "Repite con la otra pierna."]'::jsonb, '/gifs/0077.gif'),
('0078', 'Zancada hacia atrás con barra', 'barbell rear lunge', '["desplante inverso con barra", "zancada reversa con barra", "barbell rear lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja principalmente los glúteos y, en segundo plano, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en dar una zancada hacia atrás con una barra sobre la espalda alta y requiere equilibrio, coordinación y fuerza.', '["Ponte de pie con los pies al ancho de los hombros y una barra apoyada en la parte alta de la espalda.", "Da un paso hacia atrás con el pie derecho y apoya la parte delantera del pie.", "Flexiona ambas rodillas para bajar hasta que el muslo izquierdo quede paralelo al piso.", "Empuja con el talón izquierdo para volver a la posición inicial.", "Repite con la otra pierna."]'::jsonb, '/gifs/0078.gif'),
('0085', 'Peso muerto rumano con barra', 'barbell romanian deadlift', '["peso rumano", "peso muerto con bisagra de cadera", "barbell romanian deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza enfocado en los glúteos, con trabajo secundario de los isquiotibiales y la zona lumbar. Consiste en flexionar las caderas con la espalda recta, bajar la barra hasta sentir un estiramiento en los isquiotibiales y volver a ponerse de pie.', '["Ponte de pie con los pies al ancho de los hombros y las puntas hacia adelante.", "Sujeta la barra con las palmas hacia ti y las manos un poco más separadas que el ancho de los hombros.", "Inclina el torso desde las caderas, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Baja la barra hacia el piso, manteniéndola cerca del cuerpo.", "Siente cómo se estiran los isquiotibiales mientras bajas la barra.", "Cuando sientas el estiramiento en los isquiotibiales, lleva las caderas hacia adelante y vuelve a ponerte de pie.", "Contrae los glúteos al llegar arriba.", "Vuelve a bajar la barra a la posición inicial y repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0085.gif'),
('0086', 'Press militar tras nuca sentado con barra', 'barbell seated behind head military press', '["press de hombros tras nuca en banco", "press sentado con barra detrás de la cabeza", "barbell seated behind head military press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio compuesto de hombros que trabaja principalmente los deltoides y, en segundo plano, los tríceps y la espalda alta. Requiere buena movilidad y estabilidad de los hombros, además de una técnica adecuada para evitar lesiones.', '["Siéntate en un banco con la espalda recta y los pies bien apoyados en el piso.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y bájala detrás de la cabeza hasta la altura de los hombros.", "Empuja la barra hacia arriba hasta extender completamente los brazos.", "Baja la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0086.gif'),
('0091', 'Press de hombros sentado con barra', 'barbell seated overhead press', '["press militar sentado", "press de barra sobre la cabeza en banco", "barbell seated overhead press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de fuerza para los deltoides que también involucra los tríceps y la espalda alta. Se realiza sentado para estabilizar el tren inferior y concentrar el esfuerzo en el superior. Requiere buena técnica y movilidad de hombros para hacerlo de forma segura y efectiva.', '["Siéntate en un banco con la espalda recta y los pies bien apoyados en el piso.", "Sujeta la barra con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y llévala a la altura de los hombros, con los codos flexionados y las palmas hacia adelante.", "Empuja la barra sobre la cabeza hasta extender completamente los brazos.", "Haz una breve pausa arriba y baja la barra despacio hasta la altura de los hombros.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0091.gif'),
('0097', 'Sentadilla lateral con barra (versión 2)', 'barbell side split squat v. 2', '["zancada lateral con barra versión 2", "desplante lateral con barra variante 2", "barbell side split squat v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja principalmente los cuádriceps y también involucra los glúteos, los isquiotibiales y las pantorrillas. Consiste en dar un paso lateral y bajar en sentadilla con una barra sobre la espalda alta, lo que requiere fuerza, equilibrio y coordinación.', '["Ponte de pie con los pies más separados que el ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén una barra sobre la parte alta de la espalda, apoyada en los hombros.", "Da un paso amplio hacia la derecha con el pie derecho, manteniendo el izquierdo apoyado.", "Flexiona la rodilla derecha y baja en sentadilla, manteniendo el pecho elevado y la espalda recta.", "Empuja con el talón derecho para volver a la posición inicial.", "Repite hacia el otro lado, dando el paso con el pie izquierdo.", "Sigue alternando los lados hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0097.gif'),
('0098', 'Sentadilla lateral con barra', 'barbell side split squat', '["sentadilla con barra y postura amplia", "sentadilla abierta con barra", "barbell side split squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja los cuádriceps y también involucra los glúteos, los isquiotibiales y las pantorrillas. Consiste en hacer una sentadilla con los pies separados y una barra sobre la espalda alta, con énfasis en el movimiento lateral y la estabilidad.', '["Ponte de pie con los pies más separados que el ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén una barra sobre la parte alta de la espalda, apoyada en los trapecios.", "Mantén firme la zona abdominal y el pecho elevado mientras bajas en sentadilla, flexionando las rodillas y las caderas.", "Mientras bajas, lleva las rodillas hacia los lados y mantén el peso sobre los talones.", "Baja hasta que los muslos queden paralelos al piso y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0098.gif'),
('0099', 'Sentadilla dividida con barra', 'barbell single leg split squat', '["sentadilla con un pie adelantado", "desplante fijo con barra", "barbell single leg split squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja los cuádriceps y también involucra los glúteos, los isquiotibiales y las pantorrillas. Requiere equilibrio, coordinación y fuerza para hacer una sentadilla con una pierna adelantada y una barra sobre la espalda alta.', '["Ponte de pie con los pies al ancho de los hombros y sostén una barra sobre la parte alta de la espalda.", "Da un paso amplio hacia adelante con una pierna, manteniendo el torso erguido.", "Baja flexionando la rodilla y la cadera de la pierna delantera, mientras mantienes extendida la pierna de atrás.", "Sigue bajando hasta que el muslo delantero quede paralelo al piso.", "Haz una breve pausa y empuja con el talón delantero para volver a la posición inicial.", "Completa la cantidad de repeticiones que quieras realizar y luego cambia de pierna."]'::jsonb, '/gifs/0099.gif'),
('0101', 'Sentadilla rápida con barra', 'barbell speed squat', '["sentadilla de velocidad con barra", "sentadilla explosiva con peso", "barbell speed squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Variante dinámica de la sentadilla tradicional que se enfoca en la velocidad y la explosividad. Trabaja principalmente los glúteos, con una participación importante de los cuádriceps, los isquiotibiales y las pantorrillas. Requiere buena técnica, equilibrio y fuerza para realizarla de forma segura, especialmente con peso adicional.', '["Ponte de pie con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra sobre la parte alta de la espalda, apoyada en los trapecios o en la parte posterior de los hombros.", "Mantén firme la zona abdominal y el pecho elevado mientras llevas las caderas hacia atrás y hacia abajo, como si fueras a sentarte en una silla.", "Baja hasta que los muslos queden paralelos al piso o hasta donde puedas llegar con comodidad.", "Empuja con los talones para levantarte y contrae los glúteos al llegar arriba.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0101.gif'),
('0102', 'Sentadilla con barra (de rodillas)', 'barbell squat (on knees)', '["sentadilla arrodillado con barra", "sentadilla con rodillas en el piso", "barbell squat (on knees)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Variante de la sentadilla tradicional que se realiza de rodillas. Trabaja los cuádriceps y también involucra los glúteos, los isquiotibiales y las pantorrillas. Requiere estabilidad abdominal, equilibrio y buena técnica para manejar la barra de forma segura.', '["Arrodíllate en el piso con las rodillas al ancho de las caderas y las puntas de los pies hacia adelante.", "Coloca una barra sobre los hombros y sujétala con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Mantén firme la zona abdominal y el pecho elevado mientras bajas despacio flexionando las rodillas, sin encorvar la espalda.", "Sigue bajando hasta que los muslos queden paralelos al piso o hasta donde puedas llegar con comodidad.", "Haz una breve pausa abajo y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0102.gif'),
('0116', 'Peso muerto con barra y piernas rectas', 'barbell straight leg deadlift', '["peso muerto de piernas rígidas", "peso muerto con piernas extendidas", "barbell straight leg deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos", "Zona lumbar"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja principalmente los isquiotibiales y, en segundo plano, los glúteos y la zona lumbar. Requiere mantener la espalda recta y flexionar correctamente las caderas para estirar y fortalecer la cadena posterior de forma segura.', '["Ponte de pie con los pies al ancho de los hombros y las puntas hacia adelante.", "Sujeta la barra con las palmas hacia ti y las manos un poco más separadas que el ancho de los hombros.", "Inclina el torso desde las caderas y baja la barra hacia el piso, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Baja la barra hasta sentir un estiramiento en los isquiotibiales.", "Activa los isquiotibiales y los glúteos para levantar la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0116.gif'),
('0117', 'Peso muerto sumo con barra', 'barbell sumo deadlift', '["peso muerto con postura amplia", "peso muerto con piernas abiertas", "barbell sumo deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Cuádriceps", "Zona lumbar"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de fuerza que trabaja principalmente los glúteos, con una participación importante de los isquiotibiales, los cuádriceps y la zona lumbar. Se realiza con una postura amplia y enfatiza la fuerza de las caderas y las piernas.', '["Ponte de pie con los pies más separados que el ancho de los hombros y las puntas hacia afuera.", "Coloca una barra en el piso frente a ti, centrada entre los pies.", "Flexiona las rodillas y baja las caderas para sujetar la barra con las palmas hacia ti, manteniendo la espalda recta y el pecho elevado.", "Mantén firme la zona abdominal y empuja con los talones para levantar la barra del piso, extendiendo las caderas y las rodillas al mismo tiempo.", "Mientras subes, mantén el pecho elevado y la espalda recta, y lleva las caderas hacia adelante para activar bien los glúteos.", "Haz una breve pausa arriba y baja la barra despacio hasta la posición inicial, manteniendo el control durante todo el movimiento.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0117.gif'),
('0118', 'Remo inclinado con barra y agarre invertido', 'barbell reverse grip bent over row', '["remo con barra en supinación", "remo con agarre supino", "barbell reverse grip bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja principalmente la espalda alta y, en segundo plano, los bíceps y los antebrazos. Consiste en llevar una barra hacia la parte baja del pecho con el torso inclinado y requiere buena técnica y estabilidad abdominal.', '["Ponte de pie con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta una barra con las palmas hacia abajo y las manos un poco más separadas que el ancho de los hombros.", "Inclina el torso hacia adelante desde las caderas hasta que quede casi paralelo al piso, manteniendo la espalda recta y el pecho elevado.", "Lleva la barra hacia la parte baja del pecho, juntando los omóplatos.", "Haz una breve pausa arriba y baja la barra despacio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que quieras realizar."]'::jsonb, '/gifs/0118.gif'),
('0122', 'Press de banca con barra y agarre amplio', 'barbell wide bench press', '["Press plano con agarre abierto", "Pecho con barra y manos separadas", "barbell wide bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de fuerza que trabaja principalmente los pectorales y, de forma secundaria, los hombros y tríceps. Se realiza con una barra y un banco, bajando la barra al pecho con un agarre amplio y empujándola de nuevo hacia arriba.', '["Acuéstate en un banco plano, con los pies bien apoyados en el suelo y la espalda contra el banco.", "Agarra la barra con las manos un poco más separadas que el ancho de los hombros.", "Saca la barra del soporte y sostenla justo encima del pecho, con los brazos completamente extendidos.", "Baja la barra despacio hacia el pecho, con los codos ligeramente abiertos.", "Haz una breve pausa cuando la barra toque el pecho y luego empújala hacia arriba hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0122.gif'),
('0124', 'Sentadilla con barra y postura amplia', 'barbell wide squat', '["Sentadilla abierta con barra", "Sentadilla con pies separados", "barbell wide squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja principalmente los cuádriceps y, de forma secundaria, los glúteos, isquiotibiales y pantorrillas. Consiste en hacer una sentadilla con los pies bien separados y una barra sobre la parte alta de la espalda.', '["Párate con los pies más separados que el ancho de los hombros y las puntas ligeramente hacia afuera.", "Coloca la barra sobre la parte alta de la espalda, apoyada en los trapecios o en la parte posterior de los hombros.", "Mantén el abdomen firme y el pecho elevado mientras bajas en sentadilla, llevando la cadera hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar con comodidad.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0124.gif'),
('0127', 'Sentadilla Zercher con barra', 'barbell zercher squat', '["Sentadilla con barra en los codos", "Sentadilla con carga en el pliegue de los brazos", "barbell zercher squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio del tren inferior en el que sostienes la barra en los pliegues de los codos para trabajar glúteos, cuádriceps, isquiotibiales, pantorrillas y zona media. Exige bastante estabilidad abdominal, fuerza del tren superior y una técnica adecuada de sentadilla.', '["Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra en los pliegues de los codos y agárrala con las manos para darle estabilidad.", "Mantén el abdomen firme y el pecho elevado mientras llevas la cadera hacia atrás y abajo para hacer la sentadilla.", "Mantén las rodillas alineadas con las puntas de los pies y el peso sobre los talones.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0127.gif'),
('0129', 'Fondos en banco (rodillas flexionadas)', 'bench dip (knees bent)', '["Fondos de tríceps en banco", "Fondos en silla con rodillas dobladas", "bench dip (knees bent)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros. Se realiza con un banco o una silla y ayuda a desarrollar la fuerza de la parte superior de los brazos.', '["Siéntate en el borde de un banco o una silla y agarra el borde con las manos a los lados de la cadera.", "Desliza los glúteos fuera del banco y estira las piernas al frente, manteniendo los talones en el suelo.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.", "Haz una breve pausa abajo y luego empuja para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0129.gif'),
('0139', 'Dominadas de bíceps con agarre cerrado', 'biceps narrow pull-ups', '["Dominadas supinas cerradas", "Dominadas con palmas hacia ti", "biceps narrow pull-ups"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los bíceps y, de forma secundaria, los antebrazos y hombros. Consiste en subir el cuerpo hacia una barra con agarre cerrado y palmas hacia ti; exige bastante fuerza y coordinación del tren superior.', '["Cuélgate de una barra de dominadas con las palmas hacia ti y las manos al ancho de los hombros.", "Mantén el abdomen firme y sube hacia la barra, concentrándote en usar los bíceps para levantar el cuerpo.", "Haz una breve pausa arriba y luego baja despacio hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0139.gif'),
('0140', 'Dominada de bíceps', 'biceps pull-up', '["Dominada con agarre prono", "Dominada enfocada en bíceps", "biceps pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal que trabaja los bíceps y, de forma secundaria, los antebrazos y hombros. Consiste en subir el cuerpo hacia una barra con agarre prono, concentrándote en flexionar los codos para aumentar el trabajo de los bíceps.', '["Cuélgate de una barra de dominadas con las palmas hacia adelante y las manos al ancho de los hombros.", "Mantén el abdomen firme y sube flexionando los codos, acercando el pecho a la barra.", "Haz una pausa arriba y luego baja despacio hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0140.gif'),
('0148', 'Press de hombros alternado en polea', 'cable alternate shoulder press', '["Press alterno de hombros con poleas", "Empuje de hombros alternando brazos en polea", "cable alternate shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los deltoides que consiste en empujar una manija de polea por encima de la cabeza a la vez, alternando los brazos. Requiere estabilidad y coordinación.', '["Párate con los pies al ancho de los hombros y toma las manijas de la máquina de poleas con agarre prono.", "Coloca las manos a la altura de los hombros, con las palmas hacia adelante.", "Mantén el abdomen firme y la espalda recta.", "Empuja una manija hacia arriba y hacia adelante hasta extender el brazo por completo.", "Haz una breve pausa arriba y luego baja la manija despacio hasta la posición inicial.", "Repite con el otro brazo.", "Alterna los brazos hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0148.gif'),
('0151', 'Press de pecho en polea', 'cable bench press', '["Press de pecho de pie con poleas", "Empuje de pecho en polea", "cable bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en máquina de poleas que trabaja los pectorales, tríceps y hombros. El movimiento se parece al press de banca tradicional, pero las poleas mantienen una tensión constante durante todo el recorrido.', '["Ajusta las poleas a la altura del pecho y coloca las manijas.", "Párate de espaldas a la máquina, con los pies al ancho de los hombros.", "Toma las manijas con agarre prono y da un paso al frente para tensar los cables.", "Apoya bien los pies en el suelo y mantén el abdomen firme.", "Flexiona los codos y lleva las manos a la altura de los hombros, manteniendo los codos en un ángulo de 90 grados.", "Empuja las manijas hacia adelante hasta extender los brazos por completo frente a ti.", "Haz una breve pausa y luego regresa despacio, llevando las manos de nuevo a la altura de los hombros.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0151.gif'),
('0157', 'Peso muerto en polea', 'cable deadlift', '["Peso muerto con cable", "Levantamiento de cadera en polea", "cable deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Cuádriceps", "Zona lumbar"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja principalmente los glúteos y, de forma secundaria, los isquiotibiales, cuádriceps y zona lumbar. Consiste en levantar la carga de una polea desde una posición baja, flexionando y extendiendo la cadera hasta quedar de pie.', '["Párate frente a la máquina de poleas con los pies al ancho de los hombros.", "Flexiona la cadera y las rodillas, bajando el torso hasta que la espalda quede paralela al suelo.", "Toma las manijas con agarre prono, manteniendo los brazos rectos y los hombros hacia atrás.", "Activa los glúteos y los isquiotibiales para levantar las manijas, extendiendo la cadera hasta quedar de pie.", "Haz una breve pausa arriba y luego baja las manijas despacio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0157.gif'),
('0169', 'Press inclinado en polea', 'cable incline bench press', '["Press de pecho inclinado con poleas", "Pecho superior en banco inclinado con poleas", "cable incline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en banco inclinado con manijas de polea que trabaja los pectorales superiores, deltoides y tríceps. La resistencia de las poleas mantiene una tensión constante durante el movimiento y ayuda a desarrollar fuerza y masa muscular en la parte superior del pecho.', '["Ajusta el banco a una inclinación de 45 grados.", "Coloca las manijas en las poleas altas.", "Siéntate en el banco de frente a la máquina de poleas, con los pies bien apoyados en el suelo.", "Toma las manijas con agarre prono y llévalas a la altura de los hombros.", "Empuja las manijas hacia adelante y arriba hasta extender los brazos por completo.", "Haz una breve pausa y luego baja las manijas despacio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0169.gif'),
('0180', 'Remo sentado en polea baja', 'cable low seated row', '["Remo bajo con cable", "Jalón sentado hacia el torso", "cable low seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de fuerza en máquina de poleas que trabaja principalmente la parte alta de la espalda y, de forma secundaria, los bíceps y antebrazos. Consiste en jalar las manijas hacia el torso, manteniendo la espalda recta y juntando los omóplatos.', '["Siéntate en la máquina con los pies bien apoyados en las plataformas y las rodillas ligeramente flexionadas.", "Toma las manijas con agarre prono, con las palmas hacia abajo.", "Mantén la espalda recta e inclínate un poco hacia adelante, con los codos ligeramente flexionados.", "Jala las manijas hacia el cuerpo, juntando los omóplatos.", "Haz una breve pausa al terminar de jalar y luego deja que las manijas regresen despacio a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0180.gif'),
('0189', 'Remo inclinado a un brazo en polea', 'cable one arm bent over row', '["Remo unilateral inclinado con cable", "Remo con una mano en polea", "cable one arm bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de jalón unilateral en polea que trabaja la parte alta de la espalda y requiere estabilidad abdominal y coordinación. Se enfoca en mantener una técnica adecuada y controlar el movimiento.', '["Párate frente a una máquina de poleas con los pies al ancho de los hombros.", "Flexiona un poco las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta.", "Toma la manija con una mano, con la palma hacia adentro, y extiende el brazo por completo.", "Jala la manija hacia el cuerpo, manteniendo el codo cerca del costado, hasta que la mano llegue a la parte baja del pecho.", "Haz una breve pausa y luego extiende el brazo despacio hasta volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de lado."]'::jsonb, '/gifs/0189.gif'),
('0219', 'Press de hombros en polea', 'cable shoulder press', '["Press sobre la cabeza con poleas", "Empuje de hombros con cable", "cable shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio compuesto en máquina de poleas que trabaja los deltoides. Consiste en empujar las manijas desde la altura de los hombros hasta arriba de la cabeza, activando también los tríceps y la parte alta de la espalda.', '["Ajusta la máquina de poleas para que las manijas queden a la altura de los hombros.", "Párate de espaldas a la máquina con los pies al ancho de los hombros.", "Toma las manijas con agarre prono y llévalas a la altura de los hombros, con los codos flexionados y hacia afuera.", "Empuja las manijas hacia arriba hasta extender los brazos por completo sobre la cabeza.", "Haz una breve pausa arriba y luego baja las manijas despacio hasta la altura de los hombros.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0219.gif'),
('0239', 'Remo sentado en polea con espalda recta', 'cable straight back seated row', '["Remo en polea sin encorvar la espalda", "Remo sentado con cable y torso recto", "cable straight back seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos", "Hombros"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de fuerza en máquina de remo en polea que trabaja la parte alta de la espalda. Consiste en jalar las manijas hacia el cuerpo con la espalda recta, activando también los bíceps, antebrazos y hombros.', '["Siéntate en la máquina de remo en polea con los pies bien apoyados en las plataformas y las rodillas ligeramente flexionadas.", "Toma las manijas con agarre prono, con las palmas hacia abajo.", "Mantén la espalda recta e inclínate un poco hacia adelante desde la cadera.", "Jala las manijas hacia el cuerpo, juntando los omóplatos.", "Haz una breve pausa al terminar de jalar y luego deja que las manijas regresen despacio a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0239.gif'),
('0251', 'Fondos para pecho', 'chest dip', '["Fondos pectorales en paralelas", "Pecho en barras paralelas", "chest dip"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal en barras paralelas que trabaja principalmente los pectorales y, de forma secundaria, los tríceps y hombros. Requiere bastante fuerza, estabilidad y control del tren superior.', '["Sostente en las barras paralelas con los brazos completamente extendidos y el cuerpo recto.", "Baja el cuerpo flexionando los codos hasta que los hombros queden por debajo de los codos.", "Empuja y estira los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0251.gif'),
('0253', 'Dominadas (agarre paralelo cerrado)', 'chin-ups (narrow parallel grip)', '["Dominadas con agarre neutro cerrado", "Dominadas con manos juntas en paralelo", "chin-ups (narrow parallel grip)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja la parte alta de la espalda, con una participación importante de los bíceps y antebrazos. Consiste en subir el cuerpo hacia una barra con agarre paralelo cerrado, desarrollando fuerza en la espalda alta y los brazos.', '["Cuélgate de una barra de dominadas con un agarre paralelo cerrado y las palmas hacia ti.", "Activa los músculos de la espalda y sube el cuerpo hacia la barra, manteniendo los codos cerca del cuerpo.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja el cuerpo despacio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0253.gif'),
('0258', 'Flexión de reloj', 'clock push-up', '["Flexión con giro lateral", "Flexión con extensión lateral de brazo", "clock push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio dinámico con peso corporal que trabaja el pecho, tríceps, hombros y zona media. Incluye un giro y la extensión de un brazo hacia un lado al bajar en la flexión, lo que exige más estabilidad y coordinación.', '["Colócate en plancha alta, con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Baja el cuerpo hacia el suelo flexionando los codos y manteniéndolos cerca de los costados.", "Mientras bajas, gira el cuerpo hacia la izquierda y extiende el brazo izquierdo hacia un lado.", "Empuja para volver a la posición inicial mientras giras el cuerpo hacia el centro.", "Repite la flexión, esta vez girando el cuerpo hacia la derecha y extendiendo el brazo derecho hacia un lado.", "Sigue alternando los lados en cada repetición."]'::jsonb, '/gifs/0258.gif'),
('0259', 'Flexión con agarre cerrado', 'close-grip push-up', '["Flexión con manos juntas", "Flexión cerrada para tríceps", "close-grip push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros. Se realiza con las manos juntas debajo de los hombros y los codos cerca del cuerpo.', '["Colócate en plancha alta, con las manos cerca una de la otra, justo debajo de los hombros.", "Mantén el abdomen firme y baja el cuerpo hacia el suelo, con los codos cerca de los costados.", "Empuja con las palmas para extender los brazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0259.gif'),
('0279', 'Flexión declinada', 'decline push-up', '["Flexión con pies elevados", "Flexión con pies sobre una superficie", "decline push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja los pectorales con los pies elevados, lo que aumenta la dificultad respecto a una flexión estándar. También activa los tríceps y hombros de forma secundaria.', '["Apoya las manos en el suelo, un poco más separadas que el ancho de los hombros, y coloca los pies sobre una superficie estable y elevada.", "Mantén el cuerpo en línea recta de la cabeza a los pies y el abdomen firme.", "Baja el pecho hacia el suelo flexionando los codos y manteniéndolos cerca del cuerpo.", "Empuja con las palmas para extender los brazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0279.gif'),
('0283', 'Flexión diamante', 'diamond push-up', '["Flexión con manos en diamante", "Flexión de tríceps con manos juntas", "diamond push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros. Se realiza en posición de plancha con las manos juntas formando un diamante y requiere bastante fuerza y estabilidad del tren superior.', '["Colócate en plancha alta, con las manos juntas y los pulgares e índices formando un diamante.", "Mantén el cuerpo en línea recta de la cabeza a los pies, con el abdomen y los glúteos firmes.", "Baja el pecho hacia el diamante que forman las manos, manteniendo los codos cerca del cuerpo.", "Haz una breve pausa abajo y luego empuja para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0283.gif'),
('0289', 'Press de banca con mancuernas', 'dumbbell bench press', '["Press plano con mancuernas", "Pecho con mancuernas en banco plano", "dumbbell bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio clásico de fuerza del tren superior que trabaja principalmente los pectorales y, de forma secundaria, los tríceps y hombros. Se realiza acostado en un banco, empujando las mancuernas desde la altura del pecho hasta extender los brazos por completo.', '["Acuéstate en un banco plano, con los pies bien apoyados en el suelo y la espalda contra el banco.", "Sostén una mancuerna en cada mano, con las palmas hacia adelante y los brazos extendidos sobre el pecho.", "Baja las mancuernas despacio a los lados del pecho, manteniendo los codos en un ángulo de 90 grados.", "Haz una breve pausa y luego empuja las mancuernas hacia arriba hasta volver a la posición inicial, extendiendo los brazos por completo.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0289.gif'),
('0291', 'Sentadilla a banco con mancuerna', 'dumbbell bench squat', '["Sentadilla con mancuerna hasta el banco", "Sentadilla con apoyo en banco", "dumbbell bench squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio del tren inferior que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, isquiotibiales y pantorrillas. Consiste en bajar en sentadilla hasta un banco mientras sostienes una mancuerna; el banco ayuda a guiar la profundidad y la técnica.', '["Coloca una mancuerna en el suelo frente a un banco.", "Párate de espaldas al banco con los pies al ancho de los hombros.", "Flexiona las rodillas y la cadera para bajar hacia el banco, manteniendo el pecho elevado y la espalda recta.", "Cuando los glúteos toquen el banco, empuja con los talones para ponerte de pie y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0291.gif'),
('0293', 'Remo inclinado con mancuernas', 'dumbbell bent over row', '["Remo con dos mancuernas", "Remo con torso inclinado", "dumbbell bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto para la parte alta de la espalda que consiste en inclinar el torso desde la cadera y jalar las mancuernas hacia el pecho, manteniendo la espalda recta.', '["Párate con los pies al ancho de los hombros y las rodillas ligeramente flexionadas, sosteniendo una mancuerna en cada mano con las palmas hacia el cuerpo.", "Inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta y el abdomen firme.", "Deja los brazos colgando hacia el suelo, con los codos ligeramente flexionados.", "Jala las mancuernas hacia el pecho, juntando los omóplatos.", "Haz una breve pausa arriba y luego baja las mancuernas despacio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0293.gif'),
('0300', 'Peso muerto con mancuernas', 'dumbbell deadlift', '["Peso muerto con dos mancuernas", "Levantamiento desde el suelo con mancuernas", "dumbbell deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio compuesto que trabaja principalmente los glúteos y, de forma secundaria, los isquiotibiales y la zona lumbar. Consiste en levantar mancuernas desde el suelo mediante la flexión de cadera y la extensión de las piernas y la espalda.', '["Párate con los pies al ancho de los hombros y las puntas hacia adelante.", "Sostén una mancuerna en cada mano, con las palmas hacia el cuerpo y los brazos extendidos hacia abajo.", "Flexiona la cadera y las rodillas para bajar las mancuernas hacia el suelo, manteniendo la espalda recta.", "Empuja con los talones y extiende la cadera y las rodillas para levantar las mancuernas y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0300.gif'),
('0301', 'Press declinado con mancuernas', 'dumbbell decline bench press', '["Press de pecho en banco declinado", "Pecho inferior con mancuernas", "dumbbell decline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en banco declinado que trabaja principalmente los pectorales inferiores y, de forma secundaria, los tríceps y hombros. Consiste en empujar las mancuernas hacia arriba desde una posición declinada, con buena técnica y control.', '["Acuéstate en un banco declinado, con los pies asegurados y la cabeza más baja que la cadera.", "Sostén una mancuerna en cada mano y extiende los brazos hacia arriba sobre el pecho, con las palmas hacia adelante.", "Baja las mancuernas despacio a los lados del pecho, manteniendo los codos en un ángulo de 90 grados.", "Empuja las mancuernas hacia arriba hasta volver a la posición inicial, extendiendo los brazos por completo.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0301.gif'),
('0314', 'Press inclinado con mancuernas', 'dumbbell incline bench press', '["Press de pecho en banco inclinado", "Pecho superior con mancuernas", "dumbbell incline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren superior que trabaja principalmente la parte superior de los pectorales, además de los hombros y tríceps. Se realiza con mancuernas en un banco inclinado y requiere estabilidad y control durante todo el movimiento.', '["Ajusta un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con los pies bien apoyados en el suelo y la espalda firme contra el respaldo.", "Sostén una mancuerna en cada mano, con las palmas hacia adelante, y levántalas a la altura de los hombros.", "Baja las mancuernas despacio a los lados del pecho, manteniendo los codos en un ángulo de 90 grados.", "Empuja las mancuernas hacia arriba hasta volver a la posición inicial, extendiendo los brazos por completo.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0314.gif'),
('0336', 'Zancada con mancuernas', 'dumbbell lunge', '["Desplante con mancuernas", "Zancada al frente con peso", "dumbbell lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja los glúteos, cuádriceps, isquiotibiales y pantorrillas. Consiste en dar una zancada al frente mientras sostienes mancuernas, regresar a la posición inicial y alternar las piernas.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano.", "Da un paso al frente con el pie derecho y baja el cuerpo en posición de zancada.", "Mantén la espalda recta y el pecho elevado mientras bajas.", "Empuja con el talón derecho para volver a la posición inicial.", "Repite con la pierna izquierda.", "Alterna las piernas hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0336.gif'),
('0352', 'Press de banca con mancuernas y agarre neutro', 'dumbbell neutral grip bench press', '["Press plano con palmas enfrentadas", "Press con mancuernas paralelas", "dumbbell neutral grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de empuje en banco con mancuernas y las palmas enfrentadas. Trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros.', '["Acuéstate en un banco plano, con los pies bien apoyados en el suelo y la espalda contra el banco.", "Sostén una mancuerna en cada mano con agarre neutro, es decir, con las palmas enfrentadas, y los brazos extendidos sobre el pecho.", "Baja las mancuernas despacio hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una breve pausa abajo y luego empuja las mancuernas hasta volver a la posición inicial, extendiendo los brazos por completo.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0352.gif'),
('0360', 'Press de hombro a un brazo con mancuerna (versión 2)', 'dumbbell one arm shoulder press v. 2', '["Press unilateral con mancuerna versión 2", "Empuje sobre la cabeza a una mano versión 2", "dumbbell one arm shoulder press v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de empuje por encima de la cabeza a un brazo que trabaja los deltoides y activa los tríceps y la espalda alta para estabilizar el cuerpo. Desarrolla fuerza y estabilidad del hombro y exige activar la zona media al trabajar de un solo lado.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna con una mano a la altura del hombro, con la palma hacia adelante.", "Mantén el abdomen firme y empuja la mancuerna directamente hacia arriba, por encima de la cabeza, hasta extender el brazo por completo.", "Haz una breve pausa arriba y luego baja la mancuerna despacio hasta la altura del hombro.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/0360.gif'),
('0361', 'Press de hombro a un brazo con mancuerna', 'dumbbell one arm shoulder press', '["Press unilateral de hombro", "Empuje sobre la cabeza con una mancuerna", "dumbbell one arm shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de empuje por encima de la cabeza a un brazo que trabaja principalmente los deltoides y, de forma secundaria, los tríceps y la espalda alta. Requiere estabilidad abdominal y coordinación para mantener el equilibrio al empujar con un solo brazo.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna con una mano a la altura del hombro, con la palma hacia adelante.", "Empuja la mancuerna hacia arriba hasta extender el brazo por completo sobre la cabeza.", "Haz una breve pausa arriba y luego baja la mancuerna despacio hasta la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/0361.gif'),
('0371', 'Sentadilla con salto y mancuernas', 'dumbbell plyo squat', '["Sentadilla pliométrica con mancuernas", "Sentadilla explosiva con peso", "dumbbell plyo squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Avanzado', 'Pliometría', 'Ejercicio dinámico del tren inferior que combina una sentadilla con un salto pliométrico mientras sostienes mancuernas. Trabaja glúteos, cuádriceps, isquiotibiales y pantorrillas, y requiere potencia explosiva, coordinación y equilibrio.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano a los costados.", "Baja en sentadilla flexionando las rodillas y llevando la cadera hacia atrás.", "Al llegar a la parte más baja de la sentadilla, impúlsate con fuerza hacia arriba y salta.", "Mientras estás en el aire, cambia rápidamente la posición de los pies para caer con el otro pie adelante.", "Baja de inmediato en sentadilla y vuelve a saltar, cambiando otra vez la posición de los pies.", "Sigue alternando la posición de los pies en cada salto hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0371.gif'),
('0381', 'Zancada hacia atrás con mancuernas', 'dumbbell rear lunge', '["Desplante inverso con mancuernas", "Zancada reversa con peso", "dumbbell rear lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, isquiotibiales y pantorrillas. Consiste en dar una zancada hacia atrás con mancuernas, lo que exige equilibrio y fuerza en cada pierna.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano.", "Da un paso hacia atrás con el pie derecho y baja el cuerpo en posición de zancada.", "Flexiona la rodilla izquierda y baja hasta que el muslo izquierdo quede paralelo al suelo.", "Haz una breve pausa y luego empuja con el talón izquierdo para volver a la posición inicial.", "Repite del otro lado, dando el paso hacia atrás con el pie izquierdo."]'::jsonb, '/gifs/0381.gif'),
('0404', 'Press de hombros sentado con mancuernas (agarre paralelo)', 'dumbbell seated shoulder press (parallel grip)', '["Press sentado con agarre neutro", "Press de hombros sentado con palmas enfrentadas", "dumbbell seated shoulder press (parallel grip)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los deltoides que se realiza sentado, con mancuernas y agarre neutro. También trabaja los tríceps y la parte alta de la espalda de forma secundaria.', '["Siéntate en un banco con una mancuerna en cada mano y las palmas hacia adentro.", "Levanta las mancuernas a la altura de los hombros, con los codos flexionados y las palmas hacia adelante.", "Empuja las mancuernas hacia arriba hasta extender los brazos por completo sobre la cabeza.", "Haz una breve pausa arriba y luego baja las mancuernas despacio hasta la altura de los hombros.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0404.gif'),
('0405', 'Press de hombros sentado con mancuernas', 'dumbbell seated shoulder press', '["Press sentado con mancuernas", "Empuje de hombros en banco con mancuernas", "dumbbell seated shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los deltoides que se realiza sentado, empujando mancuernas por encima de la cabeza para fortalecer los hombros y la parte superior de los brazos.', '["Siéntate en un banco con una mancuerna en cada mano, apoyada sobre los muslos.", "Levanta las mancuernas a la altura de los hombros, con las palmas hacia adelante.", "Empuja las mancuernas hacia arriba hasta extender los brazos por completo sobre la cabeza.", "Haz una breve pausa arriba y luego baja las mancuernas despacio hasta la altura de los hombros.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0405.gif'),
('0410', 'Sentadilla búlgara con mancuernas', 'dumbbell single leg split squat', '["Sentadilla con pie trasero elevado", "Zancada estática con pie en banco y mancuernas", "dumbbell single leg split squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio unilateral del tren inferior que trabaja principalmente los cuádriceps y, de forma secundaria, los glúteos, isquiotibiales y pantorrillas. Requiere equilibrio, coordinación y fuerza al mantener una pierna elevada y añadir la resistencia de las mancuernas.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano.", "Da un paso al frente con un pie y acomódate con el pie delantero bien apoyado en el suelo y el trasero elevado sobre un banco o escalón.", "Baja el cuerpo flexionando la rodilla y la cadera delanteras, con la rodilla trasera ligeramente flexionada y el talón trasero sin tocar el suelo.", "Sigue bajando hasta que el muslo delantero quede paralelo al suelo y luego empuja con el talón delantero para volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna y repite."]'::jsonb, '/gifs/0410.gif'),
('0411', 'Sentadilla a una pierna con mancuernas', 'dumbbell single leg squat', '["Sentadilla unilateral con mancuernas", "Sentadilla con una pierna al frente y peso", "dumbbell single leg squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Avanzado', 'Fuerza', 'Ejercicio exigente del tren inferior que trabaja los glúteos, cuádriceps, isquiotibiales y pantorrillas. Requiere equilibrio, coordinación y fuerza para hacer la sentadilla sobre una sola pierna mientras sostienes mancuernas como resistencia adicional.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano.", "Extiende una pierna hacia adelante y mantenla sin tocar el suelo durante todo el ejercicio.", "Flexiona la pierna de apoyo y baja el cuerpo como si fueras a sentarte en una silla.", "Mantén el pecho elevado y la espalda recta.", "Haz una breve pausa abajo y luego empuja con el talón para volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna."]'::jsonb, '/gifs/0411.gif'),
('0413', 'Sentadilla con mancuernas', 'dumbbell squat', '["Sentadilla con dos mancuernas", "Sentadilla con peso a los costados", "dumbbell squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de fuerza del tren inferior que trabaja los glúteos, cuádriceps e isquiotibiales, además de activar las pantorrillas. Consiste en bajar y subir en sentadilla con buena técnica, sosteniendo una mancuerna en cada mano.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano a los costados.", "Mantén el pecho elevado y el abdomen firme mientras flexionas las rodillas y la cadera para bajar, como si fueras a sentarte en una silla.", "Sigue bajando hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar con comodidad.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0413.gif'),
('0414', 'Press de hombros alternado de pie con mancuernas', 'dumbbell standing alternate overhead press', '["Press alterno de pie", "Empuje alternado sobre la cabeza con mancuernas", "dumbbell standing alternate overhead press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Core"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de hombros que consiste en empujar las mancuernas por encima de la cabeza, alternando los brazos mientras estás de pie. Trabaja los deltoides y también activa los tríceps y la zona media para mantener la estabilidad.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros y con las palmas hacia adelante.", "Empuja una mancuerna por encima de la cabeza hasta extender el brazo por completo.", "Baja la mancuerna de nuevo a la altura del hombro.", "Repite con el otro brazo.", "Sigue alternando los brazos hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0414.gif'),
('0426', 'Press de hombros de pie con mancuernas', 'dumbbell standing overhead press', '["Press de pie con mancuernas", "Empuje sobre la cabeza de pie con mancuernas", "dumbbell standing overhead press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto para los deltoides que consiste en empujar mancuernas desde la altura de los hombros hasta arriba de la cabeza mientras estás de pie.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano a la altura de los hombros y con las palmas hacia adelante.", "Empuja las mancuernas hacia arriba hasta extender los brazos por completo sobre la cabeza.", "Haz una breve pausa arriba y luego baja las mancuernas despacio hasta la altura de los hombros.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0426.gif'),
('0432', 'Peso muerto con mancuernas y piernas rígidas', 'dumbbell stiff leg deadlift', '["Peso muerto con piernas casi rectas", "Peso muerto de piernas semirrígidas con mancuernas", "dumbbell stiff leg deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja los glúteos y los isquiotibiales, con activación adicional de la zona lumbar. Consiste en flexionar la cadera con las piernas casi rectas, enfatizando el estiramiento y la contracción de la cadena posterior.', '["Párate con los pies al ancho de los hombros, sosteniendo una mancuerna en cada mano con agarre prono.", "Mantén la espalda recta y el abdomen firme mientras flexionas la cadera para bajar las mancuernas hacia el suelo, permitiendo una ligera flexión de las rodillas.", "Baja las mancuernas hasta sentir que se estiran los isquiotibiales y luego aprieta los glúteos y empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0432.gif'),
('0434', 'Peso muerto con mancuernas y piernas rectas', 'dumbbell straight leg deadlift', '["peso muerto de piernas rígidas con mancuernas", "peso muerto para glúteos con mancuernas", "dumbbell straight leg deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza que trabaja los glúteos, los músculos posteriores de los muslos y la zona lumbar. Consiste en flexionar la cadera con la espalda recta para bajar las mancuernas hacia el suelo y luego volver a la posición inicial.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano con agarre prono.", "Mantén la espalda recta y el abdomen firme, flexiona la cadera y baja las mancuernas hacia el suelo mientras inclinas el torso hacia adelante.", "Sigue bajando las mancuernas hasta sentir un estiramiento en la parte posterior de los muslos, con las rodillas ligeramente flexionadas.", "Haz una breve pausa abajo y luego activa los glúteos y los músculos posteriores de los muslos para levantar el torso y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0434.gif'),
('0450', 'Press JM en banco con barra Z', 'ez barbell jm bench press', '["press de tríceps con barra Z", "press JM acostado", "ez barbell jm bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Barra Z', 'Avanzado', 'Fuerza', 'Movimiento de press enfocado en los tríceps que se realiza en un banco con una barra Z. Combina elementos del press de banca con agarre cerrado y la extensión de tríceps, y también involucra el pecho y los hombros.', '["Acuéstate boca arriba en un banco, con los pies bien apoyados en el suelo y la espalda contra el banco.", "Sujeta la barra Z con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Baja la barra hacia el pecho y mantén los codos cerca del cuerpo.", "Empuja la barra hacia arriba hasta volver a la posición inicial y extender completamente los brazos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0450.gif'),
('0471', 'Flexión en parada de manos', 'handstand push-up', '["flexiones verticales contra la pared", "flexiones de pino", "handstand push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros", "Pecho", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal que trabaja los tríceps, los hombros, el pecho y la zona media. Requiere mucha fuerza en el tren superior, equilibrio, coordinación y experiencia con movimientos en posición invertida.', '["Busca una pared y párate de espaldas a ella, a unos pasos de distancia.", "Apoya las manos en el suelo al ancho de los hombros e impulsa los pies hacia arriba hasta apoyarlos contra la pared, quedando en parada de manos.", "Flexiona los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo alineado.", "Empuja el suelo con las manos y extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0471.gif'),
('0490', 'Flexión inclinada con agarre cerrado', 'incline close-grip push-up', '["flexiones cerradas en banco", "flexiones de tríceps con manos elevadas", "incline close-grip push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal enfocado en los tríceps, que también trabaja el pecho y los hombros. Se realiza con las manos sobre una superficie elevada y los codos cerca del cuerpo.', '["Apoya las manos en una superficie elevada, como un banco o escalón, un poco más separadas que el ancho de los hombros.", "Extiende las piernas hacia atrás y apóyate sobre la parte delantera de los pies, formando una línea recta de la cabeza a los talones.", "Flexiona los codos para bajar el pecho hacia la superficie elevada y mantenlos cerca de los costados.", "Haz una breve pausa abajo y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0490.gif'),
('0492', 'Flexión inclinada con salto en profundidad', 'incline push up depth jump', '["flexiones en banco con salto", "flexiones inclinadas con salto desde altura", "incline push up depth jump"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Pliometría', 'Ejercicio dinámico que combina una flexión inclinada con un salto pliométrico en profundidad. Trabaja el pecho, los tríceps, los hombros y la zona media, y requiere fuerza en el tren superior y explosividad en el tren inferior.', '["Busca una superficie elevada, como un banco o escalón, y apoya las manos en el borde al ancho de los hombros.", "Lleva los pies hacia atrás y mantén el cuerpo en línea recta de la cabeza a los talones.", "Flexiona los codos para bajar el pecho hacia el borde de la superficie, manteniendo el cuerpo alineado.", "Empuja con las palmas para extender los brazos y volver a la posición inicial.", "Salta desde el borde de la superficie y aterriza suavemente con las rodillas ligeramente flexionadas.", "Repite la flexión y el salto en profundidad hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0492.gif'),
('0493', 'Flexión inclinada', 'incline push-up', '["flexiones con manos elevadas", "flexiones en banco", "incline push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los pectorales mediante una flexión con las manos apoyadas en una superficie elevada, como un banco o escalón. Esta variante reduce la carga respecto a una flexión convencional, por lo que resulta más accesible para principiantes.', '["Apoya las manos en una superficie elevada, como un banco o escalón, un poco más separadas que el ancho de los hombros.", "Extiende las piernas hacia atrás y apóyate sobre la parte delantera de los pies, formando una línea recta de la cabeza a los talones.", "Flexiona los codos para bajar el pecho hacia la superficie elevada, manteniendo el cuerpo alineado.", "Haz una breve pausa abajo y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0493.gif'),
('0494', 'Flexión inclinada con agarre inverso', 'incline reverse grip push-up', '["flexiones en banco con agarre supino", "flexiones elevadas con manos invertidas", "incline reverse grip push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal para los pectorales, realizado con las manos en una superficie elevada y las palmas orientadas hacia ti, en agarre inverso. Enfatiza la parte superior del pecho y los tríceps, y requiere estabilidad y control.', '["Apoya las manos en el borde de un banco o superficie elevada, un poco más separadas que el ancho de los hombros.", "Extiende las piernas hacia atrás y apóyate sobre la parte delantera de los pies, formando una línea recta de la cabeza a los talones.", "Flexiona los codos para bajar el pecho hacia el banco y mantenlos cerca de los costados.", "Haz una breve pausa abajo y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0494.gif'),
('0513', 'Sentadilla con salto (versión 2)', 'jump squat v. 2', '["sentadilla explosiva variante 2", "sentadilla pliométrica versión 2", "jump squat v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Intermedio', 'Pliometría', 'Ejercicio pliométrico del tren inferior que trabaja los glúteos, los cuádriceps, los músculos posteriores de los muslos y las pantorrillas. Consiste en saltar de forma explosiva desde una sentadilla y aterrizar suavemente antes de repetir.', '["Párate con los pies al ancho de los hombros.", "Baja a una sentadilla flexionando las rodillas y llevando la cadera hacia atrás.", "Salta de forma explosiva y extiende completamente la cadera y las rodillas.", "Aterriza suavemente sobre la parte delantera de los pies y baja de inmediato a otra sentadilla.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0513.gif'),
('0514', 'Sentadilla con salto', 'jump squat', '["sentadilla explosiva", "sentadilla pliométrica", "jump squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Intermedio', 'Pliometría', 'Ejercicio pliométrico enfocado en los glúteos que también trabaja los cuádriceps, los músculos posteriores de los muslos y las pantorrillas. Combina una sentadilla con un salto explosivo para desarrollar potencia y explosividad en el tren inferior.', '["Párate con los pies al ancho de los hombros.", "Baja a una sentadilla flexionando las rodillas y llevando la cadera hacia atrás.", "Salta de forma explosiva y extiende la cadera, las rodillas y los tobillos.", "Mientras estás en el aire, lleva rápidamente los brazos hacia adelante para mantener el equilibrio.", "Aterriza suavemente sobre la parte delantera de los pies y pasa de inmediato a la siguiente repetición.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0514.gif'),
('0571', 'Remo sentado alternado en máquina con agarre cerrado', 'lever alternating narrow grip seated row', '["remo alterno con agarre estrecho", "remo sentado alternando brazos", "lever alternating narrow grip seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Intermedio', 'Fuerza', 'Ejercicio en máquina para la parte superior de la espalda. Consiste en jalar alternadamente cada agarre hacia el torso mientras mantienes una buena postura.', '["Ajusta la altura del asiento y la posición de la plataforma para los pies para quedar bien alineado.", "Siéntate en la máquina con la espalda recta y los pies completamente apoyados en la plataforma.", "Sujeta los agarres con las manos cerca una de la otra y las palmas enfrentadas.", "Mantén el pecho elevado y los hombros hacia atrás durante todo el ejercicio.", "Jala un agarre hacia el torso mientras mantienes el otro inmóvil.", "Junta los omóplatos al final del movimiento.", "Regresa lentamente el agarre a la posición inicial y repite con el otro lado.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0571.gif'),
('0572', 'Dominada asistida en máquina', 'lever assisted chin-up', '["dominadas con asistencia", "dominadas en máquina de ayuda", "lever assisted chin-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que facilita las dominadas mediante asistencia y ayuda a desarrollar fuerza en los dorsales, los bíceps y los antebrazos. Es ideal si todavía no puedes hacer dominadas sin ayuda.', '["Ajusta la máquina al nivel de resistencia deseado.", "Párate sobre la plataforma para los pies y sujeta los agarres con agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Cuélgate con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y sube hacia los agarres, guiando el movimiento con el pecho.", "Sigue subiendo hasta que la barbilla quede por encima de los agarres.", "Haz una breve pausa arriba y luego baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0572.gif'),
('0574', 'Remo inclinado en máquina', 'lever bent over row', '["remo con barra inclinado hacia adelante", "remo de espalda con barra", "lever bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de fuerza con barra que trabaja la parte superior de la espalda. Requiere buena postura, estabilidad de la zona media y una técnica adecuada para evitar lesiones.', '["Párate con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sostén la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta y el pecho elevado.", "Jala la barra hacia la parte baja del pecho y junta los omóplatos.", "Haz una breve pausa arriba y luego baja lentamente la barra a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0574.gif'),
('0578', 'Peso muerto en máquina', 'lever deadlift', '["peso muerto guiado", "peso muerto para glúteos en máquina", "lever deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Cuádriceps"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina enfocado en los glúteos, que también trabaja los músculos posteriores de los muslos y los cuádriceps. La máquina guía el movimiento y aporta estabilidad, lo que lo hace accesible para una amplia variedad de personas.', '["Ajusta la altura del asiento y la plataforma para los pies a la posición deseada.", "Siéntate en la máquina con la espalda contra la almohadilla y los pies completamente apoyados en la plataforma.", "Sujeta los agarres o los lados del asiento para mantener la estabilidad.", "Activa los glúteos y los músculos posteriores de los muslos, y empuja con los talones para levantar el peso.", "Mantén la espalda recta y evita encorvar los hombros.", "Extiende completamente la cadera al final de la subida y aprieta los glúteos.", "Baja el peso de forma controlada, manteniendo la tensión en los glúteos y los músculos posteriores de los muslos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0578.gif'),
('0587', 'Press militar en máquina', 'lever military press', '["press vertical de hombros en máquina", "empuje militar en máquina", "lever military press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Pecho superior"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de hombros en máquina que trabaja principalmente los deltoides y también involucra los tríceps y la parte superior del pecho. La estabilidad de la máquina lo hace adecuado para desarrollar fuerza y técnica.', '["Ajusta la altura del asiento y siéntate en la máquina con la espalda contra el respaldo.", "Sujeta los agarres con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Empuja los agarres hacia arriba hasta extender completamente los brazos, sin bloquear los codos.", "Haz una breve pausa arriba y luego baja lentamente los agarres a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0587.gif'),
('0588', 'Remo sentado en máquina con agarre cerrado', 'lever narrow grip seated row', '["remo en máquina con agarre estrecho", "remo sentado con palmas enfrentadas", "lever narrow grip seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que trabaja la parte superior de la espalda y, de forma secundaria, los bíceps y los antebrazos. Consiste en jalar los agarres hacia el torso desde una posición sentada, concentrándote en juntar los omóplatos.', '["Ajusta la altura del asiento y los apoyos para los pies para mantener una postura correcta.", "Siéntate en la máquina con los pies completamente apoyados y las rodillas ligeramente flexionadas.", "Sujeta los agarres con las manos cerca una de la otra y las palmas enfrentadas.", "Mantén la espalda recta e inclina el torso ligeramente hacia adelante.", "Jala los agarres hacia el torso y junta los omóplatos.", "Haz una breve pausa al final del jalón.", "Deja que los agarres regresen lentamente y vuelve a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0588.gif'),
('0589', 'Remo inclinado a un brazo en máquina', 'lever one arm bent over row', '["remo unilateral con barra", "remo de espalda a una mano con barra", "lever one arm bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio unilateral de espalda con barra que trabaja la parte superior de la espalda, los bíceps y los antebrazos. Requiere mantener estable el torso inclinado mientras jalas el peso con un brazo, lo que exige estabilidad de la zona media y coordinación.', '["Párate con los pies al ancho de los hombros, flexiona ligeramente las rodillas y sostén una barra con agarre prono.", "Inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta y la cabeza levantada.", "Deja que la barra cuelgue frente a ti con los brazos completamente extendidos.", "Jala la barra hacia el pecho y mantén los codos cerca del cuerpo.", "Junta los omóplatos al final de la subida.", "Baja la barra a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0589.gif'),
('0590', 'Press de hombro a un brazo en máquina', 'lever one arm shoulder press', '["press unilateral de hombro en máquina", "empuje de hombro a una mano", "lever one arm shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los deltoides que se realiza con un brazo a la vez, lo que permite concentrar el trabajo muscular y desarrollar fuerza unilateral. También involucra los tríceps y la parte superior de la espalda.', '["Ajusta la altura del asiento y siéntate en la máquina con la espalda contra la almohadilla.", "Sujeta el agarre de la máquina con una mano y coloca el codo en un ángulo de 90 grados.", "Empuja el agarre hacia arriba hasta extender completamente el brazo por encima de la cabeza.", "Haz una breve pausa arriba y luego baja lentamente el agarre a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/0590.gif'),
('0591', 'Fondo de tríceps en máquina con agarre prono', 'lever overhand triceps dip', '["fondos en máquina con agarre por arriba", "fondos de tríceps con agarre prono", "lever overhand triceps dip"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina enfocado en los tríceps, que también trabaja el pecho y los hombros. Consiste en bajar y subir el cuerpo con una máquina que aporta estabilidad y resistencia controlada.', '["Ajusta la máquina a la altura adecuada y acomoda el cuerpo para quedar firme en la posición.", "Sujeta los agarres con agarre prono y coloca el cuerpo con los brazos completamente extendidos.", "Flexiona los codos para bajar el cuerpo, manteniendo la parte superior de los brazos cerca de los costados.", "Sigue bajando hasta que la parte superior de los brazos quede paralela al suelo.", "Haz una breve pausa y luego extiende los codos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0591.gif'),
('0603', 'Press de hombros en máquina', 'lever shoulder press', '["press de deltoides en máquina", "empuje de hombros sentado en máquina", "lever shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Pecho"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que trabaja los deltoides y, de forma secundaria, los tríceps y el pecho. La máquina guía el movimiento para aportar seguridad y estabilidad.', '["Ajusta la altura del asiento y siéntate en la máquina con la espalda contra el respaldo.", "Sujeta los agarres con agarre prono y coloca las manos a la altura de los hombros.", "Empuja los agarres hacia arriba hasta extender completamente los brazos, sin bloquear los codos.", "Haz una breve pausa arriba y luego baja lentamente los agarres a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0603.gif'),
('0627', 'Dominada con agarre mixto', 'mixed grip chin-up', '["dominadas con agarre alterno", "dominadas con agarre combinado", "mixed grip chin-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal enfocado en los dorsales, que también trabaja los bíceps y los antebrazos. Consiste en subir el cuerpo hacia una barra con agarre mixto, lo que exige fuerza de agarre y potencia de jalón en el tren superior.', '["Sujeta la barra de dominadas con agarre supino, con las palmas hacia ti y las manos un poco más separadas que el ancho de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y los pies sin tocar el suelo.", "Activa los músculos de la espalda y sube hacia la barra, guiando el movimiento con el pecho.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente y con control a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0627.gif'),
('0638', 'Dominada a un brazo con agarre supino', 'one arm chin-up', '["dominadas a una mano", "dominada unilateral con palma hacia ti", "one arm chin-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio muy avanzado con peso corporal que trabaja el dorsal ancho y requiere mucha fuerza, coordinación y capacidad de agarre. Consiste en subir el cuerpo hacia una barra con un solo brazo, con la opción de apoyar la otra mano en la muñeca.', '["Párate frente a una barra de dominadas con los pies al ancho de los hombros.", "Levanta un brazo y sujeta la barra con la palma hacia ti; con la otra mano, sujeta la muñeca para darte apoyo.", "Cuélgate con el brazo completamente extendido, el cuerpo recto y el abdomen firme.", "Flexiona el codo y contrae los músculos de la espalda para subir hacia la barra.", "Sigue subiendo hasta que la barbilla quede por encima de la barra y luego baja lentamente a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo y repite."]'::jsonb, '/gifs/0638.gif'),
('0639', 'Fondo a un brazo', 'one arm dip', '["fondos de tríceps a una mano", "fondo unilateral en banco", "one arm dip"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal enfocado en los tríceps, que también trabaja el pecho y los hombros. Requiere mucha fuerza en el tren superior, equilibrio y coordinación para sostener el peso del cuerpo con un brazo mientras realizas el fondo.', '["Párate de espaldas a un banco o silla con los pies al ancho de los hombros.", "Apoya una mano detrás de ti sobre el banco o la silla, con los dedos apuntando hacia el cuerpo.", "Extiende las piernas hacia adelante y mantén los talones apoyados en el suelo.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o la silla.", "Haz una breve pausa abajo y luego empuja con las palmas para extender los brazos y volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de lado y repite con el otro brazo."]'::jsonb, '/gifs/0639.gif'),
('0642', 'Flexión con patada hacia afuera', 'outside leg kick push-up', '["flexiones con patada lateral externa", "flexiones con apertura de pierna", "outside leg kick push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio dinámico con peso corporal que combina una flexión tradicional con una patada lateral. Trabaja los glúteos e involucra los cuádriceps, los músculos posteriores de los muslos y las pantorrillas. Exige fuerza en el tren superior, estabilidad de la zona media, coordinación y movilidad del tren inferior.', '["Colócate en posición de flexión, con las manos un poco más separadas que el ancho de los hombros y los pies juntos.", "Flexiona los codos para bajar el cuerpo hacia el suelo, manteniendo la espalda recta y el abdomen firme.", "Al subir, da una patada hacia un lado con una pierna, extendiéndola por completo y activando los glúteos.", "Regresa la pierna a la posición inicial y repite la flexión, alternando las piernas en cada repetición.", "Sigue alternando las patadas y las flexiones hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0642.gif'),
('0651', 'Dominada (agarre neutro)', 'pull up (neutral grip)', '["dominadas con palmas enfrentadas", "dominadas con agarre paralelo", "pull up (neutral grip)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja el dorsal ancho y también involucra los bíceps y los antebrazos. Se realiza colgándote con las palmas enfrentadas, subiendo hasta que la barbilla pase la barra y bajando con control.', '["Cuélgate de una barra de dominadas con agarre neutro, las palmas enfrentadas y los brazos completamente extendidos.", "Activa el abdomen y junta los omóplatos.", "Flexiona los codos para subir hacia la barra y llévalos hacia abajo, en dirección a la cadera.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente y con control a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0651.gif'),
('0652', 'Dominada', 'pull-up', '["dominadas con agarre prono", "jalón con peso corporal en barra", "pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los dorsales de la espalda y también involucra los bíceps y los antebrazos. Requiere mucha fuerza en el tren superior, coordinación y control, por lo que resulta exigente para muchas personas.', '["Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.", "Activa el abdomen y junta los omóplatos.", "Flexiona los codos para subir el cuerpo y acercar el pecho a la barra.", "Haz una pausa arriba y luego baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0652.gif'),
('0658', 'Flexión (en pared) (versión 2)', 'push-up (wall) v. 2', '["flexiones contra la pared versión 2", "flexiones de pie en pared variante 2", "push-up (wall) v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Variante de la flexión tradicional adecuada para principiantes, realizada de pie contra una pared. Trabaja principalmente los pectorales y también involucra los tríceps y los hombros. Es ideal para quienes empiezan a entrenar fuerza o buscan una alternativa de bajo impacto a las flexiones en el suelo.', '["Párate frente a una pared, aproximadamente a un brazo de distancia.", "Apoya las manos en la pared a la altura de los hombros, un poco más separadas que el ancho de estos.", "Lleva los pies hacia atrás y mantenlos al ancho de la cadera.", "Activa el abdomen y mantén el cuerpo en línea recta de la cabeza a los talones.", "Flexiona los codos y acerca el pecho a la pared, manteniendo el cuerpo recto.", "Haz una breve pausa y luego empuja para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0658.gif'),
('0659', 'Flexión (en pared)', 'push-up (wall)', '["flexiones contra la pared", "flexiones de pie con apoyo en pared", "push-up (wall)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Deltoides"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Variante de la flexión tradicional adecuada para principiantes, realizada de pie contra una pared. Trabaja principalmente los pectorales y también involucra los tríceps y los deltoides. Es ideal para quienes empiezan a entrenar fuerza o necesitan una alternativa de bajo impacto.', '["Párate frente a una pared, aproximadamente a un brazo de distancia.", "Apoya las manos en la pared a la altura de los hombros, un poco más separadas que el ancho de estos.", "Retrocede unos pasos, manteniendo el cuerpo recto y los pies al ancho de la cadera.", "Flexiona los codos y acerca el pecho a la pared, manteniendo el cuerpo alineado.", "Empuja para volver a la posición inicial y extender los brazos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0659.gif'),
('0660', 'Flexión con agarre cerrado sobre mancuernas', 'push-up close-grip off dumbbell', '["flexiones cerradas con mancuernas", "flexiones de tríceps apoyado en mancuernas", "push-up close-grip off dumbbell"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Variante de la flexión enfocada en los tríceps, que también trabaja el pecho y los hombros. Se realiza sujetando mancuernas apoyadas en el suelo, lo que aumenta el recorrido y exige mayor estabilidad.', '["Colócate en posición de flexión con las manos cerca una de la otra, justo debajo de los hombros.", "Sujeta una mancuerna en cada mano y mantenlas apoyadas en el suelo.", "Flexiona los codos para bajar el cuerpo hacia el suelo y mantenlos cerca de los costados.", "Empuja con las palmas para extender los brazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0660.gif'),
('0661', 'Flexión con patada hacia adentro', 'push-up inside leg kick', '["flexiones con patada interna", "flexiones con patada de pierna hacia adentro", "push-up inside leg kick"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio dinámico con peso corporal que combina una flexión convencional con una patada lateral. Trabaja los glúteos e involucra la zona media, los cuádriceps, los músculos posteriores de los muslos y las pantorrillas. Requiere coordinación, equilibrio y fuerza.', '["Colócate en posición de flexión, con las manos un poco más separadas que el ancho de los hombros y los pies juntos.", "Flexiona los codos para bajar el cuerpo hacia el suelo, manteniendo la espalda recta y el abdomen firme.", "Al subir, levanta una pierna del suelo y da una patada hacia un lado, manteniéndola recta.", "Baja la pierna y repite la flexión; luego cambia a la otra pierna.", "Sigue alternando las patadas de pierna en cada repetición de flexión."]'::jsonb, '/gifs/0661.gif'),
('0662', 'Flexión', 'push-up', '["flexiones de pecho", "pechadas", "push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Deltoides", "Core"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio clásico con peso corporal que trabaja los pectorales, los tríceps, los deltoides y la zona media. Consiste en bajar y subir el cuerpo con los brazos mientras mantienes una línea recta de la cabeza a los talones.', '["Colócate en plancha alta, con las manos un poco más separadas que el ancho de los hombros y los pies juntos.", "Activa el abdomen y flexiona los codos para bajar el cuerpo hacia el suelo, manteniéndolo alineado.", "Haz una breve pausa cuando el pecho esté justo por encima del suelo y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0662.gif'),
('0664', 'Flexión con plancha lateral', 'push-up to side plank', '["flexiones con giro lateral", "flexiones combinadas con plancha de lado", "push-up to side plank"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Hombros", "Pecho", "Tríceps"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio compuesto con peso corporal que combina una flexión tradicional con un giro hacia una plancha lateral. Trabaja los abdominales e involucra los hombros, el pecho y los tríceps, además de exigir estabilidad de la zona media y equilibrio.', '["Colócate en posición de flexión, con las manos al ancho de los hombros y el cuerpo alineado.", "Flexiona los codos para bajar el cuerpo hacia el suelo, manteniendo el abdomen firme.", "Empuja para volver a la posición inicial.", "Pasa el peso a la mano izquierda y gira el cuerpo hacia la derecha, levantando el brazo derecho hacia el techo.", "Mantén la plancha lateral durante unos segundos y luego vuelve a la posición inicial.", "Repite la flexión y la plancha lateral hacia el lado contrario.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0664.gif'),
('0666', 'Flexión con un brazo elevado', 'raise single arm push-up', '["flexiones con un brazo extendido al lado", "flexiones con elevación lateral de brazo", "raise single arm push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal que trabaja los pectorales e involucra los tríceps, los hombros y la zona media. Requiere mucha fuerza, equilibrio y coordinación, ya que mantienes un brazo extendido hacia un lado mientras haces la flexión.', '["Colócate en posición de flexión, con las manos un poco más separadas que el ancho de los hombros y los pies juntos.", "Extiende un brazo hacia un lado y mantenlo paralelo al suelo.", "Flexiona los codos para bajar el cuerpo hacia el suelo, manteniendo la espalda recta y el abdomen firme.", "Empuja para volver a la posición inicial, usando los músculos del pecho para levantar el cuerpo.", "Repite con el otro brazo extendido."]'::jsonb, '/gifs/0666.gif'),
('0670', 'Dominada tras nuca', 'rear pull-up', '["dominadas posteriores", "dominadas por detrás de la cabeza", "rear pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal que trabaja el dorsal ancho y también involucra los bíceps y los antebrazos. Consiste en subir el cuerpo hacia una barra con agarre prono, con énfasis en la fuerza y el control de la espalda.', '["Sujeta la barra de dominadas con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y sube hacia la barra, manteniendo los codos cerca del cuerpo.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0670.gif'),
('0672', 'Fondo inverso', 'reverse dip', '["fondos invertidos", "fondos de tríceps en paralelas", "reverse dip"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal enfocado en los tríceps que se realiza entre dos barras paralelas. También involucra el pecho y los hombros.', '["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto.", "Flexiona los codos para bajar el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.", "Haz una breve pausa y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0672.gif'),
('0673', 'Jalón al pecho en máquina con agarre inverso', 'reverse grip machine lat pulldown', '["jalón dorsal en máquina con agarre supino", "jalón al pecho con palmas hacia ti", "reverse grip machine lat pulldown"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio para el dorsal ancho realizado en máquina con agarre supino, que también involucra los bíceps y los antebrazos. Se realiza sentado y con movimientos controlados, concentrándote en jalar los agarres hacia el pecho y juntar los omóplatos.', '["Ajusta la altura del asiento y siéntate en la máquina con las rodillas debajo de las almohadillas y los pies bien apoyados en el suelo.", "Sujeta los agarres con agarre supino y las manos un poco más separadas que el ancho de los hombros.", "Siéntate erguido, con el pecho hacia afuera y los hombros hacia atrás, manteniendo un ligero arco en la zona lumbar.", "Jala los agarres hacia el pecho y junta los omóplatos.", "Haz una breve pausa abajo y luego deja que los agarres regresen lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0673.gif'),
('0674', 'Dominada con agarre inverso', 'reverse grip pull-up', '["dominadas supinas", "dominadas con palmas hacia ti", "reverse grip pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal enfocado en los dorsales. Consiste en subir el cuerpo hacia una barra con agarre supino y también involucra los bíceps y los antebrazos.', '["Sujeta la barra de dominadas con agarre supino y las manos al ancho de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y sube hacia la barra, guiando el movimiento con el pecho.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0674.gif'),
('0677', 'Fondos en anillas', 'ring dips', '["fondos en aros de gimnasia", "fondos de tríceps en anillas", "ring dips"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal realizado en anillas de gimnasia. Trabaja principalmente los tríceps, con una participación importante del pecho y los hombros. La inestabilidad de las anillas exige mucha fuerza, equilibrio y coordinación.', '["Sostén el cuerpo en las anillas con los brazos completamente extendidos y el cuerpo recto.", "Flexiona los codos para bajar el cuerpo hasta que los hombros queden por debajo de los codos.", "Extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0677.gif'),
('0678', 'Dominada estilo Rocky', 'rocky pull-up pulldown', '["dominadas tipo Rocky", "jalón en barra estilo Rocky", "rocky pull-up pulldown"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal enfocado en los dorsales, que también trabaja los bíceps y los antebrazos. Consiste en subir el cuerpo hacia una barra y bajar con control, lo que requiere mucha fuerza en el tren superior y coordinación.', '["Párate frente a una barra de dominadas con los pies al ancho de los hombros.", "Levanta los brazos y sujeta la barra con agarre prono, con las manos un poco más separadas que el ancho de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y sube hacia la barra, guiando el movimiento con el pecho.", "Haz una breve pausa arriba y luego baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0678.gif'),
('0688', 'Dominada escapular', 'scapular pull-up', '["retracciones escapulares en barra", "dominadas de omóplatos", "scapular pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Bíceps", "Romboides", "Deltoides posteriores"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los trapecios y ayuda a mejorar el control de los omóplatos y la estabilidad de los hombros. Se realiza colgándote de una barra y llevando los omóplatos hacia atrás sin flexionar los codos.', '["Cuélgate de una barra de dominadas con las palmas hacia afuera y los brazos completamente extendidos.", "Lleva los omóplatos hacia abajo y hacia atrás.", "Activa los músculos de la espalda y sube el cuerpo hacia la barra, concentrándote en juntar los omóplatos.", "Haz una breve pausa arriba y luego baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0688.gif'),
('0699', 'Flexión con toque de hombro', 'shoulder tap push-up', '["flexiones con toque de hombros alternado", "pechadas con toque al hombro", "shoulder tap push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Core"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que combina una flexión convencional con un toque de hombro alternado al terminar cada subida. Trabaja el pecho, los tríceps y la zona media, y requiere equilibrio y coordinación para estabilizar el cuerpo durante el toque.', '["Colócate en plancha alta, con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta de la cabeza a los talones.", "Flexiona los codos para bajar el cuerpo hacia el suelo y mantenlos cerca de los costados.", "Al subir, levanta la mano derecha del suelo y toca el hombro izquierdo.", "Vuelve a apoyar la mano derecha y repite la flexión; esta vez, levanta la mano izquierda y toca el hombro derecho.", "Sigue alternando los toques de hombro en cada repetición de flexión.", "Mantén estable la zona media y evita girar demasiado la cadera durante todo el ejercicio.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0699.gif'),
('0717', 'Flexión lateral', 'side push-up', '["flexión de costado", "tríceps con peso corporal de lado", "side push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros", "Pecho", "Core"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los tríceps y también involucra los hombros, el pecho y la zona media. Se realiza acostado de lado, elevando el cuerpo con el brazo que queda abajo, lo que exige fuerza y estabilidad.', '["Acuéstate de lado con las piernas extendidas y una sobre la otra.", "Apoya la mano del brazo que queda abajo en el piso, justo debajo del hombro, con los dedos hacia adelante.", "Empuja el piso con esa mano para levantar el cuerpo, manteniendo las piernas rectas y la zona media firme.", "Extiende el brazo de arriba hacia el techo y mantén el cuerpo alineado desde la cabeza hasta los talones.", "Baja el cuerpo con control hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de lado."]'::jsonb, '/gifs/0717.gif'),
('0725', 'Flexión a un brazo', 'single arm push-up', '["flexión con una mano", "pecho a un brazo", "single arm push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal que trabaja los pectorales y también involucra los tríceps, los hombros y la zona media. Requiere mucha fuerza, equilibrio y coordinación, por lo que es adecuado para personas avanzadas.', '["Colócate en posición de flexión con las manos al ancho de los hombros y una de ellas un poco más abierta que la otra.", "Mantén firme la zona media y baja el cuerpo hacia el piso flexionando los codos, sin perder la espalda recta.", "Mientras bajas, pasa el peso hacia un lado y levanta el brazo contrario, extendiéndolo hacia el costado.", "Empuja con el pecho y los tríceps para volver a la posición inicial mientras apoyas de nuevo el brazo extendido.", "Repite el movimiento y alterna el brazo que extiendes en cada repetición."]'::jsonb, '/gifs/0725.gif'),
('0748', 'Press de banca en máquina Smith', 'smith bench press', '["press plano en Smith", "pecho en máquina Smith", "smith bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de pecho en máquina Smith, cuya barra sigue una trayectoria guiada. Trabaja principalmente los pectorales y, de forma secundaria, los tríceps y los hombros. Ofrece más estabilidad que el press de banca con peso libre, lo que facilita su uso a personas con menos experiencia o que buscan una alternativa más segura para levantar cargas pesadas.', '["Ajusta la barra de la máquina Smith a la altura del pecho.", "Acuéstate boca arriba en el banco con los pies bien apoyados en el piso.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Desengancha la barra y bájala hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta volver a la posición inicial y extender por completo los brazos.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0748.gif'),
('0750', 'Sentadilla tipo silla en máquina Smith', 'smith chair squat', '["sentadilla silla en Smith", "sentadilla guiada tipo silla", "smith chair squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith que trabaja principalmente los cuádriceps y también los glúteos, los isquiotibiales y las pantorrillas. La trayectoria guiada aporta estabilidad, lo que resulta útil para aprender la técnica de sentadilla o buscar una alternativa más segura a las sentadillas con peso libre.', '["Ajusta la barra de la máquina Smith a una altura cómoda.", "Colócate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Apoya la barra en la parte alta de la espalda, sobre los trapecios.", "Mantén firme la zona media y el pecho elevado mientras bajas lentamente, flexionando las rodillas y las caderas.", "Baja hasta que los muslos queden paralelos al piso o hasta donde puedas llegar con comodidad.", "Haz una pausa breve y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0750.gif'),
('0751', 'Press de banca con agarre cerrado en máquina Smith', 'smith close-grip bench press', '["press cerrado en Smith", "press de tríceps en Smith", "smith close-grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio compuesto en máquina Smith que trabaja principalmente los tríceps y también el pecho y los hombros. El agarre cerrado aumenta la participación de los tríceps al empujar la barra.', '["Ajusta la altura del asiento y acomódate en el banco con los pies apoyados en el piso.", "Sujeta la barra con agarre cerrado, con las manos un poco más juntas que el ancho de los hombros.", "Baja la barra hacia el pecho manteniendo los codos cerca del cuerpo.", "Haz una pausa breve abajo y luego empuja la barra hacia arriba hasta volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0751.gif'),
('0752', 'Peso muerto en máquina Smith', 'smith deadlift', '["peso muerto en Smith", "peso muerto con barra guiada", "smith deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Cuádriceps", "Zona lumbar"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio compuesto de tren inferior en máquina Smith que trabaja principalmente los glúteos y también los isquiotibiales, los cuádriceps y la zona lumbar. La trayectoria guiada de la barra puede ayudar a mantener la estabilidad y la técnica al aprender el peso muerto.', '["Coloca la barra de la máquina Smith a la altura de las caderas.", "Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Flexiona las caderas y las rodillas, mantén la espalda recta y el pecho elevado, y sujeta la barra con agarre prono un poco más abierto que el ancho de los hombros.", "Mantén firme la zona media y levanta la barra extendiendo las caderas y las rodillas, sin alejarla del cuerpo.", "Termina de enderezarte hasta extender por completo las caderas y las rodillas.", "Baja la barra con control flexionando las caderas y las rodillas, sin perder la espalda recta.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0752.gif'),
('0753', 'Press declinado en máquina Smith', 'smith decline bench press', '["press de banca declinado en Smith", "pecho declinado en Smith", "smith decline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en banco declinado y máquina Smith que trabaja principalmente los pectorales y también los tríceps y los hombros. El movimiento guiado ofrece mayor seguridad y estabilidad que el press declinado con peso libre.', '["Ajusta el banco declinado al ángulo deseado.", "Acuéstate en el banco con los pies asegurados debajo de los rodillos.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Desengancha la barra y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve abajo y luego empuja la barra hacia arriba hasta volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0753.gif'),
('0755', 'Sentadilla hack en máquina Smith', 'smith hack squat', '["sentadilla hack en Smith", "sentadilla hack con barra guiada", "smith hack squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith que trabaja principalmente los glúteos y también los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en hacer una sentadilla con la barra apoyada sobre la parte alta de los trapecios y los hombros, con la estabilidad y el soporte de la máquina.', '["Ajusta la barra de la máquina Smith a una altura adecuada para ti.", "Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Colócate debajo de la barra y apóyala sobre la parte alta de los trapecios y los hombros.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Mantén firme la zona media y el pecho elevado mientras desenganchas la barra.", "Da un paso hacia atrás y coloca los pies un poco más separados que el ancho de los hombros.", "Flexiona las rodillas y baja el cuerpo manteniendo el pecho elevado y la espalda recta.", "Sigue bajando hasta que los muslos queden paralelos al piso o un poco más abajo.", "Haz una pausa breve abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0755.gif'),
('0757', 'Press inclinado en máquina Smith', 'smith incline bench press', '["press de banca inclinado en Smith", "pecho superior en Smith", "smith incline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de pecho en máquina Smith con el banco inclinado de 30 a 45 grados. Trabaja principalmente la parte superior de los pectorales y también los hombros y los tríceps. La estabilidad de la máquina facilita su uso a personas con menos experiencia, aunque requiere buena técnica y control.', '["Ajusta el banco a una inclinación de 30 a 45 grados.", "Siéntate en el banco con la espalda apoyada en el respaldo y los pies firmes en el piso.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Desengancha la barra y bájala lentamente hacia la parte alta del pecho, manteniendo los codos ligeramente hacia adentro.", "Haz una pausa breve abajo y luego empuja la barra hacia arriba hasta volver a la posición inicial y extender por completo los brazos.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0757.gif'),
('0760', 'Prensa de piernas en máquina Smith', 'smith leg press', '["press de piernas en Smith", "prensa de glúteos en Smith", "smith leg press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith que trabaja principalmente los glúteos y también los cuádriceps, los isquiotibiales y las pantorrillas. Se realiza sentado, empujando una plataforma con las piernas mediante la extensión y flexión de las rodillas y las caderas.', '["Ajusta el asiento y la plataforma para los pies de la máquina Smith a una posición cómoda.", "Siéntate con la espalda apoyada en el respaldo y los pies sobre la plataforma, separados al ancho de los hombros.", "Sujeta las agarraderas o los lados de la máquina para mantener la estabilidad.", "Aleja la plataforma extendiendo las piernas y mantén la espalda apoyada en el respaldo.", "Haz una pausa breve con las piernas completamente extendidas.", "Flexiona lentamente las rodillas y deja que la plataforma se acerque a ti hasta volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0760.gif'),
('0765', 'Press de hombros sentado en máquina Smith', 'smith seated shoulder press', '["press militar sentado en Smith", "hombros sentado en Smith", "smith seated shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio en máquina que trabaja los deltoides. Ofrece estabilidad y soporte para desarrollar fuerza en los hombros con menor riesgo de perder el equilibrio. También involucra los tríceps y la parte alta de la espalda.', '["Ajusta la altura del asiento para que las agarraderas queden al nivel de los hombros.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies en el piso.", "Sujeta las agarraderas con agarre prono y sácalas de los soportes, extendiendo por completo los brazos.", "Baja las agarraderas hasta la altura de los hombros, manteniendo los codos ligeramente flexionados.", "Empuja las agarraderas por encima de la cabeza hasta extender por completo los brazos.", "Haz una pausa breve arriba y luego baja lentamente las agarraderas hasta la altura de los hombros.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0765.gif'),
('0766', 'Press de hombros en máquina Smith', 'smith shoulder press', '["press militar en Smith", "press de hombros con barra guiada", "smith shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio compuesto en máquina Smith que trabaja los deltoides. La máquina aporta estabilidad y permite concentrarse en la fuerza de empuje y el desarrollo muscular.', '["Ajusta la altura del asiento y acomódate en la máquina Smith con los pies separados al ancho de los hombros.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra de los soportes y colócala a la altura de los hombros, con los codos flexionados y las palmas hacia adelante.", "Empuja la barra hacia arriba hasta extender por completo los brazos por encima de la cabeza.", "Haz una pausa breve arriba y luego baja lentamente la barra hasta la altura de los hombros.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0766.gif'),
('0768', 'Sentadilla búlgara en máquina Smith', 'smith single leg split squat', '["sentadilla con pie elevado en Smith", "zancada búlgara en Smith", "smith single leg split squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith que trabaja los cuádriceps y también involucra los glúteos y los isquiotibiales. Requiere equilibrio y fuerza unilateral, ya que una pierna se mantiene elevada detrás del cuerpo sobre un banco o escalón.', '["Párate frente a la máquina Smith con los pies al ancho de los hombros.", "Apoya un pie detrás de ti sobre un banco o escalón, con los dedos hacia adelante.", "Sujeta la barra de la máquina Smith para mantener la estabilidad.", "Flexiona la rodilla de adelante y baja el cuerpo a una posición de zancada, manteniendo la espalda recta.", "Haz una pausa breve abajo y luego empuja con el talón de adelante para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de pierna."]'::jsonb, '/gifs/0768.gif'),
('0769', 'Zancada de velocista en máquina Smith', 'smith sprint lunge', '["zancada de corredor en Smith", "zancada con pie sobre la barra", "smith sprint lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Avanzado', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith que trabaja principalmente los glúteos y también los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en llevar un pie hacia atrás, apoyarlo sobre la barra y realizar una zancada, lo que exige equilibrio, fuerza y coordinación.', '["Coloca la barra de la máquina Smith a la altura de las caderas.", "Párate de espaldas a la máquina con los pies al ancho de los hombros.", "Lleva el pie derecho hacia atrás y apoya el empeine sobre la barra.", "Flexiona la rodilla izquierda y baja el cuerpo a una posición de zancada, manteniendo la espalda recta.", "Empuja con el talón izquierdo para volver a la posición inicial.", "Repite del otro lado, llevando el pie izquierdo hacia atrás.", "Sigue alternando los lados hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0769.gif'),
('0770', 'Sentadilla en máquina Smith', 'smith squat', '["sentadilla en Smith", "sentadilla con barra guiada", "smith squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith que trabaja principalmente los glúteos y también los cuádriceps, los isquiotibiales y las pantorrillas. La trayectoria guiada aporta estabilidad para aprender la técnica de sentadilla o concentrarse en la activación muscular sin tener que equilibrar una barra libre.', '["Coloca la barra de la máquina Smith a una altura adecuada para hacer la sentadilla.", "Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Colócate debajo de la barra y apóyala sobre la parte alta de los trapecios y los hombros.", "Sujeta la barra con agarre amplio, con las manos un poco más separadas que el ancho de los hombros.", "Mantén firme la zona media, desengancha la barra y da un paso hacia atrás para dejar libres los soportes.", "Mantén el pecho elevado y la espalda recta, e inicia la sentadilla flexionando las caderas y las rodillas.", "Baja hasta que los muslos queden paralelos al piso o un poco más abajo.", "Haz una pausa breve abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0770.gif'),
('0772', 'Press militar tras nuca de pie en máquina Smith', 'smith standing behind head military press', '["press de hombros tras nuca en Smith", "press detrás de la cabeza en Smith", "smith standing behind head military press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Máquina Smith', 'Avanzado', 'Fuerza', 'Ejercicio de hombros en máquina Smith que trabaja los deltoides. Se realiza de pie, empujando la barra desde detrás de la cabeza hasta llevarla por encima de ella.', '["Ajusta la altura del asiento de la máquina Smith para que la barra quede al nivel de los hombros.", "Párate con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra de los soportes y da un paso hacia atrás, manteniendo una postura estable.", "Coloca la barra detrás de la cabeza, apoyada sobre la parte alta de los trapecios.", "Mantén firme la zona media y el pecho elevado durante todo el ejercicio.", "Empuja la barra por encima de la cabeza hasta extender por completo los brazos.", "Haz una pausa breve arriba y luego baja lentamente la barra hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0772.gif'),
('0774', 'Press militar de pie en máquina Smith', 'smith standing military press', '["press de hombros de pie en Smith", "press vertical de pie con barra guiada", "smith standing military press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja los deltoides y utiliza la máquina Smith para aportar estabilidad. También involucra los tríceps y la parte alta de la espalda. La trayectoria fija puede facilitar el aprendizaje del press por encima de la cabeza, aunque requiere buena movilidad de hombros y estabilidad en la zona media.', '["Párate con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra de los soportes y bájala hasta la altura de los hombros, con las palmas hacia adelante.", "Empuja la barra hacia arriba hasta extender por completo los brazos por encima de la cabeza.", "Haz una pausa breve arriba y luego baja lentamente la barra hasta la altura de los hombros.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0774.gif'),
('0778', 'Flexión araña', 'spider crawl push up', '["flexión con rodilla al codo", "flexión con rodillas alternadas", "spider crawl push up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Core", "Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal que combina una flexión con un movimiento dinámico de rodilla. Trabaja los glúteos, la zona media, el pecho y los hombros, y requiere coordinación, fuerza y estabilidad.', '["Colócate en posición de flexión con las manos un poco más separadas que el ancho de los hombros y los pies juntos.", "Acerca la rodilla derecha al codo derecho sin apoyarla en el piso.", "Mientras llevas la rodilla derecha de regreso, flexiona los codos para bajar el cuerpo hacia el piso.", "Empuja para volver a la posición inicial y repite acercando la rodilla izquierda al codo izquierdo.", "Sigue alternando los lados hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0778.gif'),
('0786', 'Envión con sentadilla', 'squat jerk', '["jerk con sentadilla", "envión con barra y sentadilla", "squat jerk"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Movimiento avanzado de halterofilia que combina una sentadilla y un envión, y requiere potencia explosiva, coordinación y equilibrio. Trabaja principalmente los cuádriceps, con una participación importante de los glúteos, los isquiotibiales, las pantorrillas y la zona media.', '["Comienza con la barra apoyada sobre los hombros y los pies separados al ancho de los hombros.", "Baja a una posición de sentadilla, manteniendo el pecho elevado y las rodillas alineadas con las puntas de los pies.", "Al llegar al fondo de la sentadilla, impúlsate de forma explosiva con las piernas y empuja la barra por encima de la cabeza.", "Cuando la barra llegue a su punto más alto, baja rápidamente a una posición de tijera, con un pie adelante y el otro atrás.", "Recibe la barra por encima de la cabeza con los brazos completamente extendidos y la rodilla de atrás tocando ligeramente el piso.", "Levántate desde la posición de tijera y vuelve a juntar los pies.", "Baja la barra hasta los hombros y repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0786.gif'),
('0803', 'Flexión superman', 'superman push-up', '["flexión con brazo y pierna contrarios", "flexión con extensión alternada", "superman push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Core", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal que trabaja los pectorales y también involucra la zona media y los hombros. Consiste en alternar la extensión de un brazo y la pierna contraria durante la flexión, lo que requiere mucho equilibrio, fuerza y coordinación.', '["Colócate en plancha alta con las manos un poco más separadas que el ancho de los hombros y los pies juntos.", "Mantén firme la zona media y baja el cuerpo hacia el piso con los codos cerca de los costados.", "Mientras bajas, levanta al mismo tiempo el brazo derecho y la pierna izquierda, y extiéndelos.", "Haz una pausa breve en la posición elevada y luego baja el brazo y la pierna mientras empujas para volver a la posición inicial.", "Repite el movimiento levantando esta vez el brazo izquierdo y la pierna derecha.", "Sigue alternando los lados hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0803.gif'),
('0806', 'Flexión en suspensión', 'suspended push-up', '["flexión con correas", "pecho en suspensión", "suspended push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Variante exigente de la flexión tradicional que se realiza con un sistema de entrenamiento en suspensión. La mayor inestabilidad exige más trabajo de la zona media y más fuerza del tren superior.', '["Busca un sistema de entrenamiento en suspensión y ajústalo a una altura adecuada.", "Párate de espaldas al punto de anclaje y sujeta las agarraderas con agarre prono.", "Avanza con los pies e inclina el cuerpo hacia adelante hasta que tu peso quede sostenido por las correas.", "Mantén el cuerpo alineado desde la cabeza hasta los talones y la zona media firme, y baja el pecho hacia las agarraderas.", "Empuja con el pecho y los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0806.gif'),
('0809', 'Sentadilla dividida en suspensión', 'suspended split squat', '["zancada en suspensión", "sentadilla con pie en correa", "suspended split squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio de tren inferior que trabaja principalmente los cuádriceps y también los glúteos, los isquiotibiales y las pantorrillas. Se realiza con peso corporal y un sistema de entrenamiento en suspensión, y requiere equilibrio, fuerza y coordinación.', '["Párate de espaldas a un sistema de entrenamiento en suspensión, con los pies al ancho de los hombros.", "Extiende una pierna hacia adelante y coloca el empeine en el soporte para el pie del sistema de suspensión.", "Flexiona la pierna de apoyo y baja el cuerpo a una posición de zancada, manteniendo el pecho elevado y la rodilla alineada con la punta del pie.", "Empuja con el talón para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de pierna."]'::jsonb, '/gifs/0809.gif'),
('0811', 'Peso muerto con barra hexagonal', 'trap bar deadlift', '["peso muerto con barra trampa", "peso muerto con trap bar", "trap bar deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Cuádriceps", "Zona lumbar"]'::jsonb, 'Barra hexagonal', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de tren inferior que trabaja los glúteos, los isquiotibiales, los cuádriceps y la zona lumbar. La barra hexagonal permite mantener el torso más erguido y puede generar menos exigencia en la zona lumbar que el peso muerto convencional con barra.', '["Párate con los pies al ancho de los hombros y la barra hexagonal en el piso frente a ti.", "Flexiona las caderas y las rodillas para bajar y sujetar las agarraderas de la barra con agarre prono.", "Mantén la espalda recta y el pecho elevado mientras levantas la barra del piso extendiendo las caderas y las rodillas.", "Mientras subes, concéntrate en empujar con los talones y apretar los glúteos al final del movimiento.", "Baja la barra al piso flexionando las caderas y las rodillas, y mantén la espalda recta durante todo el movimiento.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0811.gif'),
('0812', 'Fondo de tríceps (en banco con piernas extendidas)', 'triceps dip (bench leg)', '["fondos en banco con pies en el piso", "tríceps en banco con piernas rectas", "triceps dip (bench leg)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los tríceps y utiliza un banco como apoyo. También involucra el pecho y los hombros. Consiste en bajar y subir el cuerpo con los brazos, manteniendo las piernas extendidas y los pies en el piso.', '["Siéntate en el borde de un banco y sujeta el borde con las manos, con los dedos hacia adelante.", "Avanza con los pies, desliza los glúteos fuera del banco y extiende los brazos.", "Flexiona los codos y baja el cuerpo hacia el piso, manteniendo la espalda cerca del banco.", "Empuja con las palmas para extender los brazos y volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0812.gif'),
('0813', 'Fondo de tríceps (entre bancos)', 'triceps dip (between benches)', '["fondos entre dos bancos", "tríceps entre bancos", "triceps dip (between benches)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja los tríceps. Se realiza sosteniendo el peso con las manos entre dos bancos y bajando y subiendo el cuerpo.', '["Siéntate en un banco y sujeta el borde con las manos, con los dedos hacia adelante.", "Desliza los glúteos fuera del banco y sostén tu peso con las manos.", "Flexiona los codos y baja el cuerpo hacia el piso, manteniendo la espalda cerca del banco.", "Haz una pausa breve abajo y luego empuja para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0813.gif'),
('0814', 'Fondo de tríceps', 'triceps dip', '["fondos en banco", "fondos en silla", "triceps dip"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los tríceps y también involucra el pecho y los hombros. Se realiza con un banco o una silla y consiste en bajar y subir el cuerpo usando los brazos.', '["Siéntate en el borde de un banco o una silla y sujeta el borde con las manos, con los dedos hacia adelante.", "Desliza los glúteos fuera del banco y sostén tu peso con las manos.", "Flexiona los codos y baja el cuerpo hacia el piso, manteniendo la espalda cerca del banco.", "Haz una pausa breve abajo y luego empuja para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0814.gif'),
('0815', 'Fondos de tríceps en el piso', 'triceps dips floor', '["tríceps con apoyo en el suelo", "fondos de brazos en el suelo", "triceps dips floor"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los tríceps y se realiza usando el piso o una superficie estable, como una silla o un banco. También involucra el pecho y los hombros.', '["Siéntate en el borde de una silla o un banco, con las manos junto a las caderas y los dedos hacia adelante.", "Desliza los glúteos fuera de la silla y mantén las piernas extendidas frente a ti.", "Extiende los brazos dejando una ligera flexión en los codos para mantener la tensión en los tríceps y reducirla en las articulaciones.", "Flexiona lentamente los codos para bajar el cuerpo hacia el piso hasta formar un ángulo de unos 90 grados.", "Al llegar abajo, empuja contra la silla para extender los codos y volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0815.gif'),
('0818', 'Jalón al pecho con doble agarre paralelo', 'twin handle parallel grip lat pulldown', '["jalón en polea con agarre neutro", "jalón dorsal con dos agarraderas", "twin handle parallel grip lat pulldown"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Romboides", "Deltoides posteriores"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio en polea que trabaja principalmente los dorsales y también los bíceps, los romboides y los deltoides posteriores. Se realiza sentado, jalando unas agarraderas paralelas hacia el pecho y concentrándose en juntar los omóplatos.', '["Ajusta la altura del asiento y colócate frente a la máquina de poleas.", "Sujeta las agarraderas con agarre prono y las manos separadas al ancho de los hombros.", "Siéntate y coloca los muslos debajo de las almohadillas, con los pies apoyados en el piso.", "Inclínate ligeramente hacia atrás y mantén el pecho elevado, sin alterar la posición natural de la columna.", "Jala las agarraderas hacia la parte alta del pecho y junta los omóplatos.", "Haz una pausa breve abajo y siente la contracción de los dorsales.", "Deja que las agarraderas suban lentamente hasta volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0818.gif'),
('0861', 'Remo sentado en polea', 'cable seated row', '["remo bajo en polea", "remo sentado con cable", "cable seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de fuerza que trabaja principalmente la parte alta de la espalda y también los bíceps y los antebrazos. Se realiza en una máquina de remo en polea, jalando las agarraderas hacia el torso mientras se mantiene la espalda recta y se juntan los omóplatos.', '["Siéntate en la máquina de remo en polea con los pies apoyados en las plataformas y las rodillas ligeramente flexionadas.", "Sujeta las agarraderas con agarre prono, manteniendo la espalda recta y los hombros relajados.", "Jala las agarraderas hacia el cuerpo y junta los omóplatos.", "Haz una pausa breve al terminar de jalar y luego deja que las agarraderas regresen lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0861.gif'),
('0869', 'Press de hombros en máquina (versión 2)', 'lever shoulder press v. 2', '["press de hombros en máquina de palancas", "press sentado para deltoides", "lever shoulder press v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Pecho"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que trabaja principalmente los deltoides y también los tríceps y el pecho. Se realiza sentado, empujando las agarraderas hacia arriba y hacia adelante para trabajar los hombros.', '["Ajusta la altura del asiento y el respaldo de la máquina a una posición cómoda.", "Siéntate con la espalda apoyada en el respaldo y los pies en el piso.", "Sujeta las agarraderas con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Empuja las agarraderas hacia arriba y hacia adelante hasta extender los brazos, sin bloquear los codos.", "Haz una pausa breve arriba y luego baja lentamente las agarraderas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0869.gif'),
('1256', 'Press declinado con barra y agarre invertido', 'barbell reverse grip decline bench press', '["press declinado con agarre supino", "pecho declinado con agarre invertido", "barbell reverse grip decline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio de pecho en banco declinado que se realiza con barra y agarre invertido o supino. Esta variante trabaja la parte baja del pecho y aumenta la participación de los tríceps y los hombros.', '["Acuéstate en un banco declinado con los pies asegurados y la cabeza más baja que las caderas.", "Sujeta la barra con agarre invertido y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra de los soportes y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve abajo y luego empuja la barra hacia arriba hasta volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1256.gif'),
('1257', 'Press inclinado con barra y agarre invertido', 'barbell reverse grip incline bench press', '["press inclinado con agarre supino", "pecho superior con agarre invertido", "barbell reverse grip incline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio de pecho en banco inclinado que se realiza con barra y agarre invertido o supino. Trabaja la parte alta del pecho y también los tríceps y los hombros. Requiere buena técnica y control para realizarlo con seguridad, especialmente por el agarre poco habitual y la posición inclinada.', '["Ajusta el banco a una inclinación de 45 grados.", "Acuéstate en el banco con los pies apoyados en el piso.", "Sujeta la barra con agarre invertido y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra de los soportes y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta volver a la posición inicial y extender por completo los brazos.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1257.gif'),
('1258', 'Press de banca con barra y agarre invertido amplio', 'barbell wide reverse grip bench press', '["press plano con agarre supino amplio", "pecho con barra y agarre invertido abierto", "barbell wide reverse grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio de pecho que trabaja principalmente los pectorales y también los tríceps y los hombros. Consiste en acostarse en un banco y empujar una barra con agarre amplio e invertido o supino.', '["Acuéstate boca arriba en un banco con los pies apoyados en el piso y la espalda contra el banco.", "Sujeta la barra con agarre invertido amplio y las manos un poco más separadas que el ancho de los hombros.", "Saca la barra de los soportes y sostenla justo encima del pecho con los brazos completamente extendidos.", "Baja lentamente la barra hacia el pecho, manteniendo los codos cerca del cuerpo y las muñecas rectas.", "Haz una pausa breve cuando la barra toque el pecho y luego empújala hacia arriba hasta volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1258.gif'),
('1273', 'Flexión con palmada', 'clap push up', '["flexión con aplauso", "flexión explosiva con palmada", "clap push up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Pliometría', 'Ejercicio pliométrico con peso corporal que trabaja los pectorales, los tríceps y los hombros. Consiste en impulsarse de forma explosiva, dar una palmada en el aire y volver a la posición de flexión. Requiere mucha fuerza del tren superior, potencia y coordinación.', '["Colócate en plancha alta con las manos un poco más separadas que el ancho de los hombros.", "Flexiona los codos para bajar el cuerpo hacia el piso y mantén firme la zona media.", "Empuja de forma explosiva con las palmas para despegar el cuerpo del piso.", "Da una palmada en el aire antes de volver a apoyar las manos en la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1273.gif'),
('1275', 'Flexión con caída de rodillas', 'drop push up', '["flexión con apoyo de rodillas al bajar", "flexión con rodillas al piso", "drop push up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los pectorales y también los tríceps y los hombros. Consiste en bajar el pecho desde una posición de plancha, apoyar las rodillas al llegar abajo y luego empujar para subir.', '["Colócate en plancha alta con las manos un poco más separadas que el ancho de los hombros.", "Baja el pecho hacia el piso manteniendo los codos cerca del cuerpo.", "Cuando el pecho quede apenas por encima del piso, baja rápidamente las rodillas hasta apoyarlas.", "Extiende los brazos para empujar el cuerpo hacia arriba y volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1275.gif'),
('1306', 'Flexión pliométrica', 'plyo push up', '["flexión explosiva", "flexión con despegue de manos", "plyo push up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Pliometría', 'Ejercicio explosivo con peso corporal que trabaja los pectorales y también los tríceps, los hombros y la zona media. Consiste en empujar con suficiente fuerza para que las manos se despeguen del piso, lo que exige potencia, coordinación y fuerza del tren superior.', '["Colócate en plancha alta con las manos un poco más separadas que el ancho de los hombros.", "Flexiona los codos para bajar el pecho hacia el piso, manteniendo el cuerpo alineado.", "Empuja de forma explosiva contra el piso y usa los músculos del pecho para impulsar el tren superior y despegarlo.", "Vuelve a apoyar las manos suavemente en la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1306.gif'),
('1308', 'Press de banca con agarre amplio en máquina Smith', 'smith wide grip bench press', '["press plano con agarre abierto en Smith", "pecho con agarre amplio en Smith", "smith wide grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de pecho en máquina Smith con agarre amplio para trabajar los pectorales. También involucra los tríceps y los hombros. La estabilidad de la máquina facilita su uso a personas con menos experiencia, aunque requiere buena técnica y control.', '["Coloca el banco en una posición cómoda dentro de la máquina Smith.", "Acuéstate en el banco con los pies apoyados en el piso.", "Sujeta la barra con agarre amplio y las manos un poco más separadas que el ancho de los hombros.", "Desengancha la barra y bájala lentamente hacia el pecho, manteniendo los codos abiertos hacia los lados.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta volver a la posición inicial y extender por completo los brazos.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1308.gif'),
('1309', 'Press declinado con agarre amplio en máquina Smith', 'smith wide grip decline bench press', '["press declinado con agarre abierto en Smith", "pecho bajo con agarre amplio en Smith", "smith wide grip decline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en máquina Smith con agarre amplio que trabaja la parte baja de los pectorales y también involucra los tríceps y los hombros. El ángulo declinado y el agarre amplio enfatizan el pecho bajo y requieren buen control y técnica.', '["Ajusta el banco declinado al ángulo deseado.", "Acuéstate en el banco con los pies asegurados debajo de los rodillos.", "Sujeta la barra con agarre amplio y las manos un poco más separadas que el ancho de los hombros.", "Desengancha la barra y bájala lentamente hacia el pecho, manteniendo los codos hacia afuera.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta volver a la posición inicial y extender por completo los brazos.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1309.gif'),
('1311', 'Flexión con manos abiertas', 'wide hand push up', '["flexión con apoyo amplio", "flexión con manos separadas", "wide hand push up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja los pectorales al aumentar la separación entre las manos, dando más énfasis al pecho que una flexión convencional. También involucra los tríceps y los hombros.', '["Colócate en plancha alta con las manos más separadas que el ancho de los hombros.", "Mantén el cuerpo alineado desde la cabeza hasta los pies.", "Flexiona los codos para bajar el pecho hacia el piso, manteniéndolos cerca de los costados.", "Empuja con las palmas para extender los brazos y volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1311.gif'),
('1320', 'Remo sentado con cuerdas cruzadas en polea', 'cable rope crossover seated row', '["remo en polea con cuerdas cruzadas", "remo sentado con agarre de cuerdas", "cable rope crossover seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para la parte alta de la espalda que se realiza en una máquina de poleas con accesorios de cuerda. También involucra los bíceps y los antebrazos.', '["Siéntate en la máquina de remo con los pies apoyados en las plataformas y las rodillas ligeramente flexionadas.", "Sujeta las cuerdas de la polea con agarre prono y las palmas enfrentadas.", "Inclínate ligeramente hacia atrás, manteniendo la espalda recta y la zona media firme.", "Jala las cuerdas hacia el pecho y junta los omóplatos.", "Haz una pausa breve al terminar de jalar y luego afloja la tensión lentamente hasta volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/1320.gif'),
('1321', 'Remo sentado en polea con cuerda y asiento elevado', 'cable rope elevated seated row', '["Remo alto sentado con cuerda", "Espalda en polea con asiento elevado", "cable rope elevated seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para la espalda alta que se realiza en un asiento elevado con una polea y una cuerda. Enfatiza la retracción de los omóplatos y el trabajo de la espalda alta, y también activa los bíceps y los antebrazos.', '["Siéntate en el asiento elevado de frente a la máquina de poleas.", "Sujeta los extremos de la cuerda con agarre prono y las palmas enfrentadas.", "Mantén la espalda recta e inclínate ligeramente hacia atrás, con las rodillas un poco flexionadas.", "Jala la cuerda hacia el cuerpo, juntando los omóplatos y contrayendo los músculos de la espalda.", "Haz una breve pausa en la posición de máxima contracción.", "Afloja la tensión lentamente y extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1321.gif'),
('1323', 'Remo sentado en polea con cuerda', 'cable rope seated row', '["Remo bajo con cuerda", "Jalón sentado con cuerda para espalda", "cable rope seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para la espalda alta que se realiza con una cuerda en una máquina de poleas. También trabaja los bíceps y los antebrazos como músculos secundarios.', '["Siéntate en la máquina de remo con los pies bien apoyados en los soportes y las rodillas ligeramente flexionadas.", "Sujeta los extremos de la cuerda con agarre prono y las palmas enfrentadas.", "Mantén la espalda recta e inclínate ligeramente hacia adelante, con los codos un poco flexionados.", "Jala la cuerda hacia el cuerpo, juntando los omóplatos.", "Haz una breve pausa al final del jalón y luego afloja la tensión lentamente para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1323.gif'),
('1326', 'Dominada con agarre supino', 'chin-up', '["Dominada con palmas hacia ti", "Dominada supina", "chin-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja los dorsales, los bíceps y los antebrazos. Consiste en elevar el cuerpo hacia una barra con agarre supino hasta que la barbilla pase por encima de ella.', '["Cuélgate de una barra de dominadas con las palmas hacia ti y las manos separadas al ancho de los hombros.", "Activa el abdomen y eleva el cuerpo hacia la barra, guiando el movimiento con el pecho.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1326.gif'),
('1327', 'Dominada supina con agarre cerrado', 'close grip chin-up', '["Dominada cerrada con palmas hacia ti", "Dominada con agarre supino estrecho", "close grip chin-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal para los dorsales, con una participación importante de los bíceps y los antebrazos. Consiste en elevar el cuerpo hacia una barra con agarre supino cerrado para desarrollar fuerza en el tren superior.', '["Sujeta la barra de dominadas con las palmas hacia ti y las manos separadas al ancho de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y los pies sin tocar el suelo.", "Activa los músculos de la espalda y eleva el cuerpo hacia la barra, manteniendo los codos cerca del torso.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1327.gif'),
('1329', 'Remo inclinado con mancuernas y giro de muñecas', 'dumbbell palm rotational bent over row', '["Remo con mancuernas y rotación de palmas", "Remo inclinado con giro de agarre", "dumbbell palm rotational bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto para la espalda alta que también trabaja los bíceps y los antebrazos. El giro de las palmas añade un desafío de coordinación y aumenta la activación muscular.', '["Párate con los pies separados al ancho de los hombros y una mancuerna en cada mano con agarre prono.", "Inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta y las rodillas ligeramente flexionadas.", "Deja los brazos colgando hacia abajo, con las palmas orientadas hacia el cuerpo.", "Activa el abdomen y jala las mancuernas hacia el pecho, manteniendo los codos cerca del torso.", "Mientras subes las mancuernas, gira las palmas hasta orientarlas hacia afuera.", "Junta los omóplatos en la parte alta del movimiento.", "Baja las mancuernas lentamente y gira las palmas para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1329.gif'),
('1344', 'Remo inclinado con barra Z y agarre supino', 'ez bar reverse grip bent over row', '["Remo con barra Z y agarre inverso", "Remo supino con barra Z", "ez bar reverse grip bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Barra Z', 'Intermedio', 'Fuerza', 'Ejercicio compuesto para la espalda alta que también trabaja los bíceps y los antebrazos. Se realiza con el torso inclinado, jalando una barra Z hacia la parte baja del pecho con agarre supino.', '["Párate con los pies separados al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra Z con agarre supino, las palmas hacia arriba y las manos separadas al ancho de los hombros.", "Inclina el torso hacia adelante desde la cadera hasta dejarlo casi paralelo al suelo, con la espalda recta y el pecho elevado.", "Jala la barra Z hacia la parte baja del pecho, juntando los omóplatos.", "Haz una breve pausa arriba y luego baja la barra Z lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1344.gif'),
('1350', 'Remo sentado en máquina', 'lever seated row', '["Remo con apoyo de pecho", "Espalda en máquina de remo", "lever seated row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para la espalda alta. Consiste en jalar las agarraderas hacia el torso mientras estás sentado, concentrándote en juntar los omóplatos.', '["Ajusta la altura del asiento y los soportes para los pies a una posición cómoda.", "Siéntate en la máquina con el pecho contra la almohadilla y los pies sobre los soportes.", "Sujeta las agarraderas con agarre prono y las manos separadas al ancho de los hombros.", "Mantén la espalda recta y el abdomen firme.", "Jala las agarraderas hacia el cuerpo, juntando los omóplatos.", "Haz una breve pausa al final del jalón.", "Deja que las agarraderas regresen lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1350.gif'),
('1359', 'Remo inclinado en máquina Smith', 'smith bent over row', '["Remo con barra guiada", "Remo para espalda en Smith", "smith bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio compuesto en máquina Smith que trabaja la espalda alta, los bíceps y los antebrazos. Consiste en inclinar el torso desde la cadera, mantener la espalda recta y jalar la barra hacia la parte baja del pecho.', '["Coloca la barra de la máquina Smith a la altura de la cadera.", "Párate frente a la barra con los pies separados al ancho de los hombros.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Jala la barra hacia la parte baja del pecho, juntando los omóplatos.", "Haz una breve pausa arriba y luego baja la barra lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1359.gif'),
('1361', 'Remo inclinado en máquina Smith con agarre supino', 'smith reverse grip bent over row', '["Remo en Smith con agarre inverso", "Remo supino con barra guiada", "smith reverse grip bent over row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio compuesto en máquina Smith para la espalda alta. Se realiza con el torso inclinado, jalando la barra con agarre supino para trabajar la espalda alta, los bíceps y los antebrazos.', '["Coloca la barra de la máquina Smith a la altura de la cadera.", "Párate frente a la barra con los pies separados al ancho de los hombros.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta.", "Sujeta la barra con agarre supino y las manos separadas al ancho de los hombros.", "Jala la barra hacia la parte baja del pecho, juntando los omóplatos.", "Haz una breve pausa arriba y luego baja la barra lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1361.gif'),
('1367', 'Dominada tras nuca con agarre amplio', 'wide grip rear pull-up', '["Dominada posterior abierta", "Dominada detrás de la cabeza", "wide grip rear pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal para los dorsales que también activa los bíceps y los antebrazos. Consiste en elevar el cuerpo hacia una barra con agarre prono amplio, con énfasis en el desarrollo de la espalda alta.', '["Sujeta la barra de dominadas con agarre prono amplio y las manos un poco más separadas que el ancho de los hombros.", "Cuélgate de la barra con los brazos completamente extendidos y el cuerpo recto.", "Activa los músculos de la espalda y eleva el cuerpo hacia la barra, guiando el movimiento con el pecho.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1367.gif'),
('1385', 'Elevación de talones sentado en prensa', 'lever seated squat calf raise on leg press machine', '["Pantorrillas en prensa de piernas", "Extensión de tobillos en prensa", "lever seated squat calf raise on leg press machine"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Cuádriceps", "Isquiotibiales", "Glúteos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para las pantorrillas que se realiza sentado en una prensa de piernas, flexionando y extendiendo los tobillos.', '["Ajusta el asiento de la prensa de piernas para que las rodillas queden ligeramente flexionadas al apoyar los pies en la plataforma.", "Siéntate con la espalda contra el respaldo y los pies completamente apoyados en la plataforma, separados al ancho de los hombros.", "Apoya los dedos y la parte delantera de los pies en la plataforma, dejando los talones fuera del borde.", "Libera los seguros y aleja la plataforma extendiendo las rodillas.", "Una vez que tengas las rodillas completamente extendidas, baja lentamente los talones para estirar las pantorrillas.", "Haz una breve pausa abajo y luego empuja la plataforma de nuevo, elevando los talones al contraer las pantorrillas.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1385.gif'),
('1399', 'Fondo en banco con pies en el suelo', 'bench dip on floor', '["Fondos de tríceps en banco", "Fondos en silla", "bench dip on floor"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para los tríceps que también activa el pecho y los hombros. Consiste en apoyar las manos en el borde de un banco o una silla, bajar el cuerpo flexionando los codos y luego empujar para subir.', '["Siéntate en el borde de un banco o una silla y sujeta el borde con las manos, con los dedos hacia adelante.", "Desliza los glúteos fuera del banco y sostén tu peso con las manos.", "Baja el cuerpo flexionando los codos hasta que la parte superior de los brazos quede paralela al suelo.", "Extiende los brazos para elevar el cuerpo y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1399.gif'),
('1410', 'Zancada lateral con barra', 'barbell lateral lunge', '["Desplante lateral con barra", "Estocada al lado con barra", "barbell lateral lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de tren inferior para los glúteos que también trabaja los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en dar un paso lateral con una barra sobre la espalda alta y requiere fuerza, equilibrio y coordinación.', '["Párate con los pies separados al ancho de los hombros y una barra apoyada sobre la parte alta de la espalda.", "Da un paso amplio hacia un lado con el pie derecho, manteniendo el izquierdo apoyado en su lugar.", "Flexiona la rodilla derecha y baja el cuerpo a una posición de zancada, manteniendo la pierna izquierda recta.", "Empuja con el pie derecho para volver a la posición inicial.", "Repite del otro lado, dando el paso con el pie izquierdo."]'::jsonb, '/gifs/1410.gif'),
('1420', 'Sentadilla con salto desde rodillas con barra', 'kneeling jump squat', '["Salto desde rodillas con barra", "Sentadilla explosiva desde rodillas", "kneeling jump squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Avanzado', 'Pliometría', 'Ejercicio dinámico de tren inferior para los glúteos que también trabaja los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en saltar de forma explosiva desde una posición de rodillas con una barra sobre la espalda alta.', '["Comienza de rodillas en el suelo, con los pies separados al ancho de las caderas y los dedos hacia adelante.", "Sostén una barra sobre la parte alta de la espalda, apoyada en los hombros.", "Activa el abdomen y los glúteos, y salta de forma explosiva extendiendo las caderas y las rodillas.", "Al saltar, impúlsate con los dedos de los pies y extiende por completo los tobillos, las rodillas y las caderas.", "Aterriza suavemente y flexiona las rodillas para absorber el impacto.", "Pasa de inmediato a la siguiente repetición y repite el movimiento de sentadilla con salto."]'::jsonb, '/gifs/1420.gif'),
('1421', 'Flexión modificada bajando a los antebrazos', 'modified push up to lower arms', '["Flexión con descenso a antebrazos", "Flexión de manos a antebrazos", "modified push up to lower arms"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Tríceps", "Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal para los antebrazos que también trabaja los tríceps, el pecho y los hombros. Consiste en pasar de una posición de flexión al apoyo sobre los antebrazos y luego empujar para volver a subir.', '["Comienza en posición de flexión, con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Baja el cuerpo hacia el suelo flexionando los codos y manteniéndolos cerca de los costados.", "Cuando los codos formen un ángulo de 90 grados, apoya los antebrazos en el suelo, con los codos justo debajo de los hombros.", "Haz una breve pausa y luego empuja con las palmas para levantar los antebrazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1421.gif'),
('1429', 'Dominada con agarre amplio', 'wide grip pull-up', '["Dominada abierta", "Dominada con agarre prono ancho", "wide grip pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal para los dorsales, con una participación importante de los bíceps y los antebrazos. Consiste en colgarse con un agarre más amplio que los hombros, elevar la barbilla por encima de la barra y bajar de forma controlada.', '["Cuélgate de una barra de dominadas con las palmas hacia afuera y las manos más separadas que el ancho de los hombros.", "Activa el abdomen y junta los omóplatos.", "Eleva el cuerpo hacia la barra hasta que la barbilla quede por encima de ella.", "Baja de forma controlada hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1429.gif'),
('1430', 'Fondo para pecho (en estación de fondos y dominadas)', 'chest dip (on dip-pull-up cage)', '["Fondos pectorales en paralelas", "Pecho en barras paralelas", "chest dip (on dip-pull-up cage)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal para los pectorales que también trabaja los tríceps y los hombros. Consiste en sostener el cuerpo sobre barras paralelas, bajar flexionando los codos y luego empujar para subir.', '["Ajusta las barras de fondos a una altura que te permita sujetarlas cómodamente.", "Párate entre las barras y coloca una mano en cada una, con una separación un poco mayor que el ancho de los hombros.", "Da un salto y extiende los brazos para sostener tu peso sobre las barras.", "Flexiona las rodillas y cruza los tobillos detrás de ti.", "Baja el cuerpo flexionando los codos, con el pecho elevado y los hombros abajo.", "Sigue bajando hasta que los hombros queden por debajo de los codos o hasta que sientas un estiramiento en el pecho.", "Empuja con las palmas y extiende los codos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1430.gif'),
('1431', 'Dominada supina asistida de pie en máquina', 'assisted standing chin-up', '["Dominada supina con asistencia de pie", "Dominada con apoyo para los pies en máquina", "assisted standing chin-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que facilita las dominadas con apoyo adicional para desarrollar fuerza en los dorsales, los bíceps y los antebrazos. La máquina reduce el peso corporal que debes levantar, lo que permite mantener una buena técnica y progresar gradualmente.', '["Ajusta la máquina al nivel de asistencia que quieras usar.", "Párate sobre la plataforma y sujeta las agarraderas con agarre prono y una separación un poco mayor que el ancho de los hombros.", "Mantén el pecho elevado y los hombros hacia atrás, activa el abdomen y flexiona ligeramente las rodillas.", "Eleva el cuerpo flexionando los codos y llevándolos hacia abajo, junto a los costados.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1431.gif'),
('1432', 'Dominada prona asistida de pie en máquina', 'assisted standing pull-up', '["Dominada con asistencia de pie", "Dominada prona con apoyo en máquina", "assisted standing pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los dorsales que ofrece asistencia para realizar dominadas. Es adecuado para quienes están desarrollando la fuerza necesaria para hacerlas sin ayuda.', '["Ajusta el peso y la altura de la máquina según lo que necesites.", "Párate de frente a la máquina con los pies separados al ancho de los hombros.", "Sujeta las agarraderas con agarre prono y una separación un poco mayor que el ancho de los hombros.", "Activa los dorsales y los bíceps, y eleva el cuerpo hacia las agarraderas.", "Haz una breve pausa arriba, contrayendo los músculos de la espalda.", "Baja lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1432.gif'),
('1433', 'Sentadilla frontal en máquina Smith (agarre de cargada)', 'smith front squat (clean grip)', '["Sentadilla frontal en Smith con agarre de cargada", "Sentadilla con barra guiada al frente", "smith front squat (clean grip)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith para los glúteos, con una participación importante de los cuádriceps, los isquiotibiales, las pantorrillas y la zona media. El agarre de cargada requiere buena movilidad de hombros y muñecas, y el movimiento exige una técnica adecuada para mantener el equilibrio y la seguridad.', '["Coloca la barra de la máquina Smith a la altura de los hombros.", "Párate frente a la barra con los pies separados al ancho de los hombros.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Da un paso atrás y acomoda la barra sobre la parte delantera de los hombros, apoyándola en las clavículas y los deltoides.", "Mantén el pecho elevado, la espalda recta y el abdomen firme.", "Baja el cuerpo flexionando las rodillas y las caderas, como si fueras a sentarte en una silla.", "Sigue bajando hasta que los muslos queden paralelos al suelo o un poco más abajo.", "Haz una breve pausa y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1433.gif'),
('1434', 'Sentadilla con barra baja en máquina Smith', 'smith low bar squat', '["Sentadilla en Smith con barra baja", "Sentadilla de barra baja guiada", "smith low bar squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de tren inferior en máquina Smith que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, los isquiotibiales y las pantorrillas. La máquina aporta estabilidad, lo que facilita aprender la mecánica de la sentadilla sin dejar de ofrecer un trabajo de fuerza exigente.', '["Coloca la barra de la máquina Smith a una altura que te permita apoyarla cómodamente sobre la parte alta de la espalda.", "Párate con los pies separados al ancho de los hombros y las puntas ligeramente hacia afuera.", "Colócate debajo de la barra y apóyala sobre la parte alta de la espalda, en los trapecios.", "Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.", "Saca la barra de los soportes extendiendo las piernas y dando un paso atrás para alejarte de la estructura.", "Respira profundamente y contrae el abdomen.", "Inicia la sentadilla llevando las caderas hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo o un poco más abajo.", "Mantén el pecho elevado y la espalda recta durante todo el movimiento.", "Empuja con los talones para ponerte de pie, extendiendo las caderas y las rodillas.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1434.gif'),
('1435', 'Sentadilla con barra baja', 'barbell low bar squat', '["Sentadilla con barra sobre deltoides posteriores", "Sentadilla trasera de barra baja", "barbell low bar squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de tren inferior para los glúteos, con una participación importante de los cuádriceps, los isquiotibiales y las pantorrillas. Se realiza con la barra en una posición más baja sobre la espalda, apoyada en los deltoides posteriores, y requiere buena técnica, estabilidad de la zona media y movilidad de cadera.', '["Párate con los pies separados al ancho de los hombros y la barra apoyada sobre la parte alta de la espalda.", "Mantén el pecho elevado y el abdomen firme mientras bajas lentamente, flexionando las rodillas y llevando las caderas hacia atrás.", "Sigue bajando hasta que los muslos queden paralelos al suelo o un poco más abajo.", "Haz una breve pausa y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1435.gif'),
('1436', 'Sentadilla con barra alta', 'barbell high bar squat', '["Sentadilla con barra sobre trapecios", "Sentadilla trasera de barra alta", "barbell high bar squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de tren inferior que trabaja principalmente los glúteos, con una participación importante de los cuádriceps, los isquiotibiales, las pantorrillas y la zona media. Consiste en hacer una sentadilla con la barra apoyada en los trapecios.', '["Párate con los pies separados al ancho de los hombros y las puntas ligeramente hacia afuera.", "Coloca la barra sobre la parte alta de la espalda, apoyada en los trapecios.", "Activa el abdomen y mantén el pecho elevado mientras comienzas a bajar, llevando las caderas hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.", "Empuja con los talones para ponerte de pie, extendiendo las caderas y las rodillas.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1436.gif'),
('1451', 'Fondo sentado en máquina', 'lever seated dip', '["Fondos de tríceps en máquina", "Empuje de tríceps sentado en máquina", "lever seated dip"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los tríceps que también trabaja el pecho y los hombros. Consiste en empujar las agarraderas hacia abajo mientras estás sentado, simulando el movimiento de un fondo de forma controlada.', '["Ajusta la altura del asiento para que los pies queden completamente apoyados en el suelo y las rodillas formen un ángulo de 90 grados.", "Sujeta las agarraderas de la máquina con las palmas hacia abajo y los brazos completamente extendidos.", "Baja el cuerpo lentamente flexionando los codos hasta que la parte superior de los brazos quede paralela al suelo.", "Haz una breve pausa y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1451.gif'),
('1456', 'Press militar de pie con barra y agarre cerrado', 'barbell standing close grip military press', '["Press de hombros con barra y agarre estrecho", "Press militar cerrado de pie", "barbell standing close grip military press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de fuerza para los deltoides que también trabaja los tríceps y la espalda alta. Consiste en empujar una barra desde los hombros por encima de la cabeza con agarre cerrado y requiere estabilidad de la zona media y fuerza en los hombros.', '["Párate con los pies separados al ancho de los hombros y sujeta la barra con agarre prono, con las manos un poco más juntas que el ancho de los hombros.", "Lleva la barra a la altura de los hombros, manteniendo los codos cerca del cuerpo.", "Empuja la barra por encima de la cabeza hasta extender completamente los brazos.", "Baja la barra de nuevo hasta la altura de los hombros.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1456.gif'),
('1457', 'Press militar de pie con barra y agarre amplio', 'barbell standing wide military press', '["Press de hombros con barra y agarre ancho", "Press militar abierto de pie", "barbell standing wide military press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto para los deltoides que también activa los tríceps y la espalda alta. Se realiza de pie, empujando una barra desde los hombros por encima de la cabeza con un agarre más amplio que el ancho de los hombros.', '["Párate con los pies separados al ancho de los hombros y sujeta la barra con agarre prono, un poco más amplio que el ancho de los hombros.", "Lleva la barra a la altura de los hombros, manteniendo los codos ligeramente por delante de ella.", "Empuja la barra por encima de la cabeza hasta extender completamente los brazos.", "Baja la barra de nuevo hasta la altura de los hombros y repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1457.gif'),
('1459', 'Peso muerto rumano con mancuernas', 'dumbbell romanian deadlift', '["Peso muerto con mancuernas estilo rumano", "Bisagra de cadera con mancuernas", "dumbbell romanian deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los glúteos, los isquiotibiales y la espalda baja. Consiste en hacer una bisagra de cadera con mancuernas, con énfasis en el desarrollo de la cadena posterior y la mecánica de este movimiento.', '["Párate con los pies separados al ancho de los hombros y una mancuerna en cada mano con agarre prono.", "Mantén la espalda recta y el abdomen firme mientras llevas las caderas hacia atrás y bajas las mancuernas hacia el suelo, dejando que las rodillas se flexionen ligeramente.", "Baja las mancuernas hasta sentir un estiramiento en los isquiotibiales; luego empuja con los talones y activa los glúteos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1459.gif'),
('1460', 'Zancada caminando', 'walking lunge', '["Desplantes caminando", "Zancadas con desplazamiento", "walking lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal para los glúteos que también activa los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en avanzar haciendo zancadas alternadas y requiere equilibrio, coordinación y fuerza en el tren inferior.', '["Párate con los pies separados al ancho de los hombros.", "Da un paso hacia adelante con la pierna derecha y baja el cuerpo a una posición de zancada.", "Mantén el torso erguido y la rodilla delantera alineada con el tobillo.", "Impúlsate con el pie derecho y lleva el izquierdo hacia adelante para hacer una zancada con la pierna izquierda.", "Sigue alternando las piernas y avanzando a un ritmo constante y controlado.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1460.gif'),
('1461', 'Sentadilla completa con barra (vista desde atrás)', 'barbell full squat (back pov)', '["Sentadilla profunda con barra vista posterior", "Sentadilla trasera completa vista de espalda", "barbell full squat (back pov)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de tren inferior, mostrado desde atrás, que trabaja los glúteos, los cuádriceps, los isquiotibiales, las pantorrillas y la zona media. Consiste en hacer una sentadilla profunda con una barra sobre la espalda alta y requiere fuerza, equilibrio y buena técnica.', '["Párate con los pies separados al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra sobre la parte alta de la espalda, apoyada en los trapecios o los deltoides posteriores.", "Activa el abdomen y mantén el pecho elevado mientras comienzas a bajar.", "Flexiona las rodillas y las caderas, llevando las caderas hacia atrás y abajo como si fueras a sentarte en una silla.", "Baja hasta que los muslos queden paralelos al suelo o un poco más abajo.", "Mantén las rodillas alineadas con las puntas de los pies y el peso sobre los talones.", "Empuja con los talones para ponerte de pie, extendiendo las caderas y las rodillas.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1461.gif'),
('1462', 'Sentadilla completa con barra (vista lateral)', 'barbell full squat (side pov)', '["Sentadilla profunda con barra vista de lado", "Sentadilla trasera completa de perfil", "barbell full squat (side pov)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto de tren inferior, mostrado de lado, que trabaja los glúteos, los cuádriceps y los isquiotibiales, mientras las pantorrillas y la zona media aportan estabilidad. Consiste en bajar con una barra sobre la espalda alta y luego impulsarte para volver a estar de pie.', '["Párate con los pies separados al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra sobre la parte alta de la espalda, apoyada en los trapecios o los deltoides posteriores.", "Activa el abdomen y mantén el pecho elevado mientras comienzas a bajar.", "Flexiona las rodillas y las caderas, llevando las caderas hacia atrás y abajo como si fueras a sentarte en una silla.", "Baja hasta que los muslos queden paralelos al suelo o un poco más abajo.", "Mantén las rodillas alineadas con las puntas de los pies y el peso sobre los talones.", "Empuja con los talones para ponerte de pie, extendiendo las caderas y las rodillas.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1462.gif'),
('1467', 'Flexión sobre antebrazos', 'push-up on lower arms', '["Flexión de tríceps en antebrazos", "Flexión desde plancha de antebrazos", "push-up on lower arms"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal para los tríceps que se realiza desde una plancha sobre los antebrazos. También activa el pecho y los hombros.', '["Comienza en posición de plancha con los antebrazos en el suelo y los codos justo debajo de los hombros.", "Activa el abdomen y mantén el cuerpo en línea recta de la cabeza a los pies.", "Baja el pecho hacia el suelo flexionando los codos y manteniéndolos cerca del cuerpo.", "Haz una breve pausa abajo y luego empuja para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1467.gif'),
('1476', 'Sentadilla a una pierna', 'one leg squat', '["Sentadilla pistola", "Sentadilla unilateral con pierna al frente", "one leg squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'También conocida como sentadilla pistola, es un ejercicio exigente de tren inferior para los glúteos que también activa los cuádriceps, los isquiotibiales y las pantorrillas. Requiere mucho equilibrio, fuerza y coordinación para bajar sobre una pierna mientras mantienes la otra extendida sin tocar el suelo.', '["Párate con los pies separados al ancho de los hombros.", "Extiende una pierna hacia adelante y mantenla sin tocar el suelo.", "Flexiona la pierna de apoyo y baja el cuerpo como si fueras a sentarte en una silla.", "Mantén el pecho elevado y la espalda recta.", "Empuja con el talón para volver a la posición inicial.", "Repite con la otra pierna."]'::jsonb, '/gifs/1476.gif'),
('1489', 'Sentadilla sissy', 'sissy squat', '["Sentadilla con inclinación hacia atrás", "Sentadilla de cuádriceps con peso corporal", "sissy squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Pantorrillas", "Glúteos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal para los cuádriceps que requiere una flexión profunda de rodillas y mucho equilibrio, y suele realizarse con poco apoyo. Enfatiza la fuerza y el control de los cuádriceps, y también activa las pantorrillas y los glúteos.', '["Párate con los pies separados al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sujétate de un objeto estable si necesitas ayuda para mantener el equilibrio.", "Baja lentamente flexionando las rodillas e inclinándote hacia atrás, manteniendo el torso erguido.", "Sigue bajando hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.", "Haz una breve pausa y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1489.gif'),
('1545', 'Sentadilla Zercher completa con barra', 'barbell full zercher squat', '["Sentadilla con barra en el pliegue de los codos", "Sentadilla profunda Zercher", "barbell full zercher squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas", "Core"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio compuesto de tren inferior en el que sostienes la barra en los pliegues de los codos. Trabaja los glúteos, los cuádriceps, los isquiotibiales, las pantorrillas y la zona media. La posición de la barra exige mucha fuerza y estabilidad de la zona media.', '["Párate con los pies separados al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sostén la barra en los pliegues de los codos y sujétala con las manos para darle estabilidad.", "Activa el abdomen y mantén el pecho elevado mientras llevas las caderas hacia atrás y abajo para hacer la sentadilla.", "Mantén las rodillas alineadas con las puntas de los pies y el peso sobre los talones.", "Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.", "Empuja con los talones para ponerte de pie y contrae los glúteos al terminar de subir.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1545.gif'),
('1623', 'Press inclinado con mancuernas y agarre neutro', 'dumbbell palms in incline bench press', '["Press inclinado con palmas enfrentadas", "Press de pecho inclinado con agarre neutro", "dumbbell palms in incline bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los tríceps que también trabaja el pecho y los hombros. Se realiza en un banco inclinado con mancuernas y las palmas hacia adentro para mantener los codos cerca del cuerpo, lo que aumenta la activación de los tríceps.', '["Ajusta un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con la espalda contra el respaldo y los pies completamente apoyados en el suelo.", "Sostén una mancuerna en cada mano con agarre prono y las palmas hacia adentro.", "Extiende los brazos hacia arriba, sobre el pecho, dejando los codos ligeramente flexionados.", "Baja las mancuernas lentamente hacia los hombros, manteniendo los codos cerca del cuerpo.", "Haz una breve pausa abajo y luego empuja las mancuernas hacia arriba para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1623.gif'),
('1624', 'Press de banca inverso con mancuernas', 'dumbbell reverse bench press', '["Press plano inverso con mancuernas", "Press de pecho inverso con mancuernas", "dumbbell reverse bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que se realiza acostado en un banco, empujando mancuernas hacia arriba con agarre prono. Trabaja los pectorales y también activa los tríceps y los hombros.', '["Acuéstate boca arriba en un banco plano, con los pies completamente apoyados en el suelo y las rodillas flexionadas.", "Sostén una mancuerna en cada mano con agarre prono y las palmas orientadas hacia los pies.", "Extiende los brazos hacia el techo, dejando los codos ligeramente flexionados.", "Baja las mancuernas lentamente hacia el pecho, dejando que los codos se abran hacia los lados.", "Haz una breve pausa abajo y luego empuja las mancuernas hacia arriba para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1624.gif'),
('1625', 'Press declinado con agarre cerrado en máquina Smith', 'smith machine decline close grip bench press', '["Press cerrado declinado en Smith", "Press de tríceps en banco declinado con barra guiada", "smith machine decline close grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio compuesto para los tríceps que también trabaja el pecho y los hombros. Se realiza en una máquina Smith con un banco declinado y un agarre cerrado en la barra.', '["Coloca el banco de la máquina Smith en posición declinada.", "Acuéstate en el banco con los pies firmemente apoyados en el suelo.", "Sujeta la barra con agarre cerrado, con las manos un poco más juntas que el ancho de los hombros.", "Saca la barra de los soportes y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una breve pausa cuando la barra quede justo encima del pecho.", "Empuja la barra hacia arriba hasta extender completamente los brazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1625.gif'),
('1626', 'Press declinado inverso con agarre cerrado en máquina Smith', 'smith machine reverse decline close grip bench press', '["Press inverso cerrado declinado en Smith", "Press de pecho declinado inverso con barra guiada", "smith machine reverse decline close grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Máquina Smith', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que se realiza en una máquina Smith en posición declinada. Trabaja los pectorales con agarre cerrado y también activa los tríceps y los hombros. El ángulo declinado y el agarre cerrado requieren buena técnica y control.', '["Ajusta la máquina Smith para trabajar en posición declinada.", "Acuéstate en el banco con los pies sujetos debajo de las almohadillas.", "Sujeta la barra con agarre cerrado, con las manos un poco más juntas que el ancho de los hombros.", "Saca la barra de los soportes y bájala lentamente hacia el pecho, manteniendo los codos pegados al cuerpo.", "Haz una breve pausa abajo y luego empuja la barra hacia arriba para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1626.gif'),
('1644', 'Curl en polea con sentadilla', 'cable squatting curl', '["Sentadilla con curl de bíceps en polea", "Curl de bíceps en cuclillas con polea", "cable squatting curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que combina una sentadilla con un curl de bíceps en polea. Trabaja los bíceps y los antebrazos, mientras el tren inferior y la zona media aportan estabilidad.', '["Coloca una agarradera en la posición más baja de la máquina de poleas.", "Párate de frente a la máquina con los pies separados al ancho de los hombros.", "Sujeta la agarradera con agarre supino, las palmas hacia arriba y los brazos completamente extendidos.", "Baja a una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.", "Mientras bajas en la sentadilla, flexiona los codos para llevar la agarradera hacia los hombros, manteniéndolos cerca de los costados.", "Haz una breve pausa en la parte alta del curl y contrae los bíceps.", "Baja la agarradera lentamente hasta volver a la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1644.gif'),
('1651', 'Zancada con curl de bíceps y giro de boliche con mancuernas', 'dumbbell bicep curl lunge with bowling motion', '["Desplante con curl y giro de torso", "Curl con mancuernas y zancada estilo boliche", "dumbbell bicep curl lunge with bowling motion"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos", "Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que combina una zancada hacia adelante, un curl de bíceps y un giro de torso que imita un lanzamiento de boliche. Trabaja los bíceps y también activa los antebrazos, los hombros, la zona media y las piernas para mantener la estabilidad y la coordinación.', '["Párate con los pies separados al ancho de los hombros y una mancuerna en cada mano, con las palmas hacia adelante.", "Da un paso hacia adelante con el pie derecho, flexiona la rodilla derecha y baja a una posición de zancada.", "Mientras avanzas en la zancada, flexiona los codos para llevar las mancuernas hacia los hombros, manteniéndolos cerca del cuerpo.", "En la parte baja de la zancada, gira el torso hacia la derecha como si fueras a lanzar una bola de boliche.", "Invierte el movimiento: lleva el pie derecho hacia atrás y vuelve a la posición inicial mientras bajas las mancuernas.", "Repite la zancada con el curl, esta vez girando el torso hacia la izquierda.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1651.gif'),
('1655', 'Sentadilla con curl de bíceps con mancuernas', 'dumbbell biceps curl squat', '["Sentadilla con flexión de bíceps", "Curl de bíceps combinado con sentadilla", "dumbbell biceps curl squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio compuesto que combina un curl de bíceps tradicional con una sentadilla para trabajar los brazos y el tren inferior. Se enfoca en los bíceps y también requiere coordinación y algo de fuerza en las piernas.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano, con las palmas hacia adelante.", "Mantén la espalda recta y los codos pegados a los costados. Exhala mientras subes las mancuernas hacia los hombros.", "Haz una breve pausa arriba y contrae los bíceps.", "Inhala mientras bajas lentamente las mancuernas a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1655.gif'),
('1658', 'Zancada con curl de bíceps con mancuernas', 'dumbbell lunge with bicep curl', '["Desplante con curl de bíceps", "Zancada al frente con flexión de bíceps", "dumbbell lunge with bicep curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Cuádriceps", "Isquiotibiales"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que combina una zancada al frente con un curl de bíceps para trabajar tanto los bíceps como los músculos del tren inferior.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano, con las palmas hacia adelante.", "Da un paso al frente con el pie derecho y baja en una zancada. Dobla la rodilla derecha a 90 grados y deja la izquierda apenas por encima del suelo.", "Mientras avanzas en la zancada, sube las mancuernas hacia los hombros sin separar los codos del cuerpo.", "Haz una breve pausa abajo y luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas a los costados.", "Repite la zancada y el curl de bíceps del otro lado, dando el paso al frente con el pie izquierdo.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1658.gif'),
('1685', 'Sentadilla con brazos arriba', 'squat to overhead reach', '["Sentadilla con extensión de brazos", "Sentadilla con alcance hacia arriba", "squat to overhead reach"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Core"]'::jsonb, 'Peso corporal', 'Principiante', 'Movilidad', 'Ejercicio con peso corporal que combina una sentadilla tradicional con una extensión de brazos por encima de la cabeza. Trabaja los cuádriceps, los glúteos, los isquiotibiales y la zona media, y ayuda a mejorar la fuerza del tren inferior, la movilidad y la coordinación.', '["Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Baja en una sentadilla, doblando las rodillas y llevando la cadera hacia atrás.", "Al subir de la sentadilla, estira los brazos por encima de la cabeza como si quisieras alcanzar el techo.", "Baja los brazos y dobla las rodillas para volver a bajar en sentadilla.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1685.gif'),
('1686', 'Sentadilla con brazos arriba y giro', 'squat to overhead reach with twist', '["Sentadilla con rotación de torso", "Sentadilla con alcance y giro", "squat to overhead reach with twist"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Core"]'::jsonb, 'Peso corporal', 'Principiante', 'Movilidad', 'Ejercicio dinámico con peso corporal que combina una sentadilla tradicional con un alcance por encima de la cabeza y un giro del torso. Trabaja los cuádriceps, los glúteos, los isquiotibiales y la zona media, y mejora la fuerza del tren inferior, la estabilidad de la zona media y la movilidad de rotación.', '["Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Baja en una sentadilla, doblando las rodillas y llevando la cadera hacia atrás.", "Al subir de la sentadilla, levanta los brazos por encima de la cabeza y gira el torso hacia un lado.", "Vuelve a la posición inicial y repite la sentadilla, esta vez girando el torso hacia el lado contrario.", "Sigue alternando los lados en cada repetición."]'::jsonb, '/gifs/1686.gif'),
('1688', 'Zancada con giro', 'lunge with twist', '["Desplante con rotación", "Zancada con giro de torso", "lunge with twist"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Cuádriceps", "Glúteos", "Isquiotibiales"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio dinámico que combina una zancada al frente con una rotación del torso. Se enfoca en los abdominales y también trabaja los cuádriceps, los glúteos y los isquiotibiales. Mejora la estabilidad de la zona media, el equilibrio y la fuerza del tren inferior.', '["Párate con los pies al ancho de los hombros.", "Da un paso al frente con el pie derecho y baja en una zancada.", "Mientras haces la zancada, gira el torso hacia la derecha y acerca el codo izquierdo a la rodilla derecha.", "Haz una breve pausa y vuelve a la posición inicial.", "Repite del otro lado, dando el paso al frente con el pie izquierdo y girando el torso hacia la izquierda.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1688.gif'),
('1717', 'Sentadilla con remo en polea (con cuerda)', 'cable squat row (with rope attachment)', '["Remo con cuerda en sentadilla", "Sentadilla con jalón de remo", "cable squat row (with rope attachment)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Romboides", "Deltoides posteriores"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que combina una sentadilla con un remo en polea con cuerda. Se enfoca en los dorsales y también trabaja los bíceps, los romboides y los deltoides posteriores. Requiere coordinación, estabilidad de la zona media y fuerza.', '["Coloca una cuerda en la polea a la altura de la cintura.", "Párate frente a la máquina con los pies al ancho de los hombros.", "Dobla las rodillas y baja en una sentadilla, manteniendo la espalda recta y el pecho elevado.", "Agarra la cuerda con las palmas hacia abajo y las manos al ancho de los hombros.", "Activa la zona media y jala la cuerda hacia el cuerpo, juntando los omóplatos.", "Mantén los codos cerca del cuerpo y sigue jalando hasta que las manos lleguen al pecho.", "Haz una breve pausa al terminar el jalón y luego deja que la cuerda vuelva lentamente, extendiendo los brazos hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1717.gif'),
('1719', 'Press inclinado con barra y agarre cerrado', 'barbell incline close grip bench press', '["Press de tríceps en banco inclinado", "Press de banca inclinado cerrado", "barbell incline close grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren superior que trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros. Se realiza en un banco inclinado con una barra y agarre cerrado para maximizar la activación de los tríceps.', '["Ajusta un banco inclinado a 45 grados.", "Acostate en el banco con los pies bien apoyados en el suelo.", "Agarra la barra con las manos un poco más juntas que el ancho de los hombros.", "Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una breve pausa cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1719.gif'),
('1732', 'Zancada al frente con extensión de tríceps con mancuernas', 'dumbbell forward lunge triceps extension', '["Desplante con extensión de tríceps", "Zancada con tríceps sobre la cabeza", "dumbbell forward lunge triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros", "Core"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que combina una zancada con una extensión de tríceps por encima de la cabeza. Trabaja los tríceps, los hombros, la zona media y las piernas.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano.", "Da un paso al frente con el pie derecho y baja en una zancada.", "Mantén la espalda recta y el pecho elevado.", "Estira los brazos por encima de la cabeza, manteniendo los codos cerca de las orejas.", "Dobla los codos para bajar las mancuernas detrás de la cabeza.", "Haz una breve pausa y luego estira los brazos para volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna y repite."]'::jsonb, '/gifs/1732.gif'),
('1743', 'Press de banca con mancuernas y giro', 'dumbbell twisting bench press', '["Press plano con giro de muñecas", "Press de pecho con rotación", "dumbbell twisting bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Variante del press de banca con mancuernas que incorpora un giro de muñecas para aumentar el trabajo de los tríceps, el pecho y los hombros. Requiere coordinación y control para realizar el giro de forma segura durante el press.', '["Acuéstate en un banco plano con los pies bien apoyados en el suelo y la espalda apoyada en el banco.", "Sostén una mancuerna en cada mano con agarre prono, con las palmas orientadas en dirección contraria a ti.", "Estira los brazos sobre el pecho, dejando una ligera flexión en los codos.", "Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.", "Mientras bajas las mancuernas, gira las muñecas para que las palmas queden hacia ti al llegar abajo.", "Haz una breve pausa abajo y luego empuja las mancuernas hacia arriba para volver a la posición inicial.", "Mientras subes las mancuernas, gira las muñecas hasta que las palmas vuelvan a quedar orientadas en dirección contraria a ti.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1743.gif'),
('1753', 'Fondos en tres bancos', 'three bench dip', '["Fondos de tríceps con pies elevados", "Fondos entre bancos", "three bench dip"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal para los tríceps que utiliza tres bancos para elevar los pies y las manos. Aumenta el recorrido y la dificultad en comparación con los fondos tradicionales.', '["Siéntate en un banco y agarra el borde con las manos, con los dedos hacia adelante.", "Desliza los glúteos fuera del banco y sostén tu peso con las manos.", "Coloca los pies sobre un segundo banco y, si usas un tercero, eleva más las piernas.", "Dobla los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.", "Empuja para subir de nuevo a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1753.gif'),
('1756', 'Peso muerto a una pierna con barra', 'barbell single leg deadlift', '["Peso muerto unilateral con barra", "Peso muerto en una sola pierna con barra", "barbell single leg deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Barra', 'Avanzado', 'Fuerza', 'Ejercicio unilateral del tren inferior que trabaja principalmente los glúteos y, de forma secundaria, los isquiotibiales y la zona lumbar. Exige equilibrio, coordinación y fuerza al inclinarte desde la cadera sobre una sola pierna mientras sostienes una barra.', '["Párate con los pies al ancho de las caderas y sostén una barra frente a los muslos con las palmas hacia el cuerpo.", "Pasa el peso al pie izquierdo y levanta ligeramente el pie derecho del suelo.", "Inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta y la pierna derecha extendida hacia atrás para equilibrarte.", "Baja la barra hacia el suelo, manteniéndola cerca del cuerpo y la pierna izquierda ligeramente flexionada.", "Haz una breve pausa abajo y luego activa los glúteos y los isquiotibiales para levantar el torso y volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de lado."]'::jsonb, '/gifs/1756.gif'),
('1757', 'Peso muerto a una pierna con mancuerna', 'dumbbell single leg deadlift', '["Peso muerto unilateral con mancuerna", "Peso muerto en una sola pierna con mancuerna", "dumbbell single leg deadlift"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio unilateral del tren inferior que trabaja los glúteos, los isquiotibiales y la zona lumbar. Exige equilibrio, coordinación y fuerza para estabilizarte sobre una pierna mientras te inclinas desde la cadera y levantas una mancuerna.', '["Párate con los pies al ancho de las caderas y una mancuerna en la mano derecha.", "Pasa el peso a la pierna izquierda y levanta ligeramente el pie derecho del suelo.", "Mantén la espalda recta e inclina el torso hacia adelante desde la cadera, bajando la mancuerna hacia el suelo.", "Al mismo tiempo, estira la pierna derecha hacia atrás y mantén la rodilla izquierda ligeramente flexionada.", "Baja la mancuerna hasta que el torso y la pierna derecha queden paralelos al suelo.", "Haz una breve pausa y luego activa los glúteos y los isquiotibiales para volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de lado."]'::jsonb, '/gifs/1757.gif'),
('1759', 'Sentadilla a una pierna (pistola) para hombre', 'single leg squat (pistol) male', '["Sentadilla pistola masculina", "Sentadilla unilateral con pierna al frente", "single leg squat (pistol) male"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'La sentadilla a una pierna o sentadilla pistola es un ejercicio exigente del tren inferior que trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas. Requiere mucha fuerza, equilibrio y movilidad para ejecutarse correctamente, por lo que es adecuada para personas de nivel avanzado.', '["Párate con los pies al ancho de los hombros y los brazos extendidos al frente.", "Levanta el pie derecho del suelo y estira la pierna hacia adelante.", "Baja lentamente, doblando la rodilla izquierda y llevando la cadera hacia atrás.", "Mantén el pecho elevado y la espalda recta mientras bajas.", "Baja hasta que el muslo izquierdo quede paralelo al suelo o hasta donde puedas llegar cómodamente.", "Haz una breve pausa abajo y luego empuja con el talón izquierdo para volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna."]'::jsonb, '/gifs/1759.gif'),
('1760', 'Sentadilla copa con mancuerna', 'dumbbell goblet squat', '["Sentadilla goblet", "Sentadilla con mancuerna al pecho", "dumbbell goblet squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio del tren inferior que trabaja los cuádriceps y también activa los glúteos, los isquiotibiales y las pantorrillas. Consiste en hacer una sentadilla sosteniendo una mancuerna cerca del pecho y es útil para desarrollar fuerza y mejorar la técnica de sentadilla.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna vertical contra el pecho con ambas manos.", "Mantén el pecho elevado y la zona media activa. Baja en una sentadilla, llevando la cadera hacia atrás y doblando las rodillas.", "Sigue bajando hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1760.gif'),
('1763', 'Dominada con agarre al ancho de los hombros', 'shoulder grip pull-up', '["Dominada con agarre prono", "Dominada con agarre medio", "shoulder grip pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja los dorsales y también activa los bíceps y los antebrazos. Consiste en subir el cuerpo hacia una barra con agarre prono al ancho de los hombros.', '["Agarra la barra de dominadas con las manos al ancho de los hombros y las palmas orientadas en dirección contraria a ti.", "Cuélgate con los brazos completamente extendidos.", "Activa los músculos de la espalda y sube el cuerpo hacia la barra hasta que la barbilla la sobrepase.", "Haz una breve pausa arriba y luego baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1763.gif'),
('1772', 'Elevación de codos - flexión inversa', 'elbow lift - reverse push-up', '["Flexión inversa para espalda alta", "Levantamiento de torso con codos pegados", "elbow lift - reverse push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente la espalda alta y, de forma secundaria, los tríceps y los hombros. Consiste en levantar el torso del suelo con los codos cerca de los costados, concentrándote en contraer los músculos de la espalda alta.', '["Acuéstate boca abajo en el suelo con las piernas extendidas y las manos directamente debajo de los hombros.", "Activa la zona media y empuja con las palmas para levantar el torso del suelo, manteniendo los codos cerca de los costados.", "Haz una breve pausa arriba y contrae los músculos de la espalda alta.", "Baja lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1772.gif'),
('2187', 'Press de banca con barra y agarre cerrado inverso', 'barbell reverse close-grip bench press', '["Press cerrado con agarre supino", "Press de tríceps con agarre invertido", "barbell reverse close-grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros. Se realiza acostado en un banco, empujando una barra con agarre inverso o supino, lo que aumenta el énfasis en los tríceps respecto al press de banca tradicional.', '["Acuéstate en un banco plano con los pies bien apoyados en el suelo y la espalda apoyada en el banco.", "Agarra la barra con agarre inverso y las manos al ancho de los hombros.", "Saca la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.", "Baja lentamente la barra hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una breve pausa cuando la barra quede apenas por encima del pecho.", "Empuja la barra hacia arriba hasta la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2187.gif'),
('2287', 'Prensa de piernas alternada en máquina', 'lever alternate leg press', '["Prensa alterna de piernas", "Prensa unilateral alternada", "lever alternate leg press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que trabaja principalmente los cuádriceps y, de forma secundaria, los isquiotibiales y los glúteos. Consiste en empujar una plataforma con una pierna a la vez, lo que permite desarrollar la fuerza del tren inferior de forma controlada.', '["Ajusta el asiento y la plataforma para los pies de la máquina a la posición deseada.", "Siéntate en la máquina con la espalda apoyada en el respaldo y los pies sobre la plataforma.", "Sujeta las agarraderas o los costados de la máquina para mantener la estabilidad.", "Empuja la plataforma con un pie y extiende la pierna hasta que quede casi recta.", "Haz una breve pausa y luego dobla lentamente la pierna para volver a la posición inicial.", "Repite con la otra pierna.", "Sigue alternando las piernas hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2287.gif'),
('2318', 'Press de hombros en máquina (versión 3)', 'lever shoulder press v. 3', '["Press de deltoides en máquina", "Press sentado de hombros en máquina", "lever shoulder press v. 3"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Pecho"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que trabaja los deltoides de los hombros y también activa los tríceps y el pecho de forma secundaria. Consiste en empujar las agarraderas hacia arriba y hacia adelante desde una posición sentada, con estabilidad y control para desarrollar fuerza en los hombros.', '["Ajusta la altura del asiento y el respaldo de la máquina a una posición cómoda.", "Siéntate con la espalda apoyada en el respaldo y los pies bien apoyados en el suelo.", "Agarra las agarraderas con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Empuja las agarraderas hacia arriba y hacia adelante hasta extender los brazos sin bloquear los codos.", "Haz una breve pausa arriba y luego baja lentamente las agarraderas a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2318.gif'),
('2330', 'Jalón al pecho en polea con recorrido completo', 'cable lat pulldown full range of motion', '["Jalón dorsal de recorrido completo", "Jalón al pecho de amplitud completa", "cable lat pulldown full range of motion"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Romboides", "Deltoides posteriores"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de fuerza en polea que trabaja los dorsales y también activa los bíceps, los romboides y los deltoides posteriores. Consiste en jalar una barra hacia el pecho desde una posición sentada, con énfasis en completar todo el recorrido para optimizar la activación muscular.', '["Siéntate en la máquina de jalón al pecho con las rodillas debajo de las almohadillas.", "Agarra la barra de la polea con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Inclina el torso ligeramente hacia atrás, mantén el pecho elevado y conserva un leve arco en la zona lumbar.", "Jala la barra hacia la parte superior del pecho, juntando los omóplatos.", "Haz una breve pausa abajo y luego deja que la barra vuelva lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2330.gif'),
('2363', 'Fondos de pecho con agarre ancho en paralelas altas', 'wide-grip chest dip on high parallel bars', '["Fondos abiertos para pecho", "Fondos pectorales en barras altas", "wide-grip chest dip on high parallel bars"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los pectorales y, de forma secundaria, los tríceps y los hombros. Requiere bastante fuerza en el tren superior, estabilidad, control y experiencia con los fondos.', '["Colócate en las barras paralelas con los brazos completamente extendidos y el cuerpo suspendido.", "Inclina el torso ligeramente hacia adelante y dobla los codos para bajar hasta que el pecho quede apenas por encima de las barras.", "Haz una breve pausa y luego empuja, estirando los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2363.gif'),
('2364', 'Fondos de pecho asistidos con agarre ancho (de rodillas)', 'assisted wide-grip chest dip (kneeling)', '["Fondos abiertos en máquina asistida", "Fondos pectorales con apoyo de rodillas", "assisted wide-grip chest dip (kneeling)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina que trabaja principalmente los pectorales y, de forma secundaria, los tríceps y los hombros. La asistencia de la máquina permite realizarlo a quienes todavía no tienen la fuerza necesaria para hacer fondos sin ayuda.', '["Ajusta la máquina a la altura deseada y apoya bien las rodillas en la almohadilla.", "Sujeta las agarraderas con un agarre ancho y mantén los codos ligeramente flexionados.", "Dobla los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.", "Empuja y extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2364.gif'),
('2368', 'Sentadilla en tijera', 'split squats', '["Zancada estática", "Desplante fijo", "split squats"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio del tren inferior que trabaja principalmente los cuádriceps y también activa los glúteos, los isquiotibiales y las pantorrillas. Se realiza con peso corporal, adelantando un pie y bajando hasta que el muslo delantero quede paralelo al suelo antes de volver a la posición inicial.', '["Párate con los pies al ancho de los hombros.", "Da un paso al frente con un pie y colócalo unos 60 cm por delante del otro.", "Baja el cuerpo doblando las rodillas y las caderas, sin encorvar la espalda.", "Sigue bajando hasta que el muslo delantero quede paralelo al suelo y la rodilla trasera apenas por encima del suelo.", "Haz una breve pausa y luego empuja con el talón delantero para volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna y repite."]'::jsonb, '/gifs/2368.gif'),
('2398', 'Flexión con agarre cerrado (rodillas apoyadas)', 'close-grip push-up (on knees)', '["Flexiones cerradas de rodillas", "Flexión de tríceps con rodillas en el suelo", "close-grip push-up (on knees)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros. Se realiza con las rodillas apoyadas, lo que facilita su ejecución para principiantes y personas que están desarrollando fuerza en el tren superior.', '["Apoya las manos y las rodillas en el suelo, con las manos al ancho de los hombros y las rodillas al ancho de las caderas.", "Dobla los codos para bajar el torso hacia el suelo, manteniéndolos cerca de los costados.", "Haz una breve pausa cuando el pecho quede apenas por encima del suelo.", "Empuja con las palmas para estirar los brazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2398.gif'),
('2400', 'Curl femoral inverso (en máquina de dominadas con polea)', 'inverse leg curl (on pull-up cable machine)', '["Curl de piernas inverso en polea", "Flexión de rodillas con tobilleras", "inverse leg curl (on pull-up cable machine)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los isquiotibiales y, de forma secundaria, los glúteos y las pantorrillas. Consiste en acostarte boca abajo, sujetar unas correas de tobillo a una polea y flexionar las piernas hacia los glúteos.', '["Ajusta la polea para que las correas de los tobillos queden en la posición más baja.", "Acuéstate boca abajo en el banco con las piernas extendidas y las correas sujetas a los pies.", "Sujeta las agarraderas del banco para mantener la estabilidad.", "Dobla las rodillas y lleva los pies hacia los glúteos, contrayendo los isquiotibiales.", "Haz una breve pausa al final de la flexión y luego baja lentamente las piernas a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2400.gif'),
('2432', 'Press de banca con barra Z y agarre cerrado', 'ez-bar close-grip bench press', '["Press cerrado con barra Z", "Press de tríceps con barra Z", "ez-bar close-grip bench press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Barra Z', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren superior que trabaja principalmente los tríceps y, de forma secundaria, el pecho y los hombros. Se realiza acostado en un banco, con agarre cerrado en una barra Z para enfatizar la activación de los tríceps.', '["Acuéstate en un banco plano con los pies bien apoyados en el suelo y la espalda apoyada en el banco.", "Agarra la barra Z con agarre cerrado, las manos al ancho de los hombros y las palmas hacia adelante.", "Saca la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.", "Baja lentamente la barra hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una breve pausa cuando la barra toque el pecho.", "Empuja la barra hacia arriba hasta la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2432.gif'),
('2462', 'Fondos de pecho en barra recta', 'chest dip on straight bar', '["Fondos pectorales en barra", "Fondos sobre barra recta", "chest dip on straight bar"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los pectorales y, de forma secundaria, los tríceps y los hombros. Requiere bastante fuerza en el tren superior, estabilidad y control.', '["Agarra las barras paralelas con las palmas hacia abajo y los brazos completamente extendidos.", "Dobla las rodillas y cruza los tobillos.", "Dobla los brazos y baja el cuerpo hasta que los hombros queden por debajo de los codos.", "Empuja y estira los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2462.gif'),
('2611', 'Prensa horizontal a una pierna en máquina', 'lever horizontal one leg press', '["Prensa horizontal unilateral", "Prensa de glúteos a una pierna", "lever horizontal one leg press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza del tren inferior realizado en máquina. Trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en alejar una plataforma del cuerpo con una pierna a la vez, aumentando la exigencia de fuerza unilateral y estabilidad.', '["Ajusta el asiento para que las rodillas formen un ángulo de 90 grados al apoyar los pies en la plataforma.", "Siéntate con la espalda apoyada en el respaldo y los pies al ancho de los hombros sobre la plataforma.", "Sujeta las agarraderas o los costados de la máquina para mantener la estabilidad.", "Extiende la pierna para alejar la plataforma del cuerpo, manteniendo la espalda apoyada en el respaldo.", "Haz una breve pausa con la pierna completamente extendida y luego dóblala lentamente para volver a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna."]'::jsonb, '/gifs/2611.gif'),
('2795', 'Zancada con subida al banco con mancuernas', 'dumbbell step up lunge', '["Desplante elevado con mancuernas", "Zancada entre bancos con mancuernas", "dumbbell step up lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Aductores", "Pantorrillas", "Abdominales"]'::jsonb, 'Mancuerna', 'Avanzado', 'Fuerza', 'Sostén las mancuernas a los costados y adopta una postura de zancada amplia, con el pie delantero sobre un banco y el trasero elevado sobre otro banco detrás de ti. Baja verticalmente hasta que el pie delantero toque suavemente el suelo y luego empuja con el talón delantero para volver a subir al banco de adelante.', '["Coloca dos bancos firmes separados aproximadamente por la longitud de una zancada. Sostén las mancuernas a los costados, eleva el pecho y mantén firme la zona media.", "Apoya toda la planta del pie delantero en el banco de adelante y el empeine del pie trasero en el banco de atrás. Mantén la cadera alineada hacia adelante y la mirada al frente.", "Inhala y baja verticalmente doblando ambas rodillas. Mantén la rodilla delantera alineada con los dedos centrales del pie y el talón apoyado.", "Baja hasta que el pie delantero toque suavemente el suelo o hasta que el muslo delantero quede al menos paralelo al suelo, manteniendo el torso erguido y la columna neutra.", "Exhala y empuja con el talón y la parte media del pie delantero para extender la rodilla y la cadera y volver a la posición inicial sobre los bancos.", "Impúlsate lo menos posible con la pierna trasera. Mantén las mancuernas quietas y los hombros bajos.", "Haz una pausa, recupera el equilibrio y completa todas las repeticiones antes de cambiar de pierna."]'::jsonb, '/gifs/2795.gif'),
('2796', 'Zancada con subida al banco con mancuernas (variante 2)', 'dumbbell step-up lunge', '["Subida a plataforma con mancuernas", "Subida al escalón con pesas", "dumbbell step-up lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto del tren inferior que trabaja los cuádriceps y también activa los glúteos, los isquiotibiales y las pantorrillas. Consiste en subir a una plataforma elevada sosteniendo mancuernas y requiere equilibrio, coordinación y fuerza en el tren inferior.', '["Párate frente a un escalón o plataforma con una mancuerna en cada mano y las palmas hacia los costados del cuerpo.", "Coloca el pie derecho sobre el escalón, asegurándote de apoyar toda la planta.", "Empuja con el talón derecho para subir el cuerpo al escalón y lleva también el pie izquierdo arriba.", "Cuando tengas ambos pies sobre el escalón, baja el pie izquierdo a la posición inicial y deja el derecho arriba.", "Repite el movimiento, alternando el pie con el que subes cada vez.", "Continúa hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2796.gif'),
('2797', 'Sentadilla con salto al escalón y zancada atrás con barra', 'barbell squat jump step rear lunge', '["Salto al escalón con barra y desplante atrás", "Sentadilla con salto y zancada inversa con barra", "barbell squat jump step rear lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas", "Abdominales", "Aductores"]'::jsonb, 'Barra', 'Avanzado', 'Pliometría', 'Coloca una barra sobre la parte alta de la espalda y párate frente a un escalón bajo y estable. Haz una sentadilla con salto para aterrizar sobre el escalón y luego da un paso atrás en una zancada inversa antes de volver al inicio.', '["Apoya la barra sobre la parte superior de los trapecios y agárrala al ancho de los hombros. Párate entre 15 y 30 cm frente a un escalón firme, con los pies al ancho de las caderas y las puntas ligeramente hacia afuera.", "Mantén firme la zona media y la columna neutra, y baja a un cuarto de sentadilla o media sentadilla.", "Impúlsate con los pies y salta al escalón. Aterriza suavemente sobre ambos pies, con las rodillas alineadas con las puntas y los talones apoyados.", "Ponte de pie sobre el escalón, lleva un pie hacia atrás hasta el suelo y baja en una zancada inversa controlada, con la espinilla delantera vertical y la rodilla trasera debajo de la cadera.", "Empuja con el talón delantero para volver a quedar de pie en el suelo, en la posición inicial.", "Repite el salto y alterna la pierna de la zancada en cada repetición, manteniendo el torso erguido y la barra estable.", "Usa un escalón bajo y una carga ligera. Detén la serie si pierdes el control al aterrizar o el equilibrio."]'::jsonb, '/gifs/2797.gif'),
('2798', 'Sentadilla con salto y zancada atrás con barra', 'barbell squat jump step rear lunge', '["Sentadilla con salto y desplante inverso con barra", "Salto con barra y zancada hacia atrás", "barbell squat jump step rear lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Avanzado', 'Pliometría', 'Ejercicio dinámico del tren inferior que combina una sentadilla con salto y una zancada inversa, con una barra apoyada sobre la parte alta de la espalda. Trabaja los cuádriceps, los glúteos, los isquiotibiales y las pantorrillas, y requiere fuerza, coordinación y equilibrio.', '["Párate con los pies al ancho de los hombros y una barra apoyada sobre la parte alta de la espalda.", "Baja en una sentadilla, doblando las rodillas y llevando la cadera hacia atrás.", "Impúlsate con fuerza hacia arriba y salta lo más alto que puedas.", "Aterriza suavemente y enseguida da un paso atrás con una pierna para hacer una zancada inversa.", "Baja hasta que el muslo delantero quede paralelo al suelo, manteniendo la espalda recta.", "Empuja con el talón delantero para volver a la posición inicial.", "Repite la secuencia de salto y zancada con la otra pierna.", "Sigue alternando las piernas hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2798.gif'),
('2803', 'Sentadilla con mancuernas con apoyo', 'dumbbell supported squat', '["Sentadilla apoyada con mancuernas", "Sentadilla con pesas a los costados", "dumbbell supported squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio del tren inferior que trabaja los cuádriceps y también activa los glúteos, los isquiotibiales y las pantorrillas. Consiste en hacer una sentadilla sosteniendo mancuernas a los costados para mejorar la fuerza y la estabilidad.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano a los costados.", "Mantén el pecho elevado y la zona media activa. Baja lentamente, doblando las rodillas y llevando la cadera hacia atrás.", "Sigue bajando hasta que los muslos queden paralelos al suelo o hasta donde puedas llegar cómodamente.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2803.gif'),
('2804', 'Sentadilla con mancuernas con apoyo (variante 2)', 'dumbbell supported squat', '["Sentadilla sissy con mancuernas", "Sentadilla con soporte y mancuernas", "dumbbell supported squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas", "Abdominales"]'::jsonb, 'Máquina', 'Intermedio', 'Fuerza', 'Colócate en un banco de sentadilla sissy o con soporte, con los tobillos sujetos y las pantorrillas contra la almohadilla, sosteniendo una o dos mancuernas a la altura del pecho. Baja doblando las rodillas y manteniendo el torso erguido; luego empuja con los pies para volver a ponerte de pie.', '["Ajusta el soporte para que los tobillos queden bien sujetos debajo del rodillo y las pantorrillas toquen la almohadilla trasera. Párate erguido sobre la plataforma, con los pies al ancho de las caderas y las puntas hacia adelante.", "Sostén una mancuerna vertical frente al pecho, en posición de copa, o dos mancuernas a la altura de los hombros. Mantén firme la zona media y la columna neutra.", "Inhala y empieza a bajar doblando las rodillas hacia adelante, alineándolas con el segundo y tercer dedo de cada pie, mientras mantienes la cadera relativamente extendida y el torso erguido.", "Mantén los talones apoyados y las espinillas guiadas por el soporte. Evita redondear la zona lumbar o dejar que las rodillas se metan hacia adentro.", "Baja de forma controlada hasta que los muslos queden paralelos al suelo o hasta una profundidad cómoda, sin perder la presión de los pies ni la posición de la columna.", "Empuja con la parte media de los pies para extender las rodillas y volver a ponerte de pie. Exhala al superar la parte más difícil del movimiento.", "Haz una breve pausa, vuelve a activar la zona media y repite hasta completar las repeticiones previstas con un ritmo fluido y controlado."]'::jsonb, '/gifs/2804.gif'),
('2805', 'Peso muerto a una pierna con mancuerna y apoyo en cajón', 'dumbbell single leg deadlift with stepbox support', '["Peso muerto unilateral con apoyo elevado", "Peso muerto con mancuerna y pie en banco", "dumbbell single leg deadlift with stepbox support"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio unilateral del tren inferior que trabaja principalmente los glúteos y, de forma secundaria, los isquiotibiales y la zona lumbar. Exige equilibrio, estabilidad y fuerza, por lo que es adecuado para personas con algo de experiencia en el entrenamiento con pesas.', '["Párate con los pies al ancho de las caderas y una mancuerna en la mano derecha.", "Coloca el pie izquierdo sobre un cajón o una superficie elevada detrás de ti.", "Mantén la espalda recta y la zona media activa. Inclina el torso hacia adelante desde la cadera y baja la mancuerna hacia el suelo.", "Mientras bajas la mancuerna, levanta la pierna izquierda hacia atrás, manteniendo una línea recta desde la cabeza hasta el talón.", "Baja la mancuerna hasta sentir un estiramiento en los isquiotibiales derechos y luego vuelve a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de lado."]'::jsonb, '/gifs/2805.gif'),
('2806', 'Peso muerto a una pierna con mancuerna y apoyo en cajón (variante 2)', 'dumbbell single leg deadlift with stepbox support', '["Peso muerto unilateral con pie trasero apoyado", "Peso muerto con mancuerna y apoyo en escalón", "dumbbell single leg deadlift with stepbox support"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos", "Erectores de la columna", "Pantorrillas", "Antebrazos", "Abdominales"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Párate sobre una pierna con el otro pie apoyado suavemente en un escalón o cajón bajo detrás de ti. Sostén una mancuerna en la mano del mismo lado de la pierna de trabajo e inclínate de forma controlada desde la cadera para cargar los isquiotibiales; luego vuelve a ponerte de pie.', '["Coloca un escalón o cajón bajo entre 30 y 45 cm detrás de ti y apoya suavemente la punta del pie que no trabaja. Párate erguido sobre la pierna de trabajo y sostén una mancuerna con la mano de ese mismo lado, con el brazo extendido.", "Coloca el pie de trabajo debajo de la cadera y mantén la rodilla ligeramente flexionada, entre 10 y 20 grados. Activa la zona media y mantén las caderas y los hombros alineados hacia adelante.", "Lleva la cadera hacia atrás e inclina el torso desde ahí, manteniendo la mancuerna cerca de la espinilla y casi sin cambiar la flexión de la rodilla de trabajo.", "Mantén la columna neutra desde la cabeza hasta la pelvis. Baja hasta sentir un estiramiento marcado en los isquiotibiales o hasta acercar el torso a la horizontal sin encorvarte.", "Mantén entre el 80 y el 90 % del peso sobre la pierna de trabajo. Usa el pie trasero solo para equilibrarte, sin impulsarte con él.", "Empuja con el talón de la pierna de trabajo y extiende la cadera para ponerte de pie, sin arquear en exceso la zona lumbar.", "Vuelve a activar la zona media y completa las repeticiones; luego cambia de lado."]'::jsonb, '/gifs/2806.gif'),
('2809', 'Sentadilla en tijera con barra (versión 2)', 'barbell split squat (version 2)', '["Zancada estática con barra al frente", "Desplante fijo con barra en las manos", "barbell split squat (version 2)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Aductores", "Pantorrillas", "Abdominales"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Sostén una barra con ambas manos frente a las caderas y los brazos extendidos, y adopta una postura de zancada. Baja verticalmente en una sentadilla en tijera y empuja con el pie delantero para subir, manteniendo la barra cerca del cuerpo y nivelada.', '["Párate erguido con los pies al ancho de las caderas. Sostén una barra con las palmas hacia el cuerpo y las manos justo por fuera de los muslos.", "Adelanta un pie para adoptar una postura de zancada amplia, con el pie delantero completamente apoyado, el talón trasero levantado y las puntas hacia adelante.", "Activa los abdominales, mantén el pecho elevado, la cadera alineada hacia adelante y la barra cerca de los muslos.", "Baja verticalmente doblando ambas rodillas, con el torso erguido y la rodilla delantera alineada con los dedos centrales del pie.", "Baja hasta que el muslo delantero quede casi paralelo al suelo y la rodilla trasera apenas por encima del suelo. Mantén el peso sobre la parte media y el talón del pie delantero.", "Empuja con el pie delantero y la parte delantera del pie trasero para volver a ponerte de pie sin bloquear las rodillas.", "Mantén la barra nivelada y cerca del cuerpo. Evita que la rodilla delantera se meta hacia adentro o que el talón se levante.", "Completa todas las repeticiones de un lado y luego cambia de pierna y repite."]'::jsonb, '/gifs/2809.gif'),
('2810', 'Sentadilla en tijera con barra (versión 3)', 'barbell split squat v. 2', '["Zancada estática con barra en la espalda", "Desplante con barra en espalda alta", "barbell split squat v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza del tren inferior que trabaja los cuádriceps y también activa los glúteos, los isquiotibiales y las pantorrillas. Consiste en adelantar un pie y bajar el cuerpo con una barra apoyada sobre la parte alta de la espalda.', '["Párate con los pies al ancho de los hombros y una barra apoyada sobre la parte alta de la espalda.", "Da un paso amplio al frente con el pie derecho, manteniendo el torso erguido.", "Baja doblando las rodillas y las caderas hasta que el muslo derecho quede paralelo al suelo.", "Haz una breve pausa y luego empuja con el talón derecho para volver a la posición inicial.", "Repite con la pierna izquierda adelante hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2810.gif'),
('2812', 'Sentadilla en tijera con subida al banco con mancuernas', 'dumbbell step-up split squat', '["Subida al banco con mancuernas y rodilla arriba", "Subida al escalón con elevación de rodilla", "dumbbell step-up split squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio del tren inferior que trabaja los cuádriceps y también los glúteos, los isquiotibiales y las pantorrillas. Consiste en subir a un banco o escalón sosteniendo mancuernas y requiere equilibrio, coordinación y fuerza.', '["Párate frente a un banco o escalón con una mancuerna en cada mano y las palmas hacia el cuerpo.", "Coloca el pie derecho sobre el banco o escalón, asegurándote de apoyar toda la planta.", "Sube al banco o escalón con el pie derecho, empujando con el talón para levantar el cuerpo.", "Mientras subes, levanta la rodilla izquierda hacia el pecho.", "Haz una pausa arriba y luego baja lentamente el pie izquierdo al suelo, dejando el derecho sobre el banco o escalón.", "Repite el movimiento con el pie izquierdo sobre el banco o escalón.", "Sigue alternando los pies hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/2812.gif'),
('3011', 'Flexión escapular inclinada', 'incline scapula push up', '["Flexiones de escápulas en banco", "Flexión inclinada para serrato", "incline scapula push up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Serrato anterior', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal realizado en un banco inclinado que trabaja principalmente el serrato anterior y también activa los tríceps y los hombros. Enfatiza el movimiento de juntar y separar los omóplatos para mejorar la estabilidad y la fuerza de los hombros.', '["Ajusta un banco inclinado a 45 grados.", "Coloca las manos sobre el banco, un poco más separadas que el ancho de los hombros.", "Apoya los pies en el suelo al ancho de las caderas.", "Baja el pecho hacia el banco, manteniendo los codos cerca del cuerpo.", "Mientras bajas, lleva los omóplatos hacia atrás y júntalos.", "Empuja con las palmas para extender los brazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3011.gif'),
('3012', 'Fondos escapulares', 'scapula dips', '["Fondos para trapecios", "Fondos con movimiento de escápulas", "scapula dips"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Romboides", "Deltoides"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los trapecios y la espalda alta al juntar y bajar las escápulas. Ayuda a mejorar la estabilidad y la fuerza de los hombros.', '["Párate con los pies al ancho de los hombros y los brazos extendidos al frente.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta.", "Baja el cuerpo flexionando los codos y juntando los omóplatos, como si quisieras sujetar un lápiz entre ellos.", "Haz una breve pausa abajo y luego empuja con las manos para extender los codos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3012.gif'),
('3019', 'Dominadas en banco', 'bench pull-ups', '["Dominadas en apoyo horizontal", "Jalón corporal en banco", "bench pull-ups"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para los dorsales en el que acercas el pecho a una barra o superficie horizontal manteniendo el cuerpo recto. También trabaja los bíceps y los antebrazos.', '["Colócate debajo de una barra o una superficie horizontal firme que esté a la altura del pecho.", "Sujeta la barra o la superficie con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Quédate colgado con los brazos completamente extendidos y el cuerpo recto.", "Acerca el pecho a la barra o la superficie juntando los omóplatos y flexionando los codos.", "Sigue subiendo hasta que la barbilla quede por encima de la barra o la superficie.", "Baja de forma controlada hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3019.gif'),
('3021', 'Flexión escapular', 'scapula push-up', '["Flexión de escápulas", "Flexión para serrato anterior", "scapula push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Serrato anterior', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Movilidad', 'Ejercicio con peso corporal que trabaja el serrato anterior y mejora la movilidad y la estabilidad escapular. Se realiza en plancha alta, enfocándose en el movimiento de los omóplatos más que en el de los codos.', '["Colócate en plancha alta, con las manos justo debajo de los hombros y el cuerpo en línea recta.", "Baja el pecho hacia el suelo manteniendo los codos cerca del cuerpo.", "Mientras bajas, junta los omóplatos y lleva el pecho hacia adelante.", "Haz una breve pausa abajo y luego empuja para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3021.gif'),
('3119', 'Sentadilla tipo silla', 'potty squat', '["Sentadilla con peso corporal", "Sentadilla simulando sentarse", "potty squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Cuádriceps", "Glúteos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Sentadilla con peso corporal que trabaja los abdominales, los cuádriceps y los glúteos. Consiste en bajar como si fueras a sentarte en una silla, con la espalda recta y el pecho levantado, y luego volver a ponerte de pie.', '["Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Baja flexionando las rodillas y llevando la cadera hacia atrás, como si fueras a sentarte en una silla.", "Mantén el pecho levantado y la espalda recta durante todo el movimiento.", "Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas hacerlo con comodidad.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3119.gif'),
('3132', 'Sentadilla tipo silla con apoyo', 'potty squat with support', '["Sentadilla asistida", "Sentadilla con soporte", "potty squat with support"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Sentadilla con peso corporal enfocada en los glúteos, realizada con un apoyo estable para mantener el equilibrio. Es adecuada para desarrollar fuerza en el tren inferior y aprender la técnica de la sentadilla.', '["Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Sujétate de un apoyo estable, como una silla o una pared, para mantener el equilibrio.", "Baja a una posición de sentadilla flexionando las rodillas y llevando la cadera hacia atrás.", "Mantén el pecho levantado y la espalda recta durante todo el movimiento.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3132.gif'),
('3142', 'Sentadilla sumo en máquina Smith', 'smith sumo squat', '["Sentadilla abierta en Smith", "Sentadilla sumo en barra guiada", "smith sumo squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de tren inferior en máquina Smith que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, los isquiotibiales y las pantorrillas. La postura amplia y el recorrido guiado de la barra facilitan el desarrollo de la técnica y la fuerza.', '["Ajusta la barra de la máquina Smith a la altura de la cadera.", "Párate con los pies más separados que el ancho de los hombros y las puntas hacia afuera.", "Colócate debajo de la barra y apóyala sobre la espalda alta y los hombros.", "Activa el abdomen y mantén el pecho levantado mientras bajas en sentadilla, llevando la cadera hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo o hasta donde puedas hacerlo con comodidad.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3142.gif'),
('3145', 'Flexión plus', 'push-up plus', '["Flexión con empuje escapular", "Flexión con separación de omóplatos", "push-up plus"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Variante de la flexión tradicional que añade una separación de los omóplatos al final de la subida. Este movimiento aumenta el trabajo del serrato anterior y mejora la estabilidad de los hombros.', '["Colócate en plancha alta, con las manos un poco más separadas que el ancho de los hombros y el cuerpo alineado de la cabeza a los talones.", "Baja el cuerpo hacia el suelo flexionando los codos y manteniéndolos cerca de los costados.", "Cuando el pecho esté justo por encima del suelo, empuja con las manos para extender los brazos y elevar el torso.", "Al llegar arriba, separa los omóplatos empujando la espalda alta hacia el techo.", "Haz una breve pausa y luego invierte el movimiento: junta los omóplatos y baja el cuerpo para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3145.gif'),
('3167', 'Remo en sentadilla con peso corporal (con toalla)', 'bodyweight squatting row (with towel)', '["Sentadilla con remo con toalla", "Remo con toalla en sentadilla", "bodyweight squatting row (with towel)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio compuesto que trabaja la espalda alta, los bíceps y los hombros. Combina una sentadilla con un remo usando una toalla como resistencia para desarrollar fuerza y coordinación.', '["Párate con los pies al ancho de los hombros y sostén una toalla al frente con las palmas hacia abajo.", "Flexiona las rodillas y baja en sentadilla, manteniendo la espalda recta y el pecho levantado.", "Mientras bajas, jala la toalla hacia el pecho y junta los omóplatos.", "Haz una breve pausa abajo y luego vuelve lentamente a la posición inicial mientras extiendes los brazos.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3167.gif'),
('3168', 'Remo en sentadilla con peso corporal', 'bodyweight squatting row', '["Sentadilla con remo corporal", "Remo corporal desde sentadilla", "bodyweight squatting row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja la espalda alta, los bíceps y los hombros. Combina una sentadilla con un movimiento de remo y requiere fuerza y coordinación.', '["Párate con los pies al ancho de los hombros y sujétate de un objeto firme o un sistema de entrenamiento en suspensión, con los brazos extendidos.", "Baja en sentadilla manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.", "Desde la sentadilla, jala el cuerpo hacia el objeto o el sistema de suspensión, juntando los omóplatos.", "Haz una breve pausa arriba y luego baja lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3168.gif'),
('3194', 'Sentadilla Frankenstein', 'frankenstein squat', '["Sentadilla con barra al frente", "Sentadilla con brazos extendidos", "frankenstein squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Variante de sentadilla en la que sostienes la barra frente al cuerpo con los brazos rectos. Trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas, con énfasis en la postura, la estabilidad del abdomen y la fuerza del tren inferior.', '["Párate con los pies al ancho de los hombros y sostén la barra frente al cuerpo con los brazos rectos.", "Mantén la espalda recta y baja flexionando las rodillas y la cadera, como si fueras a sentarte en una silla.", "Sigue bajando hasta que los muslos queden paralelos al suelo o hasta donde puedas hacerlo con comodidad.", "Haz una breve pausa y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3194.gif'),
('3211', 'Flexión con rodillas apoyadas (hombre)', 'kneeling push-up (male)', '["Flexión de rodillas", "Flexión de pecho con apoyo de rodillas", "kneeling push-up (male)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los pectorales y, de forma secundaria, los tríceps y los hombros. Se realiza con las rodillas apoyadas, como una variante más sencilla de la flexión tradicional para desarrollar fuerza básica en el tren superior.', '["Arrodíllate en el suelo y coloca las manos al ancho de los hombros, con los dedos hacia adelante.", "Extiende las piernas hacia atrás y apóyate sobre la parte delantera de los pies, formando una línea recta de la cabeza a los talones.", "Activa el abdomen y baja el cuerpo hacia el suelo flexionando los codos y manteniéndolos cerca de los costados.", "Baja hasta que el pecho quede justo por encima del suelo y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3211.gif'),
('3216', 'Flexión con toque de pecho (hombre)', 'chest tap push-up (male)', '["Flexión tocando el pecho", "Flexión con toque alternado", "chest tap push-up (male)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Flexión exigente con peso corporal que trabaja los pectorales, los tríceps y los hombros. Requiere fuerza, coordinación y equilibrio para sostener el cuerpo por un momento con una mano mientras tocas el pecho con la otra.', '["Colócate en plancha alta, con las manos un poco más separadas que el ancho de los hombros y el cuerpo en línea recta.", "Baja el cuerpo hacia el suelo flexionando los codos y manteniéndolos cerca de los costados.", "Mientras bajas, toca el pecho con la mano derecha.", "Empuja para volver a la posición inicial.", "Repite el movimiento y esta vez toca el pecho con la mano izquierda.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3216.gif'),
('3217', 'Flexión hindú modificada (hombre)', 'modified hindu push-up (male)', '["Flexión hindú adaptada", "Flexión con cadera elevada", "modified hindu push-up (male)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja los pectorales, los tríceps, los hombros y el abdomen. Combina una flexión con una posición similar a la del perro boca abajo, y exige fuerza y movilidad.', '["Colócate en posición de flexión, con las manos un poco más separadas que el ancho de los hombros y los pies al ancho de la cadera.", "Baja el cuerpo hacia el suelo flexionando los codos y manteniendo el abdomen activo.", "Mientras bajas, lleva el peso hacia atrás y eleva la cadera hacia el techo hasta formar una V invertida con el cuerpo.", "Sigue bajando hasta que el pecho quede justo por encima del suelo; luego invierte el movimiento, baja la cadera y extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3217.gif'),
('3222', 'Media sentadilla con salto (hombre)', 'semi squat jump (male)', '["Salto desde media sentadilla", "Sentadilla parcial con salto", "semi squat jump (male)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Cardio'), 'Cardio', 'Sistema cardiovascular', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Intermedio', 'Cardio', 'Ejercicio pliométrico que estimula el sistema cardiovascular y trabaja los cuádriceps, los isquiotibiales y las pantorrillas. Combina una sentadilla parcial con un salto explosivo para mejorar la condición cardiovascular, la potencia del tren inferior y la coordinación.', '["Párate con los pies al ancho de los hombros.", "Flexiona las rodillas y baja en sentadilla.", "Salta de forma explosiva, extendiendo la cadera y las rodillas mientras balanceas los brazos para impulsarte.", "Aterriza suavemente sobre la parte delantera de los pies y pasa de inmediato a la siguiente repetición.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3222.gif'),
('3281', 'Sentadilla completa en máquina Smith', 'smith full squat', '["Sentadilla profunda en Smith", "Sentadilla completa en barra guiada", "smith full squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio compuesto de tren inferior en máquina Smith que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, los isquiotibiales y las pantorrillas. La máquina aporta estabilidad para quienes aún no se sienten cómodos con las sentadillas con peso libre, aunque sigue siendo necesario mantener una buena técnica y el abdomen activo.', '["Ajusta la barra de la máquina Smith a la altura de los hombros.", "Párate con los pies al ancho de los hombros y las puntas ligeramente hacia afuera.", "Colócate debajo de la barra y apóyala sobre los trapecios, en la parte alta de la espalda.", "Sujeta la barra con las manos un poco más separadas que el ancho de los hombros.", "Desengancha la barra y da un paso hacia atrás, manteniendo una postura estable.", "Mantén el pecho levantado y el abdomen activo; comienza la sentadilla llevando la cadera hacia atrás y flexionando las rodillas.", "Baja hasta que los muslos queden paralelos al suelo o hasta donde te permita la flexibilidad.", "Haz una breve pausa abajo y luego empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3281.gif'),
('3287', 'Fondos de tríceps en banco', 'elbow dips', '["Fondos en silla", "Fondos con flexión de codos", "elbow dips"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para los tríceps que se realiza con un banco o una silla. Consiste en bajar y subir el cuerpo flexionando y extendiendo los codos, con la espalda cerca del banco.', '["Siéntate en el borde de un banco o una silla y sujeta el borde con las manos junto a la cadera.", "Desliza la cadera hacia adelante hasta sacarla del banco y estira las piernas, manteniendo los talones en el suelo.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.", "Haz una breve pausa abajo y luego empuja con las manos para extender los brazos y volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3287.gif'),
('3288', 'Fondos coreanos', 'korean dips', '["Fondos estilo coreano", "Fondos coreanos en paralelas", "korean dips"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal en barras paralelas que trabaja los pectorales, los tríceps y los hombros. Requiere mucha fuerza en el tren superior, movilidad de hombros y estabilidad para bajar profundamente entre las barras y volver a subir.', '["Colócate entre dos barras paralelas con los brazos extendidos, sosteniendo el peso del cuerpo.", "Baja flexionando los codos hasta que la parte superior de los brazos quede paralela al suelo.", "Haz una breve pausa y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3288.gif'),
('3289', 'Fondos imposibles', 'impossible dips', '["Fondos imposibles en paralelas", "Fondos avanzados para tríceps", "impossible dips"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Pecho", "Hombros"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio exigente con peso corporal entre barras paralelas que se enfoca en los tríceps y también trabaja el pecho y los hombros. Requiere mucha fuerza y control del tren superior, además de experiencia con variantes de fondos.', '["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido.", "Flexiona las rodillas y cruza los tobillos.", "Baja flexionando los codos hasta que la parte superior de los brazos quede paralela al suelo.", "Haz una breve pausa y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3289.gif'),
('3293', 'Dominada arquero', 'archer pull up', '["Dominada tipo arquero", "Dominada con un brazo extendido", "archer pull up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Dominada exigente con peso corporal que trabaja los dorsales y requiere mucha fuerza, coordinación y control. Consiste en subir flexionando un brazo mientras mantienes el otro recto, alternando los lados en cada repetición.', '["Cuélgate de una barra de dominadas con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Activa el abdomen y lleva los omóplatos hacia abajo y hacia atrás.", "Mientras subes, flexiona un brazo y acerca ese codo al costado, manteniendo el otro brazo recto.", "Sigue subiendo hasta que la barbilla quede por encima de la barra y el brazo que trabaja esté completamente flexionado.", "Baja de forma controlada, estira el brazo que flexionaste y repite el movimiento hacia el otro lado.", "Alterna los lados en cada repetición."]'::jsonb, '/gifs/3293.gif'),
('3294', 'Flexión arquero', 'archer push up', '["Flexión tipo arquero", "Flexión con un brazo extendido", "archer push up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Flexión exigente con peso corporal que trabaja los pectorales, los tríceps, los hombros y el abdomen. Al extender un brazo hacia un lado, aumenta la carga sobre el brazo que trabaja y exige más fuerza, equilibrio y coordinación.', '["Colócate en posición de flexión con las manos un poco más separadas que el ancho de los hombros.", "Extiende un brazo hacia un lado, paralelo al suelo.", "Baja el cuerpo flexionando los codos, con la espalda recta y el abdomen activo.", "Empuja para volver a la posición inicial.", "Repite hacia el otro lado, extendiendo el brazo contrario.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3294.gif'),
('3327', 'Flexión en plancha completa', 'full planche push-up', '["Flexión en planche", "Flexión sin apoyo de pies", "full planche push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps", "Core"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio avanzado con peso corporal que trabaja los pectorales, los hombros, los tríceps y el abdomen. Requiere mucha fuerza, equilibrio y coordinación para hacer una flexión manteniendo todo el cuerpo separado del suelo, sostenido únicamente por las manos.', '["Colócate en posición de flexión con las manos un poco más separadas que el ancho de los hombros.", "Activa el abdomen y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.", "Mientras bajas, inclina el cuerpo hacia adelante y levanta los pies del suelo, equilibrándote sobre las manos.", "Sigue bajando hasta que el pecho quede justo por encima del suelo.", "Empuja con las manos y extiende los brazos para volver a elevar el cuerpo hasta la posición inicial.", "Mantén el cuerpo alineado de la cabeza a los talones durante todo el movimiento.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3327.gif'),
('3418', 'Dominada en L', 'l-pull-up', '["Dominada con piernas al frente", "Dominada con piernas en L", "l-pull-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Antebrazos"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Dominada exigente con peso corporal que trabaja los dorsales, el abdomen, los bíceps y los antebrazos. Requiere mantener las piernas rectas al frente y paralelas al suelo, formando una L durante todo el movimiento.', '["Sujeta la barra de dominadas con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Cuélgate con los brazos completamente extendidos y el cuerpo recto.", "Activa los dorsales y los bíceps para subir hacia la barra, manteniendo los codos cerca del cuerpo.", "Sigue subiendo hasta que la barbilla quede por encima de la barra.", "Haz una breve pausa arriba y luego baja lentamente hasta volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3418.gif'),
('3470', 'Zancada hacia adelante (hombre)', 'forward lunge (male)', '["Desplante al frente", "Zancada frontal con peso corporal", "forward lunge (male)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en dar una zancada hacia adelante y volver a ponerse de pie, alternando las piernas.', '["Párate con los pies al ancho de la cadera y las manos en la cintura.", "Da un paso amplio hacia adelante con el pie derecho y baja en zancada.", "Flexiona la rodilla derecha hasta unos 90 grados, manteniéndola alineada con el tobillo.", "Impúlsate con el pie derecho para volver a la posición inicial.", "Repite con la pierna izquierda y alterna los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3470.gif'),
('3533', 'Cuádriceps (sentadilla con peso corporal)', 'quads (bodyweight squat)', '["Sentadilla sin pesas", "Sentadilla para cuádriceps", "quads (bodyweight squat)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Sentadilla con peso corporal que trabaja principalmente los cuádriceps y también activa los isquiotibiales y los glúteos. Es un movimiento básico para desarrollar fuerza en el tren inferior y se realiza sin equipo.', '["Párate con los pies al ancho de los hombros.", "Baja flexionando las rodillas y llevando la cadera hacia atrás, como si fueras a sentarte en una silla.", "Mantén el pecho levantado y la espalda recta.", "Baja hasta que los muslos queden paralelos al suelo.", "Empuja con los talones para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3533.gif'),
('3543', 'Sentadilla con salto y caída con peso corporal', 'bodyweight drop jump squat', '["Sentadilla con salto juntando los pies", "Salto con caída en sentadilla", "bodyweight drop jump squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Intermedio', 'Pliometría', 'Ejercicio pliométrico que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, los isquiotibiales y las pantorrillas. Combina saltos explosivos con movimientos rápidos de los pies y exige coordinación, potencia y fuerza del tren inferior.', '["Párate con los pies al ancho de los hombros.", "Baja en sentadilla flexionando las rodillas y llevando la cadera hacia atrás.", "Salta de forma explosiva, extendiendo la cadera, las rodillas y los tobillos.", "Mientras estás en el aire, junta rápidamente los pies.", "Aterriza suavemente sobre la parte delantera de los pies y baja de inmediato a una sentadilla.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3543.gif'),
('3547', 'Curl de bíceps y press de hombros sentado con mancuernas', 'dumbbell seated biceps curl to shoulder press', '["Curl y press sentado", "Bíceps y hombros con mancuernas", "dumbbell seated biceps curl to shoulder press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que combina un curl de bíceps con un press de hombros sentado. Trabaja los bíceps y los hombros para desarrollar fuerza en la parte superior de los brazos y los hombros.', '["Siéntate en un banco con la espalda recta y los pies bien apoyados en el suelo.", "Sostén una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.", "Mantén los codos cerca de los costados y flexiónalos para subir las mancuernas hacia los hombros.", "Cuando los antebrazos queden verticales, gira las muñecas para que las palmas miren hacia adelante.", "Empuja las mancuernas por encima de la cabeza hasta extender completamente los brazos.", "Invierte el movimiento para bajar las mancuernas hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3547.gif'),
('3582', 'Zancada con salto', 'lunge with jump', '["Desplante con salto", "Zancada alternada con salto", "lunge with jump"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Avanzado', 'Pliometría', 'Ejercicio dinámico de tren inferior que combina una zancada tradicional con un salto pliométrico. Trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas, y requiere equilibrio, coordinación y fuerza explosiva.', '["Párate con los pies al ancho de los hombros.", "Da un paso hacia adelante con el pie derecho y baja en zancada.", "Impúlsate con el pie derecho y salta, cambiando la posición de los pies en el aire.", "Aterriza suavemente con el pie izquierdo al frente y baja de inmediato en zancada.", "Sigue alternando zancadas y saltos hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3582.gif'),
('3635', 'Zancada hacia adelante con mancuerna contralateral', 'dumbbell contralateral forward lunge', '["Desplante con carga contralateral", "Zancada con mancuerna en la mano opuesta", "dumbbell contralateral forward lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de tren inferior que trabaja principalmente los glúteos y, de forma secundaria, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en dar una zancada hacia adelante sosteniendo una mancuerna en la mano opuesta a la pierna que avanza, lo que exige fuerza, equilibrio y coordinación.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano.", "Da un paso hacia adelante con el pie derecho, manteniendo la espalda recta y el abdomen activo.", "Baja flexionando ambas rodillas hasta que el muslo derecho quede paralelo al suelo.", "Empuja con el talón derecho para volver a la posición inicial.", "Repite con la pierna izquierda.", "Alterna las piernas hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3635.gif'),
('3655', 'Zancada caminando con rodillas altas', 'walking high knees lunge', '["Desplante caminando con elevación de rodilla", "Zancada con rodilla al pecho", "walking high knees lunge"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Cardio'), 'Cardio', 'Sistema cardiovascular', '["Cuádriceps", "Isquiotibiales", "Glúteos", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Principiante', 'Cardio', 'Ejercicio dinámico con peso corporal que combina elevaciones de rodilla con zancadas hacia adelante. Estimula el sistema cardiovascular y trabaja los cuádriceps, los isquiotibiales, los glúteos y las pantorrillas para mejorar la resistencia cardiovascular, la coordinación y la fuerza del tren inferior.', '["Párate con los pies al ancho de la cadera.", "Eleva la rodilla derecha hacia el pecho lo más que puedas, manteniendo el equilibrio sobre la pierna izquierda.", "Da un paso hacia adelante con el pie derecho y baja en zancada, flexionando ambas rodillas a 90 grados.", "Impúlsate con el pie derecho y eleva la rodilla izquierda hacia el pecho.", "Da un paso hacia adelante con el pie izquierdo y baja en zancada.", "Sigue avanzando y alternando las piernas, con el abdomen activo y a un ritmo constante.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3655.gif'),
('3662', 'Flexión de pica a cobra', 'pike-to-cobra push-up', '["Flexión de V invertida a cobra", "Flexión con transición a cobra", "pike-to-cobra push-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Core", "Hombros", "Tríceps"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio dinámico con peso corporal que combina una flexión, una posición de pica y la postura de cobra. Trabaja principalmente los glúteos y también el abdomen, los hombros y los tríceps. La transición entre la V invertida y la cobra exige fuerza, flexibilidad y coordinación.', '["Colócate en posición de flexión, con las manos un poco más separadas que el ancho de los hombros y los pies juntos.", "Activa el abdomen y eleva la cadera hacia el techo hasta formar una V invertida con el cuerpo.", "Baja el torso hacia el suelo flexionando los codos y manteniéndolos cerca del cuerpo.", "Mientras bajas, lleva el peso hacia adelante y pasa a la postura de cobra, extendiendo los brazos y levantando el pecho.", "Invierte el movimiento flexionando los codos y bajando el pecho hacia el suelo.", "Empuja con las manos para volver a la posición de V invertida.", "Continúa bajando la cadera hacia el suelo hasta volver a la posición inicial de flexión.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3662.gif'),
('3769', 'Sentadilla de reverencia', 'curtsey squat', '["Sentadilla cruzada", "Zancada de reverencia", "curtsey squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Cuádriceps", "Isquiotibiales", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio de tren inferior que trabaja los glúteos, los cuádriceps, los isquiotibiales y las pantorrillas. Consiste en cruzar una pierna en diagonal por detrás de la otra, flexionar ambas rodillas para bajar y volver a la posición inicial. También exige equilibrio y coordinación.', '["Párate con los pies al ancho de los hombros.", "Da un paso diagonal hacia atrás con el pie derecho, cruzándolo por detrás de la pierna izquierda.", "Flexiona ambas rodillas y baja el cuerpo como si hicieras una reverencia.", "Mantén el torso erguido y el peso sobre el pie de adelante.", "Empuja con el pie de adelante para volver a la posición inicial.", "Repite hacia el otro lado, dando un paso diagonal hacia atrás con el pie izquierdo y cruzándolo por detrás del cuerpo."]'::jsonb, '/gifs/3769.gif'),
('3785', 'Flexión inclinada (en caja)', 'incline push-up (on box)', '["Flexión con manos en caja", "Flexión con apoyo elevado", "incline push-up (on box)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja principalmente los pectorales y, de forma secundaria, los tríceps y los hombros. Se realiza apoyando las manos en una superficie elevada, como una caja, y haciendo una flexión.', '["Coloca las manos en el borde de una caja o superficie elevada, un poco más separadas que el ancho de los hombros.", "Extiende las piernas hacia atrás y apóyate sobre la parte delantera de los pies, formando una línea recta de la cabeza a los talones.", "Baja el pecho hacia la caja flexionando los codos y manteniendo el cuerpo en línea recta.", "Haz una breve pausa abajo y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/3785.gif'),
('3886', 'Complejo con mancuernas de flexión, remo, cargada y press', 'dumbbell complex push up row clean and press', '["Combinación de flexión, remo y press", "Flexión con remo y cargada con mancuernas", "dumbbell complex push up row clean and press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Pectorales", "Tríceps", "Dorsales", "Abdominales", "Cuádriceps", "Glúteos"]'::jsonb, 'Mancuerna', 'Avanzado', 'Fuerza', 'Desde una plancha alta sujetando dos mancuernas, haz una flexión y un remo con cada brazo. Luego realiza una cargada y un press por encima de la cabeza antes de volver a la plancha.', '["Coloca dos mancuernas en el suelo al ancho de los hombros y sujeta los mangos en plancha alta; separa los pies entre el ancho de la cadera y el de los hombros, activa el abdomen y mantén las muñecas alineadas.", "Baja en una flexión controlada, manteniendo el cuerpo alineado de la cabeza a los talones.", "Desplaza ligeramente el peso y haz un remo con la mancuerna derecha hacia las costillas sin girar el torso; vuelve a apoyarla en el suelo y repite con la izquierda.", "Con un salto o dando pasos, lleva los pies por fuera de las mancuernas, manteniendo la espalda recta y la cadera baja.", "Impúlsate con las piernas y la cadera para llevar las mancuernas a los hombros en una cargada; recíbelas en una sentadilla parcial con los codos hacia adelante.", "Ponte de pie y empuja las mancuernas por encima de la cabeza hasta extender completamente los brazos, sin levantar las costillas.", "Baja las mancuernas a los hombros y luego flexiona la cadera para colocarlas en el suelo, manteniendo la curvatura natural de la columna.", "Lleva los pies hacia atrás con un salto o dando pasos para volver a la plancha y comenzar la siguiente repetición."]'::jsonb, '/gifs/3886.gif'),
('4256', 'Sentadilla con bajada de escalón', 'stepdown squat', '["Bajada de escalón a una pierna", "Sentadilla unilateral en escalón", "stepdown squat"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Glúteos", "Isquiotibiales", "Pantorrillas", "Abductores", "Abdominales"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Párate sobre un escalón estable con una pierna de apoyo y el otro pie fuera del borde. Baja de forma controlada hasta tocar suavemente el suelo con el talón libre y luego impúlsate para volver a quedar erguido.', '["Párate erguido sobre un escalón firme de 15 a 30 cm de altura, con las puntas de los pies hacia adelante y las manos en la cintura o extendidas para mantener el equilibrio.", "Lleva todo el peso sobre la pierna de apoyo, manteniendo la pelvis nivelada y el abdomen activo.", "Flexiona la rodilla y la cadera de la pierna de apoyo para bajar, acercando el talón de la pierna libre al suelo por delante.", "Mantén la rodilla de apoyo alineada con el segundo y el tercer dedo del pie, sin dejar que se vaya hacia adentro.", "Toca suavemente el suelo con el talón libre sin pasarle el peso.", "Empuja con la parte media del pie y el talón de apoyo para extender la rodilla y la cadera y volver a la posición inicial.", "Completa todas las repeticiones de forma lenta y controlada, y luego cambia de pierna."]'::jsonb, '/gifs/4256.gif'),
('0022', 'Pullover y press con barra', 'barbell pullover to press', '["Pullover con empuje de barra", "Pullover combinado con press", "barbell pullover to press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Tríceps", "Pecho", "Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja los dorsales, los tríceps, el pecho y los hombros. Consiste en bajar una barra por detrás de la cabeza mientras estás acostado en un banco y luego empujarla de vuelta sobre el pecho.', '["Acuéstate boca arriba en un banco, con la cabeza en un extremo y los pies apoyados en el suelo.", "Sujeta la barra con agarre prono, con las palmas en dirección opuesta a ti, y extiende los brazos sobre el pecho.", "Mantén los brazos rectos y baja la barra por detrás de la cabeza describiendo un arco, hasta sentir un estiramiento en los dorsales.", "Haz una breve pausa y luego invierte el movimiento, empujando la barra hasta la posición inicial sobre el pecho.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0022.gif'),
('0023', 'Curl alternado de bíceps con barra', 'barbell alternate biceps curl', '["Curl de bíceps alterno con barra", "Bíceps alternados con barra", "barbell alternate biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los bíceps que se realiza de pie, levantando una barra con cada brazo de forma alternada. También trabaja los antebrazos de forma secundaria.', '["Párate erguido con los pies al ancho de los hombros y sostén una barra en cada mano, con las palmas hacia adelante.", "Mantén fija la parte superior de los brazos y exhala mientras flexionas los codos para subir las barras, contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las barras queden a la altura de los hombros.", "Haz una breve pausa arriba mientras aprietas los bíceps.", "Inhala mientras bajas lentamente las barras hasta la posición inicial.", "Repite alternando los brazos hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0023.gif'),
('0031', 'Curl con barra', 'barbell curl', '["Curl de bíceps con barra", "Bíceps de pie con barra", "barbell curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio clásico de fuerza para los bíceps que consiste en subir una barra desde los muslos hasta los hombros, manteniendo los codos cerca del torso.', '["Párate erguido con los pies al ancho de los hombros y sujeta una barra con agarre supino, con las palmas hacia adelante.", "Mantén los codos cerca del torso y exhala mientras flexionas los codos para subir la barra, contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y la barra quede a la altura de los hombros.", "Haz una breve pausa arriba mientras aprietas los bíceps.", "Inhala mientras bajas lentamente la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0031.gif'),
('0034', 'Pullover declinado con barra y brazos flexionados', 'barbell decline bent arm pullover', '["Pullover con codos flexionados en banco declinado", "Pullover con barra en declive", "barbell decline bent arm pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Tríceps", "Pecho"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto con barra en banco declinado que trabaja principalmente los dorsales y, de forma secundaria, los tríceps y el pecho. Requiere fuerza y control para bajar y subir la barra por detrás de la cabeza con seguridad y buena técnica.', '["Acuéstate en un banco declinado, con la cabeza más baja que la cadera y los pies asegurados.", "Sujeta una barra con agarre prono, con las palmas en dirección opuesta a ti, y extiende los brazos sobre el pecho.", "Baja la barra por detrás de la cabeza de forma controlada, manteniendo los brazos ligeramente flexionados.", "Haz una breve pausa y luego contrae los dorsales para subir la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0034.gif'),
('0037', 'Pullover declinado con barra y agarre amplio', 'barbell decline wide-grip pullover', '["Pullover con agarre ancho en banco declinado", "Pullover en declive con manos separadas", "barbell decline wide-grip pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Tríceps", "Pecho"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto con barra en banco declinado que trabaja los dorsales, los tríceps y el pecho. Consiste en bajar la barra por detrás de la cabeza con los brazos rectos y luego volver a la posición inicial.', '["Acuéstate en un banco declinado, con la cabeza más baja que la cadera y los pies asegurados.", "Sujeta una barra con agarre amplio y extiende los brazos sobre el pecho.", "Baja la barra por detrás de la cabeza de forma controlada, manteniendo los brazos rectos.", "Haz una breve pausa y luego sube la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0037.gif'),
('0038', 'Curl de arrastre con barra', 'barbell drag curl', '["Curl con codos atrás", "Curl arrastrado para bíceps", "barbell drag curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio enfocado en los bíceps que consiste en subir una barra manteniendo los codos hacia atrás para enfatizar la contracción y reducir la participación de los hombros. También trabaja los antebrazos de forma secundaria.', '["Párate con los pies al ancho de los hombros y sujeta una barra con agarre supino, con las palmas hacia arriba.", "Deja la barra frente a los muslos con los brazos extendidos.", "Mantén fija la parte superior de los brazos y contrae los bíceps para flexionar los codos y subir la barra hacia el pecho.", "Haz una breve pausa arriba y luego baja lentamente la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0038.gif'),
('0040', 'Elevación frontal y pullover con barra', 'barbell front raise and pullover', '["Elevación de hombros y pullover", "Elevación al frente y pase detrás de la cabeza", "barbell front raise and pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja los pectorales y, de forma secundaria, los deltoides y tríceps. Combina una elevación de barra al frente con un pullover detrás de la cabeza, y requiere fuerza, coordinación y movilidad de hombros.', '["Párate con los pies al ancho de los hombros y sujeta una barra con agarre prono, con las palmas hacia abajo.", "Mantén los brazos rectos y eleva la barra frente a ti hasta la altura de los hombros.", "Haz una breve pausa arriba y luego baja lentamente la barra a la posición inicial.", "Después, baja la barra detrás de la cabeza, manteniendo los brazos rectos.", "Haz una breve pausa abajo y luego vuelve a subir la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0040.gif'),
('0041', 'Elevación frontal con barra', 'barbell front raise', '["Elevación de hombros al frente", "Elevación anterior con barra", "barbell front raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Bíceps", "Tríceps"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides al elevar una barra desde los muslos hasta la altura de los hombros con los brazos rectos.', '["Párate con los pies al ancho de los hombros y sujeta una barra frente a los muslos con agarre prono.", "Mantén los brazos rectos y eleva la barra hacia adelante y arriba hasta la altura de los hombros.", "Haz una breve pausa arriba y luego baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0041.gif'),
('0056', 'Extensión de tríceps acostado con barra y agarre cerrado', 'barbell lying close-grip triceps extension', '["Press francés con agarre cerrado", "Tríceps en banco con barra y agarre estrecho", "barbell lying close-grip triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los tríceps que se realiza acostado en un banco, con una barra y agarre cerrado. Favorece el desarrollo de los tríceps y también involucra los hombros de forma secundaria.', '["Acuéstate boca arriba en un banco, con los pies apoyados en el suelo y la cabeza en un extremo del banco.", "Sujeta la barra con agarre cerrado, las manos al ancho de los hombros y las palmas hacia arriba.", "Estira por completo los brazos para elevar la barra sobre el pecho.", "Sin mover la parte superior de los brazos, dobla los codos y baja lentamente la barra hacia la frente.", "Haz una breve pausa abajo y luego estira los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0056.gif'),
('0057', 'Extensión acostado con barra', 'barbell lying extension', '["Press francés con barra", "Rompecráneos con barra", "barbell lying extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los tríceps, también conocido como rompecráneos. Se realiza acostado en un banco, bajando una barra hacia la frente al doblar los codos y luego estirando los brazos para subirla.', '["Acuéstate boca arriba en un banco, con los pies apoyados en el suelo y la cabeza en un extremo del banco.", "Sujeta la barra con agarre prono y las manos al ancho de los hombros, y estira los brazos hacia arriba sobre el pecho.", "Sin mover la parte superior de los brazos, dobla los codos y baja lentamente la barra hacia la frente.", "Haz una breve pausa y luego estira los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0057.gif'),
('0059', 'Curl predicador acostado con barra', 'barbell lying preacher curl', '["Curl Scott acostado con barra", "Bíceps en banco predicador con barra", "barbell lying preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza en un banco predicador para reducir la participación de los hombros y concentrar el trabajo en los bíceps.', '["Siéntate en un banco predicador con el pecho contra la almohadilla y los brazos extendidos sobre el borde, sujetando una barra con agarre supino.", "Sin mover la parte superior de los brazos, exhala y dobla los codos para subir la barra mientras contraes los bíceps.", "Sigue subiendo la barra hasta contraer por completo los bíceps y llevarla a la altura de los hombros.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala y baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0059.gif'),
('0060', 'Rompecráneos con barra', 'barbell lying triceps extension skull crusher', '["Press francés acostado con barra", "Extensión de tríceps en banco con barra", "barbell lying triceps extension skull crusher"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los tríceps, también conocido como extensión de tríceps acostado. Consiste en bajar una barra hacia la frente y volver a subirla estirando los brazos, acostado en un banco. Requiere control y buena técnica para evitar lesiones.', '["Acuéstate boca arriba en un banco, con los pies apoyados en el suelo y la cabeza en un extremo del banco.", "Sujeta la barra con agarre prono y las manos al ancho de los hombros, y estira los brazos hacia arriba sobre el pecho.", "Sin mover la parte superior de los brazos, dobla los codos y baja lentamente la barra hacia la frente.", "Haz una breve pausa cuando la barra quede justo encima de la frente y luego estira los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0060.gif'),
('0061', 'Extensión de tríceps acostado con barra', 'barbell lying triceps extension', '["Press francés con barra", "Rompecráneos en banco", "barbell lying triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los tríceps que se realiza acostado en un banco, bajando una barra hacia la frente y luego estirando los brazos para volver a subirla.', '["Acuéstate boca arriba en un banco, con los pies apoyados en el suelo y la cabeza en un extremo del banco.", "Sujeta la barra con agarre prono y las manos al ancho de los hombros, y estira los brazos hacia arriba sobre el pecho.", "Sin mover la parte superior de los brazos, dobla los codos y baja lentamente la barra hacia la frente.", "Haz una breve pausa abajo y luego estira los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0061.gif'),
('0070', 'Curl predicador con barra', 'barbell preacher curl', '["Curl Scott con barra", "Bíceps con barra en banco predicador", "barbell preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que utiliza un banco predicador para estabilizar la parte superior de los brazos, reducir el movimiento de los hombros y concentrar el esfuerzo en los bíceps. Se realiza con barra y ayuda a aumentar su fuerza y tamaño.', '["Siéntate en un banco predicador con la parte superior de los brazos sobre la almohadilla y el pecho contra el soporte.", "Sujeta la barra con agarre supino y las manos un poco más separadas que el ancho de los hombros.", "Sin mover la parte superior de los brazos, exhala y dobla los codos para subir la barra hacia los hombros.", "Haz una breve pausa arriba y aprieta los bíceps.", "Inhala y baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0070.gif'),
('0072', 'Curl con barra boca abajo en banco inclinado', 'barbell prone incline curl', '["Curl araña con barra", "Curl de bíceps con pecho apoyado", "barbell prone incline curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio para los bíceps que se realiza boca abajo en un banco inclinado. Esta posición aísla los bíceps y limita el uso de impulso o balanceo. También involucra los antebrazos de forma secundaria.', '["Ajusta un banco inclinado a 45 grados.", "Acuéstate boca abajo en el banco, con el pecho y el abdomen apoyados.", "Sujeta una barra con agarre supino y las manos al ancho de los hombros.", "Estira por completo los brazos y deja que la barra cuelgue hacia el suelo.", "Sin mover la parte superior de los brazos, exhala y dobla los codos para subir la barra mientras contraes los bíceps.", "Sigue subiendo la barra hasta contraer por completo los bíceps y llevarla a la altura de los hombros.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala y baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0072.gif'),
('0073', 'Pullover con barra', 'barbell pullover', '["Pase de barra detrás de la cabeza", "Pullover para dorsales con barra", "barbell pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Pecho", "Tríceps"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza que trabaja los dorsales y también involucra el pecho y los tríceps. Se realiza acostado en un banco, moviendo una barra en arco desde encima del pecho hasta detrás de la cabeza para estirar y contraer los músculos del tren superior.', '["Acuéstate boca arriba en un banco, con la cabeza en un extremo y los pies en el suelo.", "Sujeta una barra con las manos al ancho de los hombros y estira los brazos sobre el pecho.", "Mantén los brazos rectos y baja la barra detrás de la cabeza de forma controlada hasta sentir un estiramiento en los dorsales.", "Haz una breve pausa y luego vuelve a subir la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0073.gif'),
('0079', 'Curl inverso de muñeca con barra (variante 2)', 'barbell reverse wrist curl v. 2', '["Extensión de muñecas con barra, variante 2", "Antebrazo con barra y palmas abajo, variante 2", "barbell reverse wrist curl v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los músculos extensores. Se realiza sentado, con los antebrazos sobre los muslos, elevando una barra mediante el movimiento de las muñecas con agarre prono.', '["Siéntate en un banco con los pies apoyados en el suelo y las rodillas dobladas.", "Sujeta una barra con agarre prono, las palmas hacia abajo y las manos al ancho de los hombros.", "Apoya los antebrazos sobre los muslos y deja las muñecas fuera del borde.", "Mantén los antebrazos fijos, exhala y eleva las manos desde las muñecas todo lo que puedas.", "Mantén la contracción un momento y luego inhala mientras bajas lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0079.gif'),
('0080', 'Curl inverso con barra', 'barbell reverse curl', '["Curl de bíceps con agarre prono", "Curl con barra y palmas abajo", "barbell reverse curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio para los bíceps y antebrazos que consiste en levantar una barra flexionando los codos con agarre prono.', '["Párate erguido con los pies al ancho de los hombros y sujeta una barra con agarre prono, con las palmas hacia abajo.", "Mantén fija la parte superior de los brazos y exhala mientras doblas los codos para subir la barra, contrayendo los bíceps.", "Sigue subiendo la barra hasta contraer por completo los bíceps y llevarla a la altura de los hombros.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala mientras bajas lentamente la barra a la posición inicial, sin mover la parte superior de los brazos.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0080.gif'),
('0081', 'Curl predicador inverso con barra', 'barbell reverse preacher curl', '["Curl Scott con agarre prono", "Curl inverso en banco predicador", "barbell reverse preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps y antebrazos. Se realiza en un banco predicador con agarre prono y enfatiza el trabajo del braquial y los extensores del antebrazo.', '["Siéntate en un banco predicador con el pecho contra la almohadilla y los brazos extendidos hacia abajo, sujetando una barra con agarre prono.", "Sin mover la parte superior de los brazos, exhala y dobla los codos para subir la barra mientras contraes los bíceps.", "Sigue subiendo la barra hasta contraer por completo los bíceps y llevarla a la altura de los hombros.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala y baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0081.gif'),
('0082', 'Curl inverso de muñeca con barra', 'barbell reverse wrist curl', '["Extensión de muñecas con barra", "Antebrazo con barra y palmas abajo", "barbell reverse wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los extensores de la muñeca. Se realiza sentado, con los antebrazos sobre los muslos, elevando una barra mediante el movimiento de las muñecas con agarre prono.', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una barra con agarre prono, con las palmas hacia abajo.", "Apoya los antebrazos sobre los muslos y deja las muñecas fuera del borde.", "Eleva lentamente las manos desde las muñecas para acercar la barra al cuerpo.", "Haz una breve pausa arriba y luego baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0082.gif'),
('0088', 'Elevación de pantorrillas sentado con barra', 'barbell seated calf raise', '["Elevación de talones sentado con barra", "Pantorrillas con barra sobre los muslos", "barbell seated calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Cuádriceps"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio para las pantorrillas que se realiza sentado, elevando una barra apoyada sobre los muslos mediante el movimiento de los talones. Se enfoca en fortalecer las pantorrillas y también involucra los isquiotibiales y cuádriceps de forma secundaria.', '["Siéntate en un banco con los pies apoyados en el suelo y una barra sobre los muslos.", "Apoya la parte delantera de los pies en una plataforma elevada, como un bloque o un escalón.", "Acomoda la barra sobre los muslos y sujétala firmemente con las manos.", "Mantén la espalda recta y el abdomen firme, y extiende los tobillos para elevar los talones.", "Haz una breve pausa arriba y luego baja lentamente los talones a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0088.gif'),
('0089', 'Curl concentrado sentado con barra y agarre cerrado', 'barbell seated close-grip concentration curl', '["Curl de concentración con barra", "Bíceps sentado con agarre estrecho", "barbell seated close-grip concentration curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza sentado, con una barra y agarre cerrado. Apoyar la parte superior de los brazos contra la cara interna de los muslos ayuda a mantener una técnica estricta y concentrar la contracción en los bíceps.', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una barra con agarre supino y las manos al ancho de los hombros.", "Apoya la parte superior de los brazos contra la cara interna de los muslos, justo encima de las rodillas, y deja que la barra cuelgue frente a ti.", "Sin mover la parte superior de los brazos, exhala y dobla los codos para subir la barra hacia los hombros, contrayendo los bíceps.", "Mantén la contracción un momento y luego inhala mientras bajas lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0089.gif'),
('0092', 'Extensión de tríceps sentado sobre la cabeza con barra', 'barbell seated overhead triceps extension', '["Press francés sentado con barra", "Tríceps sentado con barra detrás de la cabeza", "barbell seated overhead triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio para los tríceps que consiste en extender los brazos sobre la cabeza estando sentado, usando una barra como resistencia. También involucra los hombros de forma secundaria.', '["Siéntate en un banco con la espalda recta y los pies apoyados en el suelo.", "Sujeta una barra con agarre prono y las manos al ancho de los hombros, y elévala sobre la cabeza.", "Dobla los codos para bajar la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de ella.", "Haz una breve pausa y luego estira los brazos para volver a subir la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0092.gif'),
('0095', 'Encogimiento de hombros con barra', 'barbell shrug', '["Elevación de hombros con barra", "Trapecios con barra", "barbell shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los trapecios. Consiste en elevar los hombros hacia las orejas mientras sostienes una barra, para fortalecer la parte superior de la espalda y el cuello.', '["Párate con los pies al ancho de los hombros y sujeta una barra frente a ti con agarre prono.", "Mantén los brazos y la espalda rectos durante todo el ejercicio.", "Eleva los hombros hacia las orejas todo lo que puedas y aprieta los trapecios arriba.", "Mantén la posición un momento y luego baja lentamente los hombros a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0095.gif'),
('0104', 'Curl inverso de muñeca de pie con barra', 'barbell standing back wrist curl', '["Extensión de muñecas de pie con barra", "Antebrazo de pie con agarre prono", "barbell standing back wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Hombros"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los extensores de la muñeca. Se realiza de pie, elevando la barra únicamente con el movimiento de las muñecas.', '["Párate erguido con los pies al ancho de los hombros y sujeta una barra con agarre prono.", "Apoya la barra sobre el dorso de las manos, con las palmas hacia abajo y los dedos apuntando hacia tu cuerpo.", "Mantén fija la parte superior de los brazos, exhala y eleva las manos desde las muñecas todo lo que puedas.", "Mantén la contracción un momento y luego inhala mientras bajas lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0104.gif'),
('0106', 'Curl de pie con barra y agarre cerrado', 'barbell standing close grip curl', '["Curl de bíceps con agarre estrecho", "Bíceps con barra y manos juntas", "barbell standing close grip curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los bíceps que también trabaja los antebrazos. Consiste en levantar una barra flexionando los codos con agarre cerrado, con énfasis en la parte interna de los bíceps.', '["Párate erguido con los pies al ancho de los hombros y sujeta una barra con agarre supino y las manos juntas.", "Mantén los codos cerca del torso y la parte superior de los brazos fija durante todo el movimiento.", "Exhala mientras doblas los codos y subes la barra contrayendo los bíceps. Continúa hasta contraerlos por completo y llevar la barra a la altura de los hombros.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala mientras bajas lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0106.gif'),
('0107', 'Elevación frontal de pie sobre la cabeza con barra', 'barbell standing front raise over head', '["Elevación de barra al frente y arriba", "Elevación frontal por encima de la cabeza", "barbell standing front raise over head"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Espalda alta"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides y, de forma secundaria, los tríceps y la parte superior de la espalda. Consiste en elevar una barra desde los muslos hasta encima de la cabeza estando de pie, y requiere control y fuerza de hombros.', '["Párate con los pies al ancho de los hombros y sujeta una barra frente a los muslos con agarre prono.", "Mantén la espalda recta y el abdomen firme.", "Eleva lentamente la barra frente a ti, con los brazos rectos y las palmas hacia abajo.", "Sigue elevando la barra hasta que quede un poco por encima de la altura de los hombros.", "Haz una breve pausa arriba y luego baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0107.gif'),
('0108', 'Elevación de pantorrillas de pie con barra', 'barbell standing leg calf raise', '["Elevación de talones con barra", "Pantorrillas de pie con barra en la espalda", "barbell standing leg calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para las pantorrillas. Se realiza de pie, con una barra sobre la parte superior de la espalda, elevando los talones del suelo para activar las pantorrillas.', '["Párate con los pies al ancho de los hombros y coloca una barra sobre la parte superior de la espalda.", "Usa las pantorrillas para elevar los talones del suelo todo lo que puedas.", "Haz una breve pausa arriba y luego baja lentamente los talones a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0108.gif'),
('0109', 'Extensión de tríceps de pie sobre la cabeza con barra', 'barbell standing overhead triceps extension', '["Press francés de pie con barra", "Tríceps de pie con barra detrás de la cabeza", "barbell standing overhead triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los tríceps que se realiza de pie, sosteniendo una barra sobre la cabeza, bajándola detrás de ella y luego estirando los brazos para volver a la posición inicial.', '["Párate con los pies al ancho de los hombros y sujeta una barra con agarre prono.", "Eleva la barra sobre la cabeza y estira por completo los brazos.", "Mantén la parte superior de los brazos cerca de la cabeza y dobla los codos para bajar lentamente la barra detrás de ella.", "Haz una breve pausa y luego estira los brazos para volver a subir la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0109.gif'),
('0110', 'Curl de pie con barra y agarre inverso', 'barbell standing reverse grip curl', '["Curl de bíceps de pie con agarre invertido", "Curl de brazos con barra de pie", "barbell standing reverse grip curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio para los bíceps y antebrazos. Se realiza sujetando una barra con agarre supino, levantándola al doblar los codos mientras estos permanecen cerca del torso y luego bajándola de nuevo.', '["Párate erguido con los pies al ancho de los hombros y sujeta una barra con agarre supino, con las palmas hacia arriba.", "Mantén los codos cerca del torso y la parte superior de los brazos fija.", "Exhala y dobla los codos mientras contraes los bíceps, acercando la barra a los hombros todo lo que puedas.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala y baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0110.gif'),
('0111', 'Elevación de pantorrillas de pie con balanceo y barra', 'barbell standing rocking leg calf raise', '["Elevación de talones con balanceo y barra", "Pantorrillas con barra y balanceo", "barbell standing rocking leg calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Cuádriceps"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio para las pantorrillas que consiste en elevar los talones mientras mantienes una barra equilibrada sobre la parte superior de la espalda. También involucra los isquiotibiales y cuádriceps de forma secundaria.', '["Párate con los pies al ancho de los hombros y sostén una barra sobre la parte superior de la espalda.", "Eleva los talones del suelo todo lo que puedas, manteniendo el equilibrio sobre la parte delantera de los pies.", "Baja lentamente los talones a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0111.gif'),
('0113', 'Curl de pie con barra y agarre amplio', 'barbell standing wide-grip curl', '["Curl de bíceps con agarre abierto", "Bíceps con barra y manos separadas", "barbell standing wide-grip curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos", "Hombros"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio para los bíceps que se realiza con una barra y las manos más separadas que el ancho de los hombros. Esta variante enfatiza la parte externa de los bíceps y también involucra los antebrazos y hombros.', '["Párate erguido con los pies al ancho de los hombros y sujeta una barra con agarre prono y las manos más separadas que el ancho de los hombros.", "Deja la barra colgando frente a los muslos, con los brazos extendidos y las palmas orientadas hacia afuera del cuerpo.", "Sin mover la parte superior de los brazos, exhala y dobla los codos para subir la barra contrayendo los bíceps.", "Sigue subiendo la barra hasta contraer por completo los bíceps y llevarla a la altura de los hombros.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala y baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0113.gif'),
('0125', 'Curl de muñeca con barra (variante 2)', 'barbell wrist curl v. 2', '["Flexión de muñecas con barra, variante 2", "Antebrazo con barra y palmas arriba, variante 2", "barbell wrist curl v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los flexores de la muñeca. Se realiza sentado, con los antebrazos sobre los muslos y las muñecas fuera del borde, elevando una barra únicamente con el movimiento de las muñecas.', '["Siéntate en un banco con los pies apoyados en el suelo y las rodillas dobladas.", "Sujeta una barra con agarre supino, las palmas hacia arriba y las manos al ancho de los hombros.", "Apoya los antebrazos sobre los muslos y deja las muñecas fuera del borde.", "Flexiona lentamente las muñecas hacia arriba para acercar la barra a los antebrazos.", "Haz una breve pausa arriba y luego baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0125.gif'),
('0126', 'Curl de muñeca con barra', 'barbell wrist curl', '["Flexión de muñecas con barra", "Antebrazo con barra y palmas arriba", "barbell wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los flexores de la muñeca. Se realiza sentado, con los antebrazos sobre los muslos, elevando una barra mediante la flexión de las muñecas.', '["Siéntate en un banco con los pies apoyados en el suelo y los antebrazos sobre los muslos, sujetando una barra con agarre supino.", "Deja que la barra ruede hasta las puntas de los dedos, manteniendo las muñecas rectas.", "Flexiona lentamente las muñecas para subir la barra hacia los antebrazos.", "Haz una breve pausa arriba y luego baja lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0126.gif'),
('0130', 'Extensión de cadera en banco', 'bench hip extension', '["Elevación de cadera en banco", "Puente de glúteos con apoyo en banco", "bench hip extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para los glúteos e isquiotibiales. Consiste en levantar la cadera de un banco hasta formar una línea recta desde las rodillas hasta los hombros, con énfasis en la activación de los glúteos y la fuerza de extensión de cadera.', '["Siéntate en un banco con la espalda apoyada contra él y los pies apoyados en el suelo.", "Coloca las manos sobre el banco para apoyarte.", "Activa los glúteos y los isquiotibiales, y levanta la cadera del banco hasta formar una línea recta desde las rodillas hasta los hombros.", "Haz una breve pausa arriba y luego baja lentamente la cadera a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0130.gif'),
('0149', 'Extensión alternada de tríceps en polea', 'cable alternate triceps extension', '["Tríceps a un brazo alternado en polea", "Extensión de codo alternada en polea", "cable alternate triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que utiliza una máquina de poleas. Consiste en extender el codo sin mover la parte superior del brazo, alternando entre ambos brazos.', '["Párate frente a la máquina de poleas con los pies al ancho de los hombros.", "Sujeta la manija con la mano derecha y eleva el brazo hasta que la parte superior quede paralela al suelo, con el codo doblado a 90 grados.", "Mantén fija la parte superior del brazo y lleva el antebrazo hacia atrás hasta estirar el brazo por completo.", "Haz una breve pausa y luego vuelve lentamente a la posición inicial.", "Repite con el brazo izquierdo.", "Sigue alternando los brazos hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0149.gif'),
('0152', 'Extensión concentrada de tríceps en polea (sobre la rodilla)', 'cable concentration extension (on knee)', '["Tríceps en polea con codo apoyado en la rodilla", "Extensión de codo concentrada en polea", "cable concentration extension (on knee)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza sentado con una polea. El codo del brazo que trabaja se apoya contra la cara interna de la rodilla para estabilizar el movimiento y concentrar el esfuerzo en la extensión del tríceps.', '["Siéntate en un banco o una silla con las rodillas dobladas y los pies apoyados en el suelo.", "Sujeta la manija de la polea con la mano derecha y apoya el codo en la cara interna de la rodilla derecha.", "Estira por completo el brazo, manteniendo el codo fijo y cerca de la rodilla.", "Haz una breve pausa al terminar la extensión y luego baja lentamente el brazo a la posición inicial.", "Completa las repeticiones deseadas y luego cambia de lado."]'::jsonb, '/gifs/0152.gif'),
('0154', 'Aperturas inversas en poleas cruzadas', 'cable cross-over reverse fly', '["Aperturas para hombro posterior en polea", "Pájaros en poleas cruzadas", "cable cross-over reverse fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Romboides", "Trapecio"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores que también trabaja los romboides y trapecios de forma secundaria. Se realiza en una máquina de poleas cruzadas y requiere buena postura, control y coordinación.', '["Coloca una manija en D en cada polea baja y párate en el centro de la máquina de poleas cruzadas.", "Sujeta las manijas con agarre prono, con las palmas hacia abajo, y da un paso al frente, dejando los pies al ancho de los hombros.", "Dobla ligeramente las rodillas e inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y el abdomen firme.", "Con los brazos abiertos a los lados y los codos ligeramente doblados, exhala y junta los omóplatos mientras jalas las poleas hacia atrás y arriba en una apertura inversa.", "Haz una breve pausa en el punto de máxima contracción y luego inhala mientras vuelves lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0154.gif'),
('0158', 'Aperturas declinadas en polea', 'cable decline fly', '["Aperturas de pecho en ángulo declinado", "Pecho inferior en polea", "cable decline fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los pectorales que utiliza una máquina de poleas ajustada a un ángulo declinado. Enfatiza la parte inferior del pecho mediante movimientos controlados de los brazos para estirar y contraer los pectorales.', '["Ajusta la máquina de poleas para trabajar en un ángulo declinado.", "Párate de espaldas a la máquina con los pies al ancho de los hombros.", "Sujeta las manijas con las palmas hacia adelante y los brazos extendidos frente a ti.", "Mantén los codos ligeramente doblados y abre los brazos hacia los lados de forma controlada.", "Haz una breve pausa al completar la apertura y luego vuelve lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0158.gif'),
('0162', 'Elevación frontal en polea', 'cable front raise', '["Elevación anterior en polea", "Hombro frontal con polea", "cable front raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Tríceps", "Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides, especialmente su porción anterior. Consiste en elevar la manija de una polea frente al cuerpo hasta la altura de los hombros, con énfasis en el control y la activación muscular.', '["Párate con los pies al ancho de los hombros y sujeta la manija de la polea con agarre prono.", "Mantén la espalda recta y el abdomen firme.", "Eleva la manija frente a ti, manteniendo los brazos rectos y las palmas hacia abajo.", "Sigue elevando hasta que los brazos queden paralelos al suelo.", "Haz una breve pausa arriba y luego baja lentamente la manija a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0162.gif'),
('0165', 'Curl martillo en polea (con cuerda)', 'cable hammer curl (with rope)', '["Curl de bíceps con cuerda", "Martillo de bíceps en polea", "cable hammer curl (with rope)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps y antebrazos que se realiza en una máquina de poleas con cuerda. Enfatiza el trabajo del braquial y el braquiorradial, manteniendo tensión constante durante todo el movimiento.', '["Párate erguido con los pies al ancho de los hombros y las rodillas ligeramente dobladas.", "Sujeta la cuerda de la polea por debajo, con las palmas enfrentadas y los brazos completamente extendidos.", "Sin mover la parte superior de los brazos, exhala y dobla los codos para subir la cuerda mientras contraes los bíceps.", "Sigue subiendo la cuerda hasta contraer por completo los bíceps y llevarla a la altura de los hombros.", "Mantén la posición un momento mientras aprietas los bíceps.", "Inhala y baja lentamente la cuerda a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0165.gif'),
('0170', 'Aperturas inclinadas en polea (sobre pelota de estabilidad)', 'cable incline fly (on stability ball)', '["Aperturas de pecho con poleas en pelota", "Aperturas inclinadas en balón de estabilidad", "cable incline fly (on stability ball)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Avanzado', 'Fuerza', 'Ejercicio de aislamiento para el pecho que combina poleas y una pelota de estabilidad, involucrando también el abdomen y los músculos estabilizadores. La inestabilidad de la pelota exige mayor equilibrio y coordinación.', '["Coloca una pelota de estabilidad en un ángulo inclinado.", "Coloca las manijas en las poleas altas de la máquina.", "Siéntate sobre la pelota de estabilidad de espaldas a la máquina, con los pies firmemente apoyados en el suelo.", "Sujeta las manijas con agarre prono y las palmas hacia adelante.", "Inclina el torso ligeramente hacia adelante, manteniendo la espalda recta y el abdomen firme.", "Abre los brazos hacia los lados de forma controlada, manteniendo los codos ligeramente doblados.", "Continúa hasta que los brazos queden paralelos al suelo.", "Haz una breve pausa y luego vuelve lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0170.gif'),
('0171', 'Aperturas inclinadas en polea', 'cable incline fly', '["Aperturas de pecho en banco inclinado con poleas", "Pecho superior con aperturas en polea", "cable incline fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para la parte superior del pecho que utiliza una máquina de poleas. Consiste en abrir y cerrar los brazos estando acostado en un banco inclinado, manteniendo tensión constante durante todo el movimiento.', '["Ajusta las poleas a una posición baja y coloca las manijas.", "Siéntate en un banco inclinado con la espalda contra el respaldo y los pies apoyados en el suelo.", "Sujeta las manijas con agarre prono y extiende los brazos frente a ti.", "Mantén los codos ligeramente doblados y abre los brazos hacia los lados de forma controlada.", "Haz una breve pausa al completar la apertura y luego vuelve lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0171.gif'),
('0172', 'Jalón inclinado en polea', 'cable incline pushdown', '["Jalón de dorsales con torso inclinado", "Jalón hacia los muslos en polea", "cable incline pushdown"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Tríceps", "Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los dorsales que se realiza en una máquina de poleas con barra recta. Requiere movimientos controlados y buena técnica para activar los dorsales; también involucra los tríceps y hombros de forma secundaria.', '["Coloca una barra recta en una polea alta.", "Párate de espaldas a la máquina con los pies al ancho de los hombros.", "Sujeta la barra con agarre prono y las manos un poco más separadas que el ancho de los hombros.", "Inclina el torso ligeramente hacia adelante y mantén la espalda recta.", "Lleva la barra hacia abajo, en dirección a los muslos, estirando los codos.", "Haz una breve pausa abajo y luego devuelve lentamente la barra a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0172.gif'),
('0173', 'Extensión inclinada de tríceps en polea', 'cable incline triceps extension', '["Tríceps en polea con torso inclinado", "Extensión de tríceps sobre la cabeza en polea", "cable incline triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que utiliza una máquina de poleas. Se realiza de pie y de espaldas a la máquina, extendiendo los brazos sobre la cabeza para concentrar el trabajo en los tríceps.', '["Ajusta la polea a una posición baja.", "Coloca una barra recta en la polea.", "Párate de espaldas a la máquina con los pies al ancho de los hombros.", "Sujeta la barra con agarre prono y estira los brazos sobre la cabeza.", "Inclina el torso ligeramente hacia adelante, manteniendo la espalda recta y el abdomen firme.", "Dobla los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.", "Haz una breve pausa y luego estira los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0173.gif'),
('0175', 'Abdominal (crunch) de rodillas en polea', 'cable kneeling crunch', '["Crunch con cuerda de rodillas", "Abdominales arrodillado en polea alta", "cable kneeling crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio abdominal que se realiza en una máquina de poleas con cuerda. Trabaja el abdomen y también involucra los oblicuos. Consiste en arrodillarse, sostener la cuerda detrás de la cabeza y flexionar el tronco hacia los muslos.', '["Coloca una cuerda en una polea alta y arrodíllate de espaldas a la máquina.", "Sujeta la cuerda con ambas manos y colócala detrás de la cabeza, manteniendo los codos hacia los lados.", "Mantén la cadera fija y flexiona el tronco para acercarlo a los muslos, contrayendo el abdomen.", "Haz una breve pausa abajo y luego vuelve lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0175.gif'),
('0176', 'Extensión de tríceps de rodillas en polea', 'cable kneeling triceps extension', '["Tríceps arrodillado con cuerda", "Extensión de codos de rodillas", "cable kneeling triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza de rodillas frente a una polea alta, extendiendo los brazos contra la resistencia.', '["Coloca una cuerda en la polea alta y arrodíllate frente a la máquina.", "Sujeta la cuerda con un agarre neutro, con las palmas enfrentadas, y lleva las manos a los lados de la cabeza.", "Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.", "Contrae los tríceps y extiende los codos hasta estirar completamente los brazos.", "Haz una breve pausa y luego flexiona lentamente los codos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0176.gif'),
('0178', 'Elevación lateral en polea', 'cable lateral raise', '["Elevaciones de hombros con polea", "Laterales para deltoides", "cable lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides, especialmente su porción lateral o media. La polea mantiene una tensión constante durante el movimiento y ayuda a desarrollar la anchura y la fuerza de los hombros.', '["Ponte de pie con los pies al ancho de los hombros y sujeta los agarres de las poleas con un agarre prono.", "Mantén los brazos rectos y el abdomen firme.", "Eleva los brazos hacia los lados hasta que queden paralelos al piso.", "Haz una breve pausa arriba y luego baja lentamente los brazos hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0178.gif'),
('0179', 'Aperturas en polea baja', 'cable low fly', '["Cruces de pecho en polea baja", "Aperturas bajas para pectorales", "cable low fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los pectorales que consiste en juntar los brazos frente al cuerpo desde una posición baja usando poleas, con énfasis en la parte inferior e interna del pecho.', '["Coloca los agarres en las poleas bajas y selecciona un peso adecuado.", "Ponte de pie en el centro de la máquina, con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta los agarres con un agarre prono y abre los brazos hacia los lados, manteniendo los codos ligeramente flexionados.", "Lleva lentamente los brazos hacia adelante en un arco controlado y crúzalos frente al cuerpo.", "Haz una breve pausa al final del movimiento y siente el estiramiento en los músculos del pecho.", "Invierte el movimiento y vuelve lentamente a la posición inicial, manteniendo la tensión en el pecho durante todo el recorrido.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0179.gif'),
('0182', 'Curl acostado en polea con agarre cerrado', 'cable lying close-grip curl', '["Curl de bíceps acostado con agarre estrecho", "Bíceps en banco con polea", "cable lying close-grip curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza acostado en un banco con una polea. Favorece una técnica estricta y mantiene una tensión constante en los bíceps.', '["Coloca una barra recta en la polea baja.", "Acuéstate boca arriba en un banco plano, con los pies bien apoyados en el piso.", "Sujeta la barra con las palmas hacia arriba y las manos al ancho de los hombros.", "Estira completamente los brazos y mantén los codos cerca del cuerpo.", "Sin mover la parte superior de los brazos, contrae los bíceps y lleva la barra hacia el pecho.", "Haz una breve pausa arriba y aprieta los bíceps.", "Baja lentamente la barra hasta la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0182.gif'),
('0184', 'Pullover acostado en polea con brazos extendidos (con cuerda)', 'cable lying extension pullover (with rope attachment)', '["Pullover con cuerda en banco", "Dorsales acostado en polea", "cable lying extension pullover (with rope attachment)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Tríceps", "Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los dorsales que se realiza acostado en un banco con una polea y una cuerda. Requiere buena técnica y control para trabajar la espalda y reducir el riesgo para los hombros.', '["Coloca una cuerda en la máquina de poleas y ajusta la polea a la posición más alta.", "Acuéstate en un banco con la cabeza hacia la máquina.", "Sujeta la cuerda con ambas manos y extiende los brazos hacia arriba, sobre el pecho.", "Mantén los brazos rectos y baja lentamente la cuerda detrás de la cabeza, controlando el movimiento.", "Haz una breve pausa abajo y luego eleva lentamente la cuerda hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0184.gif'),
('0185', 'Aperturas acostado en polea', 'cable lying fly', '["Aperturas de pecho en banco con poleas", "Cruces de pecho acostado", "cable lying fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para el pecho que se realiza en un banco con poleas. Trabaja los pectorales, con participación secundaria de los deltoides y tríceps. Consiste en abrir los brazos en un arco amplio y volver a juntarlos, concentrándote en contraer el pecho.', '["Coloca los agarres en las poleas y acuéstate en un banco plano con los pies bien apoyados en el piso.", "Sujeta los agarres con las palmas enfrentadas y los brazos extendidos sobre el pecho.", "Mantén los codos ligeramente flexionados y baja los brazos hacia los lados en un arco amplio, hasta sentir un estiramiento en el pecho.", "Haz una breve pausa y luego contrae el pecho para llevar los brazos a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0185.gif'),
('0186', 'Extensión de tríceps acostado en polea, versión 2', 'cable lying triceps extension v. 2', '["Press francés con cuerda en polea", "Tríceps acostado con polea baja", "cable lying triceps extension v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza acostado en un banco con una cuerda conectada a una polea baja. Se centra en extender los codos de forma controlada y se usa para desarrollar la fuerza y el tamaño de los tríceps.', '["Coloca una cuerda en la polea baja.", "Acuéstate boca arriba en un banco plano, con la cabeza hacia la máquina.", "Sujeta la cuerda con ambas manos, con las palmas enfrentadas, y extiende los brazos hacia arriba sobre el pecho.", "Sin mover la parte superior de los brazos, flexiona lentamente los codos para acercar la cuerda a la frente.", "Haz una breve pausa abajo y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0186.gif'),
('0188', 'Aperturas en polea media', 'cable middle fly', '["Cruces de pecho a media altura", "Aperturas de pectorales en polea", "cable middle fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los pectorales que se realiza con poleas. Favorece el desarrollo del pecho y también involucra los deltoides y tríceps como músculos secundarios.', '["Ajusta las poleas de ambos lados de la máquina a la altura del pecho.", "Ponte de pie en el centro de la máquina, con un pie ligeramente delante del otro.", "Sujeta los agarres con un agarre prono y extiende los brazos hacia los lados.", "Mantén los codos ligeramente flexionados y el cuerpo un poco inclinado hacia adelante.", "Contrae los músculos del pecho y lleva los brazos hacia adelante en un arco.", "Haz una breve pausa en el centro y luego vuelve lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0188.gif'),
('0190', 'Curl a un brazo en polea', 'cable one arm curl', '["Curl unilateral de bíceps", "Bíceps con una mano en polea", "cable one arm curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza con una polea y un brazo a la vez. Mantiene una tensión constante durante el movimiento y ayuda a desarrollar la fuerza y la masa muscular de los bíceps y antebrazos.', '["Ponte de pie frente a la máquina de poleas, con los pies al ancho de los hombros.", "Sujeta el agarre de la polea con la palma hacia arriba.", "Mantén el codo cerca del cuerpo y flexiónalo lentamente para llevar el antebrazo hacia el hombro.", "Haz una breve pausa arriba y luego baja lentamente el antebrazo hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0190.gif'),
('0192', 'Elevación lateral a un brazo en polea', 'cable one arm lateral raise', '["Elevación unilateral de hombro", "Lateral de hombro con una mano en polea", "cable one arm lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides, especialmente su porción lateral. La polea mantiene una tensión constante durante el movimiento y ayuda a desarrollar la anchura y la fuerza de los hombros.', '["Ponte de pie frente a la máquina de poleas, con los pies al ancho de los hombros.", "Sujeta el agarre con una mano y la palma hacia abajo; aléjate lo suficiente para mantener tensión en la polea.", "Mantén el brazo recto y elévalo lentamente hacia el lado hasta que quede paralelo al piso.", "Haz una breve pausa arriba y luego baja lentamente el brazo hasta la posición inicial.", "Completa la cantidad de repeticiones que desees y luego cambia de lado."]'::jsonb, '/gifs/0192.gif'),
('0194', 'Extensión de tríceps sobre la cabeza en polea (con cuerda)', 'cable overhead triceps extension (rope attachment)', '["Tríceps por encima de la cabeza con cuerda", "Extensión de codos sobre la cabeza", "cable overhead triceps extension (rope attachment)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza con una polea y una cuerda. Consiste en extender los brazos por encima de la cabeza, con participación de los hombros para estabilizar el movimiento.', '["Coloca una cuerda en una polea alta.", "Ponte de pie de espaldas a la máquina, con los pies al ancho de los hombros.", "Sujeta la cuerda con ambas manos, con las palmas enfrentadas, y lleva las manos por encima de la cabeza.", "Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante.", "Flexiona lentamente los codos para bajar la cuerda detrás de la cabeza.", "Haz una breve pausa y luego extiende los brazos hacia arriba para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0194.gif'),
('0195', 'Curl predicador en polea', 'cable preacher curl', '["Curl Scott con polea", "Bíceps en banco predicador con polea", "cable preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza con una polea y un banco predicador. Favorece una técnica estricta y mantiene una tensión constante en los bíceps durante todo el movimiento.', '["Ajusta la máquina para que el apoyo del banco predicador quede a la altura del pecho.", "Siéntate en el banco predicador, apoya la parte superior de los brazos en la almohadilla y sujeta el accesorio de la polea con las palmas hacia arriba.", "Mantén la espalda recta y los codos cerca del cuerpo.", "Flexiona lentamente los codos para llevar el accesorio hacia los hombros y aprieta los bíceps al final del movimiento.", "Haz una breve pausa y luego baja lentamente el accesorio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0195.gif'),
('0199', 'Jalón en polea (brazos rectos), versión 2', 'cable pushdown (straight arm) v. 2', '["Pullover de pie con barra en polea", "Jalón de dorsales con brazos extendidos", "cable pushdown (straight arm) v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Tríceps", "Hombros"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento que trabaja principalmente los dorsales con una barra recta conectada a una polea. También involucra los tríceps y hombros. Requiere mantener los brazos rectos y el abdomen estable durante todo el movimiento.', '["Coloca una barra recta en la polea alta.", "Ponte de pie frente a la máquina, con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con las palmas hacia abajo y mantén los brazos rectos.", "Mantén el abdomen firme y la espalda recta; exhala mientras empujas la barra hacia los muslos.", "Haz una breve pausa abajo y luego inhala mientras regresas lentamente la barra a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0199.gif'),
('0200', 'Extensión de tríceps en polea (con cuerda)', 'cable pushdown (with rope attachment)', '["Jalón de tríceps con cuerda", "Tríceps en polea alta con cuerda", "cable pushdown (with rope attachment)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza con una cuerda conectada a una polea. Se centra en extender los codos y también involucra los antebrazos como músculos secundarios.', '["Coloca una cuerda en la polea alta.", "Ponte de pie frente a la máquina, con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la cuerda con un agarre prono y las palmas enfrentadas.", "Mantén los codos cerca del cuerpo y la parte superior de los brazos inmóvil durante todo el ejercicio.", "Exhala y empuja la cuerda hacia abajo, extendiendo los codos hasta estirar completamente los brazos.", "Haz una breve pausa y luego inhala mientras flexionas lentamente los codos para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0200.gif'),
('0201', 'Extensión de tríceps en polea', 'cable pushdown', '["Jalón de tríceps con barra", "Tríceps en polea alta", "cable pushdown"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para desarrollar la fuerza y el tamaño de los tríceps usando una polea, con cierta participación de los antebrazos. Requiere movimientos controlados y una buena técnica para mejorar su efectividad y reducir el riesgo de lesión.', '["Coloca una barra recta en la polea alta.", "Ponte de pie frente a la máquina, con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con las palmas hacia abajo y las manos al ancho de los hombros.", "Mantén los codos cerca del cuerpo y la parte superior de los brazos inmóvil.", "Exhala y empuja la barra hacia abajo hasta extender completamente los codos.", "Haz una breve pausa y luego inhala mientras regresas lentamente la barra a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0201.gif'),
('0206', 'Curl inverso en polea', 'cable reverse curl', '["Curl con agarre invertido en polea", "Curl para bíceps y antebrazos con polea", "cable reverse curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps y antebrazos que se realiza con una polea. El agarre inverso pone énfasis en los músculos braquial y braquiorradial.', '["Coloca una barra recta en la polea baja.", "Ponte de pie frente a la máquina, con los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con las palmas hacia arriba y las manos al ancho de los hombros.", "Mantén los codos cerca del cuerpo y la parte superior de los brazos inmóvil durante todo el ejercicio.", "Exhala y lleva la barra hacia los hombros, contrayendo los bíceps.", "Haz una breve pausa arriba y aprieta los bíceps.", "Inhala y baja lentamente la barra hasta la posición inicial, extendiendo completamente los brazos.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0206.gif'),
('0207', 'Extensión de tríceps en polea con agarre inverso', 'cable reverse-grip pushdown', '["Jalón de tríceps con agarre supino", "Tríceps en polea con palmas hacia arriba", "cable reverse-grip pushdown"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza con una barra recta en polea y las palmas hacia arriba. Se centra en la activación de los tríceps y también involucra los antebrazos.', '["Coloca una barra recta en la polea alta.", "Ponte de pie frente a la máquina, con los pies al ancho de los hombros.", "Sujeta la barra con las palmas hacia arriba y las manos al ancho de los hombros.", "Mantén los codos cerca del cuerpo y la parte superior de los brazos inmóvil durante todo el ejercicio.", "Usa los tríceps para empujar la barra hacia abajo hasta extender completamente los brazos y contraer los tríceps.", "Haz una breve pausa y luego regresa lentamente la barra a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0207.gif'),
('0209', 'Curl predicador inverso en polea', 'cable reverse preacher curl', '["Curl Scott inverso con polea", "Curl en banco predicador con agarre prono", "cable reverse preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza con una polea y un banco predicador. El agarre inverso o prono pone énfasis en el braquial y los músculos del antebrazo.', '["Ajusta la máquina para que el apoyo del banco predicador quede a la altura del pecho.", "Siéntate en el banco predicador y apoya la parte superior de los brazos en la almohadilla, con las palmas hacia abajo y los codos completamente extendidos.", "Sujeta los agarres de la polea con un agarre supino y las manos al ancho de los hombros.", "Sin mover la parte superior de los brazos, exhala y lleva los agarres hacia los hombros, contrayendo los bíceps.", "Haz una breve pausa arriba y aprieta los bíceps.", "Inhala y baja lentamente los agarres hasta la posición inicial, extendiendo completamente los codos.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0209.gif'),
('0210', 'Curl inverso de muñeca en polea', 'cable reverse wrist curl', '["Extensión de muñeca con polea", "Antebrazo en polea con palmas hacia abajo", "cable reverse wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Antebrazos", "Muñecas"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, específicamente los extensores de la muñeca. Se realiza con una polea y fortalece los músculos encargados de extender las muñecas.', '["Conecta el cable a una polea baja y siéntate en un banco frente a la máquina.", "Sujeta el agarre de la polea con las palmas hacia abajo.", "Apoya los antebrazos sobre los muslos y deja las muñecas fuera del borde.", "Mantén los antebrazos inmóviles, exhala y eleva las manos doblando las muñecas tanto como puedas.", "Haz una breve pausa arriba y luego inhala mientras bajas lentamente las manos hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0210.gif'),
('0212', 'Abdominal (crunch) sentado en polea', 'cable seated crunch', '["Crunch sentado con polea", "Abdominales sentado con resistencia", "cable seated crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio abdominal que se realiza sentado en una máquina de poleas. Trabaja los abdominales y, de forma secundaria, los oblicuos. Consiste en flexionar el tronco hacia adelante contra resistencia, concentrándote en contraer el abdomen.', '["Siéntate en la máquina de poleas con los pies bien apoyados en el piso y las rodillas flexionadas.", "Sujeta el agarre de la polea con ambas manos y colócalo detrás de la cabeza.", "Contrae el abdomen y flexiona lentamente el tronco hacia adelante, acercando el pecho a las rodillas.", "Haz una breve pausa al final de la contracción y luego vuelve lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0212.gif'),
('0215', 'Elevación posterior sentado en polea', 'cable seated rear lateral raise', '["Aperturas posteriores sentado con poleas", "Pájaros sentado en polea", "cable seated rear lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores, con participación secundaria de los trapecios y romboides. Se realiza sentado frente a una polea, elevando los brazos hacia los lados hasta la altura de los hombros.', '["Siéntate en un banco frente a la máquina de poleas, con los pies bien apoyados en el piso.", "Sujeta los agarres con un agarre prono y extiende los brazos hacia adelante.", "Mantén los brazos rectos y elévalos lentamente hacia los lados hasta que queden paralelos al piso.", "Haz una breve pausa arriba y luego baja lentamente los brazos hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0215.gif'),
('0220', 'Encogimiento de hombros en polea', 'cable shrug', '["Trapecios con polea", "Elevación de hombros en polea", "cable shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los trapecios que se realiza con poleas. Consiste en elevar los hombros con los brazos rectos, concentrándote en contraer los trapecios.', '["Ponte de pie frente a la máquina de poleas, con los pies al ancho de los hombros.", "Sujeta los agarres con un agarre prono y deja los brazos colgando frente al cuerpo.", "Mantén los brazos rectos y eleva los hombros hacia las orejas.", "Mantén la contracción un momento y luego baja lentamente los hombros hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0220.gif'),
('0221', 'Abdominal (crunch) con inclinación lateral en polea (sobre BOSU)', 'cable side bend crunch (bosu ball)', '["Flexión lateral con polea sobre BOSU", "Oblicuos en polea sobre BOSU", "cable side bend crunch (bosu ball)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Polea', 'Avanzado', 'Fuerza', 'Ejercicio para los abdominales, especialmente los oblicuos, que se realiza con una polea mientras estás de pie sobre un BOSU para añadir inestabilidad y exigir más equilibrio.', '["Ponte de pie con los pies al ancho de los hombros y sujeta el agarre de una polea con una mano.", "Coloca la otra mano en la cadera.", "Mantén el abdomen firme y la espalda recta; inclina lentamente el tronco hacia el lado de la mano que sostiene el agarre.", "Haz una breve pausa abajo y luego vuelve lentamente a la posición inicial.", "Completa la cantidad de repeticiones que desees y luego cambia de lado."]'::jsonb, '/gifs/0221.gif'),
('0223', 'Abdominal lateral (crunch) en polea', 'cable side crunch', '["Crunch de oblicuos con polea", "Flexión lateral de abdomen en polea", "cable side crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los abdominales, especialmente los oblicuos, que usa una polea como resistencia. Consiste en inclinar el tronco hacia un lado desde la cintura para trabajar el abdomen.', '["Coloca un agarre en la polea baja y ponte de pie de lado a la máquina.", "Sujeta el agarre con la mano más alejada de la máquina y coloca la otra mano en la cadera.", "Mantén los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Con el abdomen firme, inclina el tronco hacia un lado desde la cintura y acerca el codo a la cadera.", "Haz una breve pausa abajo y luego vuelve lentamente a la posición inicial.", "Completa la cantidad de repeticiones que desees y luego cambia de lado."]'::jsonb, '/gifs/0223.gif'),
('0224', 'Extensión de muñeca de pie en polea', 'cable standing back wrist curl', '["Curl inverso de muñeca de pie", "Extensores de antebrazo en polea", "cable standing back wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos que se realiza de pie con una polea y se centra en fortalecer los extensores de la muñeca.', '["Ponte de pie frente a una máquina de poleas, con los pies al ancho de los hombros.", "Sujeta el agarre de la polea con las palmas hacia abajo.", "Mantén los brazos rectos y los codos cerca del cuerpo.", "Eleva lentamente las manos doblando las muñecas y acercando el agarre al cuerpo.", "Haz una breve pausa arriba y luego baja lentamente el agarre hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0224.gif'),
('0225', 'Aperturas inversas altas de pie en poleas cruzadas', 'cable standing cross-over high reverse fly', '["Cruces inversos altos para hombros", "Aperturas posteriores de pie con poleas", "cable standing cross-over high reverse fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides", "Deltoides posteriores"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides, con énfasis secundario en los trapecios, romboides y deltoides posteriores. Se realiza con poleas y requiere coordinación, equilibrio y control.', '["Coloca un agarre en D a cada lado de la máquina de poleas, a la altura de los hombros.", "Ponte de pie en el centro de la máquina, con los pies al ancho de los hombros.", "Sujeta los agarres con un agarre prono y extiende los brazos hacia los lados, con las palmas hacia adelante.", "Mantén los codos ligeramente flexionados y la espalda recta durante todo el ejercicio.", "Activa los músculos de los hombros y junta los omóplatos mientras jalas los agarres hacia el frente del cuerpo.", "Haz una breve pausa al final del movimiento y luego vuelve lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0225.gif'),
('0226', 'Abdominal (crunch) de pie en polea', 'cable standing crunch', '["Crunch de pie con polea alta", "Abdominales parado con polea", "cable standing crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio abdominal que se realiza de pie con una polea. Trabaja los abdominales y también involucra los oblicuos. Consiste en flexionar el tronco hacia abajo contra resistencia para mejorar la fuerza y la estabilidad del abdomen.', '["Coloca un agarre en la polea alta y ponte de pie de espaldas a la máquina.", "Sujeta el agarre con ambas manos y colócalo detrás de la cabeza, manteniendo los codos flexionados.", "Mantén los pies al ancho de los hombros y las rodillas ligeramente flexionadas.", "Con el abdomen firme, exhala y flexiona el tronco hacia las rodillas, acercando los codos a los muslos.", "Haz una breve pausa abajo y luego vuelve lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0226.gif'),
('0227', 'Aperturas de pie en polea', 'cable standing fly', '["Cruces de pecho de pie", "Aperturas de pectorales parado con poleas", "cable standing fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para el pecho que se realiza de pie con poleas. Trabaja los pectorales y también involucra los deltoides y tríceps. Requiere buena técnica, equilibrio y control para realizarlo de forma segura y efectiva.', '["Coloca los agarres en las poleas a la altura del pecho.", "Ponte de pie de espaldas a la máquina, con los pies al ancho de los hombros.", "Sujeta los agarres con un agarre prono y las palmas hacia adelante.", "Da un pequeño paso hacia adelante para generar tensión en los cables.", "Mantén el abdomen firme y la espalda recta durante todo el ejercicio.", "Con los codos ligeramente flexionados, lleva lentamente los brazos hacia adelante hasta juntar las manos frente al pecho.", "Aprieta los músculos del pecho al final del movimiento.", "Invierte lentamente el movimiento y lleva los brazos a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0227.gif'),
('0228', 'Extensión de cadera de pie en polea', 'cable standing hip extension', '["Patada de glúteo en polea", "Patada hacia atrás con polea", "cable standing hip extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Cuádriceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio para los glúteos que consiste en llevar la pierna hacia atrás contra la resistencia de una polea. También involucra los isquiotibiales y cuádriceps como músculos secundarios y requiere equilibrio y estabilidad del abdomen.', '["Conecta el cable a una polea baja y ponte de pie de espaldas a la máquina.", "Sujeta el cable alrededor del tobillo y coloca los pies al ancho de los hombros.", "Mantén el abdomen firme y la espalda recta durante todo el ejercicio.", "Lleva lentamente la pierna recta hacia atrás y aprieta los glúteos al final del movimiento.", "Haz una breve pausa y luego vuelve a la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees.", "Cambia de lado y repite con la otra pierna."]'::jsonb, '/gifs/0228.gif'),
('0229', 'Curl interno de pie en polea', 'cable standing inner curl', '["Curl de bíceps hacia adentro con polea", "Bíceps de pie en polea", "cable standing inner curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza de pie con una polea. Se centra en controlar el movimiento y contraer los bíceps, con participación de los antebrazos.', '["Ponte de pie frente a una máquina de poleas, con los pies al ancho de los hombros.", "Sujeta el agarre de la polea con las palmas hacia arriba.", "Mantén los codos cerca del cuerpo y la parte superior de los brazos inmóvil.", "Exhala y lleva el agarre hacia los hombros, contrayendo los bíceps.", "Haz una breve pausa arriba y aprieta los bíceps.", "Inhala y baja lentamente el agarre hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0229.gif'),
('0231', 'Extensión de tríceps a un brazo de pie en polea', 'cable standing one arm triceps extension', '["Tríceps unilateral de pie con polea", "Extensión de codo con una mano en polea", "cable standing one arm triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza de pie con una polea, trabajando un brazo a la vez. Requiere movimientos controlados para activar los tríceps y reducir la participación del hombro.', '["Ponte de pie frente a la máquina de poleas, con los pies al ancho de los hombros.", "Sujeta el agarre con la mano derecha y la palma hacia abajo; coloca el brazo completamente extendido y paralelo al piso.", "Mantén el codo fijo y cerca del cuerpo.", "Flexiona lentamente el codo para bajar el agarre hacia la parte posterior de la cabeza.", "Haz una breve pausa abajo y luego extiende el brazo para volver a la posición inicial.", "Completa la cantidad de repeticiones que desees y luego cambia de lado para realizar el ejercicio con el brazo izquierdo."]'::jsonb, '/gifs/0231.gif'),
('0240', 'Aperturas inversas boca arriba en polea', 'cable supine reverse fly', '["Aperturas posteriores acostado con poleas", "Pájaros en banco con poleas", "cable supine reverse fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores que se realiza acostado boca abajo en un banco con poleas. Favorece la fuerza y la estabilidad de los hombros, con activación secundaria de los trapecios y romboides.', '["Coloca un agarre en D en una polea baja y acuéstate boca abajo en un banco plano.", "Sujeta un agarre en D con cada mano, con las palmas hacia abajo, y extiende los brazos hacia adelante.", "Mantén los brazos rectos y elévalos hacia los lados hasta que queden paralelos al piso.", "Haz una breve pausa arriba y luego baja lentamente los brazos hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0240.gif'),
('0241', 'Extensión de tríceps en polea (barra en V)', 'cable triceps pushdown (v-bar)', '["Jalón de tríceps con barra en V", "Tríceps en polea alta con agarre en V", "cable triceps pushdown (v-bar)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza con una polea y una barra en V. Se usa para desarrollar la fuerza y la definición muscular de los tríceps.', '["Coloca una barra en V en la polea y ajústala a la posición más alta.", "Ponte de pie frente a la máquina, con los pies al ancho de los hombros.", "Sujeta la barra en V con las palmas hacia abajo y las manos al ancho de los hombros.", "Mantén los codos cerca del cuerpo y la parte superior de los brazos inmóvil durante todo el ejercicio.", "Contrae los tríceps y exhala mientras empujas la barra hacia abajo hasta extender completamente los brazos.", "Haz una breve pausa abajo y aprieta los tríceps.", "Inhala mientras regresas lentamente la barra a la posición inicial, controlando el movimiento.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0241.gif'),
('0242', 'Abdominal inverso (crunch) en polea con rodillas al pecho', 'cable tuck reverse crunch', '["Crunch inverso con polea", "Elevación de pelvis con rodillas al pecho en polea", "cable tuck reverse crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio abdominal con polea que también trabaja los flexores de la cadera. Consiste en llevar la pelvis y las rodillas hacia el pecho mientras estás boca arriba, usando la resistencia de la polea para aumentar la intensidad.', '["Conecta el cable a una polea baja y acuéstate boca arriba sobre una colchoneta.", "Sujeta el cable con ambas manos y extiende los brazos hacia arriba sobre el pecho.", "Flexiona las rodillas y eleva las piernas, acercando las rodillas al pecho.", "Al mismo tiempo, lleva la pelvis hacia el pecho y despega la cadera del piso.", "Haz una breve pausa arriba y luego baja lentamente las piernas y la cadera hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0242.gif'),
('0247', 'Curl de muñeca en polea', 'cable wrist curl', '["Flexión de muñeca con polea", "Antebrazo en polea con palmas hacia arriba", "cable wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los flexores de la muñeca. Se realiza con una barra recta conectada a una polea y consiste en flexionar las muñecas hacia arriba sin mover los antebrazos.', '["Coloca una barra recta en la polea baja.", "Ponte de pie frente a la máquina, con los pies al ancho de los hombros.", "Sujeta la barra con las palmas hacia arriba y las manos al ancho de los hombros.", "Apoya los antebrazos en un banco o una almohadilla y deja las muñecas fuera del borde.", "Mantén los antebrazos inmóviles, exhala y eleva las manos flexionando las muñecas tanto como puedas.", "Haz una breve pausa arriba y luego inhala mientras bajas lentamente la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0247.gif'),
('0262', 'Abdominal cruzado (crunch)', 'cross body crunch', '["Crunch cruzado", "Abdominal de codo a rodilla contraria", "cross body crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los abdominales y oblicuos. Consiste en girar el tronco para acercar un codo a la rodilla contraria, activando los músculos del abdomen.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso.", "Coloca las manos detrás de la cabeza, con los codos hacia afuera.", "Contrae el abdomen, despega la parte superior del tronco del piso y gira para acercar el codo derecho a la rodilla izquierda.", "Haz una breve pausa arriba y luego baja lentamente el tronco hasta la posición inicial.", "Repite del otro lado, acercando el codo izquierdo a la rodilla derecha.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0262.gif'),
('0267', 'Abdominal (crunch) (manos sobre la cabeza)', 'crunch (hands overhead)', '["Crunch con brazos extendidos sobre la cabeza", "Abdominal con brazos por encima de la cabeza", "crunch (hands overhead)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Variante del crunch con los brazos extendidos por encima de la cabeza, lo que aumenta la dificultad y exige una mayor activación de los músculos abdominales.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso.", "Extiende los brazos por encima de la cabeza.", "Contrae el abdomen y despega la parte superior del tronco del piso, flexionándolo hacia las rodillas.", "Haz una breve pausa arriba y luego baja lentamente el tronco hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0267.gif'),
('0274', 'Abdominal (crunch) en el piso', 'crunch floor', '["Crunch en el suelo", "Abdominal corto", "crunch floor"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio abdominal clásico que se realiza acostado boca arriba y se centra en fortalecer los abdominales con equipo mínimo.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso.", "Coloca las manos detrás de la cabeza, con los codos hacia afuera.", "Contrae el abdomen y despega los hombros del piso, flexionando el tronco hacia las rodillas.", "Haz una breve pausa arriba y luego baja lentamente los hombros hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0274.gif'),
('0277', 'Abdominal (crunch) en banco declinado', 'decline crunch', '["Crunch declinado", "Abdominal corto en banco declinado", "decline crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio abdominal en banco declinado que también involucra los flexores de la cadera como músculos secundarios. Consiste en flexionar el tronco hacia arriba mientras estás acostado sobre una superficie inclinada hacia abajo.', '["Acuéstate en un banco declinado con los pies asegurados y las rodillas flexionadas a 90 grados.", "Coloca las manos detrás de la cabeza o cruza los brazos sobre el pecho.", "Contrae el abdomen y eleva la parte superior del cuerpo hacia las rodillas, flexionando el tronco.", "Haz una breve pausa arriba y luego baja lentamente el tronco hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0277.gif'),
('0284', 'Elevación de pantorrillas tipo burro', 'donkey calf raise', '["Elevación de talones tipo burro", "Pantorrillas con peso corporal en escalón", "donkey calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para las pantorrillas. Consiste en apoyar las puntas de los pies sobre una superficie elevada y levantar los talones tanto como puedas para trabajar estos músculos.', '["Ponte de pie con las puntas de los pies sobre una superficie elevada, como un escalón o un bloque.", "Apoya las manos en un soporte firme, como una pared o una baranda, para mantener el equilibrio.", "Eleva los talones tanto como puedas, llevando el peso del cuerpo a la parte delantera de los pies.", "Haz una breve pausa arriba y luego baja lentamente los talones hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones que desees."]'::jsonb, '/gifs/0284.gif'),
('0285', 'Curl alternado de bíceps con mancuernas', 'dumbbell alternate biceps curl', '["Curl alterno", "Bíceps alternados con mancuernas", "dumbbell alternate biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio clásico de brazos que trabaja los bíceps y también los antebrazos. Consiste en subir las mancuernas de forma alternada, manteniendo fija la parte superior de los brazos y controlando el movimiento y la contracción muscular.', '["Párate derecho con una mancuerna en cada mano, las palmas hacia adelante y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones, alternando los brazos."]'::jsonb, '/gifs/0285.gif'),
('0288', 'Pullover en arco con mancuerna', 'dumbbell around pullover', '["Pullover con mancuerna en banco", "Jalón por detrás de la cabeza con mancuerna", "dumbbell around pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Dorsales"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que se realiza acostado en un banco, bajando una mancuerna por detrás de la cabeza en un arco y regresando a la posición inicial. Trabaja principalmente los pectorales y, de forma secundaria, los tríceps y los dorsales.', '["Acuéstate boca arriba en un banco, con la cabeza en un extremo y los pies firmes en el piso.", "Sostén una mancuerna con ambas manos y extiende los brazos sobre el pecho.", "Mantén los brazos rectos y baja lentamente la mancuerna por detrás de la cabeza, trazando un arco.", "Haz una pausa breve abajo y vuelve a subir la mancuerna hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0288.gif'),
('0294', 'Curl de bíceps con mancuernas', 'dumbbell biceps curl', '["Curl de pie con mancuernas", "Flexión de bíceps con mancuernas", "dumbbell biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio clásico de fuerza que trabaja los bíceps y también los antebrazos. Consiste en subir las mancuernas desde una posición con los brazos extendidos hasta la altura de los hombros, controlando el movimiento y la contracción muscular.', '["Párate derecho con una mancuerna en cada mano, las palmas hacia adelante y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0294.gif'),
('0297', 'Curl concentrado con mancuerna', 'dumbbell concentration curl', '["Curl de concentración", "Bíceps con codo apoyado en el muslo", "dumbbell concentration curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza sentado, con el brazo que trabaja apoyado en la cara interna del muslo para mantener una técnica estricta.', '["Siéntate en un banco con las piernas separadas y una mancuerna en una mano, apoyando el codo en la cara interna del muslo.", "Extiende completamente el brazo y sostén la mancuerna con la palma hacia arriba.", "Mantén fija la parte superior del brazo, exhala y sube la mancuerna hacia el hombro mientras contraes el bíceps.", "Sigue subiendo hasta que el bíceps esté completamente contraído y la mancuerna llegue a la altura del hombro.", "Haz una pausa breve arriba mientras aprietas el bíceps.", "Inhala y baja lentamente la mancuerna hasta la posición inicial.", "Repite la cantidad deseada de repeticiones y luego cambia de brazo."]'::jsonb, '/gifs/0297.gif'),
('0298', 'Curl martillo cruzado con mancuernas', 'dumbbell cross body hammer curl', '["Curl cruzado de bíceps", "Martillo hacia el hombro contrario", "dumbbell cross body hammer curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento que trabaja los bíceps y los antebrazos al subir las mancuernas cruzadas frente al cuerpo hacia el hombro contrario.', '["Párate derecho con una mancuerna en cada mano y las palmas hacia el cuerpo.", "Mantén los codos cerca del torso y fija la parte superior de los brazos.", "Exhala y sube las mancuernas contrayendo los bíceps, cruzándolas frente al cuerpo hacia el hombro contrario.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0298.gif'),
('0302', 'Aperturas declinadas con mancuernas', 'dumbbell decline fly', '["Aperturas de pecho en banco declinado", "Pecho inferior con mancuernas", "dumbbell decline fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en banco declinado que trabaja la parte inferior de los pectorales. Consiste en bajar las mancuernas hacia los lados en un arco amplio y volver a juntarlas, enfatizando el estiramiento y la contracción del pecho.', '["Acuéstate en un banco declinado con los pies asegurados y la cabeza más baja que las caderas.", "Sostén una mancuerna en cada mano, con las palmas enfrentadas y los brazos extendidos sobre el pecho.", "Baja las mancuernas hacia los lados en un arco amplio hasta sentir un estiramiento en el pecho.", "Haz una pausa breve y contrae los pectorales para regresar las mancuernas a la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0302.gif'),
('0304', 'Encogimiento declinado con mancuernas (versión 2)', 'dumbbell decline shrug v. 2', '["Encogimiento de hombros en banco declinado variante 2", "Trapecios boca abajo con mancuernas variante 2", "dumbbell decline shrug v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Trabaja los trapecios mediante encogimientos con mancuernas, acostado boca abajo en un banco declinado. Enfatiza la parte superior de la espalda y los hombros.', '["Ajusta un banco declinado a un ángulo de 45 grados.", "Acuéstate boca abajo en el banco, con el pecho y el abdomen apoyados.", "Sostén una mancuerna en cada mano, con las palmas enfrentadas y los brazos completamente extendidos.", "Mantén los brazos rectos y eleva los hombros lo más que puedas mientras juntas los omóplatos.", "Mantén la contracción durante una pausa breve y luego baja las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0304.gif'),
('0305', 'Encogimiento declinado con mancuernas', 'dumbbell decline shrug', '["Encogimiento de hombros en banco declinado", "Trapecios con mancuernas boca abajo", "dumbbell decline shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros", "Romboides"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los trapecios. Se realiza boca abajo en un banco declinado, sosteniendo mancuernas con los brazos extendidos y elevando los hombros.', '["Ajusta un banco declinado a un ángulo de 45 grados.", "Acuéstate boca abajo en el banco, con el pecho y el abdomen apoyados.", "Sostén una mancuerna en cada mano con los brazos completamente extendidos hacia el piso.", "Mantén los brazos rectos y eleva los hombros hacia las orejas lo más que puedas.", "Mantén la contracción un momento y luego baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0305.gif'),
('0306', 'Extensión de tríceps declinada con mancuernas', 'dumbbell decline triceps extension', '["Tríceps en banco declinado", "Press francés declinado con mancuernas", "dumbbell decline triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza en un banco declinado para aumentar su estiramiento y activación. También involucra los hombros de forma secundaria.', '["Acuéstate en un banco declinado con la cabeza más baja que los pies y sostén una mancuerna en cada mano, con las palmas enfrentadas.", "Extiende completamente los brazos y mantén los codos cerca de la cabeza.", "Flexiona los codos para bajar lentamente las mancuernas por detrás de la cabeza.", "Haz una pausa breve y vuelve a subir las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0306.gif'),
('0307', 'Aperturas declinadas con giro con mancuernas', 'dumbbell decline twist fly', '["Aperturas con rotación en banco declinado", "Aperturas de pecho declinadas con giro de muñecas", "dumbbell decline twist fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en banco declinado que trabaja los pectorales y también involucra los hombros y los tríceps. Consiste en bajar las mancuernas en un arco amplio con un giro que aumenta el estiramiento y la contracción del pecho.', '["Acuéstate en un banco declinado con la cabeza más baja que las caderas.", "Sostén una mancuerna en cada mano, con las palmas enfrentadas y los brazos extendidos sobre el pecho.", "Baja las mancuernas hacia los lados en un arco amplio hasta sentir un estiramiento en el pecho.", "Mientras bajas las mancuernas, gira las muñecas para que las palmas queden hacia adelante al final de la bajada.", "Invierte el movimiento y vuelve a subir las mancuernas hasta la posición inicial, apretando los pectorales arriba.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0307.gif'),
('0308', 'Aperturas con mancuernas', 'dumbbell fly', '["Aperturas de pecho en banco plano", "Aperturas planas", "dumbbell fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que se realiza acostado en un banco, usando mancuernas para estirar y contraer los pectorales mediante un movimiento en arco amplio.', '["Acuéstate boca arriba en un banco con una mancuerna en cada mano y las palmas enfrentadas.", "Extiende los brazos sobre el pecho, dejando los codos ligeramente flexionados.", "Mantén esa ligera flexión de los codos y baja los brazos hacia los lados en un arco amplio hasta sentir un estiramiento en el pecho.", "Haz una pausa breve, invierte el movimiento y vuelve a subir las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0308.gif'),
('0309', 'Elevación frontal con mancuernas (versión 2)', 'dumbbell front raise v. 2', '["Elevaciones al frente con mancuernas variante 2", "Hombro frontal con mancuernas variante 2", "dumbbell front raise v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Bíceps"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides. Consiste en elevar las mancuernas frente al cuerpo hasta la altura de los hombros, con un movimiento controlado y buena técnica.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano, con las palmas hacia los muslos.", "Mantén la espalda recta y el abdomen firme.", "Eleva lentamente las mancuernas frente a ti, con los brazos rectos, hasta la altura de los hombros.", "Haz una pausa breve arriba y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0309.gif'),
('0310', 'Elevación frontal con mancuernas', 'dumbbell front raise', '["Elevaciones al frente", "Hombro anterior con mancuernas", "dumbbell front raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Bíceps", "Trapecio"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides, especialmente su parte anterior. También involucra los bíceps y los trapecios de forma secundaria. Consiste en elevar las mancuernas frente al cuerpo hasta la altura de los hombros, con control y buena técnica.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano, con las palmas hacia los muslos.", "Mantén los brazos rectos, exhala y eleva las mancuernas frente a ti hasta la altura de los hombros.", "Haz una pausa breve arriba, inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0310.gif'),
('0311', 'Elevación lateral con mancuernas tipo full can', 'dumbbell full can lateral raise', '["Elevación lateral tipo lata llena", "Elevaciones de hombro full can", "dumbbell full can lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Manguito rotador"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides y también involucra los trapecios y el manguito rotador. Consiste en elevar las mancuernas hacia los lados con los codos ligeramente flexionados, imitando el gesto de verter el contenido de una lata, lo que ayuda a reducir el riesgo de pinzamiento del hombro.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano, con las palmas hacia el cuerpo.", "Mantén la espalda recta y el abdomen firme.", "Eleva los brazos hacia los lados, con los codos ligeramente flexionados, hasta que queden paralelos al piso.", "Haz una pausa breve arriba y baja lentamente los brazos hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0311.gif'),
('0312', 'Curl martillo con mancuernas (versión 2)', 'dumbbell hammer curl v. 2', '["Curl de bíceps tipo martillo variante 2", "Martillo de pie con mancuernas variante 2", "dumbbell hammer curl v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio con mancuernas enfocado en los bíceps, con énfasis en el músculo braquial y los antebrazos. Se realiza de pie, con las palmas hacia el torso, subiendo las mancuernas mientras se mantiene fija la parte superior de los brazos.', '["Párate derecho con una mancuerna en cada mano y las palmas hacia el torso.", "Mantén los codos cerca del torso y gira las manos hasta que las palmas queden hacia adelante.", "Toma esta postura como posición inicial.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Luego inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad recomendada de repeticiones."]'::jsonb, '/gifs/0312.gif'),
('0313', 'Curl martillo con mancuernas', 'dumbbell hammer curl', '["Curl con agarre neutro", "Martillo de bíceps", "dumbbell hammer curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los bíceps y los antebrazos. Consiste en subir las mancuernas con agarre neutro y las palmas enfrentadas, lo que enfatiza el trabajo de los músculos braquial y braquiorradial.', '["Párate derecho con una mancuerna en cada mano y las palmas hacia el torso.", "Mantén los codos cerca del torso y gira las manos hasta que las palmas queden hacia adelante.", "Toma esta postura como posición inicial.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Luego inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad recomendada de repeticiones."]'::jsonb, '/gifs/0313.gif'),
('0315', 'Curl de bíceps inclinado con mancuernas', 'dumbbell incline biceps curl', '["Bíceps sentado en banco inclinado", "Curl de bíceps con respaldo inclinado", "dumbbell incline biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para los bíceps que se realiza en un banco inclinado para aumentar su estiramiento y activación. También trabaja los antebrazos de forma secundaria.', '["Siéntate en un banco inclinado con una mancuerna en cada mano, las palmas hacia adelante y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0315.gif'),
('0317', 'Curl inclinado con mancuernas (versión 2)', 'dumbbell incline curl v. 2', '["Curl de bíceps en banco inclinado variante 2", "Bíceps sentado inclinado variante 2", "dumbbell incline curl v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio enfocado en los bíceps que se realiza en un banco inclinado. Aísla los bíceps y los antebrazos y requiere un movimiento controlado para maximizar el trabajo muscular.', '["Siéntate en un banco inclinado con una mancuerna en cada mano, las palmas hacia adelante y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0317.gif'),
('0318', 'Curl inclinado con mancuernas', 'dumbbell incline curl', '["Curl de bíceps en banco inclinado", "Bíceps con mancuernas en banco a 45 grados", "dumbbell incline curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps en banco inclinado. Enfatiza su estiramiento y contracción al reducir la participación de los hombros. Es efectivo para aumentar la fuerza y el tamaño de los bíceps.', '["Ajusta un banco inclinado a 45 grados y siéntate con una mancuerna en cada mano y las palmas hacia adelante.", "Apoya la parte superior de los brazos en el banco inclinado y deja los codos hacia abajo, con los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0318.gif'),
('0319', 'Aperturas inclinadas con mancuernas', 'dumbbell incline fly', '["Aperturas de pecho en banco inclinado", "Aperturas para pecho superior", "dumbbell incline fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en banco inclinado que trabaja la parte superior de los pectorales. Consiste en bajar las mancuernas hacia los lados en un arco amplio y volver a juntarlas, enfatizando el estiramiento y la contracción del pecho.', '["Ajusta un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con una mancuerna en cada mano y las palmas enfrentadas.", "Recuéstate en el banco y empuja las mancuernas hacia arriba hasta colocarlas sobre el pecho en la posición inicial.", "Baja las mancuernas hacia los lados en un arco amplio hasta sentir un estiramiento en el pecho.", "Haz una pausa breve y contrae los pectorales para volver a subir las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0319.gif'),
('0320', 'Curl martillo inclinado con mancuernas', 'dumbbell incline hammer curl', '["Martillo en banco inclinado", "Curl neutro sentado en banco inclinado", "dumbbell incline hammer curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de brazos que trabaja los bíceps y también los antebrazos. Se realiza sentado en un banco inclinado, lo que aumenta el estiramiento de los bíceps y exige a los músculos trabajar en un mayor rango de movimiento.', '["Siéntate en un banco inclinado con una mancuerna en cada mano, las palmas hacia el torso y los brazos completamente extendidos.", "Mantén la espalda apoyada en el banco y los pies completamente apoyados en el piso.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0320.gif'),
('0322', 'Curl interno de bíceps inclinado con mancuernas', 'dumbbell incline inner biceps curl', '["Curl de bíceps interno en banco inclinado", "Curl interior con mancuernas en banco", "dumbbell incline inner biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza en un banco inclinado para aumentar su estiramiento y activación. También trabaja los antebrazos de forma secundaria.', '["Siéntate en un banco inclinado con una mancuerna en cada mano y las palmas enfrentadas.", "Apoya la parte superior de los brazos en el banco y deja los codos hacia abajo, con las palmas hacia adelante.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0322.gif'),
('0323', 'Elevación lateral a un brazo con mancuerna en banco inclinado', 'dumbbell incline one arm lateral raise', '["Elevación lateral unilateral con mancuerna en banco inclinado", "Hombro lateral a una mano en banco inclinado", "dumbbell incline one arm lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento de hombros que se realiza en un banco inclinado. Trabaja los deltoides y ayuda a mejorar la fuerza y la estabilidad de los hombros.', '["Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.", "Inclínate hacia adelante y apoya la parte superior del brazo contra la cara interna del muslo.", "Eleva la mancuerna hacia un lado, con el brazo ligeramente flexionado y la palma hacia abajo.", "Sigue subiendo hasta que el brazo quede paralelo al piso.", "Haz una pausa breve arriba y baja lentamente la mancuerna hasta la posición inicial.", "Repite la cantidad deseada de repeticiones y luego cambia de brazo."]'::jsonb, '/gifs/0323.gif'),
('0326', 'Elevación posterior con mancuernas en banco inclinado', 'dumbbell incline rear lateral raise', '["Pájaros en banco inclinado", "Aperturas inversas con pecho apoyado", "dumbbell incline rear lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Trabaja los deltoides posteriores y, de forma secundaria, los trapecios y los romboides. Se realiza en un banco inclinado para aislar la parte posterior de los hombros.', '["Ajusta un banco inclinado a un ángulo de 45 grados.", "Siéntate en el banco con el pecho contra el respaldo y sostén una mancuerna en cada mano.", "Extiende los brazos hacia abajo con las palmas enfrentadas.", "Mantén los codos ligeramente flexionados y eleva los brazos hacia los lados hasta que queden paralelos al piso.", "Haz una pausa breve arriba y baja lentamente los brazos hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0326.gif'),
('0329', 'Encogimiento inclinado con mancuernas', 'dumbbell incline shrug', '["Encogimiento de hombros en banco inclinado", "Trapecios sentado con mancuernas", "dumbbell incline shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Trabaja los trapecios mediante encogimientos con mancuernas, sentado en un banco inclinado. Esta variante enfatiza la parte superior de los trapecios y puede ayudar a mejorar la postura y la fuerza de la parte superior de la espalda.', '["Ajusta un banco inclinado a 45 grados y siéntate con una mancuerna en cada mano.", "Apoya completamente los pies en el piso y deja los brazos colgando hacia abajo, con las palmas hacia el cuerpo.", "Mantén los brazos rectos y eleva los hombros hacia las orejas lo más que puedas.", "Mantén la contracción un momento y luego baja lentamente los hombros hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0329.gif'),
('0330', 'Extensión de tríceps inclinada con mancuernas', 'dumbbell incline triceps extension', '["Tríceps en banco inclinado", "Press francés inclinado con mancuernas", "dumbbell incline triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza en un banco inclinado para aumentar su estiramiento y activación.', '["Siéntate en un banco inclinado con una mancuerna en cada mano y las palmas hacia adentro.", "Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de ella.", "Flexiona los codos para bajar las mancuernas por detrás de la cabeza, manteniendo fija la parte superior de los brazos.", "Haz una pausa breve y extiende los brazos para volver a subir las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0330.gif'),
('0331', 'Aperturas inclinadas con giro con mancuernas', 'dumbbell incline twisted flyes', '["Aperturas con rotación en banco inclinado", "Aperturas de pecho inclinado con giro de muñecas", "dumbbell incline twisted flyes"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho en banco inclinado que trabaja la parte superior de los pectorales e incorpora un giro de muñecas para aumentar la activación muscular.', '["Ajusta un banco inclinado a 45 grados y siéntate con una mancuerna en cada mano y las palmas enfrentadas.", "Recuéstate en el banco y empuja las mancuernas hacia arriba hasta colocarlas sobre el pecho en la posición inicial, con los brazos extendidos.", "Baja las mancuernas hacia los lados en un arco amplio hasta sentir un estiramiento en el pecho.", "Mientras bajas las mancuernas, gira las muñecas para que las palmas queden hacia adelante al final de la bajada.", "Invierte el movimiento y vuelve a subir las mancuernas hasta la posición inicial, apretando los pectorales arriba.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0331.gif'),
('0334', 'Elevación lateral con mancuernas', 'dumbbell lateral raise', '["Elevaciones de hombro a los lados", "Vuelos laterales con mancuernas", "dumbbell lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento que trabaja los deltoides, especialmente su porción lateral. Se usa comúnmente para aumentar el ancho y la fuerza de los hombros.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.", "Mantén la espalda recta y el abdomen firme.", "Eleva los brazos hacia los lados hasta que queden paralelos al piso, manteniendo los codos ligeramente flexionados.", "Haz una pausa breve arriba y baja lentamente los brazos hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0334.gif'),
('0335', 'Elevación lateral y frontal con mancuernas', 'dumbbell lateral to front raise', '["Elevaciones combinadas de hombros", "Elevaciones a los lados y al frente", "dumbbell lateral to front raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Bíceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de hombros que trabaja los deltoides al combinar elevaciones laterales y frontales. También involucra los trapecios y los bíceps de forma secundaria. Ayuda a desarrollar la fuerza y la estabilidad de los hombros.', '["Párate con los pies al ancho de los hombros y una mancuerna en cada mano, con las palmas hacia el cuerpo.", "Mantén la espalda recta y el abdomen firme.", "Eleva los brazos hacia los lados hasta que queden paralelos al piso, manteniendo los codos ligeramente flexionados.", "Haz una pausa breve arriba y baja lentamente los brazos hasta la posición inicial.", "Luego eleva los brazos frente a ti hasta que queden paralelos al piso, manteniendo de nuevo los codos ligeramente flexionados.", "Haz una pausa breve arriba y baja lentamente los brazos hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0335.gif'),
('0337', 'Extensión de tríceps acostado con mancuerna (por encima de la cara)', 'dumbbell lying extension (across face)', '["Extensión acostado pasando sobre la cara", "Press francés con mancuerna sobre la cara", "dumbbell lying extension (across face)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza acostado en un banco, moviendo una mancuerna en un arco por detrás de la cabeza mediante la extensión de los brazos.', '["Acuéstate boca arriba en un banco, con los pies completamente apoyados en el piso y la cabeza en el extremo del banco.", "Sostén una mancuerna con ambas manos y extiende los brazos sobre el pecho, con las palmas enfrentadas.", "Mantén fija la parte superior de los brazos y baja lentamente la mancuerna en un arco por detrás de la cabeza hasta que los antebrazos queden paralelos al piso.", "Haz una pausa breve y contrae los tríceps para regresar la mancuerna a la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0337.gif'),
('0344', 'Extensión de tríceps acostado a un brazo con mancuerna, agarre prono', 'dumbbell lying one arm pronated triceps extension', '["Tríceps con mancuerna acostado con palma hacia abajo", "Press francés unilateral con agarre prono", "dumbbell lying one arm pronated triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza acostado en un banco con una mancuerna y agarre prono, con la palma hacia abajo. Enfatiza la fuerza y la estabilidad de los tríceps, con cierta participación de los hombros.', '["Acuéstate boca arriba en un banco, con la espalda y la cabeza apoyadas y los pies completamente apoyados en el piso.", "Sostén una mancuerna en una mano con la palma hacia abajo y extiende el brazo sobre el hombro.", "Mantén fija la parte superior del brazo y flexiona el codo para bajar lentamente la mancuerna por detrás de la cabeza.", "Haz una pausa breve abajo y vuelve a extender el brazo hasta la posición inicial.", "Repite la cantidad deseada de repeticiones y luego cambia de brazo."]'::jsonb, '/gifs/0344.gif'),
('0345', 'Elevación posterior acostado a un brazo con mancuerna', 'dumbbell lying one arm rear lateral raise', '["Pájaro unilateral en banco plano", "Apertura inversa a una mano boca abajo", "dumbbell lying one arm rear lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores que se realiza boca abajo en un banco. Ayuda a desarrollar la fuerza y la estabilidad de los hombros y también involucra los trapecios y los romboides.', '["Acuéstate boca abajo en un banco plano con una mancuerna en una mano, colgando hacia el piso.", "Mantén el brazo recto y eleva la mancuerna hacia un lado, alejándola del cuerpo.", "Haz una pausa breve arriba y baja lentamente la mancuerna hasta la posición inicial.", "Repite la cantidad deseada de repeticiones y luego cambia de brazo."]'::jsonb, '/gifs/0345.gif'),
('0346', 'Extensión de tríceps acostado a un brazo con mancuerna, agarre supino', 'dumbbell lying one arm supinated triceps extension', '["Tríceps con mancuerna acostado con palma hacia arriba", "Press francés unilateral con agarre supino", "dumbbell lying one arm supinated triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza acostado en un banco, con una sola mancuerna y agarre supino.', '["Acuéstate boca arriba en un banco, con la espalda y la cabeza apoyadas y los pies completamente apoyados en el piso.", "Sostén una mancuerna en una mano con agarre supino, con la palma hacia arriba, y extiende el brazo sobre el hombro.", "Mantén fija la parte superior del brazo y flexiona el codo para bajar lentamente la mancuerna por detrás de la cabeza.", "Haz una pausa breve abajo y vuelve a extender el brazo hasta la posición inicial.", "Repite la cantidad deseada de repeticiones y luego cambia de brazo."]'::jsonb, '/gifs/0346.gif'),
('0348', 'Elevación posterior acostado con mancuernas', 'dumbbell lying rear lateral raise', '["Pájaros en banco plano", "Aperturas inversas boca abajo", "dumbbell lying rear lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores que se realiza boca abajo en un banco para reducir el impulso y maximizar el trabajo de los hombros.', '["Acuéstate boca abajo en un banco plano con una mancuerna en cada mano y las palmas enfrentadas.", "Extiende los brazos hacia el piso, manteniendo los codos ligeramente flexionados.", "Activa los músculos de los hombros y eleva los brazos hacia los lados hasta que queden paralelos al piso.", "Haz una pausa breve arriba y baja lentamente los brazos hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0348.gif'),
('0350', 'Curl con mancuernas acostado boca arriba', 'dumbbell lying supine curl', '["Curl de bíceps acostado en banco", "Bíceps en posición supina", "dumbbell lying supine curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza acostado boca arriba en un banco. Al estabilizar el cuerpo, favorece una técnica estricta y reduce las compensaciones.', '["Acuéstate boca arriba en un banco con una mancuerna en cada mano, las palmas hacia arriba y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y sube las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo hasta que los bíceps estén completamente contraídos y las mancuernas lleguen a la altura de los hombros.", "Haz una pausa breve arriba mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0350.gif'),
('0351', 'Extensión de tríceps acostado con mancuernas', 'dumbbell lying triceps extension', '["Press francés con mancuernas en banco plano", "Rompecráneos con mancuernas", "dumbbell lying triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza acostado en un banco, extendiendo los brazos con mancuernas.', '["Acuéstate boca arriba en un banco con una mancuerna en cada mano y las palmas enfrentadas.", "Extiende los brazos sobre el pecho, manteniendo los codos cerca del cuerpo.", "Flexiona los codos para bajar las mancuernas hacia la frente.", "Haz una pausa breve y vuelve a extender los brazos hasta la posición inicial.", "Repite la cantidad deseada de repeticiones."]'::jsonb, '/gifs/0351.gif'),
('0353', 'Curl concentrado a un brazo con mancuerna (en pelota de estabilidad)', 'dumbbell one arm concentration curl (on stability ball)', '["Curl de concentración en pelota suiza", "Bíceps a una mano sentado en pelota", "dumbbell one arm concentration curl (on stability ball)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza sentado en una pelota de estabilidad, lo que aumenta el trabajo de la zona media y la exigencia de equilibrio.', '["Siéntate en una pelota de estabilidad con los pies completamente apoyados en el piso y las rodillas flexionadas a 90 grados.", "Sostén una mancuerna en una mano, con la palma hacia arriba y el brazo extendido hacia el piso.", "Apoya el codo en la cara interna del muslo, justo por encima de la rodilla.", "Mantén fija la parte superior del brazo, exhala y sube la mancuerna hacia el hombro mientras contraes el bíceps.", "Haz una pausa breve arriba, inhala y baja lentamente la mancuerna hasta la posición inicial.", "Repite la cantidad deseada de repeticiones, cambia de brazo y repite."]'::jsonb, '/gifs/0353.gif'),
('0355', 'Elevación lateral a un brazo con mancuerna', 'dumbbell one arm lateral raise', '["Elevación lateral unilateral", "Hombro lateral con una mancuerna", "dumbbell one arm lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Tríceps"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento que trabaja los deltoides, especialmente su porción lateral. También involucra los trapecios y los tríceps de forma secundaria. Ayuda a desarrollar la fuerza y la definición de los hombros y se usa habitualmente en rutinas de fuerza.', '["Párate con los pies al ancho de los hombros y una mancuerna en una mano, con la palma hacia el cuerpo.", "Mantén la espalda recta y el abdomen firme durante todo el ejercicio.", "Eleva la mancuerna hacia un lado, con el brazo recto y la palma hacia abajo.", "Sigue subiendo hasta que el brazo quede paralelo al piso.", "Haz una pausa breve arriba y baja lentamente la mancuerna hasta la posición inicial.", "Repite la cantidad deseada de repeticiones y luego cambia de brazo."]'::jsonb, '/gifs/0355.gif'),
('0356', 'Elevación lateral a un brazo con mancuerna con apoyo', 'dumbbell one arm lateral raise with support', '["Elevación lateral unilateral con apoyo", "Hombro lateral con una mano apoyada", "dumbbell one arm lateral raise with support"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Manguito rotador"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los deltoides. El apoyo permite mantener una mejor técnica y concentrar el trabajo en los hombros, reduciendo la posibilidad de usar impulso o realizar el movimiento incorrectamente.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en una mano, con la palma hacia el cuerpo.", "Apoya la otra mano en una superficie estable, como un banco o una pared.", "Mantén la espalda recta y el abdomen firme.", "Eleva la mancuerna hacia un lado, con el brazo recto y la palma hacia abajo.", "Sigue subiendo hasta que el brazo quede paralelo al piso.", "Haz una pausa breve arriba y baja lentamente la mancuerna hasta la posición inicial.", "Repite la cantidad deseada de repeticiones y luego cambia de lado."]'::jsonb, '/gifs/0356.gif'),
('0358', 'Curl inverso de muñeca a un brazo con mancuerna', 'dumbbell one arm reverse wrist curl', '["Extensión de muñeca con mancuerna", "Antebrazo con palma hacia abajo", "dumbbell one arm reverse wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Extensores de muñeca"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Trabaja los antebrazos y los extensores de la muñeca al elevar una mancuerna moviendo solo la muñeca, con el antebrazo apoyado en el muslo. Ayuda a desarrollar la fuerza y la resistencia de los antebrazos.', '["Siéntate en un banco o una silla con los pies completamente apoyados en el piso.", "Sostén una mancuerna en una mano con agarre prono y la palma hacia abajo.", "Apoya el antebrazo en el muslo y deja la muñeca fuera del borde.", "Flexiona la muñeca para bajar lentamente la mancuerna hacia el piso.", "Haz una pausa breve abajo y luego vuelve a elevar lentamente la mano hacia el cuerpo, moviendo solo la muñeca.", "Repite la cantidad deseada de repeticiones y luego cambia de brazo."]'::jsonb, '/gifs/0358.gif'),
('0359', 'Aperturas inversas a un brazo con mancuerna (con apoyo)', 'dumbbell one arm reverse fly (with support)', '["aperturas posteriores con apoyo", "hombro posterior a un brazo", "dumbbell one arm reverse fly (with support)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores que también activa los trapecios y romboides. Se realiza sentado, con un brazo apoyado en un banco para dar estabilidad, lo que facilita su ejecución al desarrollar fuerza y control en los hombros.', '["Siéntate en un banco con los pies bien apoyados en el piso y la espalda recta.", "Sostén una mancuerna en una mano con la palma hacia adentro.", "Inclínate hacia adelante y apoya la mano libre en el banco.", "Mantén el codo ligeramente flexionado y eleva el brazo hacia un lado hasta que quede paralelo al piso.", "Haz una breve pausa arriba y luego baja el brazo lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0359.gif'),
('0362', 'Extensión de tríceps a un brazo con mancuerna (en banco)', 'dumbbell one arm triceps extension (on bench)', '["extensión de tríceps sentado a una mano", "tríceps sobre la cabeza con mancuerna", "dumbbell one arm triceps extension (on bench)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza sentado en un banco. Consiste en extender un brazo por encima de la cabeza con una mancuerna, mientras los hombros ayudan a estabilizar el movimiento.', '["Siéntate en un banco con la espalda recta y los pies bien apoyados en el piso.", "Sostén una mancuerna en una mano y apoya la otra en el banco.", "Eleva la mancuerna por encima de la cabeza, manteniendo la parte superior del brazo cerca de la cabeza y el codo apuntando hacia adelante.", "Flexiona el codo para bajar la mancuerna detrás de la cabeza, sin mover la parte superior del brazo.", "Vuelve a elevar la mancuerna hasta la posición inicial, extendiendo el codo por completo.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0362.gif'),
('0364', 'Curl de muñeca a un brazo con mancuerna', 'dumbbell one arm wrist curl', '["flexión de muñeca a una mano", "antebrazo con mancuerna a un brazo", "dumbbell one arm wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los músculos del antebrazo, especialmente los flexores de la muñeca. Se realiza sentado, con el antebrazo apoyado, flexionando la muñeca para elevar una mancuerna.', '["Siéntate en un banco o una silla con los pies bien apoyados en el piso.", "Sostén una mancuerna en una mano con la palma hacia arriba y apoya el antebrazo sobre el muslo.", "Deja que la muñeca se extienda y que la mancuerna ruede hacia los dedos.", "Flexiona lentamente la muñeca hacia arriba para acercar la mancuerna al antebrazo.", "Repite hasta completar las repeticiones deseadas y luego cambia de mano."]'::jsonb, '/gifs/0364.gif'),
('0365', 'Curl de muñeca neutro con mancuernas sobre banco', 'dumbbell over bench neutral wrist curl', '["curl neutro apoyado en banco", "curl de antebrazo neutro en banco", "dumbbell over bench neutral wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps y antebrazos. Se realiza sentado, con los antebrazos apoyados en un banco y las muñecas fuera del borde, elevando las mancuernas con un agarre neutro.', '["Siéntate en un banco con los pies bien apoyados en el piso y sostén una mancuerna en cada mano con las palmas hacia arriba.", "Apoya los antebrazos en el banco y deja las muñecas fuera del borde.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para acercar las mancuernas a los hombros.", "Haz una breve pausa arriba, luego inhala y baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0365.gif'),
('0366', 'Curl de muñeca neutro a un brazo con mancuerna sobre banco', 'dumbbell over bench one arm neutral wrist curl', '["curl neutro a una mano en banco", "curl de antebrazo unilateral con apoyo", "dumbbell over bench one arm neutral wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps y antebrazos. Se realiza sentado, con el brazo extendido sobre un banco y la muñeca en posición neutra, acercando la mancuerna al hombro.', '["Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba.", "Mantén fija la parte superior del brazo y flexiona el codo para acercar la mancuerna al hombro, sin doblar la muñeca.", "Haz una breve pausa arriba y luego baja la mancuerna lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0366.gif'),
('0367', 'Curl de muñeca a un brazo con mancuerna sobre banco', 'dumbbell over bench one arm wrist curl', '["flexión de muñeca con apoyo en banco", "antebrazo a una mano sobre banco", "dumbbell over bench one arm wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los músculos del antebrazo. Se realiza sentado, con el antebrazo apoyado en un banco, moviendo la muñeca para elevar una mancuerna.', '["Siéntate en un banco con los pies bien apoyados en el piso y sostén una mancuerna en una mano con la palma hacia abajo.", "Apoya el antebrazo en el banco y deja la muñeca fuera del borde.", "Eleva lentamente la mano desde la muñeca, acercando la mancuerna al antebrazo.", "Haz una breve pausa arriba y luego baja la mancuerna lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0367.gif'),
('0368', 'Curl inverso de muñeca con mancuernas sobre banco', 'dumbbell over bench reverse wrist curl', '["extensión de muñecas en banco", "antebrazo en banco con palmas hacia abajo", "dumbbell over bench reverse wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los extensores de la muñeca. Se realiza sentado, con los antebrazos apoyados en un banco y las muñecas fuera del borde, elevando las mancuernas con el dorso de las manos hacia arriba.', '["Siéntate en un banco con los pies bien apoyados en el piso y sostén una mancuerna en cada mano con las palmas hacia abajo.", "Apoya los antebrazos en el banco y deja las muñecas fuera del borde.", "Eleva lentamente las manos desde las muñecas, acercando las mancuernas al cuerpo.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0368.gif'),
('0369', 'Curl de muñeca con mancuernas sobre banco', 'dumbbell over bench wrist curl', '["flexión de muñecas en banco", "antebrazo en banco con palmas hacia arriba", "dumbbell over bench wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos. Se realiza sentado en un banco, con los antebrazos apoyados y las palmas hacia arriba, flexionando las muñecas para elevar las mancuernas.', '["Siéntate en un banco con los antebrazos apoyados en él y sostén una mancuerna en cada mano con las palmas hacia arriba.", "Deja las muñecas fuera del borde del banco.", "Flexiona lentamente las muñecas hacia arriba y contrae los antebrazos al llegar arriba.", "Haz una breve pausa y luego baja las manos lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0369.gif'),
('0370', 'Curl martillo predicador con mancuernas', 'dumbbell preacher hammer curl', '["curl martillo en banco predicador", "curl martillo en banco scott", "dumbbell preacher hammer curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps y antebrazos. Se realiza con mancuernas, manteniendo fija la parte superior de los brazos y cuidando la técnica para maximizar el trabajo de los bíceps.', '["Párate con la espalda recta y una mancuerna en cada mano, con las palmas hacia el torso.", "Mantén los codos cerca del torso y gira las manos hasta que las palmas miren hacia adelante.", "Toma esta postura como posición inicial.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para elevar las mancuernas mientras contraes los bíceps.", "Sigue elevando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén esa posición un momento y aprieta los bíceps.", "Luego inhala y comienza a bajar las mancuernas lentamente a la posición inicial.", "Repite hasta completar la cantidad de repeticiones recomendada."]'::jsonb, '/gifs/0370.gif'),
('0372', 'Curl predicador con mancuernas', 'dumbbell preacher curl', '["curl en banco scott", "bíceps con mancuernas en banco predicador", "dumbbell preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza en un banco predicador para reducir la participación de los hombros y maximizar el trabajo de los bíceps.', '["Siéntate en un banco predicador con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella.", "Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para elevar las mancuernas mientras contraes los bíceps.", "Sigue elevando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén esa posición un momento y aprieta los bíceps.", "Inhala y comienza a bajar las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0372.gif'),
('0373', 'Extensión de tríceps con mancuerna en agarre prono', 'dumbbell pronate-grip triceps extension', '["tríceps con palmas hacia abajo", "extensión sobre la cabeza en pronación", "dumbbell pronate-grip triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio para los tríceps con una mancuerna sostenida en agarre prono, con las palmas hacia abajo. Se realiza sentado, elevando la mancuerna por encima de la cabeza y bajándola detrás de ella.', '["Siéntate en un banco o una silla con la espalda recta y los pies bien apoyados en el piso.", "Sostén una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos por encima de la cabeza.", "Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante; flexiona los codos para bajar lentamente la mancuerna detrás de la cabeza.", "Haz una breve pausa y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0373.gif'),
('0374', 'Curl con mancuernas boca abajo en banco inclinado', 'dumbbell prone incline curl', '["curl de bíceps con pecho apoyado", "curl en banco inclinado boca abajo", "dumbbell prone incline curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza acostado boca abajo en un banco inclinado. Esta posición reduce las compensaciones y favorece una contracción controlada de los bíceps.', '["Ajusta el banco a una inclinación de 45 grados.", "Acuéstate boca abajo en el banco, con el pecho y el abdomen apoyados.", "Sostén una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para elevar las mancuernas mientras contraes los bíceps.", "Sigue elevando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén esa posición un momento y aprieta los bíceps.", "Inhala y comienza a bajar las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0374.gif'),
('0375', 'Pullover con mancuerna', 'dumbbell pullover', '["pullover de pecho en banco", "mancuerna detrás de la cabeza acostado", "dumbbell pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Dorsales", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que se realiza acostado en un banco, bajando una mancuerna detrás de la cabeza y llevándola de nuevo sobre el pecho. Trabaja los pectorales y también involucra los dorsales y tríceps.', '["Acuéstate boca arriba en un banco plano, con la cabeza en un extremo y los pies en el piso.", "Sostén una mancuerna con ambas manos y extiende los brazos sobre el pecho.", "Mantén los codos ligeramente flexionados y baja lentamente la mancuerna detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros.", "Haz una breve pausa y luego eleva la mancuerna para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0375.gif'),
('0378', 'Aperturas posteriores con mancuernas', 'dumbbell rear fly', '["pájaros con mancuernas", "aperturas para hombro posterior", "dumbbell rear fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores, con trabajo secundario de trapecios y romboides. Se realiza inclinando el torso desde la cadera, con la espalda recta, y elevando las mancuernas hacia los lados mientras se juntan los omóplatos.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta.", "Deja los brazos extendidos hacia el piso con las palmas enfrentadas.", "Mantén los codos ligeramente flexionados, eleva los brazos hacia los lados y junta los omóplatos.", "Haz una breve pausa arriba y luego baja los brazos lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0378.gif'),
('0379', 'Elevación lateral posterior con mancuernas (cabeza apoyada)', 'dumbbell rear lateral raise (support head)', '["pájaros con cabeza apoyada", "aperturas posteriores con apoyo de cabeza", "dumbbell rear lateral raise (support head)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores, con trabajo secundario de trapecios y romboides. Consiste en inclinar el torso hacia adelante desde la cadera y elevar las mancuernas hacia los lados, con énfasis en la estabilidad y el control de los hombros.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta.", "Eleva los brazos hacia los lados con los codos ligeramente flexionados hasta que los brazos queden paralelos al piso.", "Haz una breve pausa arriba y luego baja los brazos lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0379.gif'),
('0380', 'Elevación lateral posterior con mancuernas', 'dumbbell rear lateral raise', '["pájaros para hombros", "elevaciones de hombro posterior", "dumbbell rear lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides posteriores, con trabajo secundario de trapecios y romboides. Se realiza inclinando el torso desde la cadera y elevando las mancuernas hacia los lados, concentrando el movimiento en los hombros.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano con las palmas hacia el cuerpo.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta y el abdomen firme.", "Eleva los brazos hacia los lados con los codos ligeramente flexionados hasta que los brazos queden paralelos al piso.", "Haz una breve pausa arriba y luego baja los brazos lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0380.gif'),
('0382', 'Curl inverso de bíceps con mancuernas', 'dumbbell reverse grip biceps curl', '["curl con agarre prono", "bíceps con palmas hacia abajo", "dumbbell reverse grip biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio para los bíceps y antebrazos que consiste en elevar las mancuernas flexionando los codos con las palmas hacia abajo.', '["Párate con la espalda recta y una mancuerna en cada mano, con las palmas hacia abajo y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para elevar las mancuernas mientras contraes los bíceps.", "Sigue elevando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén esa posición un momento y aprieta los bíceps.", "Inhala y comienza a bajar las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0382.gif'),
('0383', 'Aperturas inversas con mancuernas', 'dumbbell reverse fly', '["pájaros con pesas", "aperturas para deltoides posteriores", "dumbbell reverse fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio para los deltoides posteriores, con trabajo secundario de trapecios y romboides. Se realiza inclinando el torso desde la cadera, con la espalda recta, y elevando las mancuernas hacia los lados de forma controlada.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta.", "Deja los brazos extendidos hacia abajo frente a ti, con las palmas enfrentadas.", "Mantén los codos ligeramente flexionados y eleva los brazos hacia los lados hasta que queden paralelos al piso.", "Haz una breve pausa arriba y luego baja los brazos lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0383.gif'),
('0384', 'Curl predicador inverso con mancuernas', 'dumbbell reverse preacher curl', '["curl inverso en banco scott", "bíceps en predicador con agarre inverso", "dumbbell reverse preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps y antebrazos. Se realiza sentado en un banco predicador, con la parte superior de los brazos apoyada en la almohadilla y las mancuernas sostenidas con las palmas hacia arriba. Consiste en elevarlas flexionando los codos sin mover la parte superior de los brazos.', '["Siéntate en un banco predicador con la parte superior de los brazos apoyada en la almohadilla y el pecho contra el soporte.", "Sostén una mancuerna en cada mano con agarre supino, es decir, con las palmas hacia arriba.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para elevar las mancuernas mientras contraes los bíceps.", "Sigue elevando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén esa posición un momento y aprieta los bíceps.", "Inhala y baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0384.gif'),
('0385', 'Curl inverso de muñeca con mancuernas', 'dumbbell reverse wrist curl', '["extensión de muñecas con mancuernas", "antebrazo con agarre prono", "dumbbell reverse wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Braquial"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los músculos extensores. Se realiza sentado, con los antebrazos apoyados en los muslos, elevando las mancuernas desde las muñecas con las palmas hacia abajo.', '["Siéntate en un banco o una silla con los pies bien apoyados en el piso.", "Sostén una mancuerna en cada mano con agarre prono, es decir, con las palmas hacia abajo.", "Apoya los antebrazos sobre los muslos y deja las muñecas fuera del borde.", "Eleva lentamente las manos desde las muñecas, acercando las mancuernas al cuerpo.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0385.gif'),
('0386', 'Aperturas inversas con mancuernas y rotación', 'dumbbell rotation reverse fly', '["pájaros con giro", "aperturas posteriores con rotación de brazos", "dumbbell rotation reverse fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de hombros para los deltoides, con trabajo secundario de trapecios y romboides. Consiste en inclinar el torso desde la cadera y elevar las mancuernas hacia los lados, incorporando una rotación de los brazos.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano con las palmas hacia adentro.", "Flexiona ligeramente las rodillas e inclina el torso hacia adelante desde la cadera, manteniendo la espalda recta y el pecho elevado.", "Eleva los brazos hacia los lados con los codos ligeramente flexionados hasta que los brazos queden paralelos al piso.", "Gira los brazos hasta que las palmas queden hacia abajo.", "Baja los brazos lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0386.gif'),
('0387', 'Elevación frontal alternada con mancuernas sentado', 'dumbbell seated alternate front raise', '["elevaciones frontales por turnos en banco", "hombro frontal alternado sentado", "dumbbell seated alternate front raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Bíceps"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de hombros para los deltoides, con trabajo secundario de trapecios y bíceps. Se realiza sentado, lo que ayuda a estabilizar el cuerpo y aislar los músculos de los hombros.', '["Siéntate en un banco con la espalda recta y los pies bien apoyados en el piso.", "Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos extendidos a los lados.", "Mantén los brazos rectos y eleva una mancuerna al frente hasta que el brazo quede paralelo al piso.", "Haz una breve pausa arriba y luego baja la mancuerna lentamente a la posición inicial.", "Repite con el otro brazo.", "Alterna los brazos hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0387.gif'),
('0389', 'Extensión de tríceps con mancuerna sentado en banco', 'dumbbell seated bench extension', '["tríceps sobre la cabeza a dos manos", "extensión de tríceps sentado con ambas manos", "dumbbell seated bench extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio para los tríceps que se realiza sentado en un banco. Consiste en sostener una mancuerna sobre la cabeza con ambas manos, bajarla detrás de la cabeza y volver a extender los brazos hacia arriba.', '["Siéntate en un banco con la espalda recta y los pies bien apoyados en el piso.", "Sostén una mancuerna con ambas manos y extiende los brazos por encima de la cabeza.", "Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.", "Haz una breve pausa y luego eleva la mancuerna para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0389.gif'),
('0390', 'Curl de bíceps con mancuernas sentado (en pelota de estabilidad)', 'dumbbell seated biceps curl (on stability ball)', '["curl de bíceps en pelota suiza", "bíceps sentado en balón de estabilidad", "dumbbell seated biceps curl (on stability ball)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio enfocado en los bíceps que se realiza sentado en una pelota de estabilidad, lo que añade un trabajo de equilibrio y activación del abdomen. También trabaja los antebrazos de forma secundaria.', '["Siéntate en una pelota de estabilidad con los pies bien apoyados en el piso y la espalda recta.", "Sostén una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para elevar las mancuernas mientras contraes los bíceps.", "Sigue elevando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén esa posición un momento y aprieta los bíceps.", "Inhala y comienza a bajar las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0390.gif'),
('0391', 'Curl con mancuernas sentado', 'dumbbell seated curl', '["curl de bíceps en banco", "bíceps sentado con pesas", "dumbbell seated curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los bíceps que se realiza sentado para reducir el movimiento del cuerpo y concentrar el trabajo en los brazos.', '["Siéntate en un banco con los pies bien apoyados en el piso y una mancuerna en cada mano, con las palmas hacia adelante.", "Mantén la espalda recta y los codos cerca del torso.", "Exhala y flexiona los codos para acercar las mancuernas a los hombros, contrayendo los bíceps.", "Haz una breve pausa arriba, luego inhala y baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0391.gif'),
('0392', 'Elevación frontal con mancuernas sentado', 'dumbbell seated front raise', '["elevaciones al frente en banco", "hombro frontal sentado con pesas", "dumbbell seated front raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Bíceps"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de hombros para los deltoides. Se realiza sentado para ayudar a aislar los hombros y reducir el impulso, favoreciendo un movimiento controlado para desarrollar fuerza.', '["Siéntate en un banco con los pies bien apoyados en el piso y una mancuerna en cada mano, apoyada sobre los muslos.", "Mantén la espalda recta y el abdomen firme.", "Eleva las mancuernas al frente con las palmas hacia abajo hasta que queden a la altura de los hombros.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0392.gif'),
('0393', 'Curl interno de bíceps con mancuernas sentado', 'dumbbell seated inner biceps curl', '["curl de bíceps apoyado en muslos", "curl interno sentado con pesas", "dumbbell seated inner biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio para los bíceps y antebrazos que se realiza sentado en un banco, con la parte superior de los brazos apoyada en los muslos, elevando las mancuernas al flexionar los codos. Aísla los bíceps y reduce el impulso para desarrollar fuerza.', '["Siéntate en un banco con los pies bien apoyados en el piso y sostén una mancuerna en cada mano con las palmas hacia arriba.", "Apoya la parte superior de los brazos sobre los muslos y deja las mancuernas colgando.", "Mantén fija la parte superior de los brazos y flexiona los codos para acercar las mancuernas a los hombros, contrayendo los bíceps.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0393.gif'),
('0395', 'Elevación lateral con mancuernas sentado (versión 2)', 'dumbbell seated lateral raise v. 2', '["elevaciones laterales en banco versión 2", "hombros laterales sentado variante 2", "dumbbell seated lateral raise v. 2"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los deltoides en su segunda versión. Se realiza sentado para reducir el impulso y concentrar el esfuerzo en los hombros. Se usa habitualmente para desarrollar amplitud y fuerza en los hombros.', '["Siéntate en un banco con los pies bien apoyados en el piso y una mancuerna en cada mano, apoyada sobre los muslos.", "Mantén la espalda recta y el abdomen firme.", "Eleva las mancuernas hacia los lados con los codos ligeramente flexionados hasta que los brazos queden paralelos al piso.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0395.gif'),
('0396', 'Elevación lateral con mancuernas sentado', 'dumbbell seated lateral raise', '["elevaciones laterales en banco", "hombros laterales sentado con pesas", "dumbbell seated lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Espalda alta"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los deltoides de los hombros. Se realiza sentado para reducir el impulso y concentrar el esfuerzo en los músculos de los hombros.', '["Siéntate en un banco con los pies bien apoyados en el piso y una mancuerna en cada mano, apoyada sobre los muslos.", "Mantén la espalda recta y el abdomen firme.", "Eleva las mancuernas hacia los lados con los codos ligeramente flexionados hasta que los brazos queden paralelos al piso.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0396.gif'),
('0397', 'Curl de muñeca neutro con mancuernas sentado', 'dumbbell seated neutral wrist curl', '["curl sentado con agarre neutro", "curl de antebrazo neutro sentado", "dumbbell seated neutral wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio para los bíceps y antebrazos que consiste en elevar mancuernas con agarre neutro mientras estás sentado, con énfasis en la fuerza de las muñecas y los antebrazos.', '["Siéntate en un banco con los pies bien apoyados en el piso y sostén una mancuerna en cada mano con las palmas enfrentadas.", "Apoya los antebrazos sobre los muslos y deja las mancuernas colgando.", "Mantén las muñecas en posición neutra y flexiona los codos para acercar las mancuernas a los hombros.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0397.gif'),
('0400', 'Elevación de pantorrilla a una pierna con mancuerna sentado', 'dumbbell seated one leg calf raise', '["elevación de talón sentado a una pierna", "pantorrilla unilateral con mancuerna en el muslo", "dumbbell seated one leg calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para las pantorrillas que se realiza sentado, con una mancuerna sobre el muslo de la pierna que trabaja. Ayuda a desarrollar fuerza y masa muscular en las pantorrillas, con cierta participación de los isquiotibiales y glúteos para estabilizar.', '["Siéntate en un banco o una silla con los pies bien apoyados en el piso y una mancuerna sobre el muslo derecho.", "Extiende la pierna izquierda al frente y mantén la punta del pie hacia ti.", "Apoya la parte delantera del pie derecho en una superficie elevada, como un escalón o un disco de pesas.", "Usa los músculos de la pantorrilla para elevar el talón derecho lo más alto que puedas.", "Haz una breve pausa arriba y luego baja el talón lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de pierna."]'::jsonb, '/gifs/0400.gif'),
('0401', 'Curl de muñeca con mancuernas sentado con palmas arriba', 'dumbbell seated palms up wrist curl', '["flexión de muñecas sentado", "antebrazo sentado con agarre supino", "dumbbell seated palms up wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los músculos del antebrazo, especialmente los flexores de la muñeca. Se realiza sentado, con los antebrazos apoyados en los muslos, flexionando las muñecas para elevar las mancuernas.', '["Siéntate en un banco con los pies bien apoyados en el piso y sostén una mancuerna en cada mano con las palmas hacia arriba.", "Apoya los antebrazos sobre los muslos y deja las muñecas fuera del borde.", "Flexiona lentamente las muñecas hacia arriba y contrae los antebrazos al llegar arriba.", "Haz una breve pausa y luego baja las manos a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0401.gif'),
('0402', 'Curl predicador con mancuerna sentado', 'dumbbell seated preacher curl', '["curl scott a una mano", "bíceps unilateral en banco predicador", "dumbbell seated preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza sentado en un banco predicador para reducir el impulso y maximizar el trabajo de los bíceps.', '["Siéntate en un banco predicador con los pies bien apoyados en el piso.", "Sostén una mancuerna en una mano con la palma hacia arriba y apoya la parte superior del brazo contra la almohadilla.", "Mantén fija la parte superior del brazo, exhala y flexiona el codo para acercar la mancuerna al hombro.", "Haz una breve pausa arriba, luego inhala y baja la mancuerna lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0402.gif'),
('0403', 'Curl concentrado con mancuerna sentado en agarre inverso', 'dumbbell seated reverse grip concentration curl', '["curl de concentración con agarre inverso", "bíceps concentrado sentado con mancuerna", "dumbbell seated reverse grip concentration curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza sentado, con una mancuerna y un agarre inverso con la palma hacia arriba. Pone énfasis en una técnica estricta y en la contracción muscular.', '["Siéntate en un banco con los pies bien apoyados en el piso y sostén una mancuerna en una mano con la palma hacia arriba.", "Apoya el codo en la cara interna del muslo, justo por encima de la rodilla.", "Mantén fija la parte superior del brazo, exhala y flexiona el codo para acercar la mancuerna al hombro.", "Haz una breve pausa arriba y aprieta el bíceps.", "Inhala y baja la mancuerna lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0403.gif'),
('0406', 'Encogimiento de hombros con mancuernas', 'dumbbell shrug', '["elevación de hombros con pesas", "trapecios con mancuernas", "dumbbell shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los trapecios. Consiste en elevar los hombros hacia las orejas mientras sostienes mancuernas, para desarrollar fuerza y masa muscular en la parte superior de la espalda.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano con las palmas hacia el cuerpo.", "Mantén los brazos rectos y deja las mancuernas colgando a los lados.", "Eleva los hombros lo más alto que puedas, como si quisieras tocar las orejas con ellos.", "Mantén la contracción un segundo y luego baja los hombros lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0406.gif'),
('0409', 'Elevación de pantorrilla a una pierna con mancuerna', 'dumbbell single leg calf raise', '["elevación de talón a una pierna", "pantorrilla unilateral de pie con peso", "dumbbell single leg calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Tobillos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio unilateral para las pantorrillas que se realiza sosteniendo una mancuerna para añadir resistencia. Trabaja una pierna a la vez y exige equilibrio y fuerza.', '["Párate en el borde de un escalón o una plataforma, con la parte delantera de los pies apoyada y los talones fuera del borde.", "Sostén una mancuerna en una mano y apoya la otra en una pared o baranda.", "Eleva el talón lo más alto que puedas para subir el cuerpo y quedar de puntillas.", "Haz una breve pausa arriba y luego baja el talón lentamente por debajo del nivel del escalón.", "Repite hasta completar las repeticiones deseadas y luego cambia de pierna."]'::jsonb, '/gifs/0409.gif'),
('0416', 'Curl de bíceps con mancuernas de pie', 'dumbbell standing biceps curl', '["curl parado con mancuernas", "bíceps de pie con pesas", "dumbbell standing biceps curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio clásico de fuerza para los bíceps que también involucra los antebrazos. Consiste en elevar mancuernas flexionando los codos de pie, con énfasis en el movimiento controlado y la contracción muscular.', '["Párate con la espalda recta y una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para elevar las mancuernas mientras contraes los bíceps.", "Sigue elevando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas queden a la altura de los hombros.", "Mantén esa posición un momento y aprieta los bíceps.", "Inhala y comienza a bajar las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0416.gif'),
('0417', 'Elevación de pantorrillas con mancuernas de pie', 'dumbbell standing calf raise', '["elevación de talones con pesas", "pantorrillas parado con mancuernas", "dumbbell standing calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Tobillos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio para las pantorrillas que consiste en elevar los talones del piso mientras sostienes mancuernas para añadir resistencia.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano.", "Usa las pantorrillas para elevar los talones del piso lo más alto que puedas.", "Haz una breve pausa arriba y luego baja los talones lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0417.gif'),
('0418', 'Curl concentrado con mancuerna de pie', 'dumbbell standing concentration curl', '["curl de concentración parado", "bíceps concentrado a una mano de pie", "dumbbell standing concentration curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza de pie, trabajando un brazo a la vez para concentrarse en la contracción.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en una mano, con el brazo completamente extendido y la palma hacia adentro.", "Apoya la mano libre sobre el muslo.", "Mantén fija la parte superior del brazo, exhala y flexiona el codo para acercar la mancuerna al hombro, contrayendo el bíceps.", "Sigue elevando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna quede a la altura del hombro.", "Mantén esa posición un momento y aprieta el bíceps.", "Inhala y baja la mancuerna lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0418.gif'),
('0419', 'Elevación frontal con mancuernas de pie sobre la cabeza', 'dumbbell standing front raise above head', '["elevación frontal por encima de la cabeza", "elevaciones frontales completas con pesas", "dumbbell standing front raise above head"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Bíceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de hombros para los deltoides que consiste en elevar las mancuernas desde la altura de los muslos hasta por encima de la cabeza con un movimiento controlado.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en cada mano con agarre prono.", "Mantén los brazos rectos y eleva las mancuernas al frente hasta llevarlas por encima de la cabeza.", "Haz una breve pausa arriba y luego baja las mancuernas lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0419.gif'),
('0421', 'Curl concentrado a un brazo de pie con mancuerna', 'dumbbell standing one arm concentration curl', '["curl de concentración de pie", "bíceps concentrado con mancuerna", "dumbbell standing one arm concentration curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza de pie, trabajando un brazo a la vez para aumentar la activación muscular.', '["Párate erguido con los pies al ancho de los hombros y sostén una mancuerna en una mano, con la palma hacia arriba.", "Apoya la mano libre sobre el muslo para sostenerte.", "Mantén fija la parte superior del brazo, exhala y flexiona el codo para acercar la mancuerna al hombro, contrayendo el bíceps.", "Sigue subiendo la mancuerna hasta contraer por completo el bíceps y llegar a la altura del hombro.", "Haz una pausa breve en esa posición y aprieta el bíceps.", "Inhala y baja lentamente la mancuerna hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0421.gif'),
('0422', 'Curl a un brazo de pie con mancuerna (con apoyo en banco inclinado)', 'dumbbell standing one arm curl (over incline bench)', '["curl unilateral con apoyo en banco", "bíceps con mancuerna de pie", "dumbbell standing one arm curl (over incline bench)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza de pie, flexionando un brazo con una mancuerna y usando un banco inclinado como apoyo.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en una mano, con la palma hacia adelante.", "Apoya la otra mano en un banco inclinado para sostenerte.", "Mantén fija la parte superior del brazo, exhala y flexiona el codo para acercar la mancuerna al hombro, contrayendo el bíceps.", "Haz una pausa arriba, luego inhala y baja lentamente la mancuerna hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0422.gif'),
('0423', 'Extensión de tríceps a un brazo de pie con mancuerna', 'dumbbell standing one arm extension', '["tríceps unilateral sobre la cabeza", "extensión con mancuerna a una mano", "dumbbell standing one arm extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps en el que sostienes una mancuerna sobre la cabeza con un brazo y extiendes el codo para levantarla, concentrando el esfuerzo en el tríceps.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en una mano.", "Levanta la mancuerna por encima de la cabeza y extiende por completo el brazo.", "Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo.", "Flexiona el codo para bajar lentamente la mancuerna detrás de la cabeza.", "Haz una pausa y luego vuelve a levantar la mancuerna hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0423.gif'),
('0425', 'Curl inverso a un brazo de pie con mancuerna', 'dumbbell standing one arm reverse curl', '["curl unilateral con agarre prono", "bíceps con agarre invertido a una mano", "dumbbell standing one arm reverse curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Trabaja los bíceps y los antebrazos con una mancuerna y agarre prono, con énfasis en el braquial y los extensores del antebrazo.', '["Párate erguido con los pies al ancho de los hombros y sostén una mancuerna en una mano con agarre prono.", "Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo.", "Flexiona lentamente el codo para acercar la mancuerna al hombro, sin mover la parte superior del brazo.", "Haz una pausa arriba y luego baja lentamente la mancuerna hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas y luego cambia de brazo."]'::jsonb, '/gifs/0425.gif'),
('0428', 'Curl predicador de pie con mancuernas', 'dumbbell standing preacher curl', '["curl Scott de pie con mancuernas", "bíceps con brazos apoyados en banco", "dumbbell standing preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza de pie, apoyando la parte superior de los brazos en un banco predicador o inclinado para mantener una técnica estricta.', '["Párate erguido con los pies al ancho de los hombros y sostén una mancuerna en cada mano, con las palmas hacia adelante.", "Apoya la parte posterior de los brazos sobre un banco predicador o un banco inclinado, con los codos ligeramente flexionados.", "Mantén fija la parte superior de los brazos, exhala y levanta las mancuernas flexionando los codos y contrayendo los bíceps.", "Sigue subiendo las mancuernas hasta contraer por completo los bíceps y llegar a la altura de los hombros.", "Haz una pausa breve en esa posición y aprieta los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0428.gif'),
('0429', 'Curl inverso de pie con mancuernas', 'dumbbell standing reverse curl', '["curl con mancuernas en pronación", "bíceps de pie con agarre invertido", "dumbbell standing reverse curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio para los bíceps y los antebrazos que se realiza de pie, flexionando los codos con mancuernas y agarre prono.', '["Párate erguido con los pies al ancho de los hombros y sostén una mancuerna en cada mano, con las palmas hacia el cuerpo.", "Mantén fija la parte superior de los brazos, exhala y levanta las mancuernas flexionando los codos y contrayendo los bíceps. Sigue subiendo hasta contraerlos por completo y llevar las mancuernas a la altura de los hombros.", "Haz una pausa breve en esa posición y aprieta los bíceps.", "Inhala y baja lentamente las mancuernas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0429.gif'),
('0430', 'Extensión de tríceps de pie con mancuerna', 'dumbbell standing triceps extension', '["tríceps sobre la cabeza con mancuerna", "extensión de codo de pie", "dumbbell standing triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Mancuerna', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza de pie, elevando una mancuerna sobre la cabeza y extendiendo el brazo. También trabaja los hombros de forma secundaria.', '["Párate con los pies al ancho de los hombros y sostén una mancuerna en una mano.", "Levanta la mancuerna por encima de la cabeza, manteniendo el brazo extendido.", "Flexiona el codo y baja la mancuerna detrás de la cabeza, sin mover la parte superior del brazo.", "Vuelve a extender el brazo hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0430.gif'),
('0433', 'Pullover con mancuerna y brazos rectos', 'dumbbell straight arm pullover', '["pullover de pecho con mancuerna", "pullover en banco con brazos extendidos", "dumbbell straight arm pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Dorsales", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que también trabaja los dorsales y los tríceps. Se realiza acostado en un banco, moviendo una mancuerna en arco por encima y detrás de la cabeza con los brazos rectos.', '["Acuéstate boca arriba en un banco, con la cabeza en un extremo y los pies firmemente apoyados en el suelo.", "Sostén una mancuerna con ambas manos y extiende los brazos sobre el pecho.", "Mantén los brazos rectos y baja lentamente la mancuerna detrás de la cabeza, siguiendo un arco.", "Haz una pausa y luego vuelve a levantar la mancuerna hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0433.gif'),
('0439', 'Curl Zottman con mancuernas', 'dumbbell zottman curl', '["curl de bíceps con giro de muñecas", "curl combinado normal e inverso", "dumbbell zottman curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio que combina el curl convencional con el inverso para trabajar los bíceps y los antebrazos. El giro de muñecas en la parte alta del movimiento permite trabajar ambos grupos musculares.', '["Párate erguido con una mancuerna en cada mano y las palmas hacia el cuerpo.", "Mantén los codos cerca del torso y gira las palmas hacia adelante.", "Flexiona los codos para subir las mancuernas hasta los hombros, sin mover la parte superior de los brazos.", "Al llegar arriba, gira las muñecas para que las palmas queden orientadas hacia afuera, alejadas del cuerpo.", "Baja lentamente las mancuernas hasta la posición inicial y gira las palmas para que vuelvan a mirar hacia el cuerpo.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0439.gif'),
('0446', 'Curl con barra Z y agarre cerrado', 'ez barbell close-grip curl', '["bíceps con barra Z y manos juntas", "curl cerrado con barra", "ez barbell close-grip curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra Z', 'Principiante', 'Fuerza', 'Ejercicio enfocado en los bíceps que utiliza una barra Z con agarre cerrado y las palmas hacia arriba. También trabaja los antebrazos de forma secundaria. Consiste en acercar la barra a los hombros manteniendo los codos junto al torso.', '["Párate erguido con los pies al ancho de los hombros y sujeta la barra Z con las palmas hacia arriba y las manos al ancho de los hombros.", "Mantén los codos cerca del torso y la parte superior de los brazos fija durante todo el movimiento.", "Flexiona los codos para acercar la barra a los hombros, contrayendo los bíceps.", "Haz una pausa arriba y luego baja lentamente la barra hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0446.gif'),
('0447', 'Curl con barra Z', 'ez barbell curl', '["bíceps con barra Z", "curl de bíceps con barra en Z", "ez barbell curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra Z', 'Principiante', 'Fuerza', 'Ejercicio clásico de brazos que trabaja los bíceps con una barra Z. Se realiza de pie, con las palmas hacia arriba, acercando la barra a los hombros mientras mantienes los codos junto al torso.', '["Párate erguido con los pies al ancho de los hombros y sujeta la barra Z con las palmas hacia arriba.", "Mantén los codos cerca del torso y la parte superior de los brazos fija durante todo el movimiento.", "Exhala mientras flexionas los codos para acercar la barra a los hombros, contrayendo los bíceps.", "Haz una pausa arriba y luego inhala mientras bajas lentamente la barra hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0447.gif'),
('0449', 'Extensión de tríceps en banco inclinado con barra Z', 'ez barbell incline triceps extension', '["tríceps inclinado con barra Z", "extensión de codos con barra Z en banco inclinado", "ez barbell incline triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra Z', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza en un banco inclinado con una barra Z. Requiere una buena técnica para evitar sobrecargar los hombros y trabajar eficazmente los tríceps.', '["Ajusta un banco inclinado a un ángulo de 45 grados.", "Siéntate con la espalda apoyada en el respaldo y sujeta la barra Z con agarre prono.", "Extiende por completo los brazos por encima de la cabeza, manteniendo los codos cerca de ella.", "Flexiona los codos para bajar la barra detrás de la cabeza, sin mover la parte superior de los brazos.", "Haz una pausa y luego extiende los brazos para volver a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0449.gif'),
('0451', 'Curl con barra Z y agarre inverso', 'ez barbell reverse grip curl', '["curl inverso con barra Z", "bíceps con barra Z y agarre invertido", "ez barbell reverse grip curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra Z', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los bíceps con activación adicional de los antebrazos. Se realiza con una barra Z y las palmas hacia arriba, elevando la barra mientras mantienes los codos junto al torso.', '["Párate erguido con los pies al ancho de los hombros y sujeta la barra Z con las palmas hacia arriba.", "Mantén los codos cerca del torso y la parte superior de los brazos fija durante todo el ejercicio.", "Exhala y flexiona los codos para subir la barra, contrayendo los bíceps.", "Sigue subiendo la barra hasta contraer por completo los bíceps y llegar a la altura de los hombros.", "Haz una pausa breve en esa posición y aprieta los bíceps.", "Inhala mientras bajas lentamente la barra hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0451.gif'),
('0452', 'Curl predicador con barra Z y agarre inverso', 'ez barbell reverse grip preacher curl', '["curl Scott inverso con barra Z", "bíceps en banco predicador con agarre invertido", "ez barbell reverse grip preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra Z', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps con activación adicional de los antebrazos. Se realiza sentado en un banco predicador, usando una barra Z con agarre inverso y las palmas hacia arriba.', '["Siéntate en un banco predicador con el pecho contra la almohadilla y los pies apoyados en el suelo.", "Sujeta la barra Z con las palmas hacia arriba y las manos al ancho de los hombros.", "Apoya la parte superior de los brazos sobre la almohadilla y deja que los antebrazos cuelguen hacia abajo.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para acercar la barra a los hombros.", "Haz una pausa arriba, luego inhala y baja lentamente la barra hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0452.gif'),
('0453', 'Extensión de tríceps sentado con barra Z', 'ez barbell seated triceps extension', '["tríceps sobre la cabeza con barra Z", "extensión de codos sentado con barra", "ez barbell seated triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Barra Z', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los tríceps que se realiza sentado con una barra Z. Favorece la fuerza y el desarrollo de los tríceps, con participación de los hombros para estabilizar.', '["Siéntate en un banco con la espalda recta y los pies apoyados en el suelo.", "Sujeta la barra Z con agarre prono y las manos al ancho de los hombros.", "Levanta la barra por encima de la cabeza y extiende por completo los brazos.", "Mantén fija la parte superior de los brazos y flexiona los codos para bajar la barra detrás de la cabeza.", "Haz una pausa y luego extiende los brazos para levantar la barra hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0453.gif'),
('0454', 'Curl araña con barra Z', 'ez barbell spider curl', '["curl de bíceps araña", "bíceps con barra Z y brazos apoyados", "ez barbell spider curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Barra Z', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los bíceps que se realiza con la parte superior de los brazos apoyada en un banco predicador o una pelota de estabilidad, para reducir las compensaciones y maximizar la activación de los bíceps.', '["Párate con los pies al ancho de los hombros y sujeta la barra Z con las palmas hacia arriba.", "Apoya la parte superior de los brazos en un banco predicador o una pelota de estabilidad y deja que los codos cuelguen hacia abajo.", "Mantén fija la parte superior de los brazos, exhala y flexiona los codos para acercar la barra a los hombros.", "Haz una pausa arriba y aprieta los bíceps.", "Inhala y baja lentamente la barra hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0454.gif'),
('0455', 'Curl de dedos', 'finger curls', '["flexión de dedos con barra", "ejercicio de agarre con barra", "finger curls"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Flexores de muñeca", "Músculos de agarre"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos, especialmente los flexores de los dedos y los músculos del agarre. Ayuda a mejorar la fuerza de agarre y el desarrollo de los antebrazos.', '["Siéntate en un banco con los pies apoyados en el suelo y sostén una barra con las palmas hacia arriba.", "Apoya los antebrazos sobre los muslos y deja las muñecas fuera del borde.", "Flexiona lentamente los dedos hacia las palmas, apretando firmemente la barra.", "Mantén la contracción un momento y luego vuelve lentamente los dedos a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0455.gif'),
('0458', 'Aperturas en el suelo (con barra)', 'floor fly (with barbell)', '["aperturas de pecho en el piso", "pecho con barra acostado en el suelo", "floor fly (with barbell)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que se realiza acostado en el suelo y se enfoca en estirar y contraer los pectorales, usando una barra como resistencia.', '["Acuéstate boca arriba en el suelo, con las rodillas flexionadas y los pies apoyados.", "Sostén una barra con agarre prono y los brazos extendidos hacia arriba sobre el pecho.", "Baja lentamente la barra hacia los lados, manteniendo los codos ligeramente flexionados.", "Baja la barra hasta que los brazos queden paralelos al suelo y sientas un estiramiento en el pecho.", "Haz una pausa y luego contrae los pectorales para llevar la barra de vuelta a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0458.gif'),
('0464', 'Plancha frontal con giro', 'front plank with twist', '["plancha con rotación de torso", "plancha alta con giro", "front plank with twist"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos", "Hombros"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio para la zona media que trabaja los abdominales y los oblicuos, con participación de los hombros. Consiste en girar el torso desde una posición de plancha, lo que exige estabilidad y coordinación.', '["Colócate en plancha alta, con las manos justo debajo de los hombros y el cuerpo en línea recta de la cabeza a los pies.", "Contrae el abdomen y los glúteos para mantener la estabilidad.", "Gira el torso hacia la derecha, levanta el brazo derecho y extiéndelo hacia el techo.", "Mantén estables las caderas y las piernas mientras giras.", "Mantén la posición un momento y luego vuelve al inicio.", "Repite el giro hacia el lado izquierdo.", "Sigue alternando los lados hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0464.gif'),
('0469', 'Abdominal (crunch) con rodillas al pecho', 'groin crunch', '["encogimiento abdominal con rodillas al pecho", "abdominal acostado con elevación de rodillas", "groin crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera", "Aductores"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para los abdominales, con trabajo secundario de los flexores de cadera y la parte interna de los muslos. Se realiza boca arriba, acercando las rodillas al pecho mientras contraes el abdomen.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos detrás de la cabeza, con los codos hacia los lados.", "Contrae el abdomen y levanta las piernas del suelo, acercando las rodillas al pecho.", "Haz una pausa arriba y luego baja lentamente las piernas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0469.gif'),
('0472', 'Elevación de piernas colgado', 'hanging leg raise', '["levantamiento de piernas en barra", "abdominales colgado de la barra", "hanging leg raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio con peso corporal para los abdominales y los flexores de cadera. Consiste en colgarse de una barra de dominadas y elevar las piernas al frente, manteniendo el abdomen activo durante todo el movimiento.', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas hacia adelante.", "Contrae el abdomen y levanta las piernas frente a ti, manteniéndolas rectas.", "Sigue subiendo hasta que las piernas queden paralelas al suelo o hasta donde puedas llegar con comodidad.", "Haz una pausa arriba y luego baja lentamente las piernas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0472.gif'),
('0475', 'Elevación de piernas rectas colgado', 'hanging straight leg raise', '["levantamiento de piernas extendidas en barra", "abdominales en barra con piernas rectas", "hanging straight leg raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio avanzado para la zona media que se realiza colgado de una barra de dominadas, elevando las piernas rectas al frente. Trabaja principalmente los abdominales y también los flexores de cadera.', '["Cuélgate de una barra de dominadas con los brazos completamente extendidos y las palmas hacia adelante.", "Contrae el abdomen y levanta las piernas frente a ti, manteniéndolas rectas.", "Sigue subiendo hasta que las piernas queden paralelas al suelo o hasta donde puedas llegar con comodidad.", "Haz una pausa arriba y luego baja lentamente las piernas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0475.gif'),
('0488', 'Hiperextensión (en banco)', 'hyperextension (on bench)', '["extensión lumbar en banco", "elevación de tronco en banco de hiperextensiones", "hyperextension (on bench)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Erectores de la columna', '["Glúteos", "Isquiotibiales"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los erectores de la columna y la zona lumbar, con participación de los glúteos y los isquiotibiales. Se realiza en un banco de hiperextensiones, bajando y subiendo el torso con la espalda recta.', '["Ajusta el banco de hiperextensiones para apoyar cómodamente las caderas sobre la almohadilla y asegurar los pies.", "Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.", "Baja lentamente el torso hacia el suelo, manteniendo la espalda recta.", "Haz una pausa abajo y luego levanta el torso hasta alinearlo con las piernas.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0488.gif'),
('0489', 'Hiperextensión', 'hyperextension', '["extensión de espalda baja", "extensión lumbar con peso corporal", "hyperextension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Erectores de la columna', '["Glúteos", "Isquiotibiales"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los erectores de la columna y la zona lumbar, con énfasis secundario en los glúteos y los isquiotibiales. Se realiza en un banco de hiperextensiones, bajando y subiendo el torso con la espalda recta.', '["Ajusta el banco de hiperextensiones para apoyar la parte superior de los muslos sobre la almohadilla y asegurar los pies.", "Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza.", "Baja el torso hacia el suelo, manteniendo la espalda recta.", "Haz una pausa abajo y luego levanta el torso hasta alinearlo con las piernas.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0489.gif'),
('0496', 'Curl inverso de piernas (con apoyo en banco)', 'inverse leg curl (bench support)', '["flexión de piernas boca abajo en banco", "curl femoral con peso corporal en banco", "inverse leg curl (bench support)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal para los isquiotibiales que se realiza boca abajo sobre un banco, flexionando las piernas hacia los glúteos.', '["Acuéstate boca abajo sobre un banco, con las caderas en el borde y las piernas extendidas hacia atrás.", "Agárrate del banco para sostenerte.", "Mantén el torso quieto y flexiona las rodillas para acercar las piernas a los glúteos.", "Haz una pausa arriba y luego extiende lentamente las piernas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0496.gif'),
('0573', 'Extensión de espalda en máquina', 'lever back extension', '["extensión lumbar en máquina", "espalda baja en máquina", "lever back extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Erectores de la columna', '["Glúteos", "Isquiotibiales"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los músculos de la zona lumbar, especialmente los extensores de la columna, con trabajo secundario de glúteos e isquiotibiales. Se realiza sentado, con los pies asegurados, extendiendo la espalda contra resistencia.', '["Ajusta la máquina a tu tamaño y rango de movimiento.", "Siéntate con la espalda contra la almohadilla y los pies asegurados.", "Coloca las manos en los agarres o las barras de sujeción.", "Contrae el abdomen e inclínate lentamente hacia adelante, dejando que la espalda se redondee un poco.", "Haz una pausa abajo y siente el estiramiento en la zona lumbar.", "Usa los músculos de la espalda para levantar lentamente el torso hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0573.gif'),
('0575', 'Curl de bíceps en máquina', 'lever bicep curl', '["bíceps en máquina", "flexión de codos en máquina", "lever bicep curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los bíceps, con trabajo secundario de los antebrazos. La máquina ofrece resistencia guiada y estabilidad, por lo que resulta accesible para la mayoría de las personas.', '["Ajusta la altura del asiento y siéntate en la máquina con la espalda contra la almohadilla.", "Sujeta los agarres con las palmas hacia arriba y mantén los codos cerca de los costados.", "Exhala y flexiona los codos para subir los agarres, contrayendo los bíceps.", "Haz una pausa arriba y aprieta los bíceps.", "Inhala y baja lentamente los agarres hasta la posición inicial, extendiendo por completo los brazos.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0575.gif'),
('0580', 'Encogimiento de hombros sin agarre en máquina', 'lever gripless shrug', '["trapecios en máquina sin sujetar", "elevación de hombros sin agarre", "lever gripless shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros", "Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los trapecios que consiste en elevar los hombros sin sujetar los agarres. Esto aísla los trapecios y reduce la participación de los antebrazos.', '["Ajusta la altura del asiento y colócate en la máquina.", "Sujeta los agarres con las palmas hacia adentro y los brazos completamente extendidos.", "Mantén la espalda recta, exhala y eleva los hombros lo más que puedas.", "Mantén la contracción un momento, luego inhala y baja lentamente los hombros hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0580.gif'),
('0582', 'Curl de piernas de rodillas en máquina', 'lever kneeling leg curl', '["curl femoral arrodillado", "flexión de rodillas en máquina", "lever kneeling leg curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos"]'::jsonb, 'Máquina', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los isquiotibiales que se realiza de rodillas en una máquina. Trabaja principalmente los isquiotibiales y también los glúteos de forma secundaria.', '["Ajusta la máquina a tu cuerpo y selecciona el peso deseado.", "Arrodíllate en la máquina mirando hacia abajo, con las rodillas sobre la almohadilla y los pies asegurados debajo de los apoyos acolchados.", "Sujeta los agarres o los lados de la máquina para estabilizarte.", "Mantén el torso quieto, exhala y flexiona las rodillas para acercar las piernas a los glúteos.", "Haz una pausa arriba y aprieta los isquiotibiales.", "Inhala y baja lentamente las piernas hasta la posición inicial, extendiendo por completo las rodillas.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0582.gif'),
('0584', 'Elevación lateral en máquina', 'lever lateral raise', '["laterales de hombro en máquina", "elevaciones de brazos en máquina", "lever lateral raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Espalda alta"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los deltoides que consiste en elevar los brazos hacia los lados contra resistencia. Trabaja principalmente los deltoides laterales y, de forma secundaria, los trapecios y la espalda alta. La máquina aporta estabilidad y facilita el ejercicio a quienes tienen menos experiencia.', '["Ajusta la altura del asiento y siéntate en la máquina con la espalda contra la almohadilla.", "Sujeta los agarres con agarre prono y mantén los brazos rectos.", "Exhala y eleva los brazos hacia los lados hasta que queden paralelos al suelo.", "Haz una pausa arriba, luego inhala y baja lentamente los brazos hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0584.gif'),
('0585', 'Extensión de piernas en máquina', 'lever leg extension', '["extensión de cuádriceps", "extensión de rodillas en máquina", "lever leg extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Cuádriceps', '["Isquiotibiales"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento en máquina para los cuádriceps. Consiste en extender las rodillas para levantar un peso, trabajando principalmente la parte delantera de los muslos.', '["Ajusta la altura del asiento y el respaldo de la máquina a tu cuerpo.", "Siéntate con la espalda contra el respaldo y los pies sobre el apoyo acolchado.", "Sujeta los agarres o las barras laterales para estabilizarte.", "Estira las rodillas para extender las piernas hacia adelante y levantar el peso.", "Haz una pausa arriba y luego baja lentamente el peso hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0585.gif'),
('0586', 'Curl de piernas acostado en máquina', 'lever lying leg curl', '["curl femoral acostado", "flexión de piernas boca abajo en máquina", "lever lying leg curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Pantorrillas"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los isquiotibiales que se realiza en máquina. Consiste en flexionar las piernas contra resistencia estando boca abajo, con énfasis en la contracción y el control de los isquiotibiales.', '["Ajusta la máquina a tu cuerpo y selecciona el peso deseado.", "Acuéstate boca abajo en la máquina, con las piernas rectas y los talones contra la palanca acolchada.", "Sujeta los agarres o los lados de la máquina para estabilizarte.", "Mantén el torso quieto, exhala y flexiona las rodillas para subir las piernas lo más que puedas sin despegar las caderas de la almohadilla.", "Haz una pausa breve en esa posición y aprieta los isquiotibiales.", "Inhala y baja lentamente la palanca hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0586.gif'),
('0592', 'Curl predicador en máquina', 'lever preacher curl', '["curl Scott en máquina", "bíceps en máquina con brazos apoyados", "lever preacher curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de fuerza en máquina que trabaja principalmente los bíceps, con activación secundaria de los antebrazos. Consiste en subir los agarres manteniendo la parte superior de los brazos apoyada en una almohadilla, para aislar los bíceps y reducir las compensaciones.', '["Ajusta la altura del asiento y colócate en la máquina.", "Apoya la parte superior de los brazos sobre la almohadilla y sujeta los agarres con las palmas hacia arriba.", "Mantén la espalda recta y los codos apoyados en la almohadilla.", "Exhala y flexiona los codos para acercar los antebrazos a la parte superior de los brazos, contrayendo los bíceps.", "Haz una pausa arriba y aprieta los bíceps.", "Inhala y baja lentamente los agarres hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0592.gif'),
('0593', 'Hiperextensión inversa en máquina', 'lever reverse hyperextension', '["extensión inversa de cadera en máquina", "elevación de piernas boca abajo en máquina", "lever reverse hyperextension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Glúteos'), 'Piernas', 'Glúteos', '["Isquiotibiales", "Zona lumbar"]'::jsonb, 'Máquina', 'Intermedio', 'Fuerza', 'Ejercicio en máquina para los glúteos, con trabajo secundario de los isquiotibiales y la zona lumbar. Se realiza boca abajo, elevando las piernas con los glúteos y los isquiotibiales.', '["Ajusta la máquina a tu cuerpo y asegura los pies en los apoyos acolchados.", "Acuéstate boca abajo en la máquina, con el torso colgando fuera del borde y las caderas apoyadas en la almohadilla.", "Cruza los brazos sobre el pecho o colócalos detrás de la cabeza.", "Contrae los glúteos y los isquiotibiales para levantar las piernas hasta que queden paralelas al suelo.", "Haz una pausa arriba y luego baja lentamente las piernas hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0593.gif'),
('0594', 'Elevación de pantorrillas sentado en máquina', 'lever seated calf raise', '["elevación de talones sentado", "pantorrillas sentado en máquina", "lever seated calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Sóleo", "Estabilizadores del tobillo"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para las pantorrillas, especialmente el gastrocnemio y el sóleo. Se realiza sentado, elevando y bajando los talones contra la resistencia de la máquina.', '["Ajusta la altura del asiento para que las rodillas queden ligeramente flexionadas y los pies apoyados por completo en la plataforma.", "Coloca las puntas de los pies sobre la plataforma, dejando los talones fuera del borde.", "Sujeta los agarres o los lados del asiento para estabilizarte.", "Empuja con la parte delantera de los pies para elevar los talones lo más que puedas.", "Haz una pausa arriba y luego baja lentamente los talones hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0594.gif'),
('0595', 'Abdominal (crunch) sentado en máquina (con almohadilla de pecho)', 'lever seated crunch (chest pad)', '["abdominales en máquina con apoyo de pecho", "encogimiento abdominal sentado en máquina", "lever seated crunch (chest pad)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio abdominal en máquina que trabaja principalmente los abdominales y también los oblicuos. Combina la flexión y la extensión controladas del torso contra resistencia para desarrollar la fuerza de la zona media.', '["Ajusta la altura del asiento y la posición de la almohadilla de pecho para que te resulten cómodas.", "Siéntate en la máquina con la espalda contra la almohadilla de pecho y los pies apoyados en el suelo.", "Sujeta los agarres o las barras laterales para estabilizarte.", "Contrae el abdomen e inclínate lentamente hacia atrás, dejando que la almohadilla de pecho se mueva contigo.", "Haz una pausa en el punto de máxima contracción y siente la tensión en el abdomen.", "Contrae el abdomen para levantar de nuevo el torso y volver lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0595.gif'),
('0596', 'Aperturas sentado en máquina', 'lever seated fly', '["mariposa de pecho en máquina", "aperturas de pectoral en máquina", "lever seated fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Trapecio"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los pectorales que se realiza sentado, juntando los agarres frente al pecho.', '["Ajusta la altura del asiento y siéntate en la máquina con la espalda contra la almohadilla.", "Sujeta los agarres con agarre prono y mantén los codos ligeramente flexionados.", "Exhala y empuja los agarres hacia adelante hasta juntarlos frente al pecho.", "Haz una pausa y aprieta los pectorales.", "Inhala y vuelve lentamente a la posición inicial, dejando que los pectorales se estiren.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0596.gif'),
('0599', 'Curl de piernas sentado en máquina', 'lever seated leg curl', '["curl femoral sentado", "flexión de rodillas sentado en máquina", "lever seated leg curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Pantorrillas"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los isquiotibiales. Se realiza sentado, flexionando las rodillas contra resistencia para aislar los isquiotibiales y reducir la participación de otros grupos musculares.', '["Ajusta la máquina a tu cuerpo y siéntate con la espalda contra el respaldo.", "Coloca la parte baja de las piernas debajo de la palanca acolchada, justo por encima de los tobillos.", "Sujeta los agarres laterales de la máquina para sostenerte.", "Mantén los muslos quietos, exhala y flexiona las rodillas para subir la parte baja de las piernas lo más que puedas.", "Haz una pausa breve en esa posición y aprieta los isquiotibiales.", "Inhala y baja lentamente la palanca hasta la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0599.gif'),
('0600', 'Abdominal (crunch) con elevación de piernas sentado en máquina', 'lever seated leg raise crunch', '["abdominal combinado en máquina", "encogimiento de torso y piernas en máquina", "lever seated leg raise crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Máquina', 'Intermedio', 'Fuerza', 'Ejercicio abdominal en máquina que también trabaja los flexores de cadera. Combina la elevación de piernas con la flexión del torso hacia adelante para un trabajo exigente de la zona media.', '["Siéntate en la máquina con la espalda contra el respaldo y los pies sobre los apoyos.", "Sujeta los agarres o las barras laterales para estabilizarte.", "Contrae el abdomen y eleva lentamente las piernas hacia el pecho mientras flexionas el torso hacia adelante.", "Haz una pausa arriba y luego baja lentamente las piernas y devuelve el torso a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0600.gif'),
('0601', 'Aperturas inversas sentado en máquina (agarre paralelo)', 'lever seated reverse fly (parallel grip)', '["mariposa inversa con agarre neutro", "hombro posterior en máquina con agarre paralelo", "lever seated reverse fly (parallel grip)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para los deltoides posteriores, con trabajo secundario de los trapecios y los romboides. Se realiza sentado, jalando los agarres hacia atrás y hacia los lados mientras juntas los omóplatos.', '["Ajusta la altura del asiento y siéntate con el pecho contra la almohadilla y los pies apoyados en el suelo.", "Sujeta los agarres con las palmas enfrentadas y mantén los brazos ligeramente flexionados.", "Exhala y junta los omóplatos mientras jalas los agarres hacia atrás y hacia los lados, alejándolos del cuerpo.", "Haz una pausa en el punto de máxima contracción, luego inhala y vuelve lentamente a la posición inicial.", "Repite hasta completar las repeticiones deseadas."]'::jsonb, '/gifs/0601.gif'),
('0602', 'Aperturas inversas sentado en máquina', 'lever seated reverse fly', '["Pájaros en máquina", "Aperturas para hombro posterior", "lever seated reverse fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Hombros'), 'Hombros', 'Deltoides', '["Trapecio", "Romboides"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio sentado en máquina que trabaja principalmente los deltoides posteriores y, de forma secundaria, los trapecios y romboides. La máquina aporta estabilidad y ayuda a aislar los músculos trabajados.', '["Ajusta la altura del asiento y colócate en la máquina con el pecho contra la almohadilla y los pies bien apoyados en el piso.", "Sujeta los agarres con las palmas hacia abajo y mantén los brazos ligeramente flexionados.", "Exhala y junta los omóplatos mientras llevas los agarres hacia atrás y hacia afuera, alejándolos del cuerpo.", "Haz una breve pausa al contraer al máximo, luego inhala y regresa despacio a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0602.gif'),
('0604', 'Encogimiento de hombros en máquina', 'lever shrug', '["Elevación de hombros en máquina", "Trapecio en máquina", "lever shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para trabajar los trapecios. Consiste en elevar los hombros con los brazos estirados contra la resistencia de la máquina.', '["Ajusta la altura del asiento y colócate en la máquina con la espalda contra la almohadilla.", "Sujeta los agarres con las palmas hacia abajo y mantén los brazos estirados.", "Mantén la espalda recta y eleva los hombros hacia las orejas lo más que puedas.", "Mantén la contracción un momento y baja despacio los hombros hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0604.gif'),
('0605', 'Elevación de pantorrillas de pie en máquina', 'lever standing calf raise', '["Elevación de talones en máquina", "Pantorrillas parado en máquina", "lever standing calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Sóleo", "Estabilizadores del tobillo"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para las pantorrillas que se realiza de pie en una máquina. Consiste en subir y bajar los talones contra la resistencia de la máquina.', '["Ajusta la máquina a tu estatura y colócate de pie con los pies separados al ancho de los hombros.", "Coloca los hombros debajo de las almohadillas y sujeta los agarres para mantener la estabilidad.", "Extiende los tobillos para elevar los talones lo más que puedas.", "Haz una breve pausa arriba y baja despacio los talones hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0605.gif'),
('0607', 'Extensión de tríceps en máquina', 'lever triceps extension', '["Tríceps sentado en máquina", "Extensión de brazos en máquina", "lever triceps extension"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los tríceps realizado en máquina. Consiste en extender los brazos contra resistencia, concentrando el esfuerzo en los tríceps y reduciendo la participación de los hombros.', '["Ajusta la altura del asiento y colócate en la máquina con la espalda contra la almohadilla.", "Sujeta los agarres con las palmas hacia abajo y estira por completo los brazos frente a ti.", "Mantén fija la parte superior de los brazos y flexiona los codos para bajar despacio los agarres hacia la frente.", "Haz una breve pausa abajo y estira los brazos para empujar los agarres hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0607.gif'),
('0620', 'Elevación de piernas acostado en banco plano', 'lying leg raise flat bench', '["Elevación de piernas en banca", "Abdominales con piernas rectas en banco", "lying leg raise flat bench"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio abdominal en banco plano con peso corporal. Trabaja principalmente los abdominales y también los flexores de la cadera. Consiste en elevar las piernas estiradas hacia el techo y bajarlas de forma controlada.', '["Acuéstate boca arriba en un banco plano con la espalda bien apoyada.", "Coloca las manos debajo de los glúteos para apoyarte.", "Mantén las piernas estiradas y juntas, y elévalas hacia el techo.", "Haz una breve pausa arriba y baja despacio las piernas hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0620.gif'),
('0634', 'Abdominal (crunch) negativo', 'negative crunch', '["Crunch excéntrico", "Abdominal con bajada lenta", "negative crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio abdominal que se enfoca en la fase excéntrica, o de bajada, del crunch para aumentar la fuerza y el control de la zona media.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso.", "Coloca las manos detrás de la cabeza con los codos hacia afuera.", "Contrae los abdominales y levanta despacio la parte superior del cuerpo, encorvándote hacia adelante hasta que el torso forme un ángulo de 45 grados.", "Haz una breve pausa arriba y baja despacio la parte superior del cuerpo hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0634.gif'),
('0635', 'Abdominal (crunch) oblicuo en el piso', 'oblique crunches floor', '["Crunch con giro", "Abdominales para oblicuos en el suelo", "oblique crunches floor"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio en el piso que trabaja los abdominales, especialmente los oblicuos, al incorporar un giro del torso durante el crunch. Se realiza boca arriba con peso corporal y es adecuado para la mayoría de los niveles de condición física.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso.", "Coloca las manos detrás de la cabeza o crúzalas sobre el pecho.", "Contrae los abdominales y despega los omóplatos del piso mientras giras el torso hacia un lado.", "Haz una breve pausa y vuelve a apoyar los omóplatos en el piso.", "Repite hacia el otro lado y alterna los lados en cada repetición."]'::jsonb, '/gifs/0635.gif'),
('0643', 'Estiramiento de tríceps sobre la cabeza', 'overhead triceps stretch', '["Estiramiento de tríceps con brazo arriba", "Estiramiento de brazo por detrás de la cabeza", "overhead triceps stretch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Estiramiento', 'Estiramiento estático para los tríceps que también estira los hombros. Se realiza levantando un brazo sobre la cabeza, flexionando el codo y tirando suavemente de él con la otra mano para profundizar el estiramiento.', '["Ponte de pie o siéntate erguido con los pies separados al ancho de los hombros.", "Levanta un brazo sobre la cabeza y flexiona el codo para acercar la mano al omóplato del lado contrario.", "Con la otra mano, tira suavemente del codo hacia el lado contrario de la cabeza hasta sentir el estiramiento en el tríceps.", "Mantén el estiramiento de 15 a 30 segundos y luego suelta.", "Repite del otro lado."]'::jsonb, '/gifs/0643.gif'),
('0689', 'Elevación de piernas sentado', 'seated leg raise', '["Elevación de piernas en banca sentado", "Abdominales sentado con piernas rectas", "seated leg raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio abdominal realizado sentado en un banco. Trabaja principalmente los abdominales y también los flexores de la cadera. Elevar las piernas manteniéndolas estiradas requiere fuerza y estabilidad en la zona media.', '["Siéntate en un banco plano con la espalda recta y los pies bien apoyados en el piso.", "Apoya las manos a los lados del banco para sostenerte.", "Mantén las piernas estiradas y elévalas despacio frente a ti hasta que queden paralelas al piso.", "Haz una breve pausa arriba y baja despacio las piernas hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0689.gif'),
('0691', 'Abdominal (crunch) lateral sentado (en pared)', 'seated side crunch (wall)', '["Crunch lateral con apoyo en pared", "Oblicuos sentado contra la pared", "seated side crunch (wall)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio abdominal sentado en el piso con la espalda contra una pared. Trabaja los abdominales y oblicuos al inclinar el torso de lado a lado, acercando el codo a la cadera.', '["Siéntate en el piso con la espalda contra una pared y las piernas extendidas frente a ti.", "Flexiona las rodillas y apoya los pies en el piso, separados al ancho de las caderas.", "Coloca las manos detrás de la cabeza con los codos hacia afuera.", "Contrae los abdominales e inclínate hacia un lado, acercando el codo a la cadera.", "Haz una breve pausa y regresa a la posición inicial.", "Repite hacia el otro lado.", "Sigue alternando los lados hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0691.gif'),
('0696', 'Curl inverso de piernas autoasistido (en el piso)', 'self assisted inverse leg curl (on floor)', '["Curl femoral autoasistido en el suelo", "Flexión inversa de piernas con cadera elevada", "self assisted inverse leg curl (on floor)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Intermedio', 'Fuerza', 'Ejercicio con peso corporal que trabaja los isquiotibiales y, de forma secundaria, los glúteos y las pantorrillas. Consiste en flexionar las piernas hacia los glúteos con la cadera elevada, lo que exige bastante fuerza y control de los isquiotibiales.', '["Acuéstate boca arriba con las piernas extendidas y los brazos a los lados del cuerpo.", "Flexiona las rodillas y apoya los pies en el piso, separados al ancho de las caderas.", "Levanta la cadera del piso mientras contraes los glúteos y los isquiotibiales.", "Flexiona despacio las piernas para acercar los pies a los glúteos, manteniendo la cadera elevada.", "Haz una breve pausa al final del movimiento y vuelve a extender despacio las piernas hasta la posición inicial.", "Baja la cadera hasta apoyarla de nuevo en el piso.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0696.gif'),
('0697', 'Curl inverso de piernas autoasistido', 'self assisted inverse leg curl', '["Curl femoral inverso con peso corporal", "Flexión de piernas autoasistida", "self assisted inverse leg curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos", "Pantorrillas"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para los isquiotibiales que también trabaja los glúteos y las pantorrillas. Consiste en flexionar las piernas hacia el pecho estando boca arriba, usando las manos como apoyo si lo necesitas.', '["Acuéstate boca arriba sobre una colchoneta o un banco con las piernas extendidas.", "Coloca las manos a los lados del cuerpo o debajo de los glúteos para apoyarte.", "Flexiona las rodillas y despega los pies del piso, acercando los muslos al pecho.", "Haz una breve pausa arriba y baja despacio las piernas hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0697.gif'),
('0727', 'Elevación de pantorrilla a una pierna (sobre una mancuerna)', 'single leg calf raise (on a dumbbell)', '["Elevación de talón a una pierna con mancuerna", "Pantorrilla unilateral con mancuerna", "single leg calf raise (on a dumbbell)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Tobillos", "Pies"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio para las pantorrillas que también involucra los tobillos y los pies. Consiste en mantener el equilibrio sobre una pierna mientras sostienes una mancuerna y elevas el talón, lo que aumenta la exigencia de fuerza y equilibrio.', '["Ponte de pie con los pies separados al ancho de las caderas y sostén una mancuerna en una mano.", "Despega un pie del piso y mantén el equilibrio sobre la otra pierna.", "Contrae la pantorrilla para elevar despacio el talón lo más que puedas.", "Haz una breve pausa arriba y baja despacio el talón.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna."]'::jsonb, '/gifs/0727.gif'),
('0746', 'Encogimiento por detrás en máquina Smith', 'smith back shrug', '["Encogimiento posterior en Smith", "Trapecio por detrás en máquina Smith", "smith back shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los trapecios realizado en máquina Smith. Consiste en elevar los hombros hacia las orejas mientras sostienes la barra, concentrándote en contraer los trapecios al llegar arriba.', '["Ponte de pie con los pies separados al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con las palmas hacia abajo y las manos un poco más separadas que el ancho de los hombros.", "Mantén los brazos estirados y deja que la barra cuelgue frente a los muslos.", "Eleva los hombros directamente hacia las orejas y contrae los trapecios al llegar arriba.", "Mantén la posición un momento y baja los hombros hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0746.gif'),
('0763', 'Elevación inversa de pantorrillas en máquina Smith', 'smith reverse calf raises', '["Elevación inversa de talones en Smith", "Pantorrillas inversas en máquina Smith", "smith reverse calf raises"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio en máquina Smith que trabaja principalmente las pantorrillas y, de forma secundaria, los isquiotibiales. Consiste en subir y bajar los talones sobre un escalón, usando la barra de la máquina como apoyo.', '["Ajusta la barra de la máquina Smith a una altura justo debajo de los hombros.", "Ponte de pie frente a la barra con los pies separados al ancho de las caderas y las puntas hacia adelante.", "Apoya la parte delantera de los pies en el borde de un escalón o una plataforma, dejando los talones por fuera.", "Sujeta la barra para apoyarte, manteniendo la espalda recta y el abdomen firme.", "Eleva los talones lo más que puedas, llevando el peso del cuerpo sobre la parte delantera de los pies.", "Haz una breve pausa arriba y baja despacio los talones hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0763.gif'),
('0767', 'Encogimiento de hombros en máquina Smith', 'smith shrug', '["Elevación de hombros en Smith", "Trapecio en máquina Smith", "smith shrug"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Trapecio', '["Hombros"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio en máquina Smith para trabajar los trapecios. Consiste en elevar los hombros hacia las orejas mientras sostienes la barra, concentrándote en contraer los trapecios al llegar arriba.', '["Ponte de pie con los pies separados al ancho de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con las palmas hacia abajo y las manos un poco más separadas que el ancho de los hombros.", "Mantén los brazos estirados y los hombros relajados.", "Eleva los hombros hacia las orejas y contrae los trapecios al llegar arriba.", "Mantén la posición un momento y baja despacio los hombros hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0767.gif'),
('0771', 'Curl de muñeca de pie por detrás en máquina Smith', 'smith standing back wrist curl', '["Flexión de muñecas de pie en Smith", "Antebrazo por detrás en máquina Smith", "smith standing back wrist curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Antebrazos'), 'Antebrazos', 'Antebrazos', '["Bíceps", "Tríceps"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio de aislamiento para los antebrazos realizado en máquina Smith. Consiste en flexionar las muñecas hacia arriba mientras sostienes la barra con las palmas hacia abajo, enfocándote en la fuerza de los antebrazos.', '["Ponte de pie frente a la máquina Smith con los pies separados al ancho de los hombros.", "Sujeta la barra con las palmas hacia abajo y las manos separadas al ancho de los hombros.", "Mantén la espalda recta y los codos cerca del cuerpo.", "Flexiona despacio las muñecas hacia arriba, acercando la barra al cuerpo.", "Haz una breve pausa arriba y baja despacio la barra hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0771.gif'),
('0773', 'Elevación de pantorrillas de pie en máquina Smith', 'smith standing leg calf raise', '["Elevación de talones de pie en Smith", "Pantorrillas parado en máquina Smith", "smith standing leg calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Máquina Smith', 'Principiante', 'Fuerza', 'Ejercicio en máquina Smith que trabaja principalmente las pantorrillas y, de forma secundaria, los isquiotibiales y glúteos. Consiste en elevar los talones para quedar de puntillas y luego bajarlos, usando la máquina para aportar estabilidad y resistencia.', '["Ajusta la barra de la máquina Smith a una altura que te permita estar de pie con los pies bien apoyados en el piso y los hombros debajo de la barra.", "Colócate debajo de la barra con los pies separados al ancho de los hombros y las puntas hacia adelante.", "Coloca las manos sobre la barra para mantener la estabilidad.", "Contrae las pantorrillas y eleva despacio los talones del piso hasta quedar de puntillas.", "Haz una breve pausa arriba y baja despacio los talones hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0773.gif'),
('0795', 'Curl de pierna de pie a una pierna', 'standing single leg curl', '["Curl femoral unilateral de pie", "Flexión de rodilla parado", "standing single leg curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Piernas', 'Isquiotibiales', '["Glúteos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para los isquiotibiales y glúteos. Consiste en mantener el equilibrio sobre una pierna mientras acercas el talón de la otra a los glúteos, trabajando la activación de los isquiotibiales y la estabilidad sobre una sola pierna.', '["Ponte de pie con los pies separados al ancho de las caderas y las manos en la cintura.", "Pasa el peso a la pierna izquierda y levanta el pie derecho del piso, flexionando la rodilla.", "Acerca despacio el talón derecho a los glúteos mientras contraes los isquiotibiales.", "Haz una breve pausa arriba y baja despacio el pie derecho hasta la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de pierna."]'::jsonb, '/gifs/0795.gif'),
('0807', 'Abdominal (crunch) inverso colgado', 'suspended reverse crunch', '["Crunch inverso en barra", "Elevación de rodillas colgado", "suspended reverse crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio avanzado para la zona media que se realiza colgado de una barra de dominadas, llevando las rodillas hacia el pecho. Trabaja los abdominales y los flexores de la cadera.', '["Cuélgate de una barra de dominadas con los brazos completamente estirados y las palmas hacia adelante.", "Contrae el abdomen y eleva las rodillas hacia el pecho, acercando la pelvis a las costillas.", "Haz una breve pausa arriba y baja despacio las rodillas hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0807.gif'),
('0816', 'Press de tríceps', 'triceps press', '["Empuje de tríceps con peso corporal", "Extensión de tríceps con el cuerpo", "triceps press"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los tríceps y, de forma secundaria, los hombros. Consiste en alejar el cuerpo del piso mediante un empuje con los tríceps, generalmente desde una posición de pie con los brazos extendidos hacia adelante.', '["Ponte de pie con los pies separados al ancho de los hombros y las rodillas ligeramente flexionadas.", "Extiende los brazos frente a ti, paralelos al piso.", "Flexiona los codos y baja el cuerpo hacia el piso, manteniendo la parte superior de los brazos cerca de los costados.", "Haz una breve pausa abajo y empuja para volver a subir hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0816.gif'),
('0817', 'Estiramiento de tríceps', 'triceps stretch', '["Estiramiento de brazo sobre la cabeza", "Estiramiento de tríceps con ayuda de la otra mano", "triceps stretch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Tríceps'), 'Brazos', 'Tríceps', '["Hombros"]'::jsonb, 'Peso corporal', 'Principiante', 'Estiramiento', 'Estiramiento estático para los tríceps y hombros. Se realiza levantando un brazo sobre la cabeza y tirando suavemente del codo con la otra mano.', '["Ponte de pie o siéntate erguido con la espalda recta.", "Levanta un brazo sobre la cabeza y flexiona el codo.", "Coloca la otra mano sobre el codo flexionado y tira suavemente de él hacia la cabeza.", "Mantén la posición de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps.", "Suelta y repite con el otro brazo."]'::jsonb, '/gifs/0817.gif'),
('0826', 'Elevación vertical de piernas (en barras paralelas)', 'vertical leg raise (on parallel bars)', '["Elevación de piernas en paralelas", "Abdominales con piernas rectas en paralelas", "vertical leg raise (on parallel bars)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Avanzado', 'Fuerza', 'Ejercicio abdominal realizado con el cuerpo suspendido en barras paralelas. Consiste en elevar las piernas frente al cuerpo para trabajar los abdominales y los flexores de la cadera.', '["Sostén el cuerpo suspendido en las barras paralelas con los brazos completamente estirados y el cuerpo recto.", "Contrae el abdomen y eleva las piernas frente a ti, manteniéndolas estiradas.", "Sigue elevándolas hasta que queden paralelas al piso o un poco más arriba.", "Haz una breve pausa arriba y baja despacio las piernas hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0826.gif'),
('0868', 'Curl de bíceps en polea', 'cable curl', '["Bíceps con polea", "Flexión de brazos en polea", "cable curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Bíceps'), 'Brazos', 'Bíceps', '["Antebrazos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para los bíceps realizado en polea. Consiste en acercar el accesorio a los hombros manteniendo los codos cerca del cuerpo, con tensión constante en los bíceps durante todo el movimiento.', '["Ponte de pie frente a la máquina de poleas con los pies separados al ancho de los hombros.", "Sujeta el accesorio de la polea con las palmas hacia arriba.", "Mantén los codos cerca de los costados y la parte superior de los brazos fija.", "Exhala y flexiona los codos para acercar el accesorio a los hombros mientras contraes los bíceps.", "Haz una breve pausa arriba y aprieta los bíceps.", "Inhala y baja despacio el accesorio hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0868.gif'),
('0871', 'Abdominal (crunch) agrupado', 'tuck crunch', '["Crunch con rodillas al pecho", "Abdominal con encogimiento de piernas", "tuck crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio abdominal con peso corporal que también involucra los flexores de la cadera. Consiste en encoger el torso y llevar las rodillas al pecho al mismo tiempo, fortaleciendo la zona media.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el piso.", "Coloca las manos detrás de la cabeza con los codos hacia afuera.", "Contrae los abdominales, despega los omóplatos del piso y lleva las rodillas hacia el pecho mientras acercas la parte superior del cuerpo a las rodillas.", "Haz una breve pausa arriba y baja despacio los omóplatos mientras extiendes las piernas para volver a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0871.gif'),
('0872', 'Abdominal (crunch) inverso', 'reverse crunch', '["Crunch con elevación de cadera", "Abdominal inverso en el piso", "reverse crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja los abdominales, especialmente la parte inferior, al despegar la cadera del piso y llevar las rodillas hacia el pecho.', '["Acuéstate boca arriba con los brazos extendidos a los lados del cuerpo.", "Flexiona las rodillas y despega los pies del piso hasta que los muslos queden perpendiculares al suelo.", "Contrae los abdominales y despega la cadera del piso, llevando las rodillas hacia el pecho.", "Haz una breve pausa arriba y baja despacio la cadera hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0872.gif'),
('0873', 'Abdominal (crunch) inverso en polea', 'cable reverse crunch', '["Crunch inverso con resistencia de polea", "Abdominal con elevación de cadera en polea", "cable reverse crunch"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio abdominal que utiliza una polea para añadir resistencia al crunch inverso tradicional. Trabaja principalmente los abdominales y también los flexores de la cadera.', '["Conecta el cable a una polea baja y acuéstate boca arriba en una colchoneta.", "Sujeta el cable con ambas manos y extiende los brazos hacia el techo.", "Flexiona las rodillas y levanta las piernas, acercando los muslos al pecho.", "Mantén estable la parte superior del cuerpo y eleva la pelvis hacia el pecho, despegando la cadera de la colchoneta.", "Haz una breve pausa arriba y baja despacio la cadera hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0873.gif'),
('0874', 'Abdominal (crunch) de pie en polea (con cuerda)', 'cable standing crunch (with rope attachment)', '["Crunch parado con cuerda", "Abdominales de pie con polea", "cable standing crunch (with rope attachment)"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio abdominal de pie realizado en polea con cuerda. Trabaja los abdominales y también los oblicuos al encoger el torso hacia adelante contra resistencia, lo que exige esfuerzo de la zona media.', '["Coloca una cuerda en la polea a la altura del pecho.", "Ponte de pie de espaldas a la máquina con los pies separados al ancho de los hombros.", "Sujeta la cuerda con ambas manos y llévala detrás de la cabeza, manteniendo los codos flexionados.", "Contrae los abdominales y encoge despacio el torso hacia adelante, acercando los codos a las rodillas.", "Haz una breve pausa al contraer al máximo y regresa despacio a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/0874.gif'),
('1253', 'Elevación de pantorrillas tipo burro en máquina', 'lever donkey calf raise', '["Elevación de talones tipo burro", "Pantorrillas en máquina de burro", "lever donkey calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Máquina', 'Principiante', 'Fuerza', 'Ejercicio en máquina para las pantorrillas. Consiste en subir y bajar los talones sobre una plataforma, dejándolos por fuera del borde. La máquina aporta resistencia y apoyo para realizar el movimiento de forma controlada.', '["Ajusta la máquina a una altura adecuada para tu cuerpo.", "Colócate frente a la máquina con las puntas de los pies sobre la plataforma y los talones por fuera del borde.", "Coloca las manos en los agarres o en las barras de apoyo para mantener la estabilidad.", "Contrae las pantorrillas y eleva los talones lo más que puedas, apoyándote en la parte delantera de los pies.", "Haz una breve pausa arriba y baja despacio los talones hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1253.gif'),
('1255', 'Pullover declinado con barra', 'barbell decline pullover', '["Pullover con barra en banco declinado", "Pecho con barra detrás de la cabeza en declinado", "barbell decline pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de pecho con barra en banco declinado que trabaja los pectorales y, de forma secundaria, los tríceps y hombros. Consiste en bajar la barra en un arco detrás de la cabeza y regresar a la posición inicial, con control y estabilidad.', '["Acuéstate en un banco declinado con la cabeza más baja que la cadera y los pies asegurados.", "Sujeta la barra con agarre prono, con las palmas hacia afuera y las manos un poco más separadas que el ancho de los hombros.", "Extiende los brazos sobre el pecho, manteniendo los codos ligeramente flexionados.", "Baja la barra en un arco por detrás de la cabeza hasta sentir un estiramiento en el pecho y los hombros.", "Haz una breve pausa e invierte el movimiento para regresar la barra a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1255.gif'),
('1262', 'Aperturas declinadas a un brazo en polea', 'cable one arm decline chest fly', '["Apertura unilateral en polea con banco declinado", "Pecho a un brazo en polea declinada", "cable one arm decline chest fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio de aislamiento para los pectorales realizado a un brazo con polea y banco declinado. Enfatiza la fuerza y el control de cada lado, ayudando a mejorar la simetría muscular y el desarrollo del pecho.', '["Coloca un agarre en D en una polea baja y ajusta el banco en posición declinada.", "Acuéstate en el banco con la cabeza hacia la máquina y sujeta el agarre con la mano derecha.", "Extiende el brazo sobre el pecho, manteniendo el codo ligeramente flexionado.", "Baja el brazo hacia un lado de forma controlada hasta que la mano quede alineada con el hombro.", "Haz una breve pausa e invierte el movimiento para regresar el brazo a la posición inicial.", "Completa la cantidad de repeticiones deseada, cambia al brazo izquierdo y repite el ejercicio."]'::jsonb, '/gifs/1262.gif'),
('1263', 'Aperturas a un brazo en polea sobre pelota de ejercicios', 'cable one arm fly on exercise ball', '["Apertura unilateral con polea en pelota", "Pecho a un brazo sentado en pelota", "cable one arm fly on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio unilateral de pecho realizado sentado en una pelota de ejercicios, que añade una exigencia de equilibrio a las aperturas en polea. Trabaja los pectorales, deltoides y tríceps, y requiere estabilidad de la zona media para mantener la postura.', '["Siéntate en una pelota de ejercicios con los pies bien apoyados en el piso y la espalda recta.", "Sujeta un agarre de polea con una mano y extiende el brazo hacia un lado, paralelo al piso.", "Mantén el codo ligeramente flexionado y la palma hacia adelante.", "Lleva despacio el brazo por delante del cuerpo mientras contraes los músculos del pecho.", "Haz una breve pausa al final del movimiento y regresa despacio a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de lado."]'::jsonb, '/gifs/1263.gif'),
('1264', 'Aperturas inclinadas a un brazo en polea sobre pelota de ejercicios', 'cable one arm incline fly on exercise ball', '["Apertura unilateral inclinada con polea en pelota", "Pecho inclinado a un brazo con polea y pelota", "cable one arm incline fly on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Polea', 'Avanzado', 'Fuerza', 'Ejercicio de pecho con polea y pelota de ejercicios que trabaja los pectorales y también los deltoides y tríceps. La superficie inestable de la pelota y el movimiento a un brazo exigen equilibrio y coordinación.', '["Siéntate en una pelota de ejercicios con los pies bien apoyados en el piso y la espalda contra un banco inclinado.", "Sujeta un agarre de polea con una mano, con el brazo extendido y la palma hacia adentro.", "Mantén el codo ligeramente flexionado y baja despacio el brazo hacia un lado hasta que la mano quede alineada con el hombro.", "Haz una breve pausa y contrae los músculos del pecho para regresar el brazo a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/1264.gif'),
('1276', 'Aperturas declinadas a un brazo con mancuerna', 'dumbbell decline one arm fly', '["Apertura unilateral con mancuerna en banco declinado", "Pecho declinado a un brazo con mancuerna", "dumbbell decline one arm fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros"]'::jsonb, 'Mancuerna', 'Avanzado', 'Fuerza', 'Ejercicio unilateral de pecho en banco declinado que trabaja los pectorales y también los hombros. Requiere buen control y estabilidad para realizarlo con seguridad, especialmente por la inclinación del banco y el uso de un solo brazo.', '["Acuéstate en un banco declinado con una mancuerna en una mano, apoyada sobre el muslo.", "Ayúdate con el muslo para levantar la mancuerna hasta alinearla con el hombro, con la palma hacia el torso.", "Gira la muñeca para que la palma quede hacia adelante.", "Inhala y baja despacio la mancuerna hacia un lado hasta sentir un estiramiento en el pecho.", "Exhala y usa los músculos del pecho para subir la mancuerna hasta la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/1276.gif'),
('1277', 'Aperturas con mancuernas sobre pelota de ejercicios', 'dumbbell fly on exercise ball', '["Aperturas de pecho en pelota", "Pecho con mancuernas en balón de ejercicios", "dumbbell fly on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que también exige trabajo de la zona media y estabilidad al realizarse sobre una superficie inestable. Trabaja los pectorales y, de forma secundaria, los hombros y tríceps.', '["Siéntate en una pelota de ejercicios y sostén una mancuerna en cada mano.", "Da pasos hacia adelante y desliza el cuerpo hacia abajo sobre la pelota hasta apoyar la cabeza, el cuello y la parte superior de la espalda.", "Extiende los brazos sobre el pecho con las palmas enfrentadas.", "Flexiona ligeramente los codos y baja los brazos hacia los lados en un arco amplio hasta sentir un estiramiento en el pecho.", "Haz una breve pausa, invierte el movimiento y contrae los músculos del pecho mientras regresas las mancuernas a la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1277.gif'),
('1279', 'Aperturas inclinadas a un brazo con mancuerna', 'dumbbell incline one arm fly', '["Apertura unilateral con mancuerna en banco inclinado", "Pecho inclinado a un brazo con mancuerna", "dumbbell incline one arm fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Deltoides", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio unilateral de pecho en banco inclinado que trabaja los pectorales, deltoides y tríceps. Requiere control y estabilidad, ya que trabajar con un solo brazo aumenta la exigencia sobre los músculos estabilizadores de la zona media y del hombro.', '["Ajusta el banco inclinado a un ángulo de 30 a 45 grados.", "Siéntate en el banco con una mancuerna en una mano, apoyada sobre el muslo.", "Recuéstate en el banco y mantén los pies bien apoyados en el piso.", "Sostén la mancuerna con el brazo extendido sobre el pecho.", "Baja la mancuerna hacia un lado en un arco amplio, manteniendo el codo ligeramente flexionado.", "Haz una pausa cuando el brazo quede paralelo al piso e invierte el movimiento para regresar la mancuerna a la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/1279.gif'),
('1280', 'Aperturas inclinadas a un brazo con mancuerna sobre pelota de ejercicios', 'dumbbell incline one arm fly on exercise ball', '["Apertura unilateral inclinada con mancuerna en pelota", "Pecho inclinado a un brazo en balón de ejercicios", "dumbbell incline one arm fly on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros"]'::jsonb, 'Mancuerna', 'Avanzado', 'Fuerza', 'Ejercicio de pecho que también exige estabilidad y equilibrio por el uso de una pelota de ejercicios. Trabaja los pectorales e involucra los hombros y la zona media para estabilizar el cuerpo.', '["Siéntate en una pelota de ejercicios con una mancuerna en una mano.", "Da pasos hacia adelante y desliza el cuerpo hacia abajo sobre la pelota hasta apoyar la cabeza, el cuello y la parte superior de la espalda.", "Sostén la mancuerna con el brazo extendido sobre el pecho y la palma hacia adentro.", "Baja despacio la mancuerna hacia un lado, manteniendo el codo ligeramente flexionado.", "Haz una breve pausa cuando el brazo quede paralelo al piso.", "Contrae los músculos del pecho para subir la mancuerna hasta la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/1280.gif'),
('1284', 'Pullover acostado con mancuerna sobre pelota de ejercicios', 'dumbbell lying pullover on exercise ball', '["Pullover con mancuerna en pelota", "Pecho con mancuerna detrás de la cabeza en pelota", "dumbbell lying pullover on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Espalda"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que también trabaja los tríceps, hombros y espalda. El uso de la pelota exige equilibrio y estabilidad, por lo que resulta más exigente que el pullover convencional.', '["Siéntate en una pelota de ejercicios y desliza el cuerpo hacia adelante hasta apoyar la parte superior de la espalda sobre ella.", "Sostén una mancuerna con ambas manos y extiende los brazos sobre el pecho.", "Baja despacio la mancuerna por detrás de la cabeza, manteniendo los brazos estirados.", "Haz una breve pausa y sube la mancuerna hasta la posición inicial.", "Repite hasta completar la cantidad de repeticiones deseada."]'::jsonb, '/gifs/1284.gif'),
('1285', 'Aperturas a un brazo con mancuerna en banco', 'dumbbell one arm bench fly', '["Apertura unilateral con mancuerna en banca plana", "Pecho a un brazo con mancuerna en banco", "dumbbell one arm bench fly"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio unilateral de pecho que trabaja los pectorales y también los hombros. Requiere equilibrio y control para estabilizar el peso con un solo brazo mientras estás acostado en un banco.', '["Siéntate en un banco plano con una mancuerna en una mano, apoyada sobre el muslo.", "Recuéstate en el banco manteniendo la mancuerna contra el muslo.", "Ayúdate con la mano libre para levantar la mancuerna hasta la posición inicial.", "Sostén la mancuerna directamente sobre el hombro, con el brazo extendido y la palma hacia adentro.", "Baja la mancuerna hacia un lado en un arco amplio, manteniendo el codo ligeramente flexionado.", "Haz una pausa cuando el brazo quede paralelo al piso, invierte el movimiento y regresa la mancuerna a la posición inicial.", "Completa la cantidad de repeticiones deseada, cambia de brazo y repite."]'::jsonb, '/gifs/1285.gif'),
('1286', 'Aperturas de pecho a un brazo con mancuerna sobre pelota de ejercicios', 'dumbbell one arm chest fly on exercise ball', '["Apertura unilateral con mancuerna en pelota", "Pecho a un brazo en balón de ejercicios", "dumbbell one arm chest fly on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Mancuerna', 'Avanzado', 'Fuerza', 'Ejercicio unilateral de pecho que también exige estabilidad de la zona media y equilibrio al usar una pelota de ejercicios como apoyo. Trabaja los pectorales, hombros y tríceps.', '["Siéntate en una pelota de ejercicios con una mancuerna en una mano y los pies bien apoyados en el piso.", "Da pasos hacia adelante y deja que la pelota ruede hasta que la parte superior de la espalda quede apoyada en ella, con la cabeza, el cuello y los hombros fuera de la pelota.", "Extiende el brazo con la mancuerna sobre el pecho, con la palma hacia adentro.", "Baja despacio la mancuerna hacia un lado, manteniendo el codo ligeramente flexionado.", "Haz una breve pausa cuando el brazo quede paralelo al piso.", "Contrae los músculos del pecho para subir la mancuerna hasta la posición inicial.", "Completa la cantidad de repeticiones deseada y luego cambia de brazo."]'::jsonb, '/gifs/1286.gif'),
('1288', 'Apertura a un brazo con mancuerna sobre pelota', 'dumbbell one arm fly on exercise ball', '["Apertura unilateral en pelota de ejercicio", "Pecho a un brazo sobre pelota", "dumbbell one arm fly on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Hombros", "Tríceps"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho a un brazo con mancuerna y la parte alta de la espalda apoyada sobre una pelota de ejercicio. También exige equilibrio y estabilidad del abdomen, y aumenta el trabajo de los músculos estabilizadores.', '["Siéntate sobre una pelota de ejercicio con una mancuerna en una mano y los pies bien apoyados en el suelo.", "Da pasos hacia adelante y recuesta el cuerpo hasta apoyar la parte alta de la espalda sobre la pelota.", "Extiende el brazo con la mancuerna justo encima del pecho, con la palma hacia adentro.", "Baja lentamente la mancuerna hacia un lado, manteniendo el codo ligeramente flexionado.", "Haz una breve pausa y contrae el pecho para regresar la mancuerna a la posición inicial.", "Completa las repeticiones que desees y luego cambia de brazo."]'::jsonb, '/gifs/1288.gif'),
('1291', 'Pullover a un brazo con mancuerna sobre pelota', 'dumbbell one arm pullover on exercise ball', '["Pullover unilateral en pelota de ejercicio", "Pullover con mancuerna a una mano", "dumbbell one arm pullover on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Dorsales", "Romboides"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio de pecho que también trabaja los tríceps, dorsales y romboides. El uso de la pelota exige equilibrio y estabilidad del abdomen, además de fuerza y coordinación de un solo brazo.', '["Siéntate sobre una pelota de ejercicio con los pies bien apoyados en el suelo y las rodillas flexionadas a 90 grados.", "Sostén una mancuerna con una mano y extiende el brazo justo encima del pecho.", "Baja lentamente la mancuerna por detrás de la cabeza, manteniendo el brazo recto.", "Haz una breve pausa y vuelve a subir la mancuerna a la posición inicial.", "Completa las repeticiones que desees y luego cambia de brazo."]'::jsonb, '/gifs/1291.gif'),
('1294', 'Pullover con mancuerna y extensión de cadera sobre pelota', 'dumbbell pullover hip extension on exercise ball', '["Pullover con elevación de cadera en pelota", "Extensión de cadera y pullover con mancuerna", "dumbbell pullover hip extension on exercise ball"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Pecho'), 'Pecho', 'Pectorales', '["Tríceps", "Hombros", "Core"]'::jsonb, 'Mancuerna', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que combina un pullover con una extensión de cadera sobre una pelota de ejercicio. Trabaja los pectorales, tríceps, hombros y abdomen, y exige mayor equilibrio y coordinación por la inestabilidad de la pelota.', '["Siéntate sobre una pelota de ejercicio con los pies bien apoyados en el suelo y la mancuerna sobre los muslos.", "Da pasos cortos hacia adelante y deja que la pelota ruede por tu espalda hasta que la cabeza, el cuello y la parte alta de la espalda queden apoyados sobre ella.", "Sostén la mancuerna con ambas manos y extiende los brazos encima del pecho, manteniendo los codos ligeramente flexionados.", "Baja la mancuerna por detrás de la cabeza, manteniendo los brazos extendidos y controlando el movimiento.", "Haz una breve pausa y vuelve a subir la mancuerna a la posición inicial.", "Mantén los brazos extendidos y eleva la cadera, apretando los glúteos y activando el abdomen.", "Baja la cadera hasta regresar a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1294.gif'),
('1316', 'Pullover con barra (brazos flexionados)', 'barbell bent arm pullover', '["Pullover con codos flexionados", "Pullover para dorsales con barra", "barbell bent arm pullover"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Tríceps", "Pecho"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio compuesto que trabaja principalmente los dorsales y, en segundo plano, los tríceps y el pecho. Se realiza acostado en un banco, moviendo la barra en un arco por encima y detrás de la cabeza con fuerza y control.', '["Acuéstate boca arriba en un banco, con la cabeza en un extremo y los pies apoyados en el suelo.", "Sujeta una barra con las manos al ancho de los hombros y extiende los brazos encima del pecho.", "Baja la barra por detrás de la cabeza, manteniendo los brazos ligeramente flexionados.", "Haz una breve pausa y vuelve a subir la barra a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1316.gif'),
('1322', 'Remo con cuerda en polea en banco inclinado', 'cable rope extension incline bench row', '["Remo en polea baja con cuerda", "Remo sentado con cuerda en banco inclinado", "cable rope extension incline bench row"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Espalda alta', '["Bíceps", "Hombros"]'::jsonb, 'Polea', 'Intermedio', 'Fuerza', 'Ejercicio para la parte alta de la espalda que se realiza sentado en un banco inclinado, jalando una cuerda de polea hacia la parte alta del pecho. Enfatiza el movimiento de juntar los omóplatos y el trabajo de la espalda alta.', '["Ajusta un banco inclinado a 45 grados y prepara la máquina para usar la polea baja.", "Coloca un agarre de cuerda en la polea y siéntate en el banco inclinado de frente a la máquina.", "Sujeta la cuerda con las palmas hacia abajo e inclínate hacia adelante, manteniendo la espalda recta.", "Extiende completamente los brazos y jala la cuerda hacia la parte alta del pecho, manteniendo los codos cerca del cuerpo.", "Junta los omóplatos al final del movimiento.", "Afloja la tensión lentamente y regresa a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1322.gif'),
('1352', 'Extensión lumbar en el suelo', 'lower back curl', '["Elevación de tronco boca abajo", "Lumbares con peso corporal", "lower back curl"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Erectores de la columna', '["Glúteos", "Isquiotibiales"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja la zona lumbar, los glúteos y la parte posterior de los muslos. Consiste en elevar el tronco desde una posición boca abajo mediante la contracción de los músculos lumbares.', '["Acuéstate boca abajo con las piernas extendidas y los brazos a los lados del cuerpo.", "Activa los glúteos y la parte posterior de los muslos, y levanta lentamente el tronco del suelo, arqueando la espalda hacia arriba.", "Haz una breve pausa arriba y baja lentamente el tronco hasta regresar a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1352.gif'),
('1370', 'Elevación de talones sobre barra en el suelo', 'barbell floor calf raise', '["Pantorrillas sobre barra", "Elevación de pantorrillas con apoyo en barra", "barbell floor calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de fuerza para las pantorrillas. Consiste en apoyar la parte delantera de los pies sobre una barra y elevar los talones para trabajar estos músculos.', '["Coloca una barra en el suelo frente a ti.", "Párate con la parte delantera de los pies sobre el borde de la barra y los talones por fuera, sin apoyo.", "Sujétate de un objeto estable si necesitas ayuda para mantener el equilibrio.", "Eleva los talones lo más que puedas, usando las pantorrillas para levantar el cuerpo.", "Haz una breve pausa arriba y baja lentamente los talones hasta regresar a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1370.gif'),
('1371', 'Elevación de talones sentado con barra', 'barbell seated calf raise', '["Pantorrillas sentado con barra", "Elevación de pantorrillas con barra en los muslos", "barbell seated calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales"]'::jsonb, 'Barra', 'Principiante', 'Fuerza', 'Ejercicio de pantorrillas que se realiza sentado en un banco con una barra sobre los muslos. Al subir y bajar los talones, trabaja las pantorrillas en todo su recorrido.', '["Siéntate en un banco con los pies bien apoyados en el suelo y una barra sobre los muslos.", "Apoya la parte delantera de los pies sobre una plataforma elevada, como un bloque o un escalón.", "Baja los talones lo más que puedas, sintiendo el estiramiento en las pantorrillas.", "Eleva los talones lo más que puedas, contrayendo las pantorrillas.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1371.gif'),
('1372', 'Elevación de talones de pie con barra', 'barbell standing calf raise', '["Pantorrillas de pie con barra", "Elevación de pantorrillas con barra en la espalda", "barbell standing calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Barra', 'Intermedio', 'Fuerza', 'Ejercicio de fuerza para las pantorrillas. Se realiza de pie, con una barra sobre la parte alta de la espalda, elevando los talones del suelo.', '["Párate con los pies al ancho de los hombros y coloca una barra sobre la parte alta de la espalda.", "Eleva los talones lo más que puedas, sosteniéndote sobre las puntas de los pies.", "Haz una breve pausa arriba y baja lentamente los talones hasta regresar a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1372.gif'),
('1373', 'Elevación de talones de pie con peso corporal', 'bodyweight standing calf raise', '["Pantorrillas de pie sin pesas", "Elevación de pantorrillas con tu propio peso", "bodyweight standing calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Tobillos", "Pies"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio sencillo para las pantorrillas que consiste en elevar los talones de pie, usando únicamente el peso corporal como resistencia. Ayuda a fortalecer y tonificar las pantorrillas y puede mejorar la estabilidad de los tobillos.', '["Párate con los pies al ancho de los hombros y las puntas hacia adelante.", "Apoya las manos en una pared o superficie estable para mantener el equilibrio.", "Eleva lentamente los talones, llevando el peso del cuerpo hacia la parte delantera de los pies.", "Haz una breve pausa arriba y baja lentamente los talones hasta regresar a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1373.gif'),
('1375', 'Elevación de talones de pie en polea', 'cable standing calf raise', '["Pantorrillas de pie en polea", "Elevación de pantorrillas con cable", "cable standing calf raise"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Piernas'), 'Pantorrillas', 'Pantorrillas', '["Isquiotibiales", "Glúteos"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio para las pantorrillas que usa una polea como resistencia. Consiste en elevar los talones estando de pie y también activa, en menor medida, la parte posterior de los muslos y los glúteos.', '["Párate frente a una máquina de poleas con los pies al ancho de los hombros.", "Sujeta los agarres de la máquina o colócate una tobillera de polea en los tobillos.", "Eleva los talones del suelo, extendiendo los tobillos lo más que puedas.", "Haz una breve pausa arriba y baja lentamente los talones hasta regresar a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/1375.gif'),
('0001', 'Abdominal de tres cuartos', '3/4 sit-up', '["Abdominal 3/4", "Abdominal parcial a 45 grados", "3/4 sit-up"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera", "Zona lumbar"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio abdominal con peso corporal que consiste en elevar el tronco hasta un ángulo de 45 grados. Trabaja el abdomen, los flexores de la cadera y la zona lumbar, y se usa para desarrollar fuerza y estabilidad del tronco.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el suelo.", "Coloca las manos detrás de la cabeza, con los codos hacia afuera.", "Contrae el abdomen y eleva lentamente el tronco, flexionándolo hacia adelante hasta formar un ángulo de 45 grados.", "Haz una breve pausa arriba y baja lentamente el tronco hasta regresar a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/0001.gif'),
('0002', 'Flexión lateral a 45 grados', '45° side bend', '["Inclinación lateral de tronco", "Oblicuos de pie sin pesas", "45° side bend"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para el abdomen, especialmente los oblicuos. Consiste en inclinar el tronco hacia un lado estando de pie, manteniendo el abdomen activo para dar estabilidad y controlar el movimiento.', '["Párate con los pies al ancho de los hombros y los brazos extendidos a los lados del cuerpo.", "Mantén la espalda recta y el abdomen firme mientras inclinas lentamente el tronco hacia un lado, acercando la mano a la rodilla.", "Haz una breve pausa abajo y regresa lentamente a la posición inicial.", "Repite hacia el otro lado.", "Sigue alternando los lados hasta completar las repeticiones que desees."]'::jsonb, '/gifs/0002.gif'),
('0003', 'Abdominal bicicleta', 'air bike', '["Bicicleta abdominal", "Abdominal con codo a rodilla alternado", "air bike"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Flexores de cadera"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal que trabaja el abdomen y los flexores de la cadera. Se realiza boca arriba, alternando el contacto de codo y rodilla con un movimiento de pedaleo para activar el abdomen.', '["Acuéstate boca arriba con las manos detrás de la cabeza.", "Levanta las piernas del suelo y flexiona las rodillas a 90 grados.", "Acerca el codo derecho a la rodilla izquierda mientras estiras la pierna derecha.", "Regresa a la posición inicial y repite del otro lado, acercando el codo izquierdo a la rodilla derecha mientras estiras la pierna izquierda.", "Sigue alternando los lados con un movimiento de pedaleo hasta completar las repeticiones que desees."]'::jsonb, '/gifs/0003.gif'),
('0006', 'Toques de talón alternados', 'alternate heel touchers', '["Abdominal con toque de talones", "Toques laterales de talón", "alternate heel touchers"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Abdomen'), 'Abdomen', 'Abdominales', '["Oblicuos"]'::jsonb, 'Peso corporal', 'Principiante', 'Fuerza', 'Ejercicio con peso corporal para el abdomen, especialmente los oblicuos. Se realiza boca arriba, elevando los hombros y moviéndose de lado a lado para tocar los talones, con el abdomen activo durante todo el movimiento.', '["Acuéstate boca arriba con las rodillas flexionadas y los pies bien apoyados en el suelo.", "Extiende los brazos hacia los lados, paralelos al suelo.", "Contrae el abdomen, levanta los hombros del suelo y acerca la mano derecha al talón derecho.", "Regresa a la posición inicial y repite del lado izquierdo, acercando la mano izquierda al talón izquierdo.", "Sigue alternando los lados hasta completar las repeticiones que desees."]'::jsonb, '/gifs/0006.gif'),
('0007', 'Jalón al pecho alternado en polea', 'alternate lateral pulldown', '["Jalón dorsal alternado", "Jalón de espalda con brazos alternos", "alternate lateral pulldown"]'::jsonb, (SELECT id FROM grupos_musculares WHERE nombre = 'Espalda'), 'Espalda', 'Dorsales', '["Bíceps", "Romboides"]'::jsonb, 'Polea', 'Principiante', 'Fuerza', 'Ejercicio en polea que trabaja principalmente los dorsales y, en segundo plano, los bíceps y romboides. Consiste en jalar los agarres hacia el pecho de forma alternada para desarrollar fuerza y activar los músculos de la espalda.', '["Siéntate en la máquina de poleas con la espalda recta y los pies bien apoyados en el suelo.", "Sujeta los agarres con las palmas hacia adelante y las manos un poco más separadas que el ancho de los hombros.", "Inclínate ligeramente hacia atrás y jala los agarres hacia el pecho, juntando los omóplatos.", "Haz una breve pausa al final del jalón y deja que los agarres regresen lentamente a la posición inicial.", "Repite hasta completar las repeticiones que desees."]'::jsonb, '/gifs/0007.gif')
ON CONFLICT (codigo) DO UPDATE SET
    nombre = EXCLUDED.nombre,
    nombre_original = EXCLUDED.nombre_original,
    alias = EXCLUDED.alias,
    grupo_muscular_id = EXCLUDED.grupo_muscular_id,
    zona = EXCLUDED.zona,
    musculo_principal = EXCLUDED.musculo_principal,
    musculos_secundarios = EXCLUDED.musculos_secundarios,
    equipo = EXCLUDED.equipo,
    dificultad = EXCLUDED.dificultad,
    categoria = EXCLUDED.categoria,
    descripcion = EXCLUDED.descripcion,
    instrucciones = EXCLUDED.instrucciones,
    gif_url = EXCLUDED.gif_url;
